(window.GIM_TP=window.GIM_TP||{})["Z.Vayishlach.0"]={"from":0,"a":[[[],[],[]],[["וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים וגו'. רִבִּי יְהוּדָה פָּתַח (תהילים צ״א:י״א) כִּי מַלְאָכָיו יְצַוְּה לָךְ לִשְׁמָרְךָ בְּכָל דְרָכֶיךָ, הַאי קְרָא אוּקְמוּהָ חַבְרַיָיא, דְהָא בְּשַׁעְתָּא דְּבַר נָשׁ אָתֵי לְעַלְמָא, מִיָּד אִזְדַּמַּן בַּהֲדֵיהּ יֵצֶר הָרָע דְּאִיהוּ מְקַטְרֵג לֵיהּ לְבַר נָשׁ תָּדִיר כְּמָה דְאַתְּ אָמֵר, (בראשית ד׳:ז׳) לַפֶּתַח חַטָּאת רוֹבֵץ. מַאי חַטָּאת רוֹבֵץ, דָּא יֵצֶר הָרָע.","וְדָוִד הָכִי נָמֵי קָרְיֵיהּ חַטָּאת דִּכְתִיב, (תהילים נ״א:ה׳) וְחַטָּאתִי נֶגְדִי תָמִיד, בְּגִין דְּאִיהוּ עָבִיד לֵיהּ לְבַר נָשׁ כָּל יוֹמָא לְמֶחטֵי קַמֵּי מָארֵיהּ, וְיֵצֶר הָרָע דָּא לָא אִתְעֲדֵי מִבַּר נָשׁ מִיּוֹמָא דְאִתְיְלִיד בַּר נָשׁ לְעָלְמִין. וְיֵצֶר הַטּוֹב אָתֵי לְבַר נָשׁ מִיּוֹמָא דְאָתֵי לְאִתְדַּכָּאָה.","וְאֵימָתַי אָתֵי בַּר נָשׁ לְאִתְדַּכָּאָה כַּד אִיהוּ בַּר תְּלֵיסַר שְׁנִין, כְּדֵין אִזְדַּוַּוג בַּר נָשׁ בְּתַרְוַויְיהוּ חַד מִימִינָא וְחַד מִשְּׂמָאלָא, יֵצֶר טוֹב לִימִינָא וְיֵצֶר רַע לִשְׂמָאלָא. וְאִלֵּין אִינוּן תְּרֵין מַלְאָכִין מַמָּשׁ מְמַנָּן, וְאִינוּן מִשְׁתַּכְּחִין תָּדִיר בַּהֲדֵיהּ דְּבַר נָשׁ.","אָתֵי בַר נָשׁ לְאִתְדַּכָּאָה, הַהוּא יֵצֶר הָרָע אִתְכַּפְיָא קַמֵּיהּ וְשַׁלִּיט יְמִינָא עַל שְׂמָאלָא. וְתַרְוַויְיהוּ מִזְדַּוְּוגִין לְנַטְרָא לֵיהּ לְבַר נָשׁ בְּכָל אָרְחוֹי דְּהוּא עָבִיד. הֲדָא הוּא דִכְתִיב כִּי מַלְאָכָיו יְצַוֶּה לָךְ לִשְׁמָרְךָ בְּכָל דְּרָכֶיךָ."],[[0,"וישלח יעקב מלאכים וגו':","ר' יהודה פתח, כי מלאכיו יצוה לך לשמרך וגו', מקרא זה בארוהו החברים. כי בשעה שהאדם בא לעולם, מיד היצר הרע בא עמו, שהוא מקטרג עליו תמיד, כמו שאמר הכתוב, לפתח חטאת רובץ. מהו \u0003חטאת רובץ.\u0004 הוא היצר הרע. \u0003לפתח\u0004, פירושו לפתח בית הרחם, כלומר, תכף עם הולדו של האדם."],[1,"ודוד הכי נמי וכו':","ודוד קרא גם כן את היצר הרע בשם \u0003חטאת.\u0004 שכתוב \u0003וחטאתי\u0004 נגדי תמיד. והוא משום שבכל יום עושה את האדם להחטיא לפני רבונו. ויצה\"ר זה, אינו סר מן האדם מיום הולדו עד עולם. והיצר הטוב בא אל האדם, מיום שבא להטהר."],[2,"ואימתי אתי וכו':","ומתי האדם בא להטהר. הוא, בשעה שהוא בן י\"ג שנה, אז מתחבר האדם בשניהם, אחד בימין ואחד בשמאל, היצר הטוב בימין והיצר הרע בשמאל. ואלו הם שני מלאכים ממונים ממש, והם נמצאים עם האדם תמיד."],[3,"אתי בר נש וכו':","בא האדם להטהר, נכנע היצר הרע לפניו, והימין שולט על השמאל, ושניהם, היצר הטוב והיצר הרע, מתחברים לשמור את האדם בכל דרכיו שהוא הולך. וזהו שכתוב, כי מלאכיו יצוה לך לשמרך בכל דרכיך."]],[[0,"","וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (תהלים צא) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ לִשְׁמָרְךְ בְּכָל דְּרָכֶיךְ. פָּסוּק זֶה בֵּאֲרוּהוּ הַחֲבֵרִים, שֶׁהֲרֵי בְּשָׁעָה שֶׁאָדָם בָּא לָעוֹלָם, מִיָּד מִזְדַּמֵּן עִמּוֹ יֵצֶר הָרָע שֶׁהוּא מְקַטְרֵג לָאָדָם תָּמִיד, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ד) לַפֶּתַח חַטָּאת רֹבֵץ. מִי זֶה חַטָּאת רֹבֵץ? זֶה יֵצֶר הָרָע."],[1,"","וְכָךָ גַּם דָּוִד קָרָא לוֹ חַטָּאת, (תהלים נא) וְחַטָּאתִי נֶגְדִּי תָמִיד, מִשּׁוּם שֶׁהוּא עוֹשֶׂה כָּל יוֹם לָאָדָם לַחֲטֹא לִפְנֵי רִבּוֹנוֹ, וְיֵצֶר הָרָע הַזֶּה לֹא זָז מִבֶּן הָאָדָם מִיּוֹם שֶׁנּוֹלָד הָאָדָם לְעוֹלָמִים, וְיֵצֶר הַטּוֹב בָּא לָאָדָם מִיּוֹם שֶׁבָּא לְהִטָּהֵר."],[2,"","וּמָתַי בָּא אָדָם לְהִטָּהֵר? כְּשֶׁהוּא בֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנִים, אָז מִזְדַּוֵּג הָאָדָם בִּשְׁנֵיהֶם, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. יֵצֶר טוֹב לְיָמִין, וְיֵצֶר הָרָע לִשְׂמֹאל. וְאֵלֶּה הֵם שְׁנֵי מַלְאָכִים מַמָּשׁ מְמֻנִּים, וְהֵם נִמְצָאִים תָּמִיד עִם הָאָדָם."],[3,"","בָּא בֶּן אָדָם לְהִטַּהֵר - אוֹתוֹ יֵצֶר הָרָע נִכְפֶּה לְפָנָיו, וְשׁוֹלֵט הַיָּמִין עַל הַשְּׂמֹאל. וּשְׁנֵיהֶם מִזְדַּוְּגִים לִשְׁמֹר אֶת הָאָדָם בְּכָל דְּרָכָיו שֶׁהוּא עוֹשֶׂה. זֶהוּ שֶׁכָּתוּב כִּי מַלְאָכָיו יְצַוֶּה לָּךְ לִשְׁמָרְךְ בְּכָל דְּרָכֶיךְ."]]],[["רִבִּי אֶלְעָזָר מוֹקִים לֵיהּ לְהַאי קְרָא בְּיַעֲקֹב, דְּקוּדְשָׁא בְּרִיךְ הוּא אַזְמִין בַּהֲדֵיהּ מַלְאָכִין מַשִּׁרְיָין מְמַנָּן. בְּגִין דְהָא אִיהוּ אָתֵי שְׁלִים בְּשִׁבְטִין עִלָּאִין כֻּלְּהוּ שְׁלֵמִין כְּדְקָא יְאוּת, כְּמָה דְאִתְּמָר (דכתיב) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים וְאִתְּמָר. וְהָכָא כֵּיוָן דְּאִשְׁתְּזִיב מִנֵּיהּ דְּלָבָן וְהָא אִתְפְּרַשׁ מִנֵּיהּ כְּדֵין אִזְדַּוְּוגַת עִמֵּיהּ שְׁכִינְתָּא וְאֲתוּ מַשִּׁרְיָין קַדִּישִׁין לְסַחֲרָא לֵיהּ, וּכְדֵין וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם וְגו'. וּמֵאִינוּן מַלְאָכִין שַׁדַּר לֵיהּ לְעֵשָׂו הֲדָא הוּא דִכְתִיב וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים, מַלְאָכִים מַמָּשׁ הֲווּ וַדַּאי.","פָּתַח רִבִּי יִצְחָק וְאָמַר כְּתִיב, (תהילים ל״ה:ה׳) חוֹנֶה מַלְאַךְ יְיָ סָבִיב לִירֵאָיו וַיְחַלְּצֵם, הָא אוּקְמוּהָ. אֲבָל בְּאֲתַר חַד כְּתִיב כִּי מַלְאָכָיו יְצַוֶּה לָךְ, מַלְאָכָיו סַגִּיאִין, וְהָכָא חַד דִּכְתִיב חוֹנֶה מַלְאַךְ יְיָ סָבִיב לִירֵאָיו וַיְחַלְּצֵם. אֶלָּא כִּי מַלְאָכָיו יְצַוֶּה לָךְ, אִלֵּין שְׁאָר מַלְאָכִין. מַלְאַךְ יְיָ סָבִיב דָּא שְׁכִינְתָּא, כְּמָה דְאַתְּ אָמֵר, (שמות ג׳:ב׳) וַיֵּרָא מַלְאַךְ יְיָ אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. וּבְגִין כָּךְ חוֹנֶה מַלְאַךְ יְיָ סָבִיב לִירֵאָיו, לַאֲקָפָא לֵיהּ בְּכָל סִטְרִין בְּגִין לְשֵׁזָבָא לֵיהּ. וְכַד שְׁכִינְתָּא שַׁרְיָא בְּגַוֵּיהּ דְּבַר נָשׁ, כַּמָּה מַשִּׁרְיָין קַדִּישִׁין כֻּלְּהוּ אִזְדַּמְּנוּ לְתַמָּן.","תָּא חֲזֵי, כַּד דָּוִד מַלְכָּא אִשְׁתְּזִיב מֵאָכִישׁ מֶלֶךְ גַת כְּדֵין אָמַר הַאי, בְּגִין דִּשְׁכִינְתָּא סַחֲרָא לֵיהּ וְאִשְׁתְּזִיב מִנַּיְיהוּ מֵאָכִישׁ וּמֵעַמֵּיהּ כָּל אִינוּן דְּאַתְקִיפוּ (נ\"א דאקיפו) בֵּיהּ, מַה כְּתִיב, (שמואל א כ״א:י״ד) וַיִּתְהוֹלֵל בְּיָדָם, אַמַּאי וַיִּתְהוֹלֵל, וַיִּשְׁתַּגֵּעַ מִבָּעֵי לֵיהּ, כְּמָה דְאַתְּ אָמֵר, (שם) כִּי הֵבֵאתֶם אֶת זֶה לְהִשְׁתַּגֵּעַ עָלַי.","אֶלָּא אַהֲדַר עַל הַהוּא מִלָּה דְאֲמַר דָּוִד בְּקַדְמִיתָא דִּכְתִיב, (תהילים ע״ג:ג׳) כִּי קִנֵּאתִי בַּהוֹלְלִים וְגו'. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא חַיֶּיךָ עֲדַיִין אַנְתְּ אִצְטְרִיךְ לְהַאי, כֵּיוָן דְּעָאל לְבֵי אָכִישׁ וְאַתְקִיפוּ בֵּיהּ, מַה כְּתִיב וַיִּתְהוֹלֵל בְּיָדָם, כְּאִינוּן הוֹלְלִים דְּקַנֵּי בְּקַדְמִיתָא, וּכְדֵין אַתְיָא שְׁכִינְתָּא וְשַׁרְיָא סַחֲרָנֵיהּ דְּדָוִד.","וְאִי תֵימָא שְׁכִינְתָּא לָא שַׁרְיָא אֶלָּא (באחסנתה) בְּאַחְסַנְתֵּיהּ, דְּאִיהִי אַרְעָא קַדִּישָׁא. וַדַּאי לָא שַׁרְיָא בְּגִין (דינקין) לִינָקָא מִנָּהּ, אֲבָל לַאֲגָנָא שַׁרְיָא. וְהָכָא כַּד אֲתָא יַעֲקֹב מִבֵּי לָבָן כֻּלְּהוּ מַשִּׁרְיָין קַדִּישִׁין סַחֲרָן לֵיהּ וְלָא אִשְׁתָּאַר בִּלְחוֹדוֹי.","אָמַר רִבִּי חִזְקִיָה אִי הָכִי (ס\"א דכלהו משריין קדישין אתו בההה ושכינתא בהדיה), אַמַּאי כְּתִיב וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וְגו'. אָמַר רִבִּי יְהוּדָה בְּגִין דְּאָעִיל גַּרְמֵיהּ לְסַכָּנָה, וְהֲוָה חָמֵי לְהַהִיא סַכָּנָה בְּעֵינוֹי, אִינוּן אִתְפָּרְשׁוּ מִנֵּיהּ, וּכְדֵין אָמַר קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת, אִלֵּין אִינוּן מַשִּׁרְיָין קַדִּישִׁין דְּאִתְפָּרְשׁוּ מִנֵּיהּ.","רִבִּי יִצְחָק אָמַר בְּגִין לְשַׁבְקָא לֵיהּ עִם הַהוּא מְמַנָּא דְעֵשָׂו דְּבִרְשׁוּתָא עִלָּאָה הֲוָה אָתֵי. וְאִלֵּין אָזְלֵי לְמֵימַר שִׁירָתָא דְּמָטָא זִמְנַיְיהוּ לְשַׁבָּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּהַהִיא שַׁעְתָּא, וּלְבָתַר אַהֲדָרוּ, הֲדָא הוּא דִכְתִיב קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת אֲשֶׁר עָשִׂיתָ אֶת עַבְדֶּךָ וְגו', וְעַתָּה הָיִיתִי לִשְׁנֵי מַחֲנוֹת. מַחֲנֶה שְׁכִינְתָּא, וְכָל בֵּיתֵיהּ, (ס\"א מחנה חד הוה דכתיב מחנה אלהים זה), לִשְׁנִי מַחֲנוֹת, דְהֲוָה שְׁלִים מִכָל סִטְרִין מִתְּרֵין חוּלָקִין חִוַּור וְסוּמָק.","רִבִּי אֶלְעָזָר אָמַר, הָא אִתְּמָר, הַהוּא לֵילְיָא שׁוּלְטָנוּתָא דְסִטְרָא דְעֵשָׂו הֲוָה. בְּהַהִיא שַׁעְתָּא דְּהָא כְּתִיב (בראשית א׳:י״ד) יְהִי מְאֹרֹת חָסֵר, וּבְגִין כָּךְ וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, דְּאִשְׁתָּאַר יַעֲקֹב דְאִיהוּ שִׁמְשָׁא בִּלְחוֹדוֹי, דְּאִתְכַּסְיָא סִיהֲרָא מִן שִׁמְשָׁא. וְאַף עַל גַּב דִּנְטִירוּ (ס\"א ועם כל דא נטירו) דְּקוּדְשָׁא בְּרִיךְ הוּא לָא אִתְעֲדֵי מִנֵּיהּ מִכֹּל וָכֹל, וְעַל דָּא לא יָכוֹל לוֹ, דִּכְתִיב וַיַּרְא כִּי לא יָכוֹל לוֹ.","אִסְתַּכַּל לִימִינָא וְחָמָא לְאַבְרָהָם. אִסְתַּכַּל לִשְׂמָאלָא וְחָמָא לְיִצְחָק. אִסְתַּכַּל בְּגוּפָא וְחָמָא דְאִתְכְּלִיל מִסִּטְרָא דָא וְאִתְכְּלִיל מִסִּטְרָא דָא, כְּדֵין וַיִּגַע בְּכַף יְרֵכוֹ. בְּחַד עַמּוּדָא דְּסָמִיךְ לְגוּפָא דְּאִיהוּ לְבַר מִן גּוּפָא.","וּבְגִין כָּךְ חוֹנֶה מַלְאַךְ יְיָ סָבִיב לִירֵאָיו וַיְחַלְּצֵם, אַקִּיף לֵיהּ בְּכָל סִטְרוֹי בְּגִין לְשֵׁזָבָא לֵיהּ, וְכַד שָׁרָא שְׁכִינְתָּא בְּגַוֵּיהּ (ס\"א לגביה) כַּמָּה חֵילִין וּמַשִּׁרְיָין אָתוּ בַּהֲדֵיהּ, וּמֵאִינוּן מַלְאָכִין שַׁדַּר לְגַבֵּיהּ דְּעֵשָׂו:","וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים, אָמַר רִבִּי אַבָּא וְכִי אַמַּאי אִתְעַר אִיהוּ לְגַבֵּיהּ דְּעֵשָׂו, וְטַב הֲוָה לֵיהּ לְאִשְׁתּוּקֵי מִנֵּיהּ. אֶלָּא אָמַר יַעֲקֹב יְדַעְנָא דְּעֵשָׂו חַיִּישׁ לֵיהּ לִיקָרָא דְאַבָּא וּלְעָלַם לָא אַרְגִּיז קַמֵּיהּ, וְהָא יְדַעְנָא הוֹאִיל וְאַבָּא קַיָּים לָא מִסְתָּפִינָא מִנֵּיהּ, אֲבָל הַשְׁתָּא (הואיל דאבא קאים בעינא לאתפייס (לאתפייסא)) עִמֵּיהּ, מִיָּד וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים לְפָנָיו.","וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים. רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי י״ב:ט׳) טוֹב נִקְלָה וְעֶבֶד לוֹ מִמִּתְכַּבֵּד וַחֲסַר לֶחֶם, הַאי קְרָא עַל יֵצֶר הָרָע אִתְּמָר, בְּגִין דְּאִיהוּ מְקַטְרְגָא תָּדִיר לְגַבֵּי בְּנֵי נָשָׁא, וְיֵצֶר הָרָע אִיהוּ אָרִים לִבֵּיהּ וּרְעוּתֵיהּ דְּבַר נָשׁ בְּגַאֲוָתָא וְאָזִיל אֲבַתְרֵיהּ מְסַלְסֵל שַׂעֲרֵיהּ וּבְרֵישֵׁיהּ עַד דְּאִיהוּ אִתְגָּאֵי עֲלֵיהּ וּמָשִׁיךְ לֵיהּ לַגֵּיהִנֹּם."],[[0,"רבי אלעזר מוקים וכו':","ר\"א מעמיד את המקרא הזה ביעקב, שהקב\"ה הזמין עמו מלאכים מחנות ממונים, משום שהיה בא שלם עם השבטים העליונים, שהיו כולם שלמים כראוי, כמו שנאמר, ויעקב הלך לדרכו ויפגעו בו מלאכי אלקים, והוא נתבאר, וכאן, אחר שניצל מלבן, ונפרד ממנו, נתחברה עמו השכינה, ומחנות מלאכים קדושים באו לסבב אותו, ואז ויאמר יעקב כאשר ראם וגו', ומאלו המלאכים שלח לעשו, וזהו שכתוב, וישלח יעקב מלאכים, מלאכים ממש בודאי היו."],[1,"פתח ר' יצחק וכו':","פתח ר\"י ואמר, כתוב, חונה מלאך ה' סביב ליראיו ויחלצם, כבר בארוהו, אבל במקום אחד כתוב, כי מלאכיו יצוה לך, דהיינו הרבה מלאכים, וכאן רק אחד, שכתוב חונה מלאך וגו'. ומשיב אלא הכתוב, כי \u0003מלאכיו\u0004 יצוה לך, היינו מלאכים כרגיל, והכתוב \u0003מלאך\u0004 ה' סביב היינו השכינה, כמו שאתה אומר, וירא מלאך ה' אליו בלבת אש מתוך הסנה, שפירושו השכינה, אף מלאך שבכאן פירושו השכינה. וע\"כ חונה מלאך ה' סביב ליראיו, לסובב אותם מכל הצדדים, כדי להצילם. וכשהשכינה שורה בתוך האדם, כל הצבאות הקדושים מזדמנים שמה."],[2,"ת\"ח כד דוד וכו':","בוא וראה, בשעה שדוד המלך ניצל מאכיש מלך גת, אז אמר זה, היינו הכתוב חונה מלאך ה' וגו', משום שהשכינה הקיפה אותו וניצל מאכיש ומעמו ומכל אלו שהתקיפו אותו. מה כתוב ויתהולל בידם, ושואל, למה \u0003ויתהולל,\u0004 וישתגע היה צריך לומר, כמש\"א, כי הבאתם את זה להשתגע עלי."],[3,"אלא אהדר וכו':","ומשיב, אלא שהכתוב סובב על הדבר שאמר דוד בתחילה, שכתוב, כי קנאתי \u0003בהוללים\u0004 וגו', אמר לו הקב\"ה, חייך. עדיין תהיה צריך לזה, כיון שבא לבית אכיש, והתקיפו אותו, מה כתוב, \u0003ויתהולל בידם,\u0004 דהיינו, כאותם \u0003ההוללים\u0004 שקנא אותם תחילה, שאמר כי קנאתי בהוללים, ואז באה השכינה ושרתה מסביב לדוד."],[4,"ואי תימא שכינתא וכו':","ואם תאמר, הרי השכינה אינה שורה אלא בנחלתה, שהיא ארץ הקדושה ולמה שרתה השכינה עליו בגת שהיא חוץ לארץ. ומשיב, ודאי הוא שאינה שורה בחוץ לארץ שיוכלו לינק שפע ממנה, אבל להציל היא שורה גם בחוץ לארץ. וכאן כשבא יעקב מבית לבן, כל המחנות הקדושות סבבוהו, ולא נשאר לבדו."],[5,"א\"ר חזקיה אי הכי וכו':","אר\"ח, אם כן, למה כתוב ויותר יעקב לבדו וגו'. ואיפה היו כל מחנות המלאכים, שאתה אומר שסבבוהו ובאו עמו. אמר רבי יהודה, משום שהביא את עצמו לסכנה, שנשאר יחידי בלילה, והיה רואה בעין את הסכנה, ולפי שלא באו לשמרו אלא מסכנה שאינה נראית לעין, לכן נפרדו ממנו, ואז, מטרם שהכניס עצמו לסכנה, ואז אמר קטנתי מכל החסדים ומכל האמת אשר עשית עם עבדך, אשר אלו הם מחנות המלאכים הקדושים שסבבוהו, ועתה נפרדו ממנו. מטעם שהכניס עצמו לסכנה נראית לעין."],[6,"רבי יצחק אמר וכו':","לכן נפרדו ממנו המלאכים, כדי לעזב אותו לבדו עם אותו הממונה של עשו, שברשות העליון בא אליו, ואלו המלאכים הלכו לומר שירה, שבאותה שעה הגיע זמנם לומר שירה לפני הקב\"ה. פירוש מב' טעמים נפרדו ממנו המלאכים. א), כדי לעזבו עם המלאך לבדו ויאבק עמו. ב), שהגיע אז זמנם לומר שירה. ואחר כך חזרו אליו. וז\"ש קטנתי מכל החסדים וגו' ועתה הייתי לשני מחנות. מחנה שכינה וכל ביתו היו מחנה אחת, כמ\"ש מחנה אלקים זה. ולמה כתוב \u0003לשני מחנות,\u0004 הוא להורות שהיה שלם מכל הבחינות, מב' החלקים, שהם, לבן ואדום, שהם חסדים וחכמה, מימין ומשמאל, וע\"כ אומר לב' מחנות."],[7,"רבי אלעזר וכו':","רא\"א, למדנו, הלילה ההוא, היה שליטתו של צד עשו, דהיינו שמאל בלי ימין, באותה שעה, שכתוב, יהי מארת חסר ו' שהוא ליל רביעי, שלא יכול להאיר, מפאת היות מבלי חסדים, (כנ\"ל ב\"א דף ק\"ז ד\"ה לא אתיישב עש\"ה) ומשום זה, ויותר יעקב לבדו, שיעקב, שהוא השמש דהיינו ז\"א, נשאר לבדו בלי הנוקבא, כי הלבנה, שהיא הנוקבא, נתכסתה מן השמש, שהוא ז\"א הנקרא יעקב. ומה גם, ששמירתו של הקב\"ה לא הוסרה לגמרי מיעקב, כי על כן לא יכול לו, שכתוב וירא כי לא יכול לו."],[8,"אסתכל לימינא וכו':","ומפרש למה לא יכול לו, נסתכל המלאך לימין של יעקב, וראה את אברהם, שהוא השלמות של קו ימין, נסתכל לשמאלו של יעקב, וראה את יצחק, שהוא השלמות מקו שמאל, נסתכל בגוף של יעקב, וראה שנכלל מצד זה של ימין, ונכלל מצד זה של שמאל, שהוא השלמות של הקו האמצעי, ואין אחיזה לס\"א במקום השלמות אלא במקום החסרון, ע\"כ לא יכול לו. אז ויגע בכף ירכו, שהוא עמוד אחד הסמוך לגוף, שהוא לחוץ מן הגוף. שיש שם בחינת חסרון, וע\"כ נאחז בו המלאך, ותקע כף ירך יעקב. וכבר נתבאר זה, לעיל (ב\"א דף קל\"ג ד\"ה ויגע) ע\"ש."],[9,"ובג\"כ חונה וכו':","ובשביל זה אומר הכתוב, חונה מלאך ה' סביב ליראיו ויחלצם, הקיף אותו מכל צדדיו, כדי להצילו משרו של עשו, וכשהשכינה שרתה בתוכו, כמה צבאות ומחנות מלאכים באו עמו. ומאלו המלאכים שלח אל עשו."],[10,"וישלח יעקב מלאכים:","אמר רבי אבא, וכי למה נתעורר יעקב לשלוח מלאכים אל עשו, הלא מוטב היה לשתוק ממנו. ומשיב אלא אמר יעקב. יודע אני שעשו חרד על כבוד האב, ולא הרגיזו לעולם, ויודע אני, הואיל ואבי חי איני מפחד ממנו, לכן עתה, כל עוד שאבי חי, אני רוצה להתרצות עמו, מיד הזדרז, וישלח יעקב מלאכים לפניו."],[11,"וישלח יעקב מלאכים:","ר\"ש פתח ואמר. טוב נקלה ועבד לו ממתכבד וחסר לחם. מקרא זה על היצר הרע נאמר, משום שהוא מקטרג תמיד על בני אדם, והיצר הרע מגביה לבו ורצונו של אדם בגאוה, והאדם הולך אחריו מסלסל בשערו ובראשו, עד שיצר הרע מתגאה עליו ומושך אותו לגיהנם."]],[[0,"","רַבִּי אֶלְעָזָר מְבָאֵר אֶת הַפָּסוּק הַזֶּה בְּיַעֲקֹב, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִזְמִין עִמּוֹ מַלְאָכִים מַחֲנוֹת מְמֻנִּים, מִשּׁוּם שֶׁהֲרֵי הוּא בָּא שָׁלֵם בִּשְׁבָטִים עֶלְיוֹנִים כֻּלָּם שְׁלֵמִים כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים, וְנִתְבָּאֵר. וְכָאן, כֵּיוָן שֶׁנִּצּוֹל מִלָּבָן וַהֲרֵי נִפְרַד מִמֶּנּוּ, אָז הִזְדַּוְּגָה עִמּוֹ שְׁכִינָה, וּבָאוּ מַחֲנוֹת קְדוֹשִׁים לְהַקִּיף אוֹתוֹ, וְאָז וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם וְגוֹ', וּמֵאוֹתָם מַלְאָכִים שָׁלַח לְעֵשָׂו, זֶהוּ שֶׁכָּתוּב וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים. מַלְאָכִים מַמָּשׁ הָיוּ וַדַּאי."],[1,"","פָּתַח רַבִּי יִצְחָק וְאָמַר, כָּתוּב (תהלים לד) חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם. הֲרֵי פֵּרְשׁוּהָ. אֲבָל בְּמָקוֹם אֶחָד כָּתוּב כִּי מַלְאָכָיו יְצַוֶּה לָּךְ, מַלְאָכָיו רַבִּים, וְכָאן אֶחָד, שֶׁכָּתוּב חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם. אֶלָּא כִּי מַלְאָכָיו יְצַוֶּה לָּךְ - אֵלּוּ שְׁאָר מַלְאָכִים. מַלְאַךְ ה' סָבִיב - זוֹ שְׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר (שמות ג) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. וְלָכֵן חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו, לְהַקִּיפוֹ בְּכָל הַצְּדָדִים כְּדֵי לְהַצִּיל אוֹתוֹ, וּכְשֶׁהַשְּׁכִינָה שׁוֹרָה בְּתוֹךְ הָאָדָם, כַּמָּה מַחֲנוֹת קְדוֹשִׁים כֻּלָּם מִזְדַּמְּנִים לְשָׁם."],[2,"","בֹּא רְאֵה, כְּשֶׁדָּוִד הַמֶּלֶךְ נִצַּל מֵאָכִישׁ מֶלֶךְ גַּת, אָז אָמַר אֶת זֶה, מִשּׁוּם שֶׁהַשְּׁכִינָה הִקִּיפָה אוֹתוֹ וְנִצַּל מֵהֶם מֵאָכִישׁ וּמֵעַמּוֹ, כָּל אוֹתָם שֶׁהִתְקִיפוּ (שהקיפו) אוֹתוֹ. מַה כָּתוּב? (שמואל א כא) וַיִּתְהֹלֵל בְּיָדָם, לָמָּה וַיִּתְהֹלֵל? הָיָה צָרִיךְ לִכְתֹּב וַיִּשְׁתַּגַּע, כְּמוֹ שֶׁנֶּאֱמַר (שם) כִּי הֲבֵאתֶם אֶת זֶה לְהִשְׁתַּגֵּעַ עָלָי."],[3,"","אֶלָּא חָזַר עַל אוֹתוֹ דָּבָר שֶׁאָמַר דָּוִד בַּתְּחִלָּה, שֶׁכָּתוּב (תהלים עג) כִּי קִנֵּאתִי בַּהוֹלְלִים וְגוֹ'. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: חַיֶּיךְ עֲדַיִן אַתָּה צָרִיךְ אֶת זֶה. כֵּיוָן שֶׁנִּכְנַס לְבֵית אָכִישׁ וְהֶחֱזִיקוּ בוֹ, מַה כָּתוּב? וַיִּתְהֹלֵל בְּיָדָם, כְּאוֹתָם הוֹלְלִים שֶׁקִּנֵּא בָהֶם בַּהַתְחָלָה. וְאָז בָּאָה שְׁכִינָה וְשָׁרְתָה סְבִיב דָּוִד."],[4,"","וְאִם תֹּאמַר שֶׁהַשְּׁכִינָה לֹא שׁוֹרָה כִּי אִם בְּנַחֲלָתָהּ, שֶׁהִיא הָאָרֶץ הַקְּדוֹשָׁה - וַדַּאי לֹא שׁוֹרָה בַּעֲבוּר (שיונקים) לִינֹק מִמֶּנָּה, אֲבָל שׁוֹרָה כְּדֵי לְהָגֵן. וְכָאן כְּשֶׁבָּא יַעֲקֹב מִבֵּית לָבָן, כָּל הַמַּחֲנוֹת הַקְּדוֹשִׁים הִקִּיפוּ אוֹתוֹ, וְלֹא נִשְׁאַר לְבַדּוֹ."],[5,"","אָמַר רַבִּי חִזְקִיָּה, אִם כָּךְ (ס\"א שכל המחנות הקדושים באו יחד עמו והשכינה עמו), לָמָּה כָּתוּב וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וְגוֹ'? אָמַר רַבִּי יְהוּדָה, מִשּׁוּם שֶׁהִכְנִיס עַצְמוֹ לְסַכָּנָה וְהָיָה רוֹאֶה אוֹתָהּ סַכָּנָה בְּעֵינָיו, הֵם פָּרְשׁוּ מִמֶּנּוּ, וְאָז אָמַר, קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת, אֵלּוּ הֵם הַמַּחֲנוֹת הַקְּדוֹשִׁים שֶׁנִּפְרְדוּ מִמֶּנּוּ."],[6,"","רַבִּי יִצְחָק אָמַר, כְּדֵי לְהַשְׁאִירוֹ עִם אוֹתוֹ מְמֻנֶּה שֶׁל עֵשָׂו שֶׁהָיָה בָּא בִּרְשׁוּת עֶלְיוֹנָה, וְאֵלֶּה הָלְכוּ לוֹמַר שִׁירָה, שֶׁהִגִּיעַ זְמַנָּם לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ שָׁעָה, וְאַחַר כָּךְ חָזְרוּ. זֶהוּ שֶׁכָּתוּב קָ נְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת אֲשֶׁר עָשִׂיתָ אֶת עַבְדֶּךְ וְגוֹ', וְעַתָּה הָיִיתִי לִשְׁנֵי מַחֲנוֹת. מַחֲנֵה שְׁכִינָה, וְכָל בֵּיתוֹ. (ס\"א מחנה אחד היה, שכתוב מחנה אלהים זה). לִשְׁנֵי מַחֲנוֹת - שֶׁהָיָה שָׁלֵם מִכָּל הַצְּדָדִים מִשְּׁנֵי חֲלָקִים, לָבָן וְאָדם."],[7,"","רַבִּי אֶלְעָזָר אָמַר, הֲרֵי נִתְבָּאֵר אוֹתוֹ לַיְלָה שִׁלְטוֹן שֶׁל צַד שֶׁל עֵשָׂו הָיָה בְּאוֹתָהּ שָׁעָה, שֶׁהֲרֵי כָּתוּב (בראשית א) יְהִי מְאֹרֹת חָסֵר, וּמִשּׁוּם כָּךְ וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, שֶׁנִּשְׁאַר יַעֲקֹב, שֶׁהוּא שֶׁמֶשׁ לְבַדּוֹ, שֶׁהִתְכַּסְּתָה הַלְּבָנָה מִן הַשֶּׁמֶשׁ. וְאַף עַל גַּב שֶׁשְּׁמִירַת (ועם כל זה השמירה של) הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא זָזָה מִמֶּנּוּ מִכֹּל וָכֹל, וְעַל זֶה לֹא יָכֹל לוֹ, שֶׁכָּתוּב וַיַּרְא כִּי לֹא יָכֹל לוֹ."],[8,"","הִסְתַּכֵּל יָמִינָה וְרָאָה אֶת אַבְרָהָם, הִסְתַּכֵּל שְׂמֹאלָה וְרָאָה אֶת יִצְחָק, הִסְתַּכֵּל בַּגּוּף וְרָאָה שֶׁנִּכְלָל מִצַּד זֶה וְנִכְלָל מִצַּד זֶה, וְאָז וַיִּגַּע בְּכַף יְרֵכוֹ, בְּעַמּוּד אֶחָד הַסָּמוּךְ לַגּוּף, שֶׁהוּא מִחוּץ לַגּוּף."],[9,"","וְלָכֵן חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם, הִקִּיפוֹ בְּכָל צְדָדָיו כְּדֵי לְהַצִּילוֹ. וּכְשֶׁשָּׁרְתָה שְׁכִינָה בְּתוֹכוֹ (ס\"א אליו), כַּמָּה חֲיָלוֹת וּמַחֲנוֹת בָּאוּ עִמָּהּ, וּמֵאוֹתָם מַלְאָכִים שָׁלַח לְעֵשָׂו."],[10,"","וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים. אָמַר רַבִּי אַבָּא, וְכִי מַה הוּא הִתְעוֹרֵר אֶל עֵשָׂו? וְטוֹב הָיָה לוֹ לִשְׁתֹּק מִמֶּנּוּ. אֶלָּא, אָמַר יַעֲקֹב, יוֹדֵעַ אֲנִי שֶׁעֵשָׂו חוֹשֵׁשׁ לִכְבוֹד אַבָּא וּלְעוֹלָם לֹא הִרְגִּיז אוֹתוֹ, וַהֲרֵינִי יוֹדֵעַ, שׁהוֹאִיל וְאַבָּא קַיָּם, אֵינִי פּוֹחֵד מִמֶּנּוּ, אֲבָל עַכְשָׁו שֶׁאַבָּא קַיָּם, אֲנִי רוֹצֶה לְהִתְפַּיֵּס עִמּוֹ. מִיָּד - וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים לְפָנָיו."],[11,"","וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים, רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי יב) טוֹב נִקְלֶה וְעֶבֶד לוֹ מִמִּתְכַּבֵּד וַחֲסַר לָחֶם. פָּסוּק זֶה נֶאֱמַר עַל יֵצֶר הָרָע, מִשּׁוּם שֶׁהוּא תָמִיד מְקַטְרֵג לִבְנֵי אָדָם, וְיֵצֶר הָרָע מֵרִים לִבּוֹ וּרְצוֹנוֹ שֶׁל הָאָדָם בְּגַאֲוָה, וְהוֹלֵךְ אַחֲרָיו, מְסַלְסֵל בִּשְׂעָרוֹ וּבְרֹאשׁוֹ, עַד שֶׁמִּתְגָּאֶה עָלָיו וּמוֹשֵׁךְ אוֹתוֹ לַגֵּיהִנֹּם."]]],[["אֲבָל טוֹב נִקְלָה, הַהוּא דְּלָא אָזִיל אֲבַתְרֵיהּ דְּיֵצֶר הָרָע וְלָא אִתְגָּאֵי כְּלָל וּמָאִיךְ רוּחֵיהּ וְלִבֵּיהּ וּרְעוּתֵיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּכְדֵין הַהוּא יֵצֶר הָרָע מִתְהַפֵּךְ לְעֶבֶד לוֹ, דְּלָא יָכִיל לְשַׁלְטָאָה עֲלוֹי, וְהַהוּא בַּר נָשׁ שַׁלִּיט עֲלוֹי כְּמָה דְאַתְּ אָמֵר, (בראשית ד׳:ז׳) וְאַתָּה תִּמְשָׁל בּוֹ.","מִמִּתְכַּבֵּד, כְּמָה דְאֲמָרָן דְּאִיהוּ אוֹקִיר גַּרְמֵיהּ מְסַלְסֵל בְּשַׂעֲרֵיהּ אִתְגָּאֵי בְּרוּחֵיהּ, וְאִיהוּ חֲסַר לֶחֶם, חֲסַר מְהֵימְנוּתָא כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״א:י״ז) לֶחֶם אֱלֹהָיו וְגו' (ויקרא כ״א:ו׳) לֶחֶם אֱלֹהֵיהֶם הֵם מַקְרִיבִים וְגו'.","דָּבָר אַחֵר טוֹב נִקְלָה (ועבד לו), דָּא יַעֲקֹב דְּמָאִיךְ רוּחֵיהּ לְגַבֵּיהּ דְּעֵשָׂו. בְּגִין דִּלְבָתַר לֶיהֱוֵי עֶבֶד לוֹ וְיִשְׁלוֹט עֲלוֹי וְיִתְקַיַּים בֵּיהּ (בראשית כ״ז:כ״ט) יַעַבְדוּךָ עַמִּים וְיִשְׁתַּחֲווּ לְךָ לְאוּמִים וְגו', וַעֲדַיִן לָא הֲוָה זִמְנֵיהּ כְּלַל. אֶלָּא בְּגִין דְּסָלִיק לֵיהּ יַעֲקֹב לְבָתַר יוֹמַיָא, וְעַל דָּא הֲוָה מִיָּד נִקְלָה. וּלְבָתַר הַהוּא דְּאִיהוּ מִתְכַּבֵּד יְהֵא עֶבֶד לוֹ, הַהוּא דְּאִיהוּ חֲסַר לֶחֶם יְהֵא עַבְדָּא לְהַהוּא דְּיַהֲבוּ לֵיהּ רוֹב דָּגָן וְתִירוֹשׁ.","תָּא חֲזֵי, עַל דָּא בְּגִין דְּיָדַע יַעֲקֹב דְּאִצְטְרִיךְ לֵיהּ, הַשְׁתָּא אִתְהַפַּךְ לֵיהּ נִקְלָה. וְיוֹתֵר חָכְמָה וַעֲקִימוּ עֲבַד בְּדָא, מִכָּל מַה דְּעֲבַד לְגַבֵּי דְעֵשָׂו. דְּאִילוּ הֲוָה יָדַע עֵשָׂו חָכְמָה דָא יִקְטִיל לֵיהּ לְגַרְמֵיהּ וְלָא יֵיתֵי לְדָא, אֲבָל כֹּלָּא עֲבַד בְּחָכְמְתָא, וְעֲלֵיהּ אָמְרָה חַנָּה (שמואל א ב׳:י׳) יְיָ יֵחַתּוּ מְרִיבָיו וְגו' וְיִתֵּן עֹז לְמַלְכּוֹ וְגו':","וַיְצַו אֹתָם לֵאמֹר כֹּה תֹאמְרוּן לַאדֹנִי לְעֵשָׂו כֹּה אָמַר עַבְדְּךָ יַעֲקֹב עִם לָבָן גַּרְתִּי וָאֵחַר עַד עָתָּה. מִיָּד פָּתַח יַעֲקֹב לְאִתְהַפָּכָא לֵיהּ לְעַבְדָּא, בְּגִין דְּלָא יִסְתַּכַּל עֵשָׂו בְּאִינוּן בִּרְכָאן דְּבָרְכֵיהּ אֲבוֹי, דְּהָא יַעֲקֹב סָלִיק לוֹן לְבָתַר כְּדְקָא אֲמָרָן.","אָמַר רִבִּי יְהוּדָה מַאי חָמָא יַעֲקֹב דְּשַׁדַּר לֵיהּ לְעֵשָׂו וְאָמַר עִם לָבָן גַּרְתִּי, וְכִי מַה עָבִיד בִּשְׁלִיחוּתֵיהּ דְּעֵשָׂו (דאמר) מִלָּה דָא. אֶלָּא לָבָן הָאֲרַמִּי קָלֵיהּ אָזִיל בְּעַלְמָא דְלָא הֲוָה בַר נָשׁ דְּיִשְׁתְּזִיב מִנֵּיהּ, דְּהוּא הֲוָה חָרָשׁ בֶּחֳרָשִׁין וְרַב בְּקוֹסְמִין, וַאֲבוֹי דִבְעוֹר הֲוָה, וּבְעוֹר אֲבוֹי דְבִלְעָם, דִּכְתִיב (יהושע י״ג:כ״ב) בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם, וְלָבָן חָכָם בֶּחֳרָשִׁין וְקוֹסְמִין יַתִּיר מִכֻּלְּהוּ, וְעִם כָּל דָּא לָא יָכִיל בְּיַעֲקֹב. וּבָעָא לְאוֹבָדָא לְיַעֲקֹב בְּכַמָּה זַיְינִין הֲדָא הוּא דִכְתִיב, (דברים כ״ו:ה׳) אֲרַמִּי אוֹבֵד אָבִי.","אָמַר רִבִּי אַבָּא כּוּלֵי עַלְמָא הֲוֵי יָדְעֵי דְּלָבָן הֲוָה רַב חַכִּימִין וָחֳרָשִׁין וְקוֹסְמִין, וּמַאן דְּבָעֵי לְאוֹבָדָא בֶּחֳרָשׁוֹי לָא אִשְׁתְּזִיב מִנֵּיהּ, וְכָל מַה דְּיָדַע בִּלְעָם מִנֵּיהּ הֲוָה. וּכְתִיב בֵּיהּ בְּבִלְעָם (במדבר כ״ב:ו׳) כִּי יָדַעְתִּי אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ וַאֲשֶׁר תָּאֹר יוּאָר. וְכוּלֵי עַלְמָא הֲווּ מִסְתָּפֵי מִלָּבָן וּמֵחֳרָשׁוֹי, וּמִלָּה קַדְמָאָה דְּשַׁדַּר יַעֲקֹב לְעֵשָׂו אָמַר עִם לָבָן גַּרְתִּי. וְאִי תֵימָא דִּזְעֵיר הֲוָה יֶרַח אוֹ שַׁתָּא. לָאו הָכִי, אֶלָּא וָאֵחַר עַד עָתָּה, עֶשְׂרִין שְׁנִין אִתְאֲחָרִית עִמֵּיהּ.","וְאִי תֵימָא דְּלָא סָלִיק בְּיָדִי כְּלוּם. וַיְהִי לִי שׁוֹר וַחֲמוֹר, אִינוּן תְּרֵין גִּזְרֵי דִינִין, דְּכַד מִתְחַבְּרָן תַּרְוַויְיהוּ כְּחֲדָא, לָא מִתְחַבְּרָן אֶלָא לְאַבְאָשָׁא עַלְמָא. וּבְגִין כָּךְ כְּתִיב, (דברים כ״ב:י׳) לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּו.","צֹאן וְעֶבֶד וְשִׁפְחָה, אִלֵין אִינוּן כִּתְרֵי תַּתָּאֵי דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם (שמות י״ב:כ״ט) בְּכוֹר בְּהֵמָה (שמות י״ב:כ״ט) בְּכוֹר הַשְּׁבִי (שמות י״א:ה׳) בְּכוֹר הַשִּׁפְחָה, הֲדָא הוּא דִכְתִיב צֹאן וְעֶבֶד וְשִׁפְחָה. מִיָּד מִסְתָּפֵי הֲוָה עֵשָׂו וְנָפַק לָקֳדָמוּתֵיהּ, וּדְחִילוּ הֲוָה לֵיהּ מִיַּעֲקֹב כְּמָה דְּהֲוָה לֵיהּ לְיַעֲקֹב מֵעֵשָׂו.","לְבַר נָשׁ דְּהֲוָה אָזִיל בְּאָרְחָא, עַד דְּהֲוָה אָזִיל שָׁמַע עַל חַד לִסְטִים דְּהֲוָה כָּמַן בְּאָרְחָא, פָּגַע בֵּיהּ בַר נָשׁ אָחֳרָא. אָמַר לֵיהּ מִמָּאן אַנְתְּ, אָמַר לֵיהּ מִפְּלוֹנִי לִגְיוֹן אֲנָא, אָמַר לֵיהּ סְטֵי לָךְ מִגַּבָּאי דְּכָל מַאן דְּקָרִיב בַּהֲדָאי חַד חִוְיָא אֲנָא מַיְיתֵי וְקָטִיל לֵיהּ. אֲזַל הַהוּא בַר נָשׁ לְהַהוּא לִגְיוֹן, אָמַר לֵיהּ חַד בַר נָשׁ אָתֵי וְכָל מַאן דִּי קָרִיב בַּהֲדֵיהּ נָשְׁכֵיהּ חַד חִוְיָא דְּהוּא מַיְיתֵי וּמַיֵית."],[[0,"אבל טוב נקלה:","היינו מי שאינו הולך אחר היצר הרע, ואינו מתגאה כלל, ומשפיל רוחו ולבו ורצונו אל הקב\"ה, ואז היצר הרע מתהפך להיות עבד לו, שאינו יכול לשלוט עליו. ולהיפך, אותו האדם שולט עליו, כמו שאתה אומר, ואתה תמשול בו."],[1,"ממתכבד:","פירושו כמו שאמרנו, שהוא מכבד את עצמו, מסלסל בשערו, ומתגאה ברוחו, והוא \u0003חסר לחם,\u0004 שפירושו, חסר אמונה, כמש\"א \u0003לחם\u0004 אלקיו הוא מקריב וגו', \u0003לחם\u0004 אלקיהם הם מקריבים וגו', שלחם פירושו השכינה, אף כאן חסר \u0003לחם\u0004 פירושו חסר אמונה, שהיא השכינה."],[2,"דבר אחר טוב נקלה:","זה יעקב, שהשפיל את רוחו לפני עשו, כדי שלאחר כך יהיה עשו עבד לו, וישלוט עליו, ויתקיים בו יעבדוך עמים וישתחוו לך לאומים וגו'. ועתה עוד לא היה זמנו כלל שיעקב ישלוט עליו, ומשום שיעקב הניח אותו אל אחרית הימים על כן היה עתה נקלה. ולאחר כך, באחרית הימים, אותו שהיה \u0003מתכבד,\u0004 יהיה אז \u0003עבד לו,\u0004 אותו שיהיה אז \u0003חסר לחם,\u0004 דהיינו עשו, יהיה עבד לאותו שנתנו לו, רוב דגן ותירוש, דהיינו יעקב."],[3,"ת\"ח על דא בגין וכו':","בוא וראה, על כן, משום שידע יעקב, שהוא צריך לו עתה, הפך לפניו לנקלה, ויותר חכמה וערמה עשה בזה, מכל מה שעשה מעולם נגד עשו, ואלו הרגיש עשו בחכמה זו, היה הורג את עצמו שלא יבא לזה. אבל יעקב עשה את הכל בחכמה. ועליו אמרה חנה, ה' יחתו מריביו וגו', ויתן עוז למלכו."],[4,"ויצו אותם וגו' עבדך יעקב וגו':","מיד פתח יעקב, להתהפך לפניו לעבד, כדי שעשו לא יסתכל בברכות שברכו אביו. כי יעקב הניח אותם לאחרית הימים, כמו שאמרנו."],[5,"אמר ר' יהודה וכו':","אר\"י, מה ראה יעקב ששלח אל עשו ואמר עם לבן גרתי, וכי פעל דבר זה בשליחותו של עשו ומשיב, אלא לבן הארמי, קול הלך בעולם, שעוד לא היה אדם שינצל מידיו, כי הוא היה מכשף שבמכשפים וגדול הקוסמים, ואביו של בעור היה, ובעור היה אביו של בלעם, שכתוב בלעם בן בעור הקוסם. ולבן היה חכם בכשפים וקסמים יותר מהם. ועם כל זה, לא יכול ליעקב, והוא רצה לאבד את יעקב בכמה דרכים, כמו שכתוב, ארמי אובד אבי. וע\"כ שלח לו ואמר, עם לבן גרתי, להודיעו את כחו."],[6,"אמר רבי אבא וכו':","כל העולם היו יודעים, שלבן היה גדול החכמים והמכשפים והקוסמים, ומי שלבן רצה לאבד בכשפיו לא ניצל ממנו, וכל מה שידע בלעם מלבן היה, ובבלעם כתוב, כי ידעתי את אשר תברך מבורך וגו' וכל שכן לבן, וכל העולם היו יראים מלבן ומכשפיו. ולפיכך, מלה ראשונה ששלח יעקב לעשו, אמר, \u0003עם לבן גרתי,\u0004 ואם תאמר שזמן מועט היה, חודש או שנה. לא כן, אלא, \u0003ואחר עד עתה,\u0004 עשרים שנה התאחרתי עמו."],[7,"ואי תימא דלא סליק וכו':","ואם תאמר שלא עלה מזה בידי כלום, אמר לו, \u0003ויהי לי שור וחמור.\u0004 אלו הם שני גזרי דינים, דהיינו מזיקים, שבשעה ששניהם מתחברים יחד, אינם מתחברים אלא להרע לעולם, כלומר, שאין דרכם להזיק, זולת כשהם מתחברים. ומשום זה כתוב, לא תחרוש בשור ובחמור יחדיו. כי גורם במעשיו, שאלו שני המזיקים, שור וחמור, יתחברו יחד, ויזיקו לעולם."],[8,"צאן ועבד ושפחה,","אלו הם הכתרים התחתונים של הקליפות, שהרג הקב\"ה במצרים, הנקראים בכור בהמה, בכור השבי, בכור השפחה, וזהו שכתוב, צאן ועבד ושפחה. מיד היה מתירא עשו, ויצא לקראתו, והיה מתירא מיעקב, כמו שיעקב היה מתירא מעשו."],[9,"לב\"נ דהוה וכו':","בדומה לאדם שהיה הולך בדרך, ובעוד שהיה הולך, שמע על שודד אחד שהיה אורב בדרך. פגע בו אדם אחר, אמר לו משל מי אתה, אמר לו מגדוד צבא פלוני אני. אמר לו נטה ממני, כי כל הקרב אלי, נחש אחד אני מביא והורגו. הלך אותו האדם לשר הגדוד, ואמר לו, אדם אחד בא, וכל מי שקרב אליו, מביא עליו נחש אחד, שנושך אותו ומת."]],[[0,"","אֲבָל טוֹב נִקְלֶה - אוֹתוֹ שֶׁלֹּא הוֹלֵךְ אַחַר יֵצֶר הָרָע וְלֹא מִתְגָּאֶה כְּלָל וּמַנְמִיךְ רוּחוֹ וְלִבּוֹ וּרְצוֹנוֹ אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז אוֹתוֹ יֵצֶר הָרָע מִתְהַפֵּךְ לוֹ לְעֶבֶד, שֶׁלֹּא יָכוֹל לִשְׁלֹט עָלָיו, וְאוֹתוֹ אִישׁ שׁוֹלֵט עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ד) וְאַתָּה תִּמְשָׁל בּוֹ."],[1,"","מִמִּתְכַּבֵּד - כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהוּא מְכַבֵּד עַצְמוֹ, מְסַלְסֵל בִּשְׂעָרוֹ, מִתְגָּאֶה בְרוּחוֹ, וְהוּא חֲסַר לָחֶם - חֲסַר אֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כא) לֶחֶם אֱלֹהָיו וְגוֹ', (שם) לֶחֶם אֱלֹהֵיהֶם הֵם מַקְרִיבִם וְגוֹ'."],[2,"","דָּבָר אַחֵר טוֹב נִקְלֶה וְעֶבֶד לוֹ - זֶה יַעֲקֹב שֶׁהִנְמִיךְ רוּחוֹ לְעֵשָׂו כְּדֵי שֶׁאַחַר כָּךְ יִהְיֶה לוֹ עֶבֶד וְיִשְׁלֹט עָלָיו וְיִתְקַיֵּם בּוֹ (בראשית כז) יַעַבְדוּךְ עַמִּים וְיִשְׁתַּחֲוֻ לְךְ לְאֻמִּים וְגוֹ', וַעֲדַיִן לֹא הָיָה זְמַנּוֹ כְּלָל, אֶלָּא מִשּׁוּם שֶׁהֶעֱבִירוֹ יַעֲקֹב לְסוֹף הַיָּמִים. וְעַל זֶה הָיָה מִיָּד נִקְלֶה, וְאַחַר כָּךְ אוֹתוֹ שֶׁמִּתְכַּבֵּד יִהְיֶה עֶבֶד לוֹ. אוֹתוֹ שֶׁהוּא חֲסַר לָחֶם יִהְיֶה עֶבֶד לְאוֹתוֹ שֶׁנָּתְנוּ לוֹ רֹב דָּגָן וְתִירוֹשׁ."],[3,"","בֹּא רְאֵה, עַל זֶה, מִשּׁוּם שֶׁיָּדַע יַעֲקֹב שֶׁהִצְטָרֵךְ לוֹ, עַכְשָׁו הִתְהַפֵּךְ לוֹ לְנִקְלֶה, וְיוֹתֵר חָכְמָה וְעַקְמוּמִיּוּת עָשָׂה בָּזֶה מִכָּל מַה שֶּׁעָשָׂה לְעֵשָׂו. שֶׁאִלּוּ הָיָה יוֹדֵעַ עֵשָׂו חָכְמָה זוֹ, יַהֲרֹג אֶת עַצְמוֹ וְלֹא יָבא לִידֵי זֶה, אֲבָל הַכֹּל עָשָׂה בְּחָכְמָה, וְעָלָיו אָמְרָה חַנָּה (שמואל אב) ה' יֵחַתּוּ מְרִיבָו וְגוֹ' וְיִתֶּן עֹז לְמַלְכּוֹ וְגוֹ'."],[4,"","וַיְצַו אֹתָם לֵאמֹר כֹּה תֹאמְרוּן לַאדנִי לְעֵשָׂו כֹּה אָמַר עַבְדְּךְ יַעֲקֹב עִם לָבָן גַּרְתִּי וָאֵחַר עַד עָתָּה. מִיָּד פָּתַח יַעֲקֹב לְהִתְהַפֵּךְ לוֹ לְעֶבֶד כְּדֵי שֶׁלֹּא יִסְתַּכֵּל עֵשָׂו בְּאוֹתָן בְּרָכוֹת שֶׁבֵּרְכוֹ אָבִיו, שֶׁהֲרֵי יַעֲקֹב הֶעֱבִיר אוֹתָן לַסּוֹף, כְּפִי שֶׁאָמַרְנוּ."],[5,"","אָמַר רַבִּי יְהוּדָה, מָה רָאָה יַעֲקֹב שֶׁשָּׁלַח לְעֵשָׂו וְאָמַר עִם לָבָן גַּרְתִּי, וְכִי מֶה עָשָׂה בִּשְׁלִיחוּתוֹ שֶׁל עֵשָׂו (שאמר) דָּבָר זֶה? אֶלָּא לָבָן הָאֲרַמִּי, קוֹלוֹ הָלַךְ בָּעוֹלָם, שֶׁלֹּא הָיָה אָדָם שֶׁיִּנָּצֵל מִמֶּנּוּ, וְהוּא הָיָה מְכַשֵּׁף בִּכְשָׁפִים וְגָדוֹל בַּקּוֹסְמִים, וַאֲבִי בְּעוֹר הָיָה, וּבְעוֹר אֲבִי בִּלְעָם, שֶׁכָּתוּב (יהושע יג) בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם, וְלָבָן חָכָם בַּמְּכַשְּׁפִים וּבַקּוֹסְמִים יוֹתֵר מִכֻּלָּם, וְעִם כָּל זֶה לֹא יָכֹל לְיַעֲקֹב, וְרָצָה לְאַבֵּד אֶת יַעֲקֹב בְּכַמָּה כְּלֵי זַיִן. זֶהוּ שֶׁכָּתוּב (דברים כו) אֲרַמִּי אֹבֵד אָבִי."],[6,"","אָמַר רַבִּי אַבָּא, כָּל הָעוֹלָם הָיוּ יוֹדְעִים שֶׁלָּבָן הָיָה גְּדוֹל הַחֲכָמִים וְהַמְּכַשְּׁפִים וְהַקּוֹסְמִים, וּמִי שֶׁרָצָה לְאַבֵּד אוֹתוֹ בִּכְשָׁפָיו, לֹא נִצַּל מִמֶּנּוּ, וְכָל מַה שֶּׁיָּדַע בִּלְעָם - מִמֶּנּוּ הָיָה, וְכָתוּב בְּבִלְעָם (במדבר כב) כִּי יָדַעְתִּי אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ וַאֲשֶׁר תָּאֹר יוּאָר, וְכָל הָעוֹלָם הָיוּ פוֹחֲדִים מִלָּבָן וּמִכְּשָׁפָיו. וְדָבָר רִאשׁוֹן שֶׁשָּׁלַח יַעֲקֹב לְעֵשָׂו - אָמַר עִם לָבָן גַּרְתִּי. וְאִם תֹּאמַר שֶׁמְּעַט הָיָה, חֹדֶשׁ אוֹ שָׁנָה - לֹא כָּךְ, אֶלָּא וָאֵחַר עַד עָתָּה, עֶשְׂרִים שָׁנָה הִתְאַחַרְתִּי עִמּוֹ."],[7,"","וְאִם תֹּאמַר שֶׁלֹּא עָלָה בְיָדִי כְּלוּם - וַיְהִי לִי שׁוֹר וַחֲמוֹר. אוֹתָם שְׁנֵי גִּזְרֵי דִין, שֶׁכְּשֶׁשְּׁנֵיהֶם מִתְחַבְּרִים יַחַד, לֹא מִתְחַבְּרִים אֶלָּא לְהָרַע לָעוֹלָם, וְלָכֵן כָּתוּב (דברים כב) לֹא תַחֲר!שׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו."],[8,"","צֹאן וְעֶבֶד וְשִׁפְחָה - אֵלּוּ הֵם כְּתָרִים תַּחְתּוֹנִים שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, (שמות יב) בְּכוֹר בְּהֵמָה, (שם) בְּכוֹר הַשְּׁבִי, (שם יא) בְּכוֹר הַשִּׁפְחָה. זֶהוּ שֶׁכָּתוּב צֹאן וְעֶבֶד וְשִׁפְחָה. מִיָּד הָיָה עֵשָׂו פּוֹחֵד וְיָצָא כְּנֶגְדּוֹ, וּפַחַד הָיָה לוֹ מִיַּעֲקֹב כְּמוֹ שֶׁהָיָה לְיַעֲקֹב מֵעֵשָׂו."],[9,"","לְאִישׁ שֶׁהָיָה הוֹלֵךְ בַּדֶּרֶךְ. עַד שֶׁהָיָה הוֹלֵךְ, שָׁמַע עַל לִסְטִים אֶחָד שֶׁהָיָה אוֹרֵב בַּדֶּרֶךְ. פָּגַשׁ אוֹתוֹ אִישׁ אַחֵר, אָמַר לוֹ: מִמִּי אַתָּה? אָמַר לוֹ: אֲנִי מִלִּגְיוֹן פְּלוֹנִי. אָמַר לוֹ: סְטֵה לְךְ מִלְּפָנַי, שֶׁכָּל מִי שֶׁקָּרֵב אֵלַי, אֲנִי מֵבִיא נָחָשׁ אֶחָד שֶׁהוֹרֵג אוֹתוֹ. הָלַךְ אוֹתוֹ הָאִישׁ לְאוֹתוֹ הַלִּגְיוֹן. אָמַר לוֹ: אִישׁ אֶחָד בָּא, וְכָל מִי שֶׁקָּרֵב אֵלָיו, נוֹשֵׁךְ אוֹתוֹ נָחָשׁ אֶחָד שֶׁהוּא מֵבִיא, וּמֵת."]]],[["שָׁמַע הַהוּא לִגְיוֹן וְדָחִיל, אָמַר יָאוֹת דְּאֵזִיל לְקֳבְלֵיהּ וְאִתְפַּיֵיס בַּהֲדֵיהּ. עַד דְּחָמָא לֵיהּ הַהוּא בַר נָשׁ, אָמַר, וַוי דְּהַשְׁתָּא יִקְטְלֵינֵיהּ הַהוּא לִגְיוֹן. שָׁארֵי סָגִיד וְכָרַע לְקֳבְלֵיהּ. אָמַר הַהוּא לִגְיוֹן, אִלְמָלֵא הֲוָה לֵיהּ בִּידֵיהּ חִוְיָא לְקָטְלָא, לָא סְגִיד כּוּלַי הַאי לְקֳבְלִי. שָׁארֵי לִגְיוֹנָאָה לְאִתְגָּאָה, אָמַר, הוֹאִיל וְכָל כָּךְ כָּרַע לְקִבְלִי לָא אֶקְטְלִינֵיהּ.","כָּךָ אָמַר יַעֲקֹב עִם לָבָן גַּרְתִּי וָאֵחַר עַד עָתָּה, עֶשְׂרִין שְׁנִין אִתְאֲחָרִית עִמֵּיהּ וְאֲנָא מַיְיתֵי חִוְיָא לְקָטְלָא בְּנִי נָשָׁא. שְׁמַע עֵשָׂו, אָמַר, וַוי מַאן יָקוּם קַמֵּיהּ. דְּהַשְׁתָּא יִקְטְלִינֵיהּ יַעֲקֹב בְּפוּמֵיהּ, שָׁארֵי נָפִיק לָקֳדָמוּתֵיהּ לְאִתְפַּיְיסָא עִמֵּיהּ.","כֵּיוָן דְּחָמָא לֵיהּ מַה כְּתִיב וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ, כֵּיוָן דְּקָרִיב בַּהֲדֵיהּ שָׁארֵי כָּרַע וְסָגִיד לְקֳבְלֵיהּ. הֲדָא הוּא דִּכְתִיב וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו. אָמַר עֵשָׂו אִלְמָלֵא כָּל כָּךְ הֲוָה עִמֵּיהּ, לָא סְגִיד לְקִבְלִי, שָׁארֵי לְאִתְגָּאָה.","תָּא חֲזֵי, מַה כְּתִיב בְּבִלְעָם (במדבר כ״ב:כ׳) וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם לַיְלָה. בְּלָבָן כְּתִיב (בראשית ל״א:כ״ד) וַיָּבֹא אֱלהִים אֶל לָבָן הָאֲרַמִּי בַּחֲלוֹם הַלַּיְלָה וַיֹּאמֶר לוֹ הִשָּׁמֶר לְךָ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב וְגו'. פֶּן תְּדַבֵּר, פֶּן תַּעֲשֶׂה לְיַעֲקֹב רָעָה מִבָּעֵי לֵיהּ. אֶלָּא לָבָן לָא רָדַף אֲבַתְרֵיהּ דְּיַעֲקֹב בְּחֵילָא דְגוּבְרִין לַאֲגָחָא בֵּיהּ קְרָבָא. דְּהָא חֵילָא דְּיַעֲקֹב וּבְנוֹי רַב מִנֵּיהּ, אֶלָּא לְמִקְטְלֵיהּ בְּפוּמֵיהּ וּלְשֵׁיצָאָה כֹּלָּא. הֲדָא הוּא דִּכְתִיב אֲרַמִּי אוֹבֵד אָבִי. וּבְגִין כָּךְ פֶּן תְּדַבֵּר, וְלָא כְּתִיב פֶּן תַּעֲשֶׂה. וּכְתִיב יֵשׁ לְאֵל יָדִי לַעֲשׂוֹת. מִנַּיִן הֲוָה יָדַע דִּיְכֹלְתָּא הֲוָה בִּידֵיהּ. אֶלָּא כְּמָה דְאִתְּמָר אֱלֹהֵי אֲבִיכֶם אֱמֶשׁ אָמַר אֵלַי וְגו'.","וְדָא הוּא סַהֲדוּתָא, דְּפָּקִּיד קוּדְשָׁא בְּרִיךְ הוּא לְאַסְהָדָא. דִּכְתִיב (דברים כ״ו:ה׳) וְעָנִיתָ וְאָמַרְתָּ לִפְנֵי יְיָ אֱלֹהֶיךָ אֲרַמִּי אוֹבֵד אָבִי וְגו'. וְעָנִיתָ, כְּמָה דְאַתְּ אָמֵר, (שמות כ׳:י״ג) לֹא תַעֲנֶה בְרֵעֲךָ. (דברים י״ט:י״ח) עָנָה בְאָחִיו.","כְּתִיב בֵּיהּ בְּבִלְעָם (במדבר כ״ד:א׳) וְלא הָלַךְ כְפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים, דְּהָכִי הוּא אָרְחֵיהּ דְּאִיהוּ הֲוָה מְנַחֵשׁ. בְּלָבָן כְּתִיב, (בראשית ל) נִחַשְׁתִּי, דְּאַשְׁגַּח בַּחֲרָשׁוֹי וּבִקְסָמוֹי בְּעִסְקָא דְיַעֲקֹב, וְכַד בָּעָא לְאוֹבָדָא לְיַעֲקֹב בִּנְחָשָׁא וּבַחֲרָשָׁא דִּילֵיהּ בָּעָא לְאוֹבָדֵיהּ, וְלָא שַׁבְקֵיהּ קוּדְשָׁא בְּרִיךְ הוּא.","וְהַיְינוּ דְּאָמַר בִּלְעָם בַּר בְּרֵיהּ (במדבר כ״ג:כ״ג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל, מַאן יָכִיל לְהוֹן, דְּהָא סָבָאי בָּעָא לְאוֹבָדָא לַאֲבוּהוֹן בִּנְחָשִׁים וּבִקְסָמִים דִּילֵיהּ וְלָא סְלִיקָא בִּידוֹי. דְּלָא שַׁבְקֵיהּ לְלַטְיָא. הֲדָא הוּא דִכְתִיב כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל.","וּבְכֻלְּהוּ עֲשָׂרָה זִינֵי חֳרָשִׁין וְקוֹסְמִין דְּקוּזְטְפֵי דְּכִתְרִין תַּתָּאִין עֲבַד לָבָן לְקֳבְלֵיהּ דְּיַעֲקֹב וְלָא יָכִיל. הֲדָא הוּא דִכְתִיב, (בראשית ל״א:מ״א) וַתַּחְלֵף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מוֹנִים. דְּכֻלְּהוּ עֲבַד לָבָן לְקֳבְלֵיהּ וְלָא סְלִיקוּ בִּידוֹי לְאַבְאָשָׁא לֵיהּ, דִּכְתִיב, (בראשית ל״א:ז׳) וְהֶחלִיף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מוֹנִים וְלֹא נְתָנוֹ אֱלהִים לְהָרַע עִמָּדִי. מַאי מוֹנִים, כְּתַרְגּוּם זִינִין, וּכְתִיב (ויקרא י״ז:ז׳) לַשְּׂעִירִים אֲשֶׁר הֵם זוֹנִים אַחֲרֵיהֶם. מוֹנִים, מִינִים כְּמַשְׁמָעוֹ. וַעֲשָׂרָה זִינִין אִינוּן דְּחֲרָשִׁין וְקוֹסְמִין בְּכִתְרִין תַּתָּאִין וְכֻלְּהוּ עֲבַד לְקֳבְלֵיהּ.","עֲשָׂרָה זִינִין אִינוּן, דִּכְתִיב, (דברים י״ח:י׳-י״א) קוֹסֵם קְסָמִים מְעוֹנִן וּמְנַחֵשׁ וּמְכַשֵּׁף וְחוֹבֵר חָבֶר וְשׁוֹאֵל אוֹב וְיִדְעוֹנִי וְדוִֹרִשׁ אֶל הַמֵּתִים, הָא עֲשָׂרָה אִינוּן.","אָמַר רִבִּי יוֹסֵי נַחַשׁ וְקֶסֶם, תְּרֵי זִינֵי אִינוּן, וּבְדַרְגָּא חַד סָלְקִין. וְכַד אֲתָא בִּלְעָם בְּקֶסֶם עֲבַד לְקִבְלֵיהוֹן דְּיִשְׂרָאֵל. וְהַיְינוּ דִכְתִיב, (במדבר כ״ב:ז׳) וּקְסָמִים בְּיָדָם. וּלְקֳבְלֵיהּ דְּיַעֲקֹב אֲתָא לָבָן בְּנַחַשׁ, הַאי וְהַאי לָא סְלִיקוּ בִּידַיְיהוּ הֲדָא הוּא דִּכְתִיב, (שם כג) כִּי לא נַחַשׁ בְּיַעֲקֹב וְלא קֶסֶם בְּיִשְׂרָאֵל. כִּי לא נַחַשׁ בְּיַעֲקֹב בְּקַדְמִיתָא בְּיוֹמוֹי דְלָבָן. וְלא קֶסֶם בְּיִשְׂרָאֵל לְבָתַר בְּיוֹמוֹי דְבִלְעָם.","אָמַר בִּלְעָם לְבָלָק, תָּא חֲזֵי, מַאן יָכִיל לְהוֹן. דְּכָל קְסָמִין וַחֲרָשִׁין דִּבְכִתְרִין דִּילָן, מִקִּיזְפָא דְמַלְכוּתָא דִּלְעֵילָא (ותתא) מִתְעַטְּרָן (דהא), וְהוּא אִתְקַשַּׁר בְּהוּ, דִּכְתִיב יְיָ אֱלהָיו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ."],[[0,"שמע ההוא וכו':","שמע שר הגדוד, ופחד, אמר, מוטב לילך לקראתו ולהתרצות עמו. כיון שראה אותו האדם ההוא, פחד, אמר, ווי לי, השר יהרגני עתה. התחיל להשתחוות ולכרוע לפניו. אמר השר ההוא, אלמלי היה נחש בידו להרוג, לא היה כל כך משתחווה לפני. התחיל השר להתגאות, אמר, כיון שהוא כרע לפני כל כך, לא אהרגנו."],[1,"כך אמר וכו':","כך אמר יעקב \u0003עם לבן גרתי ואחר עד עתה,\u0004 עשרים שנה נתמהמהתי עמו, ואני מביא נחש להרוג בני אדם. שמע עשו, אמר ווי, מי יקום לפניו, כי עתה יהרגני יעקב בפיו. כי חשב, מכיון שניצח את לבן זקנו של בלעם, כחו ודאי גדול ככחו של בלעם, שנאמר עליו, אשר תברך מבורך ואשר תאר יואר, ויכול להרוג בפיו. התחיל לצאת לקראתו להתרצות עמו."],[2,"כיון דחמא ליה וכו':","כיון שראה אותו מה כתוב, ויירא יעקב מאד ויצר לו, כיון שקרב אליו, התחיל לכרוע ולהשתחוות לפניו, וזהו שכתוב, וישתחו ארצה שבע פעמים וגו', אמר עשו, אם היה לו כל כך כח, לא היה משתחוה לפני, התחיל להתגאות."],[3,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב בבלעם, ויבא אלקים אל בלעם לילה, בלבן כתיב, ויבא אלקים אל לבן הארמי בחלום הלילה, הרי שלבן היה גדול כמו בלעם. כמ\"ש לעיל. \u0003ויאמר לו השמר לך פן תדבר עם יעקב\u0004 וגו', שואל, כתוב, פן תדבר, פן תעשה ליעקב רעה, היה צריך לומר. ומשיב, אלא לבן לא רדף אחר יעקב בכח אנשים לעשות עמו מלחמה, כי כחם של יעקב ובניו היה גדול מהם, אלא רדף אחריו להרוג אותו בפיו ולכלות הכל, זהו שכתוב, ארמי אובד אבי, ומשום זה כתוב \u0003פן תדבר,\u0004 ולא כתוב פן תעשה. וכתוב יש לאל ידי לעשות, מאין ידע שהיכולת בידיו. אלא כמ\"ש, אלקי אביכם וגו'."],[4,"ודא הוא סהדותא וכו':","וזו היא העדות שצוה הקב\"ה להעיד, שכתוב וענית ואמרת וגו' ארמי אובד אבי. \u0003וענית\u0004 פירושו כמש\"א לא תענה ברעך. וכן ענה באחיו."],[5,"כתיב ביה בבלעם וכו':","כתוב בבלעם, ולא הלך כפעם בפעם לקראת \u0003נחשים,\u0004 כי כן הוא דרכו. כי היה \u0003מנחש.\u0004 וכן בלבן כתוב, \u0003נחשתי,\u0004 שהסתכל בכשפיו ובקסמיו, כדי לדעת את עסקיו של יעקב. וכשרצה להאביד את יעקב, בנחשים וכשפים שלו רצה להאבידו, ולא עזב אותו הקב\"ה, כי אמר לו \u0003פן תדבר\u0004 וגו' כנ\"ל."],[6,"והיינו דאמר בלעם וכו':","והיינו שאמר בלעם בן בנו של לבן. כי לא נחש ביעקב וגו' שאמר, מי יכול להם, כי זקני רצה להאביד את אביהם בנחשים ובקסמים שלו ולא עלה בידו, \u0003שהקב\"ה\u0004 לא הרשהו לקלל, וזהו שכתוב כי לא נחש ביעקב ולא קסם בישראל."],[7,"ובכלהו עשרה וכו':","ובכל עשרת מיני כשפים וקסמים מהארת הכתרים התחתונים, עשה לבן כנגד יעקב, ולא יכול לו, זהו שכתוב, ותחלף את משכורתי עשרת מונים וגו' כי כולם עשה לבן לנגדו, ולא עלה בידו להרע לו, שכתוב ותחליף את משכורתי עשרת מונים ולא נתנו אלקים להרע עמדי. ושואל, מה הם \u0003מונים\u0004, ומשיב, כתרגומו מינים. וכתוב לשעירים אשר הם זונים אחריהם. מונים. הם מינים כמשמעו, ועשרה מינים הם של כשפים וקסמים בכתרים התחתונים דקליפות, וכולם עשה לבן לנגדו."],[8,"עשרה זינין אינון וכו':","עשרה מינים הם, שכתוב, קוסם, קסמים, מעונן, ומנחש, ומכשף, וחובר חבר, ושואל אוב, וידעוני, ודורש אל המתים, הרי עשרה. ונראה שקסמים חושב לשני מינים להיותו לשון רבים."],[9,"אמר ר' יוסי וכו':","אר\"י נחש וקסם שני מינים הם, ובמדרגה אחת עולים, וכשבא בלעם כנגד ישראל עשה \u0003בקסם,\u0004 וזה שכתוב וקסמים בידם. וכנגד יעקב בא לבן \u0003בנחש\u0004, והן זה והן זה לא עלה בידיהם, וז\"ש, כי לא \u0003נחש\u0004 ביעקב ולא \u0003קסם\u0004 בישראל, \u0003כי לא נחש ביעקב,\u0004 היינו מתחילה בימי לבן, \u0003ולא קסם בישראל,\u0004 היינו לאחר כך בימי בלעם."],[10,"אמר בלעם וכו':","אמר בלעם לבלק, בוא וראה, מי יוכל להם, כי כל הקסמים והכשפים שבכתרים שלנו, מהארת המלכות של מעלה מתעטרים, והוא, דהיינו ז\"א, נתקשר בהם, בישראל, שכתוב, ה' אלקיו עמו ותרועת מלך בו. וע\"כ לא נוכל להם בכשפים שלנו."]],[[0,"","שָׁמַע אוֹתוֹ לִגְיוֹן וּפָחַד. אָמַר: יָפֶה שֶׁאֵלֵךְ עִמּוֹ וְאֶתְפַּיֵּס עִמּוֹ. עַד שֶׁרָאָה אוֹתוֹ אוֹתוֹ הָאִישׁ, אָמַר: אוֹי וַאֲבוֹי שֶׁעַכְשָׁו יַהֲרֹג אוֹתוֹ אוֹתוֹ הַלִּגְיוֹן. הִתְחִיל לְהִשְׁתַּחֲווֹת וְלִכְרֹעַ כְּנֶגְדּוֹ. אָמַר אוֹתוֹ לִגְיוֹן: אִלְמָלֵא הָיָה לוֹ בְּיָדוֹ נָחָשׁ לַהֲרֹג, לֹא הָיָה מִשְׁתַּחֲוֶה כָּל זֶה כְּנֶגְדִּי. הִתְחִיל הַלִּגְיוֹן לְהִתְגָּאוֹת. אָמַר: הוֹאִיל וְכָל כָּךְ כָּרַע לְנֶגְדִּי, לֹא אֶהֱרֹג אוֹתוֹ."],[1,"","כָּךָ אָמַר יַעֲקֹב, עִם לָבָן גַּרְתִּי וָאַחֵר עַד עָתָּה. עֶשְׂרִים שָׁנָה הִתְאַחַרְתִּי עִמּוֹ, וַאֲנִי מֵבִיא נָחָשׁ לַהֲרֹג בְּנֵי אָדָם. שָׁמַע עֵשָׂו, אָמַר, אוֹי מִי יָקוּם לְפָנָיו, שֶׁעַכְשָׁו יַהֲרֹג אוֹתוֹ יַעֲקֹב בְּפִיו. הִתְחִיל לָצֵאת כְּנֶגְדּוֹ לְהִתְפַּיֵּס עִמּוֹ."],[2,"","כֵּיוָן שֶׁרָאָה אוֹתוֹ מַה כָּתוּב? וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ. כֵּיוָן שֶׁקָּרַב אֵלָיו, הִתְחִיל לִכְרֹעַ וְלִסְגֹּד לְפָנָיו, זֶהוּ שֶׁכָּתוּב וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו. אָמַר עֵשָׂו, אִלְמָלֵא כָּל כָּךְ הָיָה עִמּוֹ, לֹא יִשְׁתַּחֲוֶה כְּנֶגְדִּי. הִתְחִיל לְהִתְגָּאוֹת."],[3,"","בֹּא רְאֵה מַה כָּתוּב בְּבִלְעָם, (במדבר כב) וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם לַיְלָה. בְּלָבָן כָּתוּב (בראשית לא) וַיָּבא אֱלֹהִים אֶל לָבָן הָאֲרַמִּי בַּחֲלוֹם הַלַּיְלָה וַיֹּאמֶר לוֹ הִשָּׁמֶר לְךְ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב וְגוֹ'. פֶּן תְּדַבֵּר? פֶּן תַּעֲשֶׂה לְיַעֲקֹב רָעָה צָרִיךְ לִכְתֹּב! אֶלָּא לָבָן לֹא רָדַף אַחֲרֵי יַעֲקֹב בְּכֹחַ גִּבּוֹרִים לַעֲרֹךְ בּוֹ קְרָב, שֶׁהֲרֵי חֵיל יַעֲקֹב וּבָנָיו גָּדוֹל מִמֶּנּוּ, אֶלָּא לְהָרְגוֹ בְּפִיו וּלְהַשְׁמִידוֹ אֶת הַכֹּל. זֶהוּ שֶׁכָּתוּב אֲרַמִּי אֹבֵד אָבִי. וְלָכֵן כָּתוּב פֶּן תְּדַבֵּר וְלֹא פֶּן תַּעֲשֶׂה. וְכָתוּב יֶשׁ לְאֵל יָדִי לַעֲשׂוֹת. מִנַּיִן הָיָה יוֹדֵעַ שֶׁיְּכֹלֶת הָיְתָה בְּיָדוֹ? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר אֱלֹהֵי אֲבִיכֶם אֶמֶשׁ אָמַר אֵלַי."],[4,"","וְזוֹהִי הָעֵדוּת שֶׁצִּוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָעִיד, שֶׁכָּתוּב (דברים כו) וְעָנִיתָ וְאָמַרְתָּ לִפְנֵי ה' אֱלֹהֶיךְ אֲרַמִּי אֹבֵד אָבִי וְגוֹ'. וְעָנִיתָ - כְּמוֹ שֶׁנֶּאֱמַר (שמות כ) לֹא תַעֲנֶה בְרֵעֲךְ, (דברים יט) עָנָה בְאָחִיו."],[5,"","כָּתוּב בְּבִלְעָם (במדבר כד) וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים, שֶׁכָּךְ הוּא דַּרְכּוֹ - שֶׁהוּא הָיָה מְנַחֵשׁ. בְּלָבָן כָּתוּב (בראשית ל) נִחַשְׁתִּי, שֶׁהִשְׁגִּיחַ בִּכְשָׁפָיו וּבִקְסָמָיו בָּעֵסֶק שֶׁל יַעֲקֹב, וּכְשֶׁרָצָה לְהַאֲבִיד אֶת יַעֲקֹב בַּנְּחָשִׁים וּבַכִּשּׁוּפִים שֶׁלּוֹ, רָצָה לְאַבְּדוֹ, וְלֹא עֲזָבוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא."],[6,"","וְהַיְנוּ שֶׁאָמַר בִּלְעָם בֶּן בְּנוֹ, כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. מִי יָכוֹל לָהֶם? שֶׁהֲרֵי סָבִי רָצָה לְאַבֵּד אֶת אֲבִיהֶם בַּנְּחָשִׁים וּבַקְּסָמִים שֶׁלּוֹ וְלֹא עָלָה בְיָדוֹ, שֶׁלֹּא הִשְׁאִירוֹ לְקַלֵּל. זֶהוּ שֶׁכָּתוּב כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל."],[7,"","וּבְכָל עֲשֶׂרֶת מִינֵי כְשָׁפִים וּקְסָמִים מֵהֶאָרַת הַכְּתָרִים הַתַּחְתּוֹנִים עָשָׂה לָבָן כְּנֶגֶד יַעֲקֹב, וְלֹא יָכֹל. זֶהוּ שֶׁכָּתוּב (בראשית לא) וַתַּחֲלֵף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מֹנִים. שֶׁכֻּלָּם עָשָׂה לָבָן כְּנֶגְדּוֹ וְלֹא עָלָה בְיָדוֹ לְהָרַע לוֹ, שֶׁכָּתוּב (שם) וְהֶחֱלִף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מֹנִים וְלֹא נְתָנוֹ אֱלֹהִים לְהָרַע עִמָּדִי. מַה זֶּה מֹנִים? כְּתַרְגּוּם מִינִים, וְכָתוּב (ויקרא יז) לַשְּׂעִירִם אֲשֶׁר הֵם זנִים אַחֲרֵיהֶם. מוֹנִים - מִינִים כְּמַשְׁמָעוֹ. וַעֲשָׂרָה מִינִים הֵם שֶׁל כְּשָׁפִים וּקְסָמִים בַּכְּתָרִים הַתַּחְתּוֹנִים, וְכֻלָּם עָשָׂה כְּנֶגְדּוֹ."],[8,"","עָשָׂרָה מִינִים הֵם, שֶׁכָּתוּב (דברים יח) קֹסֵם קְסָמִים מְעוֹנֵן וּמְנַחֵשׁ וּמְכַשֵּׂף וְחֹבֵר חָבֶר וְשֹׁאֵל אוֹב וְיִדְּעֹנִי וְדֹרֵשׁ אֶל הַמֵּתִים. הֲרֵי הֵם עֲשָׂרָה."],[9,"","אָמַר רַבִּי יוֹסֵי, נַחַשׁ וְקֶסֶם הֵם שְׁנֵי מִינִים, וּבְדַרְגָּה אַחַת עוֹלִים, וּכְשֶׁבָּא בִּלְעָם, בְּקֶסֶם עָשָׂה כְּנֶגֶד יִשְׂרָאֵל, וְהַיְנוּ שֶׁכָּתוּב (במדבר כב) וּקְסָמִים בְּיָדָם. וּכְנֶגֶד יַעֲקֹב בָּא לָבָן בְּנַחַשׁ. זֶה וָזֶה לֹא עָלָה בְיָדָם. זֶהוּ שֶׁכָּתוּב (שם כג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. כִּי לֹא נַחַשׁ בְּיַעֲקֹב - בַּתְּחִלָּה בִּימֵי לָבָן. וְלֹא קֶסֶם בְּיִשְׂרָאֵל - אַחַר כָּךְ בִּימֵי בִלְעָם."],[10,"","אָמַר בִּלְעָם לְבָלָק, בֹּא רְאֵה מִי יָכוֹל לָהֶם, שֶׁכָּל הַקְּסָמִים וְהַכְּשָׁפִים שֶׁבַּכְּתָרִים שֶׁלָּנוּ מֵהֶאָרַת הַמַּלְכוּת שֶׁלְּמַעְלָה (ומטה) מִתְעַטְּרִים, (שהרי) וְהוּא הִתְקַשֵּׁר בָּהֶם, שֶׁכָּתוּב ה' אֱלֹהָיו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ."]]],[["אָמַר רִבִּי יְהוּדָה חַס וְשָׁלוֹם דְהֲוָה יָדַע בִּלְעָם בִּקְדוּשָׁה דִלְעֵילָא כְּלָל. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא אִתְרָעֵי בְּעַם וְלִישָׁן אָחֳרָא דְּיִשְׁתַּמֵּשׁ בִּיקָרֵיהּ, אֶלָּא בְּנוֹי קַדִּישִׁין. וְאָמַר (ויקרא י״א:מ״ד) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים, מַאן דְּאִינוּן קַדִּישִׁין יִשְׁתַּמְשׁוּן בִּקְדוּשָּׁה, יִשְׂרָאֵל אִינוּן קַדִּישִׁין דִּכְתִיב, (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה. אַתָּה קָדוֹשׁ וְלָא עַם אָחֳרָא.","מַאן דְּאִינוּן מְסָאֲבִין, מְסָאֲבוּ אִזְדַּמַּן לוֹן לְאִסְתָּאֲבָא עֲלֵיהּ. כְּתִיב, (ויקרא י״ג:מ״ו) טָמֵא הוּא בָּדָד יֵשֵׁב מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ. וּמְסָאֲבָא לִמְסָאֲבָא קָרֵי דִּכְתִיב, (שם) וְטָמֵא טָמֵא יִקְרָא, מַאן דְּאִיהוּ טָמֵא, לְטָמֵא יִקְרָא, כֹּלָא אָזִיל בָּתַר זִינֵיהּ.","אָמַר רִבִּי יִצְחָק, יָאוֹת הוּא לְיַעֲקֹב דְּהֲוָה קַדִּישָׁא לוֹמַר דְּאִסְתָּאַב בְּלָבָן וּבַחֲרָשׁוֹי, אוֹ שְׁבָחָא הוּא דִילֵיהּ. אָמַר לֵיהּ רִבִּי יוֹסֵי, אַף עַל גַּב דְּקָאֲמַר רַבִּי יְהוּדָה, אֲנָא מְסַיֵּיעַ לָךְ. דְּהָא כְּתִיב, (בראשית כ״ז:י״ט) אָנֹכִי עֵשָׂו בְּכוֹרֶךָ. וְכִי יָאוֹת הוּא לְצַדִּיקָא כְּיַעֲקֹב לְמִחְלַף שְׁמֵיהּ בִּשְׁמָא דִּמְסָאֲבָא, אֶלָּא אָנֹכִי, פָּסְקָא טַעְמָא. וְאָמַר אָנֹכִי מַאן דְּאֲנָא, אֲבָל עֵשָׂו בְּכוֹרֶךָ וְהָא אוּקְמוּהָ.","אוּף הָכָא, וַיְהִי לִי שׁוֹר וַחֲמוֹר, לוֹמַר לָא תְשַׁוֵּי לִבָּךְ וּרְעוּתָךְ לְהַהִיא בִּרְכָתָא דְּבָרִיךְ לִי אַבָּא דְּאִתְקְיַּים בִּי. הוּא בָּרִיךְ לִי הֱוִה גְבִיר לְאַחֶיךָ וְיִשְׁתַּחֲווּ לְךָ בְּנֵי אִמֶּךָ, בְּגִין כָּךְ עַבְדְּךָ יַעֲקֹב. לַאדֹנִי לְעֵשָׂו. הוּא בָּרִיךְ לִי בְּרוֹב דָּגָן וְתִירוֹשׁ. הָא לָא אִתְקְיַּים בִּי, דְלָא אוֹצַרְנָא לוֹן. אֶלָּא, וַיְהִי לִי שׁוֹר וַחֲמוֹר צֹאן וְעֶבֶד, רָעֵי עָנָא בְּחַקְלָא. הוּא בָּרִיךְ לִי, מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ. הָא לָא אִתְקְיַּים בִּי, בְּגִין דְּהָא עִם לָבָן גַּרְתִּי, כְּגִיּוֹרָא. דְּלָא הֲוָה לִי בֵּיתָא חָדָא כָּל שֶׁכֵּן מִשְׁמַנֵּי הָאָרֶץ. וְכָל דָּא בְּגִין דְּלָא יִסְתַּכַּל בֵּיהּ בְּיַעֲקֹב עַל אִינוּן בִּרְכָאן וִיקַטְרֵג עִמֵּיהּ.","רִבִּי אַבָּא אָמַר כְּתִיב בֵּיהּ בְּיַעֲקֹב (בראשית כ״ה:כ״ז) אִישׁ תָּם יוֹשֵׁב אֹהָלִים, גְּבַר שְׁלִים. בְּגִין דְּאִיהוּ יְתִיב בִּתְרֵין מִשְׁכָּנִין עִלָּאִין. וְאַשְׁלִים לְהַאי גִיסָא וּלְהַאי גִיסָא, וְאִיהוּ לָא אָמַר דְּאִסְתָּאַב בַּחֲרָשׁוֹי. אֲבָל עַל מַה דְּקָאֲמַר רִבִּי יְהוּדָה, בְּגִין דְּלִבּוֹי שְׁלִים עַל טִיבוּ וּקְשׁוֹט דְּעֲבִיד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. דְּכָל עַלְמָא יָדְעֵי עוֹבָדוֹי דְלָבָן מַאן אִינוּן, וּמַאן יָכִיל לְאִשְׁתְּזָבָא (ס\"א מניה, כל עשרין שנין דהויתי עמיה) מִקִּטְרוּגָא דִילֵיהּ דְּבָעֵי לְאוֹבָדָא לִי. (ס\"א ואנא יתיבנא ועבדנא עמיה עשרין שנין) וְקוּדְשָׁא בְּרִיךְ הוּא שֵׁזְבַנִי מִנֵּיהּ. וְכֹלָּא הֲוָה בְּגִין דְּלָא יִסְתַּכַּל בֵּיהּ עֵשָׂו דְּאִתְקַיְּימוּ בֵּיהּ אִינוּן בִּרְכָאן, וְלָא יִנְטַר לֵיהּ דְּבָבוּ. וְעַל דָּא כְּתִיב, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְגו', וּכְתִיב, (דברים י״ח:י״ג) תָּמִים תִּהְיֶה עִם יְיָ אֱלֹהֶיךָ:","וַיָּשׁוּבוּ הַמַּלְאָכִים אֶל יַעֲקֹב לֵאמֹר בָּאנוּ אֶל אָחִיךָ אֶל עֵשָׂו וְגַם הוֹלֵךְ לִקְרָאתְךָ וְאַרְבַּע מֵאוֹת אִישׁ עִמּוֹ. כֵּיוָן דְּאָמַר בָּאנוּ אֶל אָחִיךָ, לָא יְדַעְנָא דְּאִיהוּ עֵשָׂו, וְכִי אַחִין אָחֳרָנִין הֲווּ לְיַעֲקֹב. אֶלָּא בָּאנוּ אֶל אָחִיךָ, וְאִי תֵימָא דְּהֲדַר בִּתְשׁוּבָה וְאָזִיל בְּאֹרַח מְתַקְּנָא, לָאו הָכִי, אֶלָּא עֵשָׂו הָרָשָׁע כִּדְמְעִיקָּרָא. וְגַם הוֹלֵךְ לִקְרָאתְךָ, וְאִי תֵימָא דְּאִיהוּ בִּלְחוֹדוֹי אָזִיל. לָאו, אֶלָא אַרְבַּע מֵאוֹת אִישׁ עִמּוֹ.","וְכָל כָּךְ לָמָּה, (אלא אינון) אָמְרוּ לֵיהּ, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי תָּדִיר בִּצְלוֹתְהוֹן דְּצַדִּיקַיָא וּמִתְעַטֵּר בִּצְלוֹתְהוֹן. כִּדְאַמְרִינָן, דְּהַהוּא מַלְאָכָא דִּמְמַנָּא עַל צְלוֹתְהוֹן דְּיִשְׂרָאֵל, סַנְדַּ\"לְפוֹן שְׁמֵיהּ, נָטִיל כָּל אִינוּן צְלוֹתִין וְעָבִיד מִנַּיְיהוּ עֲטָרָה לְחֲיֵי הָעוֹלָמִים וְאוּקְמוּהָ. וְכָל שֶׁכֵּן צְלוֹתְהוֹן דְּצַדִּיקַיָּא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ וְאִתְעַבְדָן עֲטָרָה לְאִתְעַטְּרָא בְּאִינוּן צְלוֹתִין לְקוּדְשָׁא בְּרִיךְ הוּא. וְאִי תֵימָא מַשִּׁרְיָין קַדִּישִׁין הֲווּ אַתְיָין עִמֵּיהּ, אַמַּאי דָּחִיל. אֶלָּא צַדִּיקַיָיא לָא סַמְכִין עַל זְכוּתַיְיהוּ, אֶלָּא עַל צְלוֹתְהוֹן וּבָעוּתְהוֹן לְגַבֵּי מָארֵיהוֹן.","וְתָּא חֲזֵי, דְּאָמַר רִבִּי שִׁמְעוֹן, צְלוֹתָא דְסַגִּיאִין סָלִיק קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וּמִתְעַטֵּר בְּהַהוּא צְלוֹתָא. בְּגִין דְּסַלְקָא בִּגְוָונִין סַגִּיאִין וְאִתְכְּלִילַת מִכַּמָּה סִטְרִין. וּבְגִין דְּאִתְכְּלִילַת מִכַּמָּה גְוָונִין אִתְעֲבִידַת עֲטָרָה וּמַנְחָא עַל רֵישָׁא דְצַדִּיק חַי הָעוֹלָמִים. וּצְלוֹתָא דְיָחִיד לָאו אִיהִי כְּלִילָא, וְלָאו אִיהִי אֶלָּא בְּגַוָּון חַד. וְעַל דָּא צְלוֹתָא דְיָחִיד לָאו אִיהוּ מִתְתַּקְנָא לְאִתְקַבְּלָא (אלא בצלותא) כִּצְלוֹתָא דְסַגִּיאִין. וְתָּא חֲזֵי, יַעֲקֹב כָּלִיל הֲוָה, וְעַל דָּא צְלוֹתֵיהּ תָּאִיב לָהּ קוּדְשָׁא בְּרִיךְ הוּא. מַה כְּתִיב וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ."],[[0,"א\"ר יהודה ח\"ו וכו':","אר\"י, חס ושלום, שבלעם היה יודע משהו בקדושה שלמעלה, וחולק על הנ\"ל שאמר שבלעם היה יודע שכשפיו נמשכים ממלכות דקדושה וכו'. כי הקב\"ה לא רצה בשום עם ולשון שישתמשו בכבודו אלא הבנים הקדושים שלו בלבדם. דהיינו ישראל שנקראים בנים לה', ואמר והתקדשתם והייתם קדושים, שפירושו, שאותם שהם קדושים ישתמשו בקדושה, ורק ישראל הם קדושים, שכתוב, כי עם קדוש אתה, אתה קדוש, ולא עם אחר."],[1,"מאן דאינון מסאבין וכו':","אותם שהם טמאים, טומאה נועדה להם להטמא, עליהם כתוב, טמא הוא בדד ישב מחוץ למחנה מושבו, דהיינו מחוץ לקדושה, והטמא קורא אל הטמא שכתוב, וטמא טמא יקרא. שפירושו, מי שהוא טמא קורא לטמא, כל דבר הולך אל מינו."],[2,"אמר ר' יצחק וכו':","אר\"י, לדברי ר' יהודה שאומר כל דבר הולך אל מינו, וכי נאה ליעקב, שהיה קדוש, שיאמר, שנטמא בלבן ובכשפיו, אפשר, שלשבח יחשב לו זה, כי אמר עם לבן גרתי. אמר לו רבי יוסי, אף על פי שאמר ר' יהודה כלא אזיל בתר זיניה, אני מתרץ לך הכתוב, שהרי כתוב, אנכי עשו בכורך, ויש לשאול. וכי נאה הוא לצדיק כיעקב שיחליף שמו בשם של טמא. אלא התירוץ הוא, \u0003באנכי\u0004 טעם מפסיק, כי תחת \u0003אנכי\u0004 כתוב פשטא, ותחת עשו בכורך כתוב זקף קטון, שנגונם מפריד את המלה אנכי, מן עשו בכורך, ופירושו, שאמר, \u0003אנכי,\u0004 מי שאני, אבל \u0003עשו בכורך\u0004, וכן בארוהו."],[3,"אוף הכי וכו':","אף כאן שכתוב, ויהי לי שור וחמור, היינו לאמור לו: אל תשים לבך ורצונך לברכה ההיא שברכני אבי, לחשוב שנתקיימה בי, הוא ברך אותי, הוה גביר לאחיך וישתחוו לך בני אמך, משום זה אומר לך, \u0003עבדך יעקב לאדני לעשו.\u0004 הוא ברך אותי, \u0003ברוב דגן ותירוש,\u0004 הרי לא נתקיים בי, כי לא אצרתי אותם, אלא, \u0003ויהי לי שור וחמור צאן ועבד,\u0004 רועה צאן בשדה. הוא ברך אותי \u0003מטל השמים ומשמני הארץ,\u0004 הרי לא נתקיים בי, \u0003רק עם לבן גרתי,\u0004 כגר, שלא היה לי שום בית, כל שכן \u0003משמני הארץ,\u0004 שלא נתקיימה בי, שלא היתה לי שום ארץ, רק עם לבן גרתי, וכל זה אמר, שלא יסתכל ביעקב לקנאותו, על הברכות, ויקטרג עליו. פירוש, שעל כן אמר \u0003לו עם לבן גרתי,\u0004 ולא מטעם שנשתבח בזה לפני עשו כמו שהקשה רבי יצחק, ואדרבה, שהזכירו לגנאי, כדי להוכיח לו שהיה גר, בלי ארץ ובלי בית. ומה שמביא ראיה מן אנכי עשו בכורך, הוא להוכיח לו, כי הכל הולך אחר הכונה, ואינו נחשב לו לעבירה, שקרא עצמו בשם של טמא, אף כאן, לא נתכוון אלא לבזיון. ואינו נחשב לו לעבירה, מה שנראה מהדברים שהיה מתפאר מחיבורו עם איש טמא. כמו שהקשה ר' יצחק."],[4,"רבי אבא אמר וכו':","רא\"א, כתוב בו ביעקב, איש תם יושב אהלים, ונקרא איש תם, משום שהוא יושב בשני משכנות עליונים שהם בינה ומלכות, שה\"ס אהל רחל ואהל לאה, והוא משלים לצד זה ולצד זה, דהיינו שמכריע בין הקוין ימין ושמאל ומשלימם. הוא לא יאמר שנטמא בכשפיו של לבן, היינו במה שאמר עם לבן גרתי, אבל על מה שאמר רבי יהודה, שכל מין הולך אחר מינו, כמו שהקשה ר' יצחק, התירוץ הוא, ע\"כ אמר עם לבן גרתי, להראות שלבו שלם בהודאה על החסד והאמת שעשה לו הקב\"ה, שכל העולם היו יודעים מעשיו של לבן מה הם, ומי יכול להנצל מקטרוגו, שרצה לאבדני, והקב\"ה הצילני מידו. ולכונה זו אמר, עם לבן גרתי, עוד, הכל היה כדי שלא יקנא בו עשו על הברכות, שלא יחשב שנתקיימו בו, ולא יהיה נוטר לו שנאה, דהיינו כמו שתירץ רבי יוסי. ועל זה כתוב, כי ישרים דרכי ה' וגו', וכתוב, תמים תהיה עם ה' אלקיך."],[5,"וישובו המלאכים וגו':","שואל, כיון שאמר \u0003באנו אל אחיך,\u0004 עוד אין אנו יודעים שהוא עשו, וכי היו אחים אחרים ליעקב, ומשיב, אלא \u0003באנו אל אחיך,\u0004 פירושו ואם תאמר שחזר בתשובה, והולך בדרך מתוקן, לא כן, אלא \u0003עשו\u0004 הרשע כמקודם לכן. \u0003וגם הולך לקראתך,\u0004 ואם תאמר, שהולך בלבדו, לא, אלא \u0003ארבע מאות איש עמו.\u0004"],[6,"וכל כך למה וכו':","ולמה אמרו לו כל זאת, משום שהקב\"ה רוצה תמיד בתפלת הצדיקים ומתעטר בתפלתם. וכמו שאמרנו, שאותו המלאך הממונה על תפלת ישראל סנדלפון שמו, הוא לוקח כל התפלות ועושה מהן עטרה לחי העולמים. ובארוה. ומכל שכן תפלותיהם של צדיקים, שהקב\"ה רוצה בהן, ונעשות עטרה, שיתעטר הקב\"ה באלו התפלות. ואם תאמר, הלא מחנות המלאכים הקדושים היו באים עמו, ולמה נתירא. אלא, הצדיקים אינם סומכים על זכותם, אלא על תפלות ובקשות אל רבונם."],[7,"ות\"ח דאמר ר\"ש וכו':","ובוא וראה, שאמר ר\"ש, תפלה של רבים, עולה לפני הקב\"ה, והקב\"ה מתעטר באותה התפלה. משום שהיא עולה בכמה אפנים, כי אחד שואל חסדים, והשני גבורות, והשלישי רחמים, ונכללת מכמה צדדים, דהיינו מצד ימין, ומצד שמאל ומאמצע, כי חסדים נמשכים מצד ימין,וגבורות מצד שמאל, ורחמים מהצד האמצעי. ומשום שנכללת מכמה אופנים, וצדדים, נעשית עטרה ומונחת על ראש צדיק חי העולמים, דהיינו יסוד, המשפיע כל הישועות אל הנוקבא, וממנה לכל הצבור, אבל תפלת יחיד אינה כלולה מכל הצדדים, והיא אינה אלא באפן אחד, או שמבקש חסדים או גבורות או רחמים, ועל כן תפלת יחיד אינה מתוקנת להתקבל כמו תפלת הרבים. כי אינה נכללת בכל ג' הקוים, כמו תפלת הרבים. ובוא וראה, יעקב היה כלול, מכל ג' הקוין, בהיותו מרכבה לקו האמצעי הכולל שניהם, ולפיכך חשק הקב\"ה בתפלתו, בהיותה בכל השלמות, מכל ג' הקוין, כמו תפלת הרבים. וע\"כ כתוב, ויירא יעקב מאד ויצר לו, כי הקב\"ה סבב לו את זה כדי שיתפלל, מטעם שחשק בתפלתו."]],[[0,"","אָמַר רַבִּי יְהוּדָה, חַס וְחָלִילָה שֶׁהָיָה יוֹדֵעַ בִּלְעָם בַּקְּדֻשָּׁה שֶׁלְּמַעְלָה כְּלָל, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הִתְרַצָּה בְעַם וְלָשׁוֹן אַחֵר שֶׁיִּשְׁתַּמֵּשׁ בִּכְבוֹדוֹ אֶלָּא בָּנָיו הַקְּדוֹשִׁים, וְאָמַר (ויקרא יא) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים. מִי שֶׁהֵם קְדוֹשִׁים יִשְׁתַּמְּשׁוּ בַּקְּדֻשָּׁה. יִשְׂרָאֵל הֵם קְדוֹשִׁים, שֶׁכָּתוּב (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה. אַתָּה קָדוֹשׁ וְלֹא עַם אַחֵר."],[1,"","מִי שֶׁהֵם טְמֵאִים, טֻמְאָה מִזְדַּמֶּנֶת לָהֶם לְהִטָּמֵא עָלָיו. כָּתוּב (ויקרא יג) טָמֵא הוּא בָּדָד יֵשֵׁב מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ, וְטָמֵא לְטָמֵא קוֹרֵא, שֶׁכָּתוּב (שם) וְטָמֵא טָמֵא יִקְרָא. מִי שֶׁהוּא טָמֵא לְטָמֵא יִקְרָא, הַכֹּל הוֹלֵךְ אַחַר מִינוֹ."],[2,"","אָמַר רַבִּי יִצְחָק, נָאֶה הוּא לְיַעֲקֹב, שֶׁהָיָה קָדוֹשׁ, לוֹמַר שֶׁנִּטְמָא בְּלָבָן וּבִכְשָׁפָיו, אוֹ שֶׁבַח הוּא שֶׁלּוֹ? אָמַר לוֹ רַבִּי יוֹסֵי, אַף עַל גַּב שֶׁאָמַר רַבִּי יְהוּדָה - אֲנִי מְסַיֵּעַ לְךְ, שֶׁהֲרֵי כָּתוּב (בראשית כז) אָנֹכִי עֵשָׂו בְּכֹרֶךְ. וְכִי יָפֶה הוּא לְצַדִּיק כְּיַעֲקֹב לְהַחֲלִיף שְׁמוֹ בְּשֵׁם טֻמְאָה? אֶלָּא אָנֹכִי, פּוֹסֵק טַעַם, וְאוֹמֵר אָנֹכִי מִי שֶׁאֲנִי, אֲבָל עֵשָׂו בְּכֹרֶךְ, וַהֲרֵי פֵּרְשׁוּהָ."],[3,"","אַף כָּאן. וַיְהִי לוֹ שׁוֹר וַחֲמֹר. לוֹמַר, אַל תָּשִׂים לִבְּךְ וּרְצוֹנְךְ לְאוֹתָהּ בְּרָכָה שֶׁבֵּרְכַנִי אַבָּא שֶׁהִתְקַיְּמָה בִּי. הוּא בֵּרַךְ אוֹתִי הֱוֵה גְבִיר לְאַחֶיךְ וְיִשְׁתַּחֲווּ לְךְ בְּנֵי אִמֶּךְ - מִשּׁוּם כָּךְ עַבְדְּךְ יַעֲקֹב לַאדנִי לְעֵשָׂו. הוּא בֵּרַךְ אוֹתִי בְּרֹב דָּגָן וְתִירוֹשׁ - הֲרֵי לֹא הִתְקַיֵּם בִּי, שֶׁלֹּא אָצַרְתִּי אוֹתָם, אֶלָּא וַיְהִי לִי שׁוֹר וַחֲמוֹר צֹאן וְעֶבֶד, רוֹעֵה צֹאן בַּשָּׂדֶה. הוּא בֵּרַךְ אוֹתִי מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ - הֲרֵי לֹא הִתְקַיֵּם בִּי, מִשּׁוּם שֶׁהֲרֵי עִם לָבָן גַּרְתִּי, כְּגֵר, שֶׁלֹּא הָיָה לִי בַּיִת אֶחָד, כָּל שֶׁכֵּן מִשְׁמַנֵּי הָאָרֶץ. וְכָל זֶה כְּדֵי שֶׁלֹּא יִסְתַּכֵּל בְּיַעֲקֹב עַל אוֹתָן בְּרָכוֹת וִיקַטְרֵג עִמּוֹ."],[4,"","רַבִּי אַבָּא אָמַר, כָּתוּב בְּיַעֲקֹב (שם כה) אִישׁ תָּם יֹשֵׁב אֹהָלִים, גֶּבֶר שָׁלֵם, מִשּׁוּם שֶׁהוּשׂ יוֹשֵׁב בִּשְׁנֵי מִשְׁכָּנִים עֶלְיוֹנִים, וְהִשְׁלִים לְצַד זֶה וּלְצַד זֶה. וְהוּא לֹא אָמַר שֶׁנִּטְמָא בִּכְשָׁפָיו. אֲבָל עַל מַה שֶׁאָמַר רַבִּי יְהוּדָה, מִשּׁוּם שֶׁלִּבּוֹ שָׁלֵם עַל טוֹב וֶאֱמֶת שֶׁעָשָׂה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל הָעוֹלָם יוֹדְעִים מַעֲשֵׂי לָבָן מַה הֵם וּמִי יָכוֹל לְהִנָּצֵל (ס\"א ממנו, כל עשרים השנים שהייתי עמו) מִקִּטְרוּגוֹ, וְרָצָה לְאַבֵּד אוֹתִי (ס\"א ואני ישבתי ועשיתי עמו עשרים שנה) וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִצִּילַנִי מִמֶּנּוּ. וְהַכֹּל הָיָה כְּדֵי שֶׁלֹּא יִסְתַּכֵּל בּוֹ עֵשָׂו שֶׁהִתְקַיְּמוּ בוֹ אוֹתָן בְּרָכוֹת וְלֹא יִשְׁמֹר לוֹ טִינָה. וְעַל זֶה כָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ', וְכָתוּב (דברים יח) תָּמִים תִּהְיֶה עִם ה' אֱ לֹהֶיךְ."],[5,"","וַיָּשֻׁבוּ הַמַּלְאָכִים אֶל יַעֲקֹב לֵאמֹר בָּאנוּ אֶל אָחִיךְ אֶל עֵשָׂו וְגַם הֹלֵךְ לִקְרָאתְךְ וְאַרְבַּע מֵאוֹת אִישׁ עִמּוֹ. כֵּיוָן שֶׁאָמַר בָּאנוּ אֶל אָחִיךְ, לֹא יָדַעְנוּ שֶׁהוּא עֵשָׂו? וְכִי אַחִים אֲחֵרִים הָיוּ לְיַעֲקֹב? אֶלָּא בָּאנוּ אֶל אָחִיךְ. וְאִם תֹּאמַר שֶׁחָזַר בִּתְשׁוּבָה וְהוֹלֵךְ בְּדֶרֶךְ תְּקִינָה - לֹא כָּךְ, אֶלָּא עֵשָׂו הָרָשָׁע כְּמוֹ מֵעִקָּרוֹ. וְגַם הֹלֵךְ לִקְרָאתְךְ. וְאִם תֹּאמַר שֶׁהוּא הוֹלֵךְ לְבַדּוֹ - לֹא, אֶלָּא אַרְבַּע מֵאוֹת אִישׁ עִמּוֹ."],[6,"","וְכָל כָּךְ לָמָּה? (אלא הם) אָמְרוּ לוֹ, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד מְרֻצֶּה בִּתְפִלּוֹת הַצַּדִּיקִים וּמִתְעַטֵּר בִּתְפִלּוֹתֵיהֶם, כְּמוֹ שֶׁאָמַרְנוּ שֶׁאוֹתוֹ הַמַּלְאָךְ הַמְמֻנֶּה עַל תְּפִלּוֹת יִשְׂרָאֵל, סַנְדַּלְפוֹ\"ן שְׁמוֹ, נוֹטֵל כָּל אוֹתָן תְּפִלּוֹת וְעוֹשֶׂה מֵהֶם עֲטָרָה לְחַי הָעוֹלָמִים וּבֵאֲרוּהָ, וְכָל שֶׁכֵּן תְּפִלּוֹת הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶן, וְנַעֲשׂוֹת עֲטָרָה לְהִתְעַטֵּר בְּאוֹתָן תְּפִלּוֹת לַקָּדוֹשׁ- בָּרוּךְ-הוּא. וְאִם תֹּאמַר, מַחֲנוֹת קְדוֹשִׁים הָיוּ בָאִים עִמּוֹ, אָז לָמָּה פָּחַד? אֶלָּא צַדִּיקִים לֹא סוֹמְכִים עַל זְכֻיּוֹתֵיהֶם, אֶלָּא עַל תְּפִלּוֹתֵיהֶם וּבַקָּשׁוֹתֵיהֶם לְרִבּוֹנָם."],[7,"","וּבֹא וּרְאֵה שֶׁאָמַר רַבִּי שִׁמְעוֹן, תְּפִלַּת רַבִּים עוֹלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִתְעַטֵּר בְּאוֹתָהּ תְּפִלָּה, מִשּׁוּם שֶׁעוֹלָה בִּגְוָנִים רַבִּים וְנִכְלֶלֶת מִכַּמָּה צְדָדִים, וּמִשּׁוּם שֶׁנִּכְלֶלֶת מִכַּמָּה גְוָנִים, נַעֲשֵׂית עֲטָרָה, וּמֻנַּחַת עַל רֹאשׁ צַדִּיק חַי הָעוֹלָמִים. וּתְפִלַּת הַיָּחִיד אֵינָהּ כְּלוּלָה וְאֵינָה אֶלָּא בְּגָוֶן אֶחָד, וְעַל כֵּן תְּפִלַּת יָחִיד אֵינָהּ מְתֻקֶּנֶת לְהִתְקַבֵּל (אלא בתפלה) כִּתְפִלַּת רַבִּים. וּבא וּרְאֵה, יַעֲקֹב הָיָה כָּלוּל, וְעַל כָּךְ תְּפִלָּתוֹ הִשְׁתּוֹקֵק לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה כָּתוּב? וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ."]]],[["רִבִּי יְהוּדָה פָּתַח וְאָמַר (משלי כ״ח:י״ד) אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד וּמַקְשֶׁה לִבּוֹ יִפּוֹל בְּרָעָה. זַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ, וְיָהַב לוֹן אוֹרַיְיתָא דִקְשׁוֹט בְּגִין לְמִזְכֵּי בָהּ לְחַיֵּי עַלְמָא, דְּכָל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא קוּדְשָׁא בְּרִיךְ הוּא מָשִׁיךְ עֲלֵיהּ חַיִּין עִלָּאִין, וְאָעִיל לֵיהּ לְחַיֵּי עַלְמָא דְאָתֵי, דִּכְתִיב, (דברים ל׳:כ׳) כִּי הִיא חַיֶּיךָ וְאֹרֶךְ יָמֶיךָ. וּכְתִיב, (שם לב) וּבַדָּבָר הַזֶּה תַּאֲרִיכוּ יָמִים. חַיִּין בְּהַאי עַלְמָא וְחַיִין בְּעַלְמָא דְאָתֵי.","רִבִּי אֶלְעָזָר אָמַר כָּל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ, לָאו מִיתָתֵיהּ עַל יְדָא דְיֵצֶר הָרָע, בְּגִין (גליון דהוא נחש והוא מלאכא דמותא. אלא מיתתהון בנשיקה דכתיב (שיר השירים א׳:ב׳) ישקני מנשיקות פיהו, כלומר על פי יי, והיא הנשיקה דהיא דביקותא דנפשא בעיקרא, וההיא דאשתדל באורייתא) דְּאִתְתַּקִּיף בְּאִילָנָא דְחַיֵּי וְלָא אַרְפֵּי מִנֵּיהּ, וּבְגִין כָּךְ צַדִּיקַיָא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא לָא מִסְתָּאֲבֵי גוּפָא דִלְהוֹן (גליון אלא הוא דכי, כגון אליהו בבי קברי דאשכחוהו רבנן, ושאילו ליה ולאו כהן הוא מר, אמר לון צדיקיא לא מסאבי במיתתהון, כמה דתנינן ביום שמת רבי בטלה כהונה, כלומר דאתעסקו ביה) דְּלָא שָׁרָא עֲלַיְיהוּ רוּחַ מְסָאֲבָא.","יַעֲקֹב אִילָנָא דְחַיֵּי הֲוָה, אַמַּאי דָּחִיל, דְּהָא לָא יָכוֹל לְשַׁלְטָאָה עֲלוֹי. וְעוֹד דְּהָא כְּתִיב וְהִנֵּה אָנֹכִי עִמָּךְ וְגו', אַמַּאי הֲוָה דָחִיל. וְתוּ דְּהָא כְּתִיב וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלהִים. אִי מַשִּׁרְיָין קַדִּישִׁין הֲווּ עִמֵּיהּ אַמַּאי הֲוָה דָחִיל.","אֶלָּא כֹּלָּא יָאוֹת הֲוָה, וְיַעֲקֹב לָא הֲוָה בָּעֵי לְמִסְמַךְ עַל נִיסָּא דְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּחָשִׁיב דְּלָאו אִיהוּ כְּדַאי דְּקוּדְשָׁא בְּרִיךְ הוּא יַעֲבִיד לֵיהּ נִיסָּא. מַאי טַעְמָא, בְּגִין דְּלָא פָלַח לְאֲבוֹי וּלְאִמֵּיהּ כְּדְקָא יְאוּת, וְלָא אִשְׁתַּדַּל בְּאוֹרַיְיתָא וְנָטַל תְּרֵי אֲחָיוֹת. וְאַף עַל גַּב דְּכֹלָּא אִתְּמָר, וְעִם כָּל דָא בָּעֵי לֵיהּ לְבַר נָשׁ לְמִדְחַל תָּדִיר וּלְצַלָּאָה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בִּצְלוֹתָא. דִּכְתִיב אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד (ולמדחל תדיר קמי קודשא בריך הוא) וְהָא אוּקְמוּהָ.","תָּא חֲזֵי, צְלוֹתָא דְּאֲבָהָן קָיְימוּ עָלְמָא, וְכָל בְּנֵי עָלְמָא עֲלַיְיהוּ קָיְימֵי וְסָמְכִין. לְעָלַם וּלְעָלְמֵי עָלְמִין, לָא אִתְנְשֵׁי זְכוּתָא דְּאֲבָהָן, בְּגִין דִּזְכוּתָא דְּאֲבָהָן אִיהוּ קִיּוּמָא דְעֵילָא וְתַתָּא, וְקִיּוּמָא דְיַעֲקֹב אִיהוּ קִיּוּמָא שְׁלִים יַתִּיר מִכֻּלְּהוּ. וּבְגִין כָּךְ בְּשַׁעְתָּא דְעָאקוּ לִבְנוֹי דְיַעֲקֹב, קוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי קַמֵּיהּ דִּיוּקְנָא דְיַעֲקֹב וְחָיִיס עַל עַלְמָא כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. יַעֲקוֹ\"ב בְּוא\"ו, אַמַּאי בְּוא\"ו, בְּגִין דְּאִיהוּ דִיוּקְנָא דְיַעֲקֹב מַמָּשׁ.","תָּא חֲזֵי, כָּל מַאן דְּחָמֵי לֵיהּ לְיַעֲקֹב כְּמַאן דְּאִסְתַּכֵּל בְּאַסְפַּקְלַרְיָא דְּנַהֲרָא, וְהָא אִתְּמָר דְּשׁוּפְרֵיהּ דְּיַעֲקֹב כְּשׁוּפְרֵיהּ דְּאָדָם קַדְמָאָה. אָמַר רִבִּי יֵיסָא, אֲנָא שְׁמַעְנָא דְּכָל מַאן דְּאִסְתַּכַּל בְּחֶלְמֵיהּ וְחָמָא לֵיהּ לְיַעֲקֹב מְקֻסְטָר בְּקוּסְפוֹי, חַיִּין אִתּוֹסְפָן לֵיהּ.","רִבִּי שִׁמְעוֹן אָמַר, הָא אִתְּמָר דְּדָוִד מַלְכָּא עַד לָא הֲוָה, לָא הֲווּ לֵיהּ חַיִּים כְּלַל. בַּר דְּאָדָם קַדְמָאָה יָהַב לֵיהּ שִׁבְעִין שְׁנִין מִדִּילֵיהּ, וְכָךְ הֲוָה קִיּוּמֵיהּ דְּדָוִד מַלְכָּא שִׁבְעִין שְׁנִין הֲווּ. וְקִיּוּמָא דְאָדָם קַדְמָאָה אֶלֶף שְׁנִין חֲסַר שִׁבְעִין. אִשְׁתַּכָּחוּ בְּהַנֵּי אֶלֶף שְׁנִין קַדְמָאֵי, אָדָם הָרִאשׁוֹן וְדָוִד מַלְכָּא.","פָּתַח וְאָמַר (תהילים כ״א:ה׳) חַיִּים שָׁאַל מִמְךָ נָתַתָּה לוֹ אֹרֶךְ יָמִים עוֹלָם וָעֶד. חַיִּים שָׁאַל מִמְךָ, דָּא דָּוִד מַלְכָּא. דְהָא כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא גִּנְתָא דְעֵדֶן אַטִּיל בֵּיהּ נִשְׁמָתָא דְדָוִד מַלְכָּא, וְאִסְתַּכַּל בֵּיהּ וְחָמֵי דְּלֵית לֵיהּ חַיִּים מִדִּילֵיהּ כְּלוּם. וְקָיְימָא קַמֵּיהּ כָּל יוֹמָא. כֵּיוָן דְּבָרָא אָדָם הָרִאשׁוֹן אָמַר הָא וַדַּאי קִיּוּמֵיהּ, וּמֵאָדָם קַדְמָאָה הֲווּ שִׁבְעִין שְׁנִין דְּאִתְקְיַּים דָּוִד מַלְכָּא בְּעַלְמָא.","תוּ אֲבָהָן שָׁבְקוּ לֵיהּ מֵחַיֵּיהוֹן כָּל חַד וְחַד, אַבְרָהָם שָׁבַק לֵיהּ, וְכֵן יַעֲקֹב וְיוֹסֵף. יִצְחָק לָא שָׁבַק לֵיהּ כְּלוּם, בְּגִין דְּדָוִד מַלְכָּא מִסִּטְרֵיהּ קָא אֲתָא.","וַדַּאי אַבְרָהָם שָׁבַק לֵיהּ חָמֵשׁ שְׁנִין, דְּהֲוָה לֵיהּ לְאִתְקַיְּימָא מֵאָה וּתְמָנִין שְׁנִין, וְאִתְקְיַּים מֵאָה וְשִׁבְעִין וְחָמֵשׁ שְׁנִין, חֲסֵרִין חָמֵשׁ. יַעֲקֹב הֲוָה לֵיהּ לְאִתְקָיְימָא בְּעַלְמָא כְּיוֹמֵי דְאַבְרָהָם, וְלָא אִתְקְיַּים אֶלָּא מֵאָה וְאַרְבָּעִין וְשֶׁבַע שְׁנִין, חֲסֵרִים תְּמַנְיָא וְעֶשְׂרִין. אִשְׁתַּכָּחוּ דְּאַבְרָהָם וְיַעֲקֹב שְׁבָקוּ לֵיהּ מֵחַיֵּיהוֹן תְּלָתִין וּתְלַת שְׁנִין. יוֹסֵף דְּאִתְקְיַּים מְאָה וְעֶשֶׂר שְׁנִין, הֲוָה לֵיהּ לְאִתְקַיָּימָא מְאָה וְאַרְבָּעִין וְשֶׁבַע שְׁנִין כְּיוֹמֵי דְיַעֲקֹב, וְחָסֵר מִנְּהוֹן תְּלָתִין וְשֶׁבַע שְׁנִין. הָא שִׁבְעִין שְׁנִין דִּשְׁבָקוּ לֵיהּ לְדָוִד מַלְכָּא לְאִתְקָיְימָא בְּהוֹן, וּבְהוּ אִתְקַיַים דָּוִד בְּכָל אִינוּן שְׁנִין דִּשְׁבָקוּ לֵיהּ אֲבָהָן."],[[0,"רבי יהודה וכו':","ר\"י פתח ואמר, אשרי אדם מפחד תמיד ומקשה לבו יפול ברעה. אשריהם ישראל, שהקב\"ה רצה בהם, ונתן להם תורת אמת, כדי לזכות בה לחיי עולם. כי כל מי שעוסק בתורה, הקב\"ה מושך עליו חיים עליונים, ומביאו לחיי העולם הבא, שכתוב, כי הוא חייך ואורך ימיך, וכתוב ובדבר הזה תאריכו ימים, כי היא חיים בעולם הזה, חיים בעולם הבא."],[1,"רבי אלעזר אמר וכו':","רא\"א, כל מי שעוסק בתורה לשמה, אין מיתתו על יד יצר הרע, שהוא מלאך המות כנ\"ל משום שנאחז בעץ החיים ולא הרפה ממנו. ומשום זה, צדיקים העוסקים בתורה אין גופם טמא, לאחר מיתתם, כי אין רוח הטומאה שורה עליהם."],[2,"יעקב אילנא דחיי וכו':","שואל יעקב שהיה עץ החיים, למה פחד, מפני עשו, הרי הס\"א, אינו יכול לשלוט עליו. ועוד, הרי כתוב, שהקב\"ה אמר לו, והנה אנכי עמך, למה היה מתירא. ועוד, הרי כתוב ויפגעו בו מלאכי אלקים, אם מחנות המלאכים הקדושים היו עמו למה פחד."],[3,"אלא כלא יאות וכו':","ומשיב, אלא הכל אמת הוא, שלא היה צריך לפחוד, אלא יעקב לא היה רוצה לסמוך על הנס של הקב\"ה, שחשב, שאינו כדאי, שהקב\"ה יעשה לו נס, מהו הטעם, הוא, משום שלא עבד את אביו ואמו כראוי, ולא עסק בתורה, דהיינו בכ\"ב השנים שהיה עם לבן, ולקח שתי אחיות, ואע\"פ שהכל נתישב, שיעקב לא חטא כלל בזה, עם כל זה, צריך האדם לפחד תמיד, ולבקש בתפלה לפני הקב\"ה, שכתוב, אשרי אדם מפחד תמיד. וכבר בארוהו."],[4,"תא חזי צלותא וכו':","בוא וראה, תפלת האבות קיימה את העולם, וכל באי העולם, עליהם מתקיימים וסומכים על זכותם, לעולם ולעולמי עולמים לא נשכחת זכות אבות, משום שזכות אבות היא קיום של מעלה ושל מטה, וקיומם של יעקב, שלם יותר מכולם, ומשום זה כשבאה עת צרה לבניו של יעקב, הקב\"ה רואה את צורתו של יעקב לפניו, ומרחם על העולם. כמש\"א, וזכרתי את בריתי יעקוב, שכתוב יעקוב עם \u0003ו',\u0004 ולמה כתוב עם \u0003ו'\u0004 משום שה \u0003ו'\u0004 היא צורתו של יעקב ממש. פירוש. כי יעקב הוא מרכבה לז\"א שה\"ס ה \u0003ו'\u0004 של השם הוי\"ה. וע\"כ צורתו של יעקב היא \u0003ו'.\u0004"],[5,"תא חזי כל מאן וכו':","בוא וראה, כל מי שראה את יעקב, הוא ומי שהסתכל באספקלריאה דנהרא, שהיא ז\"א. ולמדנו, שיפיו של יעקב הוא כיפיו של אדם הראשון. אמר ר' ייסא אני שמעתי, שכל מי שהסתכל בחלומו וראה את יעקב מעוטף בלבושיו, חיים נתוספו לו."],[6,"ר\"ש אמר וכו':","רש\"א, למדנו, שדוד המלך מטרם שבא לעולם, לא היו לו חיים כלל, מלבד שאדם הראשון נתן לו משלו ע' שנים. וכך היו חייו של דוד המלך ע' שנים. וחייו של אדם הראשון, היו אלף שנים חסר ע'. ונמצאים אדם הראשון ודוד, באלף השנים הראשונות של בריאת העולם."],[7,"פתח ואמר וכו':","פתח ואמר, חיים שאל ממך נתת לו אורך ימים עולם ועד, \u0003חיים שאל ממך,\u0004 זהו דוד המלך. כי כשברא הקב\"ה את גן העדן, והטיל בו הנשמה של דוד המלך, הסתכל בה וראה שאין לה חיים משלה כלום, וכך עמדה לפניו כל היום. כיון שברא את אדם הראשון, אמר, זהו ודאי חייו של דוד, ומאדם הראשון היו אלו ע' שנים שדוד המלך חי בעולם."],[8,"תו, אבהן וכו':","עוד פירוש. האבות הניחו לו מחייהם כל אחד ואחד. אברהם הניח לו מחייו, וכן יעקב ויוסף. יצחק לא הניח לו כלום, משום שדוד המלך בא מצדו, פירוש. כי דוד המלך ה\"ס הנוקבא מצד שמאל, שאז היא חושך ולא אור כמ\"ש להלן, וע\"כ לא היו לו חיים, כי אין חיים אלא מצד ימין, שה\"ס ז\"א הנקרא עץ החיים. וגם יצחק היה מצד שמאל, אלא שנכלל באברהם בסו\"ה, אברהם הוליד את יצחק, וכן בכח העקדה, וע\"כ היו לו חיים. וכל זה רק לעצמו, אבל ליתן חיים לדוד, לא היה יכול, מטעם שעקרו מקו שמאל היה, ולא היו לו חיים מצד עצמו אלא מכח התכללות. וז\"ש, \u0003בגין דדוד מלכא מסטריה קא אתא,\u0004 כלומר שגם יצחק מקו שמאל כמו דוד, וע\"כ לא היה יכול ליתן לו חיים משלו."],[9,"ודאי אברהם וכו':","ודאי שאברהם הניח לו חמש שנים, כי היה לו לחיות מאה ושמונים שנה, כמו יצחק, והוא חי רק מאה ושבעים וחמש שנים, וה' שנים חסרות. יעקב היה לו לחיות בעולם כימי אברהם, שהם קע\"ה שנים, ולא חי אלא קמ\"ז שנים, חסרות לו כ\"ח שנים. נמצא שאברהם ויעקב הניחו לו מחייהם ל\"ג שנים. יוסף, חי מאה ועשר שנים, היה לו לחיות קמ\"ז שנה, כימי יעקב, חסרות ל\"ז שנים, ועם ל\"ג של אברהם ויעקב, הם שבעים שנה, שהניחו לדוד המלך להתקיים בהם. ודוד חי בכל אלו השנים שהניחו לו האבות."]],[[0,"","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (משלי כח) אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד וּמַקְשֶׁה לִבּוֹ יִפּוֹל בְּרָעָה. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם וְנָתַן לָהֶם תּוֹרַת אֱמֶת כְּדֵי לִזְכּוֹת בָּהּ לְחַיֵּי עוֹלָם, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ עָלָיו חַיִּים עֶלְיוֹנִים וּמַכְנִיסוֹ לְחַיֵּי הָעוֹלָם הַבָּא, שֶׁכָּתוּב (דברים ל) כִּי הִיא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ, וְכָתוּב (שם לב) וּבַדָּבָר הַזֶּה תַּאֲרִיכוּ יָמִים. חַיִּים בָּעוֹלָם הַזֶּה, וְחַיִּים בָּעוֹלָם הַבָּא."],[1,"","רַבִּי אֶלְעָזָר אָמַר, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אֵין מִיתָתוֹ עַל יְדֵי יֵצֶר הָרָע, מִשּׁוּם (שהוא נחש, והוא מלאך המות, אלא מיתתם בנשיקה, שכתוב (שיר א) ישקני מנשיקות פיהו, כלומר על פי ה', והיא הנשיקה שהיא דבקות של הנפש בעקר, ואותו שמשתדל בתורה) שֶׁהִתְחַזֵּק בְּעֵץ הַחַיִּים וְלֹא הִרְפָּה מִמֶּנּוּ, וְלָכֵן צַדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה לֹא נִטְמָא גוּפָם (אלא הוא טהור, כמו אליהו בבית הקברות שמצאו אותו רבנן ושאלו אותו, ולא כהן הוא מר? אמר להם, צדיקים לא טמאים במיתתם, כמו ששנינו, ביום שמת רבי בטלה כהנה, כלומר שהתעסקו בו) שֶׁלֹּא שָׁרְתָה עֲלֵיהֶם רוּחַ טֻמְאָה."],[2,"","יַעָקֹב הָיָה עֵץ הַחַיִּים, לָמָּה פָּחַד, שֶׁהֲרֵי לֹא יָכוֹל לִשְׁלֹט עָלָיו? וְעוֹד, שֶׁהֲרֵי כָּתוּב וְהִנֵּה אָנֹכִי עִמָּךְ וְגוֹ', לָמָּה הָיָה פּוֹחֵד? וְעוֹד, שֶׁהֲרֵי כָּתוּב וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים, אִם מַחֲנוֹת קְדוֹשִׁים הָיוּ עִמּוֹ, לָמָּה הָיָה פּוֹחֵד?"],[3,"","אֶלָּא הַכֹּל הָיָה נָאֶה, וְיַעֲקֹב לֹא הָיָה רוֹצֶה לִסְמֹךְ עַל נֵס שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁחָשַׁב שֶׁאֵינוֹ כְּדַאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲשֶׂה לוֹ נֵס, מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא עָבַד אֶת אָבִיו וְאִמּוֹ כָּרָאוּי וְלֹא הִשְׁתַּדֵּל בַּתּוֹרָה וְנָשָׂא שְׁתֵּי אֲחָיוֹת, וְאַף עַל גַּב שֶׁהַכֹּל נִתְבָּאֵר. וְעִם כָּל זֶה צָרִיךְ לָאָדָם לִפְחֹד תָּמִיד וּלְהִתְפַּלֵּל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְפִלָּה, שֶׁכָּתוּב אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד (ולפחד תמיד מלפני הקדוש ברוך הוא), וַהֲרֵי פֵּרְשׁוּהָ."],[4,"","בֹּא רְאֵה, תְּפִלַּת הָאָבוֹת הֶעֱמִידוּ עוֹלָם, וְכָל בְּנֵי הָעוֹלָם עֲלֵיהֶם עוֹמְדִים וּסְמוּכִים, וּלְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים לֹא נִשְׁכַּחַת זְכוּת הָאָבוֹת, מִשּׁוּם שֶׁזְּכוּת הָאָבוֹת הִיא קִיּוּם שֶׁל מַעְלָה וּמַטָּה, וְקִיּוּם שֶׁל יַעֲקֹב הוּא קִיּוּם שָׁלֵם יוֹתֵר מִכֻּלָּם. וְלָכֵן בְּשָׁעָה שֶׁצָּרָה לִבְנֵי יַעֲקֹב, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אֶת דְּמוּת יַעֲקֹב וְחָס עַל הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. יַעֲקוֹ\"ב בְּוָא\"ו, לָמָּה בְּוָא\"ו? מִשּׁוּם שֶׁהוּא דְּמוּת שֶׁל יַעֲקֹב מַמָּשׁ."],[5,"","בֹּא רְאֵה, כָּל מִי שֶׁרוֹאֶה אֶת יַעֲקֹב, כְּמִי שֶׁמִּסְתַּכֵּל בְּאַסְפַּקְלַרְיָה הַמְּאִירָה (תפארת), וַהֲרֵי נֶאֱמַר שֶׁיָּפְיוֹ שֶׁל יַעֲקֹב כְּיָפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן. אָמַר רַבִּי יֵיסָא, אֲנִי שָׁמַעְתִּי, שֶׁכָּל מִי שֶׁמִּסְתַּכֵּל בַּחֲלוֹמוֹ וְרוֹאֶה אֶת יַעֲקֹב מְעֻטָּף בְּמַלְבּוּשָׁיו, מִתּוֹסְפִים לוֹ חַיִּים."],[6,"","רַבִּי שִׁמְעוֹן אָמַר, הֲרֵי נֶאֱמַר שֶׁדָּוִד הַמֶּלֶךְ, עַד שֶׁלֹּא הָיָה, לֹא הָיוּ לוֹ חַיִּים כְּלָל, פְּרָט לְזֶה שֶׁאָדָם הָרִאשׁוֹן נָתַן לוֹ שִׁבְעִים שָׁנָה מִשֶּׁלּוֹ, וְכָךְ הָיָה קִיּוּמוֹ שֶׁל דָּוִד הַמֶּלֶךְ שִׁבְעִים שָׁנָה הָיוּ, וְקִיּוּם שֶׁל אָדָם הָרִאשׁוֹן אֶלֶף שָׁנָה חָסֵר שִׁבְעִים. נִמְצְאוּ בְּאֵלֶּה אֶלֶף שָׁנִים רִאשׁוֹנוֹת אָדָם הָרִאשׁוֹן וְדָוִד הַמֶּלֶךְ."],[7,"","פָּתַח וְאָמַר, (תהלים כא) חַיִּים שָׁאַל מִמְּךְ נָתַתָּה לּוֹ אֹרֶךְ יָמִים עוֹלָם וָעֶד. חַיִּים שָׁאַל מִמְּךְ - זֶה דָּוִד הַמֶּלֶךְ. שֶׁהֲרֵי כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא גַּן עֵדֶן, הִטִּיל בּוֹ נִשְׁמַת דָּוִד הַמֶּלֶךְ, וְהִסְתַּכֵּל בּוֹ וּרְאֵה שֶׁאֵין לוֹ חַיִּים מִשֶּׁלּוֹ כְּלוּם וְעוֹמֵד לְפָנָיו כָּל הַיּוֹם. כֵּיוָן שֶׁנִּבְרָא אָדָם הָרִאשׁוֹן, אָמַר, הֲרֵי וַדַּאי קִיּוּמוֹ. וּמֵאָדָם הָרִאשׁוֹן הָיוּ שִׁבְעִים שָׁנים שֶׁהִתְקַיֵּם דָּוִד הַמֶּלֶךְ בָּעוֹלָם."],[8,"","עוֹד הָאָבוֹת הִשְׁאִירוּ לוֹ מֵחַיֵּיהֶם כָּל אֶחָד וְאֶחָד. אַבְרָהָם הִשְׁאִיר לוֹ, וְכָךְ יַעֲקֹב וְיוֹסֵף. יִצְחָק לוֹ הִשְׁאִיר לוֹ כְּלוּם, מִשּׁוּם שֶׁדָּוִד הַמֶּלֶךְ בָּא מִצִּדּוֹ."],[9,"","וַדַּאי אַבְרָהָם הִשְׁאִיר לוֹ חָמֵשׁ שָׁנִים, שֶׁהָיָה לוֹ לְהִתְקַיֵּם מֵאָה וּשְׁמוֹנִים שָׁנִים, וְהִתְקַיֵּם מֵאָה וְשִׁבְעִין וְחָמֵשׁ שָׁנִים, חֲסֵרִים חָמֵשׁ. יַעֲקֹב הָיָה לוֹ לְהִתְקַיֵּם בָּעוֹלָם כִּימֵי אַבְרָהָם, וְלֹא הִתְקַיֵּם אֶלָּא מֵאָה וְאַרְבָּעִים וְשֶׁבַע שָׁנִים. חֲסֵרִים עֶשְׂרִים וּשְׁמוֹנֶה. נִמְצָא שֶׁאַבְרָהָם וְיַנֲקֹב הִשְׁאִירוּ לוֹ מֵחַיֵּיהֶם שְׁלֹשִׁים וְשָׁלֹשׁ שָׁנִים. יוֹסֵף שֶׁהִתְקַיֵּם מֵאָה וְעֶשֶׂר שָׁנִים, הָיָה לוֹ לְהִתְקַיֵּם מֵאָה וְאַרְבָּעִים וְשֶׁבַע שָׁנִים כִּימֵי יַעֲקֹב, וְחָסֵר מֵהֶם שְׁלֹשִׁים וְשֶׁבַע שָׁנִים. הֲרֵי שִׁבְעִים שָׁנִים שֶׁהִשְׁאִירוּ לְדָוִד הַמֶּלֶךְ לְהִתְקַיֵּם בָּהֶם, וּבָהֶם הִתְקַיֵּם דָּוִד בְּכָל אוֹתָם הַשָּׁנִים שֶׁהִשְׁאִירוּ לוֹ הָאָבוֹת."]]],[["וְאִי תֵימָא יִצְחָק אַמַּאי לָא שָׁבַק לֵיהּ כְּלוּם כְּהַנֵּי, בְּגִין דְּאִיהוּ חשֶׁךְ וְדָוִד מִסִּטְרָא דְחשֶׁךְ קָא אֲתָא, וּמַאן דְּאִיהוּ בַּחשֶׁךְ לֵית לֵיהּ נְהוֹרָא כְּלַל וְלֵית לֵיהּ חַיִּים. וּבְגִין כָּךְ לָא הֲווּ לְדָוִד חַיִּים כְּלַל. אֲבָל אִלֵּין דְּהֲווּ לְהוֹן נְהוֹרָא, נְהִירוּ לֵיהּ לְדָוִד מַלְכָּא, וּמִנַּיְיהוּ אִצְטְרִיךְ לְאַנְהָרָא וּלְמֶהוֵי לֵיהּ חַיִּים, דְּהָא מִסִּטְרָא דְחשֶׁךְ לֵית לֵיהּ חַיִּים כְּלַל, וְעַל דָּא לָא אֲתָא יִצְחָק בְּחוּשְׁבְּנָא.","וְאִי תֵימָא יוֹסֵף אַמַּאי יַתִּיר מִכֻּלְּהוּ. אֶלָּא וַדַּאי יוֹסֵף בִּלְחוֹדוֹי, כְּכֻלְּהוּ בְּגִין דְּאִקְרֵי צַדִּיק, וְדָא הוּא דְאַנְהִיר לְסִיהֲרָא יַתִּיר מִכֻּלְּהוּ. וּבְגִין כָּךְ הַאי שָׁבַק לֵיהּ לְדָוִד מַלְכָּא יַתִיר מִכֻּלְּהוּ חַיִּין, דִּכְתִיב, (בראשית א׳:י״ז) וַיִּתֵּן אֹתָם אֱלהִים בִּרְקִיעַ הַשָּׁמַיִם לְהָאִיר עַל הָאָרֶץ.","תָּא חֲזֵי יַעֲקֹב צְלוֹתֵיהּ אָגִין לֵיהּ מֵעֵשָׂו, בְּגִין דְּבָעָא לְסַלְקָא זְכוּתֵיהּ לִבְנוֹי אֲבַתְרֵיהּ וְלָא לְאֲפָקָא לֵיהּ הַשְׁתָּא לְגַבֵּיהּ דְּעֵשָׂו. וְעַל דָּא צַלֵי צְלוֹתֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִסְתְּמִיךְ עַל זְכוּתֵיהּ, לְשֵׁיזָבָא לֵיהּ בְּגִינִיהּ:","וַיֹּאמֶר אִם יָבֹא עֵשָׂו אֶל הַמַּחֲנְה הָאַחַת וְהִכָּהוּ וְהָיָה הַמַּחֲנְה הַנִּשְׁאָר לִפְלֵיטָה. תָּא חֲזֵי, מַה כְּתִיב וַיַּחַץ אֶת הָעָם אֲשֶׁר אִתּוֹ וְאֶת הַצֹּאן וְאֶת הַבָּקָר וְהַגְּמַלִּים לִשְׁנֵי מַחֲנוֹת. אַמַּאי לִשְׁנֵי מַחֲנוֹת. בְּגִין דְּאָמַר אִם יָבֹא עֵשָׂו אֶל הַמַּחֲנְה הָאַחַת וְהִכָּהוּ וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה.","תָּא חֲזֵי, שְׁכִינְתָּא לָא עֲדִיאַת מֵאֹהֶל לֵאָה וּמֵאֹהֶל רָחֵל. אָמַר יַעֲקֹב יָדַעְנָא דְּהָא נְטִירוּ לוֹן לְאִלֵּין מִן קוּדְשָׁא בְּרִיךְ הוּא. מָה עֲבַד וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשׁוֹנָה, אָמַר אִם יַקְטִיל עֵשָׂו, לְאִלֵּין יַקְטֵיל. אֲבָל אִלֵּין לָא מִסְתָּפִינָא מִנַּיְיהוּ, בְּגִין דִּשְׁכִינְתָּא עִמְּהוֹן. וְעַל דָּא וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה. כֵּיוָן דְּעָבִיד הַאי אַתְקִין צְלוֹתֵיהּ עֲלַיְיהוּ, מָה כְּתִיב וַיֹּאמֶר יַעֲקֹב אֱלהֵי אָבִי אַבְרָהָם וִאלֹהֵי אָבִי יִצְחָק יְיָ הָאוֹמֵר אֵלַי שׁוּב לְאַרְצְךָ וּלְמוֹלַדְתְּךָ וְאֵטִיבָה עִמָּךְ.","רִבִּי יוֹסֵי פָּתַח וְאָמַר (תהילים ק״ב:א׳) תְּפִלָּה לֶעָנִי כִי יַעֲטֹף וְלִפְנִי יְיָ יִשְׁפֹּךְ שִׂיחוֹ. הַאי קְרָא אוּקְמוּהָ בְּכַמָּה אֲתַר. אֶלָּא דָּוִד מַלְכָּא אָמַר דָּא כַּד אִסְתַּכַּל וְחָמָא בְּמִלֵּי דְמִסְכְּנָא, וְאִסְתַּכַּל בֵּיהּ כַּד הֲוָה אָזִיל וְעָרַק מִקַּמֵּי חָמוֹי אָמַר דָּא. תְּפִלָּה לֶעָנִי, דָּא הוּא צְלוֹתָא דְּבָעֵי מִסְכְּנָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְדָא צְלוֹתָא דְּאַקְדִימַת לְכָל צְלוֹתְהוֹן דְּעַלְמָא.","כְּתִיב הָכָא תְּפִלָּה לֶעָנִי וּכְתִיב הָתָם (תהילים צ׳:א׳) תְּפִלָּה לְמשֶׁה אִישׁ הָאֱלֹהִים, מַה בֵּין הַאי לְהַאי. אֶלָּא דָּא תְּפִלָּה שֶׁל יַד וְדָא תְּפִלָּה שֶׁל רֹאשׁ, וְלֵית לְאַפְרָשָׁא בֵּין הַאי תְּפִלָּה לְעָנִי וּבֵין תְּפִלָּה לְמשֶׁה אִישׁ הָאֱלֹהִים, וְתַרְוַויְיהוּ שְׁקִילִין כְּחַד.","וְעַל דָּא צְלוֹתָא דְעָנִי אַקְדִימַת קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא מִכָּל צְלוֹתִין דְּעַלְמָא, בְּגִין דִּכְתִיב, (תהילים כ״ב:כ״ה) כִּי לא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי וְגו'. תָּא חֲזֵי, תְּפִלָּה לְעָנִי, דָּא תְּפִלָּה שֶׁל יַד. דְּעָנִי אִתְדָּבַּק בְּמִסְכְּנוּתֵיהּ, כְּמַאן דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם.","דָּבָר אַחֵר תְּפִלָּה דָּא משֶׁה. לְעָנִי דָּא דָוִד. כִּי יַעֲטֹף, כַּד אִתְכַּסְּיָא סִיהֲרָא וְאִתְכַּסֵּי שִׁמְשָׁא מִינָהּ. וְלִפְנֵי יְיָ יִשְׁפֹּךְ שִׂיחוֹ, בְּגִין לְאִתְחַבְּרָא בַּהֲדֵי שִׁמְשָׁא.","תָּא חֲזֵי, צְלוֹתָא דְכָל בְּנֵי נָשָׁא צְלוֹתָא. וּצְלוֹתָא דְמִסְכְּנָא אִיהִי צְלוֹתָא דְקָיְימָא קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא וְתָבַר תַּרְעִין וּפִתְחִין וְעָאלַת לְאִתְקַבָּלָא קַמֵּיהּ הֲדָא הוּא דִכְתִיב, (שמות כ״ב:כ״ו) וְהָיָה כִי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי, וּכְתִיב שָׁמֹעַ אֶשְׁמַע צַעֲקָתוֹ. וְלִפְנֵי יְיָ יִשְׁפֹּךְ שִׂיחוֹ, כְּמַאן דְּמִתְרַעֵם עַל דִּינוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא."],[[0,"ואי תימא יצחק וכו':","ואם תאמר, יצחק, למה לא הניח לו כלום מחייו כמו אברהם יעקב ויוסף. ומשיב, משום שיצחק היה חשך דהיינו מקו שמאל שמטרם התכללותו עם הימין הוא חשך כנ\"ל, ודוד מצד החשך בא, כלומר שגם הוא מצד שמאל, ומי שהוא בחשך, אין לו אור כלל, ואין לו חיים, ועל כן, לא היו חיים לדוד כלל. אבל אלו, דהיינו אברהם יעקב ויוסף, שהיה להם אור, כי מצד ימין הם, האירו לדוד המלך ומהם הוא צריך להאיר ושיהיה לו חיים, כלומר שמוכרח להתכלל בימין, כי מצד החשך, דהיינו משמאל, אין שם חיים כלל. וע\"כ, לא בא יצחק בחשבון."],[1,"ואי תימא יוסף וכו':","ואם תאמר, יוסף למה הניח לו חיים יותר מכולם, דהיינו ל\"ז שנים והם לא הניחו לו אלא ל\"ג שנים. ומשיב, אלא ודאי יוסף בלבדו שקול ככולם, משום שנקרא צדיק, דהיינו יסוד, הכולל את כל הספירות, וזהו שמאיר ללבנה, שהיא הנוקבא, יותר מכולם, ומשום זה, הוא הניח לדוד המלך חיים יותר מכולם. שכתוב ויתן אותם אלקים ברקיע השמים להאיר על הארץ. פירוש הרקיע הוא בחינת יסוד צדיק. דהיינו יוסף, והארץ ה\"ס הנוקבא, דהיינו דוד המלך, הרי שהמאיר אל הנוקבא הוא היסוד שה\"ס יוסף, וע\"כ נתן לו חיים יותר מכולם."],[2,"ת\"ח יעקב וכו':","בוא וראה, יעקב, תפלתו הגינה עליו מפני עשו, ולא זכותו, משום שרצה להניח את זכותו, לבניו אחריו, ולא להוציאו לצורך עצמו עתה מפני עשו. וע\"כ התפלל תפלתו אל הקב\"ה, ולא סמך עצמו על זכותו שינצל בשבילה."],[3,"ויאמר אם יבא עשו וגו':","בוא וראה, מה כתוב, ויחץ וגו' לשני מחנות. שואל למה חצה אותם לשני מחנות. ומשיב, משום שאמר אם יבא עשו וגו' והיה המחנה הנשאר לפליטה, שיש להקשות, וכי לא יכול להיות שעשו יכה את שני המחנות, ומה היא הודאות שיהיה מחנה נשאר לפליטה."],[4,"ת\"ח שכינתא לא וכו':","ואומר, בוא וראה, השכינה לא סרה מאהל לאה ומאהל רחל, אמר יעקב, יודע אני, שיש להם לאלו שמירה מן הקב\"ה. לפיכך מה עשה, וישם את השפחות ואת ילדיהן ראשונה, אמר אם יכה עשו יכה את אלו, אבל בעד אלו דהיינו בני הגבירות, איני מפחד בעדם משום שהשכינה עמהם. ולפי\"ז יהיה הפירוש של \u0003ראשונה,\u0004 ראשון לסכנה. ועל כן אמר \u0003והיה המחנה הנשאר לפליטה,\u0004 דהיינו משום שהשכינה עמהם. כיון שעשה זאת, ערך תפלתו עליהם על השפחות וילדיהן מה כתוב, ויאמר יעקב אלקי אבי אברהם וגו'."],[5,"רבי יוסי פתח וכו':","ר\"י פתח ואמר, תפלה לעני כי יעטוף וגו'. מקרא זה בארוהו בכמה מקומות. אלא דוד המלך אמר זה, כאשר הסתכל וראה בהליכות העני, והסתכל בו, בשעה שהיה הולך ובורח מפני חמיו, שאול המלך, אז אמר תפלה לעני. זו היא תפלה שהעני מתפלל לפני הקב\"ה, וזו היא תפלה, המקדימה להתקבל לפני כל תפלות העולם."],[6,"כתיב הכא תפלה וכו':","כתוב כאן תפלה לעני, וכתוב שם תפלה למשה איש האלקים, ושואל, מה בין זו לזו. ומשיב, אלא זו, התפלה לעני, היא תפלה של יד, שה\"ס הנוקבא, כי הנוקבא נקראת עני משום שאין לה מעצמה כלום והכל צריכה לקבל מז\"א. וזו, התפלה למשה, היא תפלה של ראש, שהוא ז\"א. ואין להפריד בין תפלה לעני ובין תפלה למשה, דהיינו בין הנוקבא לז\"א. כי צריכים להיות תמיד בזווג. ושניהם שקולים כאחד."],[7,"ועל דא צלותא וכו':","ועל כן תפלת העני מקדימה להתקבל לפני הקב\"ה מכל תפלות העולם, משום שכתוב, כי לא בזה ולא שקץ ענות עני וגו'. ובוא וראה, תפלה לעני היא תפלה של יד. דהיינו הנוקבא, שהיא תפלת העני הדבוק בעניו, כמי שאין לו מעצמי מאומה."],[8,"דבר אחר תפלה וכו':","פירוש אחר. תפלה, רומז על משה שהוא ז\"א. \u0003לעני,\u0004 על דוד, שהוא הנוקבא. \u0003כי יעטוף,\u0004 היינו בשעה שמתכסית הלבנה, שהיא הנוקבא, שהשמש שהוא ז\"א, נעלם ממנה. \u0003ולפני הוי\"ה,\u0004 שהוא ז\"א, \u0003ישפוך שיחו,\u0004 כדי להתחבר עם השמש, שהוא ז\"א."],[9,"ת\"ח צלותא דכל וכו':","בוא וראה, תפלת כל אדם היא תפלה, אבל תפלת העני, היא תפלה העומדת לפני הקב\"ה, שהיא שוברת שערים ופתחים, ונכנסת להתקבל לפניו. וזהו שכתוב, והיה כי יצעק אלי ושמעתי כי חנון אני, וכתוב, שמוע אשמע צעקתו. \u0003ולפני ה' שיחו,\u0004 היינו כמי שמתרעם על דיניו של הקב\"ה."]],[[0,"","וְאִם תֹּאמַר, לָמָּה יִצְחָק לֹא הִשְׁאִיר לוֹ כְּלוּם כְּאֵלֶּה? מִשּׁוּם שֶׁהוּא חֹשֶׁךְ, וְדָוִד בָּא מִצַּד הַחֹשֶׁךְ, וּמִי שֶׁהוּא בְּחֹשֶׁךְ אֵין לוֹ אוֹר כְּלָל וְאֵין לוֹ חַיִּים, וְלָכֵן לֹא הָיוּ לְדָוִד חַיִּים כְּלָל. אֲבָל אֵלֶּה שֶׁהָיָה לָהֶם אוֹר, הֵאִירוּ לְדָוִד הַמֶּלֶךְ, וּמֵהֶם הִצְטָרֵךְ לְהָאִיר וְלִהְיוֹת לוֹ חַיִּים, שֶׁהֲרֵי מִצַּד הַחֹשֶׁךְ אֵין לוֹ חַיִּים כְּלָל, וְעַל זֶה בָּא יִצְחָק בְּחֶשְׁבּוֹן."],[1,"","וְאִם תֹּאמַר, לָמָּה יוֹסֵף יוֹתֵר מִכֻּלָּם? אֶלָּא וַדַּאי יוֹסֵף בִּלְבַדּוֹ כְּמוֹ כֻּלָּם, מִשּׁוּם שֶׁנִּקְרָא צַדִּיק, וְזֶהוּ שֶׁמֵּאִיר לַלְּבָנָה יוֹתֵר מִכֻּלָּם, וְלָכֵן זֶה הִשְׁאִיר לְדָוִד הַמֶּלֶךְ יוֹתֵר מִכֻּלָּם חַיִּים, שֶׁכָּתוּב (בראשית א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמַיִם לְהָאִיר עַל הָאָרֶץ."],[2,"","בֹּא רְאֵה, יַעֲקֹב, תְּפִלָּתוֹ הֵגֵנָּה עָלָיו מֵעֵשָׂו מִשּׁוּם שֶׁרָצָה לְהַעֲבִיר זְכוּתוֹ לְבָנָיו אַחֲרָיו וְלֹא לְהוֹצִיא אוֹתָהּ עַכְשָׁו אֵצֶל עֵשָׂו, וְעַל זֶה הִתְפַּלֵּל תְּפִלָּתוֹ לַקָּדוֹשׁ- בָּרוּךְ-הוּא וְלֹא סָמַךְ עַל זְכוּתוֹ לְהַצִּילוֹ בִּגְלָלָהּ."],[3,"","וַיֹּאמֶר אִם יָבוֹא עֵשָׂו אֶל הַמַּחֲנֶה הָאַחַת וְהִכָּהוּ וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה. בּא רְאֵה מַה כָּתוּב, וַיַּחַץ אֶת הָעָם אֲשֶׁר אִתּוֹ וְאֶת הַצֹּאן וְאֶת הַבָּקָר וְהַגְּמַלִּים לִשְׁנֵי מַחֲנוֹת. לָמָּה לִשְׁנֵי מַחֲנוֹת? מִשּׁוּם שֶׁאָמַר, אִם יָבוֹא עֵשָׂו אֶל הַמַּחֲנֶה הָאַחַת וְהִכָּהוּ וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה."],[4,"","בֹּא רְאֵה שֶׁשְּׁכִינָה לֹא זָזָה מֵאֹהֶל לֵאָה וּמֵאֹהֶל רָחֵל. אָמַר יַעֲקֹב, יָדַעְתִּי שֶׁהֲרֵי שְׁמִירָה לְאֵלֶּה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. מֶה עָשָׂה? וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשֹׁנָה. אָמַר, אִם יַהֲרֹג עֵשָׂו - יַהֲרֹג אֶת אֵלֶּה, אֲבָל אֵלֶּה אֵינִי פוֹחֵד מֵהֶם, מִשּׁוּם שֶׁשְּׁכִינָה עִמָּהֶם, וְעַל זֶה - וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה. כֵּיוָן שֶׁעָשָׂה אֶת זֶה, תִּקֵּן תְּפִלָּתוֹ עֲלֵיהֶם, מַה כָּתוּב? וַיֹּאמֶר יַעֲקֹב אֱלֹהֵי אָבִי אַבְרָהָם וֵאלֹהֵי אָבִי יִצְחָק ה' הָאֹמֵר אֵלַי שׁוּב לְאַרְצְךְ וּלְמוֹלַדְתְּךְ וְאֵיטִיבָה עִמָּךְ."],[5,"","רַבִּי יוֹסֵי פָּתַח וְאָמַר, (תהלים קב) תְּפִלָּה לְעָנִי כִי יַעֲטֹף וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ. פָּסוּק זֶה בֵּאֲרוּהוּ בְּכַמָּה מְקוֹמוֹת. אֶלָּא דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה כְּשֶׁהִסְתַּכֵּל וְרָאָה בְּדִבְרֵי הֶעָנִי, וְהִסְתַּכֵּל בּוֹ כְּשֶׁהָיָה הוֹלֵךְ וּבוֹרֵחַ מִלִּפְנֵי חָמִיו אָמַר זֶה. תְּפִלָּה לְעָנִי - זוֹהִי תְפִלָּה שֶׁמְּבַקֵּשׁ הֶעָנִי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזוֹ הַתְּפִלָּה שֶׁמַּקְדִּימָה אֶת כָּל תְּפִלּוֹת הָעוֹלָם."],[6,"","כָּתוּב כָּאן תְּפִלָּה לְעָנִי, וְכָתוּב שָׁם (שם צ) תְּפִלָּה לְמֹשֶׁה אִישׁ הָאֱלֹהִים. מַה בֵּין זֶה לָזֶה? אֶלָּא זוֹ תְּפִלָּה שֶׁל יָד, וְזוֹ תְּפִלָּה שֶׁל רֹאשׁ, וְאֵין לְהַפְרִיד בֵּין הַתְּפִלָּה לְעָנִי הַזּוֹ וּבֵין תְּפִלָּה לְמֹשֶׁה אִישׁ הָאֱלֹהִים, וּשְׁתֵּיהֶן שְׁקוּלוֹת כְּאַחַת."],[7,"","וְעַל זֶה תְּפִלַּת הֶעָנִי מַקְדִּימָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל תְּפִלּוֹת הָעוֹלָם, מִשּׁוּם שֶׁכָּתוּב (שם כב) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי וְגוֹ'. בֹּא רְאֵה, תְּפִלָּה לְעָנִי זוֹ תְּפִלָּה שֶׁל יָד, שֶׁהֶעָנִי דָּבוּק בְּעָנְיוֹ כְּמִי שֶׁאֵין לוֹ מֵעַצְמוֹ כְּלוּם."],[8,"","דָּבָר אַחֵר, תְּפִלָּה - זֶה מֹשֶׁה, לְעָנִי - זֶה דָּוִד, כִי יַעֲטֹף - כְּשֶׁמִּתְכַּסָּה הַלְּבָנָה וּמִתְכַּסָּה הַשֶּׁמֶשׁ מִמֶּנָּה, וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ - כְּדֵי לְהִתְחַבֵּר עִם הַשֶּׁמֶשׁ."],[9,"","בֹּא רְאֵה, הַתְּפִלָּה שֶׁל כָּל בְּנֵי אָדָם תְּפִלָּה, וּתְפִלַּת הֶעָנִי הִיא תְפִלָּה שֶׁעוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹבֶרֶת שְׁעָרִים וּפְתָחִים וְנִכְנֶסֶת לְהִתְקַבֵּל לְפָנָיו. זֶהוּ שֶׁכָּתוּב (שמות כב) וְהָיָה כִּי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי, וְכָתוּב שָׁמֹעַ אֶשְׁמַע צַעֲקָתוֹ. וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ - כְּמִי שֶׁמִּתְרַעֵם עַל דִּין הַקָּדוֹשׁ בָּרוּךְ הוּא."]]],[["אָמַר רִבִּי אֶלְעָזָר צְלוֹתְהוֹן דְּצַדִּיקַיָיא חֶדְוָותָא לִכְנְסֶת יִשְׂרָאֵל לְאִתְעַטָּרָא קַמֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בְגִין כָּךְ חֲבִיבָא הוּא יַתִּיר קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא תָּאִיב לִצְלוֹתְהוֹן דְּצַדִּיקַיָּיא בְּשַׁעְתָּא דְּאִצְטְרִיךְ לוֹן, בְּגִין דְּיָדְעֵי לְרַצּוּיֵי לְמָארֵיהוֹן.","מַה כְּתִיב בֵּיהּ בְּיַעֲקֹב אֱלֹהֵי אָבִי אַבְרָהָם וֵאלֹהֵי אָבִי יִצְחָק יְיָ הָאוֹמֵר אֵלַי שׁוּב וְגו', אִעֲטַר וְאִקְשַׁר קִשּׁוּרָא בְּקִשּׁוּרָא חַד כְּדְקָא חָזֵי. אֱלֹהֵי אָבִי אַבְרָהָם לִימִינָא, וִאלהֵי אָבִי יִצְחָק לִשְׂמָאלָא. הָאוֹמֵר אֵלַי, הָכָא תָּלֵי מִלָּה לְאִתְעַטְּרָא לְאַתְרֵיהּ בֵּינַיְיהוּ. שׁוּב לְאַרְצְךָ וּלְמוֹלַדְתְּךָ וְאֵיטִיבָה עִמָּךְ:","קָטֹנְתִּי מִכֹּל הַחֲסָדִים, אַמַּאי הֲוָה אִצְטְרִיךְ הַאי עִם הַאי. אֶלָּא אָמַר יַעֲקֹב אַתְּ אַבְטַחְתְּ לִי לְאוֹטָבָא עִמִּי, וְאֲנָא יְדַעְנָא דְּכָל עוֹבָדָךְ כֻּלְּהוּ עַל תְּנַאי. הָא אֲנָא לֵית בִּי זְכוּתָא דְּהָא קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת אֲשֶׁר עָשִׂיתָ אֶת עַבְדֶּךָ, וְכָל מַה דַּעֲבָדַת לִי עַד יוֹמָא לָאו בְּגִין זְכוּתָאי הֲוָה אֶלָּא בְּגִינָךְ הוּא דַּעֲבָדַת לִי, וְהַהוּא טִיבוּ וּקְשׁוֹט בְּגִינָךְ הֲוָה. דְּהָא כַּד עָבַרְנָא בְּקַדְמִיתָא דְּהֲוֵינָא אָזִיל מִקַּמֵּי דְעֵשָׂו, יְחִידָאי עֲבַרְנָא לֵיהּ לְהַהוּא נַהֲרָא, וְאַנְתְּ עָבְדִית עִמִּי טִיבוּ וּקְשׁוֹט. וְהָא אֲנָא הַשְׁתָּא מַעֲבַר לֵיהּ בִּתְרֵי מַשִּׁירְיָין, אִינוּן תְּרֵין מַשִּׁירְיָין דְּפָלִיג.","עַד הָכָא סִדּוּרָא דְּשִׁבְחָא דְמָארֵיהּ, מִכָּאן וּלְהָלְאָה בָּעָא מַה דְּאִצְטְרִיךְ לֵיהּ. לְאַחֲזָאָה לְכָל בְּנִי עַלְמָא, דְּאִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְסַדְּרָא שְׁבָחָא דְמָארֵיהּ בְּקַדְמִיתָא, וּלְבָתַר יִבָּעֵי בָּעוּתֵיהּ. דְּהָכִי עֲבַד יַעֲקֹב, בְּקַדְמִיתָא סִדֵּר שְׁבָחָא דְמָרֵיהּ, וּלְבָתַר דְּסִדֵּר שְׁבָחָא אָמַר בָּעוּתֵיהּ דְּאִצְטְרִיךְ לֵיהּ.","הֲדָא הוּא דִכְתִיב הַצִּילֵנִי נָא מִיָּד אָחִי מִיַּד עֵשָׂו כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבֹא וְהִכַּנִּי אֵם עַל בָּנִים. מִכָּאן, מַאן דְּצַלֵּי צְלוֹתֵיהּ דְּבָעֵי לְפָרְשָׁא מִלּוֹי כְּדְקָא יְאוּת. הַצִּילֵנִי נָא, וְאִי תֵימָא דְהָא שֵׁזַבְתְּ לִי מִלָּבָן. מִיַּד אָחִי. וְאִי תֵימָא קְרִיבִין אוֹחֲרָנִין סְתָם, אַחִין אִקְרוּן. מִיַּד עֵשָׂו. מַאי טַעֲמָא, בְּגִין לְפָרְשָׁא מִלָּה כְּדְקָא יְאוּת. וְאִי תֵימָא אֲנָא אַמַּאי אִצְטְרִיךְ, כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבֹא וְהִכַּנִי. בְּגִין לְאִשְׁתְּמוֹדְעָא מִלָּה לְעֵילָא וּלְפָרְשָׁא לָהּ כְּדְקָא יְאוּת, וְלָא יַסְתִּים מִלָּה:","וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב עִמָּךְ וְגו'. וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב, מַאי וְאַתָּה. כְּמָה דְאַתְּ אָמֵר (נחמיה ט׳:ו׳) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם, אוּף הָכָא וְאַתָּה אָמַרְתָּ.","תָּא חֲזֵי, דָּוִד מַלְכָּא אָמַר (תהילים י״ט:ט״ו) יִהְיוּ לְרָצוֹן אִמְרֵי פִי, אִלֵּין מִלִּין דְּאִתְפָּרְשָׁן. וְהֶגְיוֹן לִבִּי, אִלֵּין מִלִּין דִּסְתִימָן דְּלָא יָכִיל בַּר נָשׁ לְפָרְשָׁא לוֹן בְּפוּמֵיהּ, דָּא הוּא הֶגְיוֹן דְּאִיהוּ בְּלִבָּא דְּלָא יָכִיל לְאִתְפָּרְשָׁא.","וְעַל דָּא אִצְטְרִיךְ מִלָּה לְאִתְפָּרְשָׁא בְּפוּמָא, וּמִלָּה דְתַלְיָא בְּלִבָּא, וְכֹלָּא רָזָא אִיהוּ. חַד לָקֳבֵל דַּרְגָּא תַּתָּאָה, וְחַד לָקֳבֵל דַּרְגָּא עִלָּאָה. מִלָּה דְאִתְפָּרְשָׁא לָקֳבֵל דַּרְגָּא תַּתָּאָה דְּאִצְטְרִיךְ לְאִתְפָּרְשָׁא. הַהוּא דְתַלְיָא בְּלִבָּא אִיהוּ לָקֳבֵל דַּרְגָּא פְּנִימָאָה יַתִּיר, וְכֹלָּא כְּחֲדָא אִיהוּ. וְעַל דָּא אָמַר יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ וְגו'.","כְּגַוְונָא דָא אָמַר יַעֲקֹב, בְּקַדְמִיתָא פָּרִישׁ מִלָּה כְּדְקָא יְאוּת, וּלְבָתַר סָתִים מִלָּה דְּאִיהִי תַּלְיָא בְּהֶגְיוֹנָא דְלִבָּא דְּלָא אִצְטְרִיךְ לְפָרְשָׁא. דִּכְתִיב, (בראשית ל״ב:י״ג) וְשַׂמְתִּי אֶת זַרְעֲךָ כְּחוֹל הַיָּם אֲשֶׁר לא יִסָּפֵר מֵרֹב. הָכָא אִיהוּ מִלָּה דְּתַלְיָא בְּלִבָּא דְּלָא אִצְטְרִיךְ לְפָרְשָׁא. וְכֵן אִצְטְרִיךְ כִּדְקָאֲמָרָן, בְּגִין לְיַחֲדָא יִחוּדָא שְׁלִים כְּדְקָא יְאוּת. זַכָּאִין אִינוּן צַדִּיקַיָא דְּיָדְעֵי לְסַדְּרָא שְׁבָחָא דְמָארֵיהוֹן כְּדְקָא יְאוּת וּלְמִבְעֵי בָּעוּתְהוֹן, וּבְגִין כָּךְ כְּתִיב (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר. (ס\"א כתיב גם את השני גם את השלישי וגו', השלש פעמים גם, רמז (גליון, ג\"ם ראשי תיבות גואל משרז גואל מרדכי גואל משיח) לשלש גאולות על ידי שלשה צדיקים משה מרדכי משיח שעתיד לגאלנו בקרוב):","וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וְגו'. רִבִּי חִיָיא פָּתַח וְאָמַר, (תהילים צ״א:י׳) לֹא תְאֻנְּה אֵלֶיךָ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךָ. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא עֲבַד בְּכָל יוֹמָא וְיוֹמָא עֲבִידְתֵּיהּ דְּאִתְחֲזֵי לֵיהּ וְהָא אוּקְמוּהָ. וְאִתְּמָר, (ד\"א ל\"ג ואי תימא) בְּיוֹמָא רְבִיעָאָה עֲבַד נְהוֹרִין. וּכְדֵין אִתְבְּרֵי סִיהֲרָא חָסֵר, נְהוֹרָא דְּאַזְעִירַת גַּרְמָהּ, וּבְגִין דְּאִיהִי מְאֹרֹת חָסֵר וא\"ו, אִתְיְהִיב דּוּכְתָּא לְשַׁלְּטָאָה כָּל רוּחִין וְשֵׁדִין וְעִלְעוּלִין וּמַזִּיקִין וְכָל רוּחֵי מְסָאֲבֵי."],[[0,"אמר ר' אלעזר וכו':","אר\"א, תפלת הצדיקים, היא שמחה לכנסת ישראל, שהיא הנוקבא, להתעטר, עם התפלה, לפני הקב\"ה. ומשום זה, היא אהובה יותר על הקב\"ה מתפלת העני, ומשום זה, הקב\"ה משתוקק לתפלת הצדיקים בשעה שצריכים להתפלל, משום שיודעים איך לרצות את רבונם."],[1,"מה כתיב ביה וכו':","מה כתוב בו ביעקב, בתפלתו, אלקי אבי אברהם ואלקי וגו', העטיר, וקשר קשר בהתקשרות אחת כראוי, שאמר \u0003אלקי אבי אברהם,\u0004 שהוא לימין, \u0003ואלקי אבי יצחק,\u0004 שהוא לשמאל, \u0003האומר אלי,\u0004 דהיינו לו עצמו שהוא קו אמצעי המכריע, כאן, בקו האמצעי, תלוי הדבר, לעטר את מקומו ביניהם, בין אברהם ויצחק שהם ימין ושמאל, וע\"כ אמר לו, שוב לארצך ולמולדתך ואיטיבה עמך."],[2,"קטנתי מכל החסדים:","שואל, מה היה צריך ליעקב לומר זאת, דהיינו קטנתי וגו' עם זה שהזכיר מקודם לכן, שוב לארצך ולמולדתך ואיטיבה עמך ומשיב, אלא אמר יעקב, אתה הבטחת להיטיב עמי, ואני יודע שכל מעשיך הם על תנאי, אם יעשו רצונך, ואני אין בי שום זכות, כי קטנתי מכל החסדים ומכל האמת אשר עשית את עבדך. ועל כן אינך צריך לקיים לי הבטחתך וכל מה שעשית לי עד היום, לא היה משום זכויותי, אלא בשביל טובך, הוא שעשית לי, וכל אותו החסד והאמת היה בשביל טובך, כי כאשר עברתי את הירדן בתחילה, בעת שהייתי בורח מפני עשו, יחידי עברתי את הנהר ההוא, ואתה עשית עמי חסד ואמת, והרי עתה אני עובר את הנהר עם שתי מחנות. דהיינו אלו שתי המחנות שחצה."],[3,"עד הכא סדורא וכו':","עד כאן אמר סדר שבחו של רבונו, מכאן ולהלאה בקש מה שצריך לו, להורות לכל בני העולם, שאדם צריך לסדר שבחו של רבונו בתחילה, ואחר כך יתפלל תפלתו. כי כן עשה יעקב, בתחילה סדר שבחו של רבונו, וא;חר שסדר השבח, אמר תפלתו שצריך."],[4,"הה\"ד הצילני נא מיד וכו':","וזה הוא שכתוב הצילני נא מיד אחי וגו', דהיינו שלאחר שסידר השבח התפלל תפלתו. מכאן נשמע, שמי שמתפלל תפלתו צריך לפרש דבריו כראוי. שאמר, \u0003הצילני נא,\u0004 שלכאורה היה זה די כי אינו צריך יותר מהצלה, עם כל זה אמר להקב\"ה: ואם תאמר, שכבר הצלת אותי מלבן, לכן פירש \u0003מיד אחי.\u0004 ואם תאמר, שגם קרובים אחרים סתם, נקראים אחים, ע\"ד שאמר לבן ליעקב הכי \u0003אחי\u0004 אתה ועבדתני חנם, לכן פירש \u0003מיד עשו.\u0004 מה הטעם, משום שצריכים לפרש הדבר כראוי. וע\"כ האריך עוד, ואמר, אם תאמר, למה אני צריך להצלה, \u0003כי ירא אנכי אותו פן יבא והכני\u0004 וגו', וכל זה כדי להסביר הדבר למעלה, ולפרש אותו כראוי, ולא לסתום הדבר."],[5,"ואתה אמרת היטב איטיב וגו':","ושואל מהו \u0003ואתה.\u0004 ומשיב, כמו שאתה אומר \u0003ואתה\u0004 מחיה את כולם, שפירושו, הנוקבא הנקראת אתה, אף כאן \u0003ואתה אמרת,\u0004 הוא שם הנוקבא."],[6,"תא חזי דוד וכו':","בוא וראה, דוד המלך אמר, \u0003יהיו לרצון אמרי פי,\u0004 אלו הם דברים שהם מפורשים, \u0003והגיון לבי,\u0004 אלו הם דברים שהם סתומים, שאין אדם יכול לפרש אותם בפיו, זה הוא \u0003הגיון\u0004 שהוא בלב, שאינו יכול לפרשו."],[7,"ועל דא אצטריך וכו':","ועל כן צריך להיות דבר שהוא מפורש בפה דהיינו, \u0003אמרי פי.\u0004 ודבר שהוא תלוי בלב, ואינו מפורש בפה דהיינו \u0003הגיון לבי,\u0004 כי הכל הוא סוד. אחד הוא כנגד המדרגה התחתונה, שהיא הנוקבא, ואחד כנגד המדרגה העליונה שהיא בינה. דבר המפורש בפה, הוא כנגד המדרגה התחתונה, הצריכה להתפרש, שה\"ס עלמא דאתגליא. דבר ההוא התלוי בלב, הוא כנגד מדרגה יותר פנימית, שהיא בינה, שהיא עלמא דאתכסיא, והכל הוא כאחד, כלומר ששניהם צריכים. וע\"כ אמר, יהיו לרצון \u0003אמרי פי והגיון לבי לפניך\u0004 וגו'."],[8,"כגוונא דא אמר יעקב וכו':","כעין זה אמר יעקב, מתחילה פירש הדבר כראוי, ואחר זה סתם הדבר, להיותו תלוי בהגיון הלב שאינו צריך להתפרש, שכתוב, ושמתי את זרעך כחול הים אשר לא יספר מרוב, כאן הוא דבר התלוי בלב, שאינו צריך להתפרש. וכן צריך להיות כמו שאמרנו ששניהם צריכים כדי ליחד יחוד השלם כראוי."],[8,"","פירוש. שיש מוחין דמספר, והיינו המפורש בפה, שה\"ס הארת החכמה המתגלה על ידי הנוקבא הנקראת פה. ויש מוחין בלי מספר, שה\"ס חסדים מכוסים. (כנ\"ל בהקדמת הזהר דף כ\"ט ד\"ה במספר) ונמשכים מבינה ונקראים הגיון לבי. ובתחילה אמר יעקב, \u0003ואתה אמרת היטב איטיב עמך,\u0004 וה\"ס מוחין דמספר, וע\"כ הקדים השם \u0003ואתה,\u0004 שהוא עלמא דאתגליא, שממנה נמשכים המוחין דמספר, ואח\"כ אמר אשר \u0003לא יספר\u0004 מרוב, שהם המוחין בלי מספר הנמשכים מעלמא דאתכסיא, שהם חסדים מכוסים. ושניהם צריכים. (כמ\"ש שם בהקדמת ספר הזהר דף ל' ד\"ה ושמא ע\"ש.) \u0003זכאין אינון צדיקייא וכו':\u0004 אשריהם הצדיקים שיודעים לסדר שבחיו של רבונם כראוי, ולהתפלל אחר כך תפלתם. ומשום זה כתוב \u0003ויאמר לי עבדי אתה ישראל אשר בך אתפאר.\u0004"],[9,"ויותר יעקב לבדו וגו':","רבי חייא פתח ואמר, לא תאנה אליך וגו', בוא וראה, כאשר ברא הקב\"ה את העולם, עשה בכל יום ויום המלאכה הראויה לו, ובארוהו. ונאמר, שביום רביעי עשה את המאורות, ואז נבראה הלבנה חסרה, שהיא אור שמיעט את עצמו, ומשום שהיא מארת חסר ו', ניתן מקום לשליטה לכל הרוחות, והשדים. ורוחות סערה, ומזיקים, וכל רוחות הטומאה. (וביאור הדברים, לעיל ב\"א דף צ\"ה ד\"ה ויאמר)."]],[[0,"","אָמַר רַבִּי אֶלְעָזָר, תְּפִלּוֹת הַצַּדִּיקִים חֶדְוָה לִכְנֶסֶת יִשְׂרָאֵל לְהִתְעַטֵּר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. מִשּׁוּם זֶה חֲבִיבָה הִיא יוֹתֵר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא תָּאֵב לִתְפִלּוֹת הַצַּדִּיקִים בְּשָׁעָה שֶׁצָּרִיךְ לָהֶם, מִשּׁוּם שֶׁיּוֹדְעִים לְרַצּוֹת אֶת רִבּוֹנָם."],[1,"","מַה כָּתוּב בְּיַעֲקֹב? אֱלֹהֵי אָבִי אַבְרָהָם וֵאלֹהֵי אָבִי יִצְחָק ה' הָאֹמֵר אֵלַי שׁוּב וְגוֹ'. הִתְעַטֵּר וְנִקְשַׁר קֶשֶׁר בְּקֶשֶׁר אֶחָד כָּרָאוּי. אֱלֹהֵי אָבִי אַבְרָהָם לְיָמִין, וֵאלֹהֵי אָבִי יִצְחָק לִשְׂמֹאל. הָאֹמֵר אֵלַי - כָּאן תָּלָה הַדָּבָר לְהִתְעַטֵּר לִמְקוֹמוֹ בֵּינֵיהֶם. שׁוּב לְאַרְצְךְ וּלְמוֹלַדְתְּךְ וְאֵיטִיבָה עִמָּךְ."],[2,"","קָטֹנְתּי מִכֹּל הַחֲסָדִים. לָמָּה הָיָה צָרִיךְ זֶה עִם זֶה? אֶלָּא, אָמַר יַעֲקֹב, אַתָּה הִבְטַחְתָּ לִי לְהֵיטִיב עִמִּי, וַאֲנִי יָדַעְתִּי שֶׁכָּל מַעֲשֶׂיךְ כֻּלָּם הֵם עַל תְּנַאי, הֲרֵי אֲנִי אֵין בִּי זְכוּת, שֶׁהֲרֵי קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת אֲשֶׁר עָשִׂיתָ אֶת עַבְדֶּךְ. וְכָל מַה שֶּׁעָשִׂיתָ לִי עַד הַיּוֹם, לֹא בִּשְׁבִיל זְכוּתִי הָיָה, אֶלָּא בִּגְלָלְךְ הוּא שֶׁעָשִׂיתָ לִי. וְאוֹתוֹ טוֹב וֶאֱמֶת בִּגְלָלְךְ הָיוּ, שֶׁהֲרֵי כְּשֶׁעָבַרְתִּי בַּתְּחִלָּה, שֶׁהָיִיתִי הוֹלֵךְ מִלִּפְנֵי עֵשָׂו, יְחִידִי עָבַרְתִּי אֶת אוֹתוֹ נָהָר, וְאַתָּה עָשִׂיתָ עִמִּי טוֹב וֶאֱמֶת, וַהֲרֵי אֲנִי עַכְשָׁו עוֹבֵר אוֹתוֹ בִּשְׁנֵי מַחֲנוֹת, הֵם שְׁנֵי הַמַּחֲנוֹת שֶׁחִלֵּק."],[3,"","עַד כָּאן סִדּוּר הַשֶּׁבַח שֶׁל רִבּוֹנוֹ. מִכָּאן וּלְהַבָּא בִּקֵּשׁ מַה שֶּׁצָּרִיךְ לוֹ, לְהַרְאוֹת לְכָל בְּנֵי הָעוֹלָם שֶׁצָּרִיךְ לוֹ לָאָדָם לְסַדֵּר שֶׁבַח שֶׁל אֲדוֹנוֹ בַּתְּחִלָּה, וְאַחַר יְבַקֵּשׁ בַּקָּשׁוֹתָיו. שֶׁכָּךְ עָשָׂה יַעֲקֹב - בַּתְּחִלָּה סִדֵּר שְׁבָחָיו שֶׁל קוֹנוֹ, וְאַחַר שֶׁסִּדֵּר הַשֶּׁבַח, אָמַר בַּקָּשָׁתוֹ שֶׁהִצְטָרֵךְ לָהּ."],[4,"","זֶהוּ שֶׁכָּתוּב: הַצִּילֵנִי נָא מִיַּד אָחִי מִיַּד עֵשָׂו כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבוֹא וְהִכַּנִי אֵם עַל בָּנִים. מִכָּאן, מִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ שֶׁצָּרִיךְ לְפָרֵשׁ דְּבָרָיו כָּרָאוּי. הַצִּילֵנִי נָא. וְאִם תֹּאמַר שֶׁהֲרֵי הִצַּלְתַּנִי מִלָּבָן - מִיַּד אָחִי. וְאִם תֹּאמַר קְרוֹבִים אֲחֵרִים סְתָם נִקְרָאִים אַחִים - מִיַּד עֵשָׂו. מָה הַטַּעַם? בִּשְׁבִיל לְפָרֵשׁ הַדָּבָר כָּרָאוּי. וְאִם תֹּאמַר, אֲנִי לָמָּה אֶצְטָרֵךְ? כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבוֹא וְהִכַּנִי. כְּדֵי לְהִוָּדַע דָּבָר לְמַעְלָה וּלְפָרְשׁוֹ כָּרָאוּי, וְלֹא יַסְתִּיר הַדָּבָר."],[5,"","וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב עִמָּךְ וְגוֹ'. וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב, מַה זֶּה וְאַתָּה? כְּמוֹ שֶׁנֶּאֱמַר (נחמיה ט) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. אַף כָּאן וְאַתָּה אָמַרְתָּ."],[6,"","בֹּא רְאֵה, דָּוִד הַמֶּלֶךְ אָמַר, (תהלים יט) יִהְיוּ לְרָצוֹן אִמְרֵי פִי, אֵלּוּ דְּבָרִים שֶׁהִתְפָּרְשׁוּ. וְהֶגְיוֹן לִבִּי - אֵלּוּ דְּבָרִים נִסְתָּרִים שֶׁלֹּא יָכוֹל בֶּן אָדָם לְפָרְשָׁם בְּפִיו, זֶהוּ הִגָּיוֹן, שֶׁהוּא בַּלֵּב, שֶׁלֹּא יָכוֹל לְהִתְפָּרֵשׁ."],[7,"","וְעַל זֶה צָרִיךְ הַדָּבָר לְהִתְפָּרֵשׁ בַּפֶּה, וְדָבָר שֶׁתָּלוּי בַּלֵּב, וְהַכֹּל סוֹד הוּא. אֶחָד כְּנֶגֶד דַּרְגָּה תַּחְתּוֹנָה, וְאֶחָד כְּנֶגֶד דַּרְגָּה עֶלְיוֹנָה. דָּבָר שֶׁהִתְפָּרֵשׁ, כְּנֶגֶד דַּרְגָּה תַּחְתּוֹנָה שֶׁהִצְטָרֵךְ לְהִתְפָּרֵשׁ. אוֹתוֹ שֶׁתָּלוּי בַּלֵּב הוּא כְּנֶגֶד דַּרְגָּה פְּנִימִית יוֹתֵר, וְהַכֹּל הוּא כְּאֶחָד. וְעַל זֶה אָמַר יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךְ וְגוֹ'."],[8,"","כְּמוֹ זֶה אָמַר יַעֲקֹב. בַּתְּחִלָּה פֵּרַשׁ הַדָּבָר כָּרָאוּי, וְאַחַר כָּךְ הִסְתִּיר הַדָּבָר שֶׁתָּלוּי בְּהֶגְיוֹן הַלֵּב שֶׁלֹּא צָרִיךְ לְפָרֵשׁ, שֶׁכָּתוּב (בראשית לב) וְשַׂמְתִּי אֶת זַרְעֲךְ כְּחוֹל הַיָּם אֲשֶׁר לֹא יִסָּפֵר מֵרֹב. כָּאן הוּא דָבָר הַתָּלוּי בַּלֵּב שֶׁלֹּא צָרִיךְ לְפָרֵשׁ, וְכֵן צָרִיךְ כְּמוֹ שֶׁאָמַרְנוּ, כְּדֵי לְיַחֵד יִחוּד שָׁלֵם כָּרָאוּי. אַשְׁרֵי הַצַּדִּיקִים שֶׁיּוֹדְעִים לְסַדֵּר שֶׁבַח רִבּוֹנָם כָּרָאוּי וּלְבַקֵּשׁ בַּקָּשָׁתָם, וְלָכֵן כָּתוּב (ישעיה מט) וַיּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. (ס\"א כתוב גם את השני גם את השלישי וגו', שלש פעמים גם, רמז (ג\"ם ראשי תבות, ' גואל משה, גואל מרדכי, גואל משיח) לשלש גאלות על ידי שלשה צדיקים, משה מרדכי משיח, שעתיד לגאלנו בקרוב)."],[9,"","וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים צא) לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה בְּכָל יוֹם וָיוֹם מַעֲשֵׂהוּ הָרָאוּי לוֹ, וַהֲרֵי פֵּרְשׁוּהָ. וְנִתְבָּאֵר, (ואם תאמר) בַּיּוֹם הָרְבִיעִי עָשָׂה מְאוֹרוֹת, וְאָז נִבְרְאָה הַלְּבָנָה חֲסֵרָה, אוֹר שֶׁהִקְטִינָה עַצְמָהּ, וּמִשּׁוּם שֶׁהִיא מְאֹרֹת חָסֵר וָא\"ו, נִתַּן מָקוֹם לִשְׁלֹט כָּל הָרוּחוֹת וְהַשֵּׁדִים וְרוּחוֹת סְעָרָה וּמַזִּיקִים וְכָל רוּחוֹת הַטֻּמְאָה."]]],[["כֻּלְּהוּ סָלְקִין וְשָׁאטִין בְּעַלְמָא לְאַסְטָאָה, וְאִתְמַנּוּן בְּדוּכְתֵּי דְּאִתְחֲרִיבוּ, וּבְחַקְלִין תַּקִּיפִין וּבְמַדְבְּרִין חֲרִיבִין. וְכֻלְּהוּ מִסִּטְרֵי רוּחַ מְסָאֲבָא. וְהָא אִתְּמָר דְּהָא רוּחַ מְסָאֲבָא דְאַתְיָא מִנָּחָשׁ עֲקִימָאָה אִיהוּ רוּחַ מְסָאֲבָא מַמָּשׁ. וְאִיהוּ אִתְמַנָּא בְּעַלְמָא לְאַסְטָאָה בַּר נָשׁ לְגַבֵּיהּ, וְעַל דָּא יֵצֶר הָרָע שַׁלִּיט בְּעַלְמָא.","וְאִיהוּ אִתְמַנֵּי לְגַבַּיְיהוּ דִבְנִי נָשָׁא וְאִשְׁתַּכַּח עִמְּהוֹן. וּבַעֲקִימוּ וּבְתַסְקוּפִין אָתֵי לְגַבַּיְיהוּ לְאַסְטָאָה לוֹן מֵאָרְחוֹי קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַסְטֵי לְאָדָם קַדְמָאָה וְגָרִים מוֹתָא לְכָל עַלְמָא, הָכִי נָמֵי אַסְטֵי לְהוּ לִבְנֵי נָשָׁא וְגָרִים לוֹן לְאִסְתָּאֲבָא.","וּמַאן דְּאָתֵי לְאִסְתָּאֲבָא אִיהוּ מָשִׁיךְ עֲלֵיהּ הַהוּא רוּחַ מְסָאֲבָא וְאִתְדַּבֵּיק בַּהֲדֵיהּ, וְכַמָּה אִינוּן דִּזְמִינִין לְסָאֲבָא לֵיהּ וּמְסָאֲבִין לֵיהּ, וְאִיהוּ מְסָאָב, וְסָאֳבִין לֵיהּ בְּהַאי עַלְמָא וּבְהַהוּא עַלְמָא וְהָא אִתְּמָר.","וּבְשַׁעֲתָא דְּאָתֵי בַּר נָשׁ לְאִתְדַּכָאָה, הַהוּא רוּחַ מְסָאֲבָא אִתְכַּפְיָיא קַמֵּיהּ וְלָא יָכִיל לְשַׁלְטָאָה עֲלוֹי, וּכְדֵין כְּתִיב, (תהילים צ״א:י׳) לא תְאֻנֶּה אֵלֶיךָ רָעָה וְנֶגַע לא יִקְרַב בְּאָהֳלֶךָ. אָמַר (ס\"א כדאמר) רַבִּי יוֹסֵי לא תְאֻנֶּה אֵלֶיךָ רָעָה, דָּא לִילִית, וְנְגַע לֹא יִקְרַב בְאָהֳלֶךָ, אִלֵּין שְׁאָר מַזִּיקִין, וְהָא אוּקְמוּהָ וְאִתְּמָר.","רִבִּי אֶלְעָזָר אָמַר הָא אֲמָרָן דְּלָא יִפּוּק בַּר נָשׁ יְחִידָאָה בְּלֵילְיָא, וְכָל שֶׁכֵּן בְּזִמְנָא דְסִיהֲרָא אִתְבְּרִיאַת וְהֲוָה (והיא) חֲסֵרָה, וְאוּקְמוּהָ. דְּהָא כְּדֵין רוּחָא מְסָאֲבָא שָׁלְטָא, וְדָא הוּא רוּחַ רָעָה, מַאן רָעָה, דָּא חִוְיָא בִישָׁא. וְנְגַע, דָּא הוּא מַאן דְּרָכִיב עַל חִוְיָא. רָעָה וְנֶגַע כְּחֲדָא אִינוּן.","וְאַף עַל גַּב דְּתָנִינָן, דְּנְגַע, אִלֵּין נִגְעֵי בְּנֵי אָדָם דְּנַפְקוּ מֵאָדָם. דְּהָא כָּל אִינוּן שְׁנִין דְּלָא קָרִיב אָדָם עִם אִתְּתֵיהּ, רוּחֵי מְסָאֲבֵי הֲווּ קָא אַתְיָין וּמִתְחַמְמָן מִנֵּיהּ וְאוֹלִידָן מִנֵּיהּ וְהַנֵּי אִקְרוּן נִגְעֵי בְּנֵי אָדָם.","וְהָא אִתְּמָר, דְּכַד בַּר נָשׁ בְּחֶלְמֵיהּ וְלָא שַׁלִּיט בְּגוּפֵיהּ וְגוּפָא אִשְׁתַּכַּךְ, רוּחַ מְסָאֲבָא אַתְיָיא וְשַׁרְיָא עֲלֵיהּ. וְאִית זִמְנִין דְּרוּחֵי נוּקְבִין מְסָאֲבִין אַתְיָין וְקָרְבָן בַּהֲדֵיהּ, וּמָשְׁכִין לֵיהּ בַּהֲדַיְיהוּ וּמִתְחַמְמָן מִנֵּיהּ, וְאוֹלִידוּ לְבָתַר רוּחִין וּמַזִּיקִין (נגעי בני אדם נ\"א כגוונא בני נשא). וּלְזִמְנִין אִתְחַזְיָין כְּחֵיזוּ בְּנֵי נָשָׁא בַּר דְּלֵית לוֹן שַׂעֲרֵי בְּרֵישָׁא.","וּבְכֹלָּא אִית לֵיהּ לְבַר נָשׁ לְאִסְתַּמְּרָא מִקַּמַּיְיהוּ, בְּגִין דִּיהַךְ בְּאָרְחֵי דְאוֹרַיְיתָא וְלָא יִסְתָּאַב בַּהֲדַיְיהוּ. דְּהָא לֵית לָךְ מַאן דְּנָאִים בְּלֵילְיָא בְּעַרְסֵיהּ, דְּלָא טָעִים טַעְמָא דְמוֹתָא וְנָפְקַת נִשְׁמָתֵיהּ מִנֵּיהּ. וְכֵיוָן דְּאִשְׁתָּאַר גּוּפָא בְּלָא נִשְׁמָתָא קַדִּישָׁא, רוּחַ מְסָאֲבָא זַמִּין וְשַׁרְיָא עֲלֵיהּ וְאִסְתָּאַב. וְהָא אוֹקִימְנָא מִלָּה, דְּלֵית לֵיהּ לְבַר נָשׁ לְאַעֲבָרָא יְדוֹי עַל עֵינוֹי בְּצַפְרָא. בְּגִין דְּהָא רוּחָא מְסָאֲבָא שַׁרְיָא עֲלַיְיהוּ וְכוּ' וְהָא אִתְּמָר.","תָּא חֲזֵי, דְּהָא יַעֲקֹב אַף עַל גַּב דְּאִתְרָחִים קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּאִשְׁתָּאַר בִּלְחוֹדוֹי, רוּחָא אָחֳרָא הֲוָה זַמִין לְאִזְדַּוְּוגָא בַּהֲדֵיהּ.","רִבִּי שִׁמְעוֹן אָמַר, תָּא חֲזֵי, מַה כְּתִיב בֵּיהּ בְּהַהוּא רָשָׁע דְּבִלְעָם, וַיֵּלֶךְ שֶׁפִי, מַהוּ שֶׁפִי, יְחִידָאי. כְּמָה דְאַתְּ אָמֵר שְׁפִיפוֹן עֲלֵי אֹרַח, כְּהַאי חִוְיָא דְּאָזִיל יְחִידָאי וְכָמִין עֲלֵי אָרְחִין וּשְׁבִילִין. הָכִי נָמֵי בִּלְעָם הֲוָה אָזִיל יְחִידָאי. מַאי טַעְמָא בְּגִין לְאַמְשָׁכָא עֲלֵיהּ רוּחָא מְסָאֲבָא. דְּכָל מַאן דְּאָזִיל יְחִידָאי בִּזְמַנִּין יְדִיעָן, אֲפִילּוּ בְּמָתָא, בְּאַתְרִין יְדִיעָן. מָשִׁיךְ עֲלֵיהּ רוּחָא מְסָאֲבָא.","בְגִין כָּךְ, בְּכָל זִמְנָא לָא יְהַךְ בַּר נָשׁ יְחִידָאי בְּאָרְחָא בְמָתָא אֶלָּא בְּאֲתַר דִּבְנֵי נָשָׁא אָזְלִין וְתָבִין וּמִשְׁתַּכְּחִין תַּמָּן, וְעַל דָּא לָא יְהַךְ בַּר נָשׁ יְחִידָאי בְּלֵילְיָא הוֹאִיל וּבְנֵי נָשָׁא לָא מִשְׁתַּכְּחֵי, וְהַיְינוּ טַעְמָא דְּלָא תָלִין נִבְלָתוֹ. דְּלָא לְקַיְימָא גּוּפָא מִיתָא בְּלָא רוּחָא עַל אַרְעָא בְּלֵילְיָא. בְּגִין כָּךְ הַהוּא רָשָׁע דְּבִלְעָם הֲוָה אָזִיל יְחִידָאי כְּהַאי נָחָשׁ כְּמָה דְאוּקְמוּהָ."],[[0,"כלהו סלקין ושאטין וכו':","כולם עולים ומשוטטים בעולם להשטות בני אדם, ונתמנו במקומות שנחרבו מישוב, ובשדות קשים, שאינם ראויים לזריעה, ובמדבריות חרבים. וכולם מצד רוח הטומאה, ולמדנו, כי רוח הטומאה הבא מנחש עקלתון, שהוא לילית, הוא רוח הטומאה ממש, והוא נתמנה בעולם, להשטות אנשים אליו. וע\"כ היצר הרע שולט בעולם."],[1,"ואיהו אתמני לגבייהו וכו':","והוא נתמנה אצל בני אדם ונמצא עמהם, ובערמה ובעלילות הוא בא אליהם, להשטות אותם מדרכי הקב\"ה. כמו שהשטה את אדם הראשון וגרם מות לכל העולם, כן הוא משטה בני אדם וגורם להם להטמא."],[2,"ומאן דאתי לאסתאבא וכו':","ומי שבא להטמא מושך עליו את רוח הטומאה ההוא, ומתדבק עמו. וכמה הם, רוחות הטומאה, הנועדים לטמא אותו, ומטמאים אותו והוא נטמא. ומטמאים אותו בעולם הזה ובעולם ההוא. וכבר נתבאר."],[3,"ובשעתא דאתי וגו':","ובשעה שאדם בא להטהר, אותו רוח הטומאה נכנע מפניו, ואינו יכול לשלוט עליו. ואז כתוב, לא תאנה אליך רעה וגו'. אמר ר' יוסי לא תאנה אליך רעה, זו היא לילית. ונגע לא יקרב באהלך, אלו הם שאר מזיקים. וכבר בארוהו, ולמדנו."],[4,"ר' אלעזר אמר וכו':","רא\"א, הרי אמרו, שלא יצא אדם יחידי בלילה, ומכל שכן בזמן שהלבנה נבראה, והיא חסרה, שאינה מאירה במילואה, ובארוהו, כי אז רוח הטומאה שולט, וזהו רוח רעה. ושואל, מי הוא רוח \u0003רעה,\u0004 ומשיב, זה הוא הנחש הרע. \u0003ונגע,\u0004 זה הוא מי שרוכב על הנחש, שהוא סמאל, רעה ונגע הם כאחד."],[5,"ואע\"ג דתנינן וכו':","ואע\"פ שלמדנו, ש \u0003נגע\u0004 הוא נגעי בני אדם שנולדו מאדם. כי אלו השנים שלא קרב אדם אל אשתו, רוחות הטומאה היו באות ונתחממו ממנו והולידו ממנו, ואלו נקראים נגעי בני אדם. פירוש. אע\"פ שלמדנו, שנגעים הם שדים שנולדו מאדם, מכל מקום אינו סותר את דברינו, שנגע הוא ס\"מ הרוכב על הנחש, כי ב' בחינות הם."],[6,"והא אתמר, דכד וכו':","והרי למדנו, כשהאדם בחלומו, ואינו שולט בגופו, והגוף נדם, רוח הטומאה בא ושורה עליו. ויש לפעמים, שרוחות נקבות טמאות באות וקרבות אליו, ומושכות אותו עמהן. ומתחממות ממנו, ומולידות אחר כך, רוחות ומזיקים ולפעמים נראים כמראה של בני אדם, אלא שאין להם שערות בראש."],[7,"ובכלא אית ליה וכו':","ומכל וכל יש לו לאדם להשמר מפניהם, כדי ללכת בדרכי התורה, ולא יטמא עמהם, כי אין לך מי שישן בלילה על מטתו, שלא יטעם טעם מיתה, ונשמתו יוצאת ממנו, וכיון שנשאר הגוף בלי הנשמה הקדושה, רוח הטומאה נועד, ושורה עליו, והוא נטמא. וכן בארנו הדבר, שאין לו לאדם להעביר ידיו על עיניו בבוקר, משים שרוח הטומאה שורה עליו וכו' וכבר למדנו זה."],[8,"תא חזי דהא יעקב וכו':","בוא וראה, כי יעקב, אע\"פ שהיה אהוב לפני הקב\"ה, מכל מקום כיון שנשאר לבדו, רוח אחר היה נועד להתחבר עמו."],[9,"רבי שמעון אמר וכו':","רש\"א בוא וראה מה כתוב בו באותו רשע בלעם, וילך שפי. מהו \u0003שפי\u0004 יחידי. הוא כמו שאתה אומר, \u0003שפיפון\u0004 עלי אורח. דהיינו כאותו הנחש ההולך יחידי, ואורב על הדרכים והשבילים, כן בלעם היה הולך יחידי. מהו הטעם. הוא, כדי להמשיך על עצמו רוח הטומאה, שכל מי שהולך יחידי בזמנים ידועים, אפילו בעיר במקומות ידועים, הוא מושך על עצמו את רוח הטומאה."],[10,"בג\"כ בכל זמנא וכו':","משום זה בכל הזמנים לא ילך אדם יחידי בדרך, ובעיר, אלא במקום שבני אדם הולכים ושבים ונמצאים שם. ועל כן לא ילך אדם יחידי בלילה. משום שלא נמצאים אז בני אדם. והוא הטעם, שלא תלין נבלתו על העץ, כדי שלא להחזיק בארץ גוף מת בלי רוח, בלילה. משום זה, אותו רשע בלעם, היה הולך יחידי כנחש הזה, כמו שבארוהו."]],[[0,"","כֻּלָּם עוֹלִים וּמְשׁוֹטְטִים בָּעוֹלָם לְהַסְטוֹת, וְנִתְמַנּוּ בִּמְקוֹמוֹת חֲרֵבִים וּבְשָׂדוֹת חֲזָקִים וּבְמִדְבָּרוֹת חֲרֵבִים, וְכֻלָּם מִצַּד רוּחַ הַטֻּמְאָה. וַהֲרֵי נִתְבָּאֵר שֶׁהֲרֵי רוּחַ הַטֻּמְאָה בָּאָה שֶׁבָּאָה מִנָּחָשׁ הָעֲקַלָּתוֹן, הוּא רוּחַ טֻמְאָה מַמָּשׁ, וְהוּא הִתְמַנָּה בָּעוֹלָם לְהַסְטוֹת בֶּן אָדָם אֵלָיו, וְעַל זֶה יֵצֶר הָרָע שׁוֹלֵט בָּעוֹלָם."],[1,"","וְהוּא הִתְמַנָּה אֵצֶל בְּנֵי אָדָם וְנִמְצָא עִמָּם, וּבְעַקְמוּמִיּוֹת וּבְתַחְבּוּלוֹת בָּא אֲלֵיהֶם לְהַסְטוֹתָם מִדַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כְּמוֹ שֶׁהִסְטָה אֶת אָדָם הָרִאשׁוֹן וְגָרַם מָוֶת לְכָל הָעוֹלָם, כָּךְ גַּם מַסְטֶה בְּנֵי אָדָם וְגוֹרֵם לָהֶם לְהִטָּמֵא."],[2,"","וּמִי שֶׁבָּא לְהִטָּמֵא, מוֹשֵׁךְ עָלָיו אוֹתוֹ רוּחַ טֻמְאָה וְנִדְבָּק עִמּוֹ. וְכַמָּה הֵם שֶׁמְּזֻמָּנִים לְטַמֵּא אוֹתוֹ, וּמְטַמְּאִים אוֹתוֹ וְהוּא טָמֵא, וּמְטַמְּאִים אוֹתוֹ בָּעוֹלָם הַזֶּה וּבְאוֹתוֹ עוֹלָם, וַהֲרֵי נִתְבָּאֵר."],[3,"","וּבְשָׁעָה שֶׁבָּא בֶּן אָדָם לְהִטָּהֵר, אוֹתוֹ רוּחַ טֻמְאָה נִכְפֶּה לְפָנָיו וְלֹא יָכוֹל לִשְׁלֹט עָלָיו, וְאָז כָּתוּב לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. אָמַר (כשאמר) רַבִּי יוֹסֵי, לֹא תְאֻנֶּה אֵלֶיךְ רָעָה - זוֹ לִילִית. וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ - אֵלּוּ שְׁאָר מַזִּיקִים, וַהֲרֵי פֵּרְשׁוּהָ וְנִתְבָּאֵר."],[4,"","רַבִּי אֶלְעָזָר אָמַר, הֲרֵי אָמַרְנוּ שֶׁלֹּא יֵצֵא אָדָם יְחִידִי בַּלַּיְלָה, וְכָל שֶׁכֵּן כְּשֶׁהַלְּבָנָה נִבְרְאָה וְהָיְתָה חֲסֵרָה, וּבֵאֲרוּהָ שֶׁהֲרֵי אָז רוּחַ טֻמְאָה שׁוֹלֶטֶת, וְזוֹהִי רוּחַ רָעָה. מִי רָעָה? זֶה נָחָשׁ הָרָע, וְנֶגַע זֶהוּ מִי שֶׁרוֹכֵב עַל הַנָּחָשׁ. רָעָה וְנֶגַע הֵם כְּאֶחָד."],[5,"","וְאַף עַל גַּב שֶׁשָּׁנִינוּ שֶׁנֶּגַע אֵלּוּ נִגְעֵי בְּנֵי אָדָם שֶׁיָּצְאוּ מֵאָדָם, שֶׁהֲרֵי כָּל אוֹתָן שָׁנִים שֶׁלֹּא קָרַב אָדָם לְאִשְׁתּוֹ, רוּחוֹת טֻמְאָה הָיוּ בָּאוֹת וּמִתְחַמְּמוֹת מִמֶּנּוּ וּמוֹלִידוֹת מִמֶּנּוּ, וְאֵלֶּה נִקְרָאִים נִגְעֵי בְּנֵי אָדָם."],[6,"","וַהֲרֵי נֶאֱמַר, שֶׁכְּשֶׁבֶּן אָדָם בַּחֲלוֹמוֹ וְלֹא שׁוֹלֵט בְּגוּפוֹ וְהַגּוּף שׁוֹכֵךְ, רוּחַ טֻמְאָה בָּאָה וְשׁוֹרָה עָלָיו, וְלִפְעָמִים רוּחוֹת נְקֵבוֹת טְמֵאוֹת בָּאוֹת וּקְרֵבוֹת אֵלָיו וּמוֹשְׁכוֹת אוֹתוֹ אֲלֵיהֶן וּמִתְחַמְּמוֹת מִמֶּנּוּ, וּמוֹלִידוֹת אַחַר כָּךְ רוּחוֹת וּמַזִּיקִים (נגעי בני אדם, כמו בני אדם), וְלִפְעָמִים נִרְאִים כְּמַרְאֵה בְּנֵי אָדָם, פְּרָט לְזֶה שֶׁאֵין לָהֶם שְׂעָרוֹת בָּרֹאשׁ."],[7,"","וּבַכֹּל יֵשׁ לָאָדָם לְהִשָּׁמֵר מִלִּפְנֵיהֶם כְּדֵי שֶׁיֵּלֵךְ בְּדַרְכֵי הַתּוֹרָה וְלֹא יִטָּמָא עִמָּם, שֶׁהֲרֵי אֵין לְךְ מִי שֶׁיָּשֵׁן בַּלַּיְלָה בְּמִטָּתוֹ וְלֹא טוֹעֵם טַעַם מָוֶת וְיוֹצֵאת נִשְׁמָתוֹ מִמֶּנּוּ, וְכֵיוָן שֶׁנִּשְׁאָר הַגּוּף בְּלִי נְשָׁמָה קְדוֹשָׁה, רוּחַ טֻמְאָה זְמִינָה וְשׁוֹרָה עָלָיו וְנִטְמָא. וַהֲרֵי בֵּאַרְנוּ דָבָר, שֶׁאֵין לָאָדָם לְהַעֲבִיר יָדָיו עַל עֵינָיו בַּבּקֶר, מִשּׁוּם שֶׁהֲרֵי רוּחַ טֻמְאָה שׁוֹרָה עֲלֵיהֶם, וַהֲרֵי נִתְבָּאֵר."],[8,"","בֹּא רְאֵה שֶׁהֲרֵי יַעֲקֹב, אַף עַל גַּב שֶׁנֶּאֱהַב עַל יְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁנִּשְׁאַר לְבַדּוֹ, רוּחַ אַחֶרֶת נוֹעֲדָה לְהִזְדַּוֵּג עִמּוֹ."],[9,"","רַבִּי שִׁמְעוֹן אָמַר, בּא רְאֵה מַה כָּתוּב בּוֹ בְּבִלְעָם הָרָשָׁע, וַיֵּלֶךְ שֶׁפִי. מַהוּ שֶׁפִי? יְחִידִי, כְּמוֹ שֶׁנֶּאֱמַר שְׁפִיפוֹן עֲלֵי אֹרַח. כַּנָּחָשׁ הַזֶּה שֶׁהוֹלֵךְ יְחִידִי וְאוֹרֵב עַל דְּרָכִים וּשְׁבִילִים, כָּךְ גַּם בִּלְעָם הָיָה הוֹלֵךְ יְחִידִי. מָה הַטַּעַם? כְּדֵי לְהַמְשִׁיךְ עָלָיו רוּחַ טֻמְאָה. שֶׁכָּל מִי שֶׁהוֹלֵךְ יְחִידִי בִּזְמַנִּים יְדוּעִים אֲפִלּוּ בָּעִיר בִּמְקוֹמוֹת יְדוּעִים, מוֹשֵׁךְ עָלָיו רוּחַ טֻמְאָה."],[10,"","לָכֵן בְּכָל זְמַן לֹא יֵלֵךְ אָדָם יְחִידִי בַּדֶּרֶךְ וּבָעִיר, אֶלָּא בְּמָקוֹם שֶׁבְּנֵי אָדָם הוֹלְכִים וְשָׁבִים וְנִמְצָאִים שָׁם, וְעַל כֵּן לֹא יֵלֵךְ אָדָם יְחִידִי בַּלַּיְלָה, הוֹאִיל וּבְנֵי אָדָם לֹא נִמְצָאִים, וְהַיְנוּ הַטַּעַם שֶׁלֹּא תָלִין נִבְלָתוֹ, שֶׁלֹּא לְהַחֲזִיק גּוּף מֵת בְּלִי רוּחַ עַל הָאָרֶץ בַּלַּיְלָה. מִשּׁוּם כָּךְ אוֹתוֹ בִּלְעָם הָרָשָׁע הָיָה הוֹלֵךְ יְחִידִי כַּנָּחָשׁ הַזֶּה, כְּמוֹ שֶׁבֵּאֲרוּהוּ."]]],[["וַיֵּאָבֵק אִישׁ עִמּוֹ, מַאי וַיֵּאָבֵק. (גליון דאמר רבי יהושע בן לוי, מלמד דסליקו אבק ברגליהון עד כורסי יקרא. כתיב הכא בהאבקו עמו, וכתיב (נחום א׳:ג׳) אבק רגליו, וההוא מלאך שרו של עשו היה, ואיהו סמאל. בגין כך, דינו הוא שיעלה אבק דרגליו עד כסא הכבוד, שהוא מקום המשפט). רִבִּי שִׁמְעוֹן אָמַר מִן אָבָק. אָבָק טָפֵל לֶעָפָר, מַה בֵּין עָפָר לְאָבָק. דָּא אָבָק דְּאִשְׁתָּאַר מִן נוּרָא וְלָא עֲבַד אִיבִּין (בעלמא) לְעָלְמִין. עָפָר דְכָל אִיבִּין נָפְקֵי מִנֵּיהּ וְאִיהוּ כְּלָלָא בְּעֵילָא וְתַתָּא.","אָמַר רִבִּי יְהוּדָה אִי הָכִי מַאי (שמואל א ב׳:ח׳) מֵקִים מֵעָפָר דָּל. אָמַר לֵיהּ כְּמַשְׁמָעוֹ, אֲבָל בְּהַאי גַוְונָא מֵקִים מֵעָפָר דָּל, בְּגִין דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם, וּמֵהַהוּא עַפְרָא נָפַק דַּל דְּלֵית לֵיהּ כְּלוּם, וּמֵהַהוּא עָפָר כָּל אִיבִּין וְכָל טִיבוּ דְעַלְמָא נָפְקֵי מִנֵּיהּ. וּבֵיהּ אִתְעֲבִידוּ כָּל עוֹבָדִין דְּעַלְמָא כְּמָה דִכְתִיב, (קהלת ג׳:כ׳) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. וְתָנִינָן הַכֹּל הָיָה מִן הֶעָפָר וְאֲפִילּוּ גַּלְגַּל חַמָּה. אֲבָל אָבָק לָא עָבִיד פֵּירִין וְאִיבִּין (לעלמא) לְעָלְמִין, וּבְגִין כָּךְ וַיֵּאָבֵק אִישׁ, דְּאַתְיָא בְּהַהוּא אָבָק וּרְכִיב עֲלֵיהּ, בְּגִין לְקַטְרְגָא לֵיהּ לְיַעֲקֹב.","עַד עֲלוֹת הַשָּׁחַר, דְּאִתְעֲבַר שׁוּלְטָנוּתֵיהּ וְאִתְחַלַּף. וְכָךְ הוּא לְזִמְנָא דְאָתֵי, בְּגִין דְּגָלוּתָא הַשְׁתָּא כְּלֵילְיָא דַמְיָא, וְאִיהוּ לֵילְיָא. וְשָׁלְטָא הַהוּא אָבָק עַל יִשְׂרָאֵל וְאִינוּן שְׁכִיבֵי לְעַפְרָא (אוחרא), עַד דְּיִסְתַּלַּק נְהוֹרָא וְיִתְנְהַר יְמָמָא. וּכְדֵין יִשְׁלְטוּן יִשְׂרָאֵל וּלְהוֹן יִתְיָהִיב מַלְכוּתָא דְּאִינוּן קַדִּישֵׁי עֶלְיוֹנִין. כְּמָה דְאַתְּ אָמֵר, (דניאל ז׳:כ״ז) וּמַלְכוּתָא וְשָׁלְטָנָא וּרְבוּתָא דִי מַלְכְוָת תְּחוֹת כָּל שְׁמַיָא יְהִיבַת לְעַם קַדִּישֵׁי עֶלְיוֹנִין מַלְכוּתֵהּ מַלְכוּת עָלַם וְכֹל שָׁלְטָנַיָא לֵהּ יִפְלְחוּן וְיִשְׁתַּמְּעוּן:","וַיֹּאמֶר שַׁלְחֵנִי כִּי עָלָה הַשָּׁחַר וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךָ כִּי אִם בֵּרַכְתָּנִי. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר השירים ו׳:י׳) מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר יָפָה כַלְּבָנָה בָּרָה כַּחַמָּה אֲיֻמָּה כַּנִּדְגָלוֹת. הַאי קְרָא אוּקְמוּהָ וְאִתְּמָר, אֲבָל מִי זֹאת הַנִּשְׁקָפָה, אִלֵּין אִינוּן יִשְׂרָאֵל בְּזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לוֹן וְיָפִיק לוֹן מִן גָּלוּתָא. כְּדֵין יִפְתַּח לוֹן פִּתְחָא דִּנְהוֹרָא (דהיא) דַּקִּיק זְעֵיר. וּלְבָתַר פִּתְחָא אַחֲרִינָא דְּאִיהוּ רַב מִינֵיהּ, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא יִפְתַּח לוֹן תַּרְעִין עִלָּאִין פְּתִיחִין לְאַרְבַּע רוּחֵי עָלְמָא.","וְכֵן כָּל מַה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל וּלְצַדִּיקַיָיא דִּי בְּהוּ, הָכִי כֻּלְּהוּ וְלָאו בְּזִמְנָא חָדָא. לְבַר נָשׁ דְּאִתְיְהִיב בַּחֲשׁוֹכָא וְדִיּוּרֵיהּ הֲוָה בַּחֲשׁוֹכָא תָּדִיר, כַּד יִבְעוּן לְאַנְהָרָא לֵיהּ, בַּעְיָין לְאִפְתְּחָא לֵיהּ נְהוֹרָא זְעֵירְתָּא כְּעֵינָא דְּמַחֲטָא, וּלְבָתַר רַב מִנֵּיהּ, וּכְדֵין בְּכָל זִמְנָא עַד דְּיִנְהֲרוּן לֵיהּ כָּל נְהוֹרָא כְּדְקָא יְאוּת.","כָּךָ אִינוּן יִשְׂרָאֵל כְּמָה דְאַתְּ אָמֵר, (שמות כ״ג:ל׳) מְעַט מְעַט אֲ גרַשֶׁנּוּ מִפָּנֶיךָ עַד אֲשֶׁר תִּפְרֶה וְגו'. וְכֵן לְמַאן דְּאָתֵי אַסְוָותָא לָאו אִיהוּ בְּשַׁעְתָּא חָדָא, אֶלָּא זְעֵיר זְעֵיר עַד דְּיִתְתַּקַּף. אֲבָל לְעֵשָׂו לָאו הָכִי, אֶלָּא בְּזִמְנָא חָדָא נָהִיר לֵיהּ וְאִתְאֲבִיד מִנֵּיהּ זְעֵיר זְעֵיר. (ולזמנא דאתי לאומות עובדי עבודת כוכבים ומזלות (ישעיהו מ״ב:י״ג) יי כגבור יצא) עַד דְּיִתְתַּקְפוּן יִשְׂרָאֵל וִישֵׁיצוּן (וישבון) לֵיהּ מִכֹּלָּא, מֵעַלְמָא דֵין וּמֵעַלְמָא דְאָתֵי. וּבְגִין דְּנָהִיר בְּשַׁעְתָּא חָדָא, הֲוָה לֵיהּ שֵׁצִיאוּ מִכֹּלָּא. אֲבָל יִשְׂרָאֵל נְהוֹרָא דִלְהוֹן זְעֵיר זְעֵיר, עַד דְּיִתְתַּקְפוּן וְיַנְהִיר לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין.","וְכֹלָּא שָׁאֲלֵי לוֹן וְאָמְרֵי מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר, אִיהוּ קַדְרוּתָא דְצַפְרָא, וְדָא אִיהוּ נְהוֹרָא דָּקִיק. וּלְבָתַר יָפָה כַלְּבָנָה, בְּגִין דְּסִיהֲרָא נְהוֹרָא דִילָהּ נָהִיר יַתִּיר מִשַּׁחַר. וּלְבָתַר בָּרָה כַּחַמָּה, בְּגִין דִּנְהוֹרֵיהּ תַּקִּיף וְנָהִיר יַתִּיר מִסִּיהֲרָא. וּלְבָתַר אֲיֻמָּה כַּנִּדְגָלוֹת, תַּקִּיפָא בִּנְהוֹרָא תַּקִּיף כְּדְקָא יְאוּת.","תָּא חֲזֵי, בְּעוֹד דְּאִתְחֲשַׁךְ יְמָמָא וְאִתְכַּסְיָא נְהוֹרָא וְאָתֵי צַפְרָא, יִתְנְהִיר בְּקַדְמִיתָא זְעֵיר זְעֵיר עַד דְּיִתְרַבֵּי נְהוֹרָא כְּדְקָא יְאוּת. דְּהָא כֵּיוָן דְּקוּדְשָׁא בְּרִיךְ הוּא יִתְעַר לְאַנְהָרָא לָהּ לִכְנֶסֶת יִשְׂרָאֵל, יִתְנְהִיר בְּקַדְמִיתָא כְּמוֹ שָׁחַר דְאִיהִי אוּכְמָא. וּלְבָתַר יָפָה כַלְּבָנָה, וּלְבָתַר בָּרָה כַּחַמָּה. וּלְבָתַר אֲיֻמָּה כַּנִּדְגָּלוֹת כְּמָה דְאִתְּמָר."],[[0,"ויאבק איש עמו:","שואל מהו ויאבק, רבי שמעון אמר, מן אבק בא אליו. כמ\"ש לפנינו. אבק טפל אל עפר. ושואל, מה בין עפר לאבק. ומשיב, \u0003אבק\u0004 הוא, שנשאר מן האש, כלומר, מה שנשאר מדבר הנשרף באש נק' אבק, ואינו עושה פירות לעולם, עפר הוא, שכל הפירות יוצאים ממנו, והוא כלל הכל, הן למעלה והן למטה. פירוש, נוקבא דז\"א נקראת \u0003עפר,\u0004 והיא כלל כל העולמות וכל מה שבבי\"ע תולדותיה. \u0003ואבק\u0004 הוא נוקבא של סמאל, שהוא אל אחר, שאינו עושה פירות, וע\"כ מכונה אבק."],[1,"אמר ר' יהודה וכו':","אר\"י, אם כן, אם עפר הוא חשוב כל כך, מה פירושו של, מקים מעפר דל. אמר לו כמשמעו, שהוא שפלות, אבל באופן זה, מקים מעפר דל, משום שהנוקבא, המכונה עפר, אין לה מעצמה ולא כלום, אלא שמקבלת הכל מז\"א ומאותו העפר, שאין לו כלום, בזמן שאינה בזווג עם ז\"א, יוצא הדל שאין לו כלום. ומאותו העפר, בזמן שהוא בזווג עם ז\"א כל הפירות וכל הטוב שבעולם יוצאים ממנו, ובו נעשו כל המעשים שבעולם, כמו שכתוב, הכל היה מן העפר והכל שב אל העפר. ולמדנו, הכל היה מן העפר, ואפילו גלגל חמה. אבל \u0003אבק\u0004 אינו עושה פירות ואבים לעולם, ועל כן, ויאבק איש, דהיינו סמאל. שהוא בא באותו אבק, דהיינו הנוקבא שלו, ורוכב עליו, כדי לקטרג על יעקב."],[2,"עד עלות השחר וכו':","שאז ממשלתו עברה וחלפה. וכך הוא לעתיד לבא. כי הגלות דומה עתה ללילה, והוא לילה, כלומר שהוא חשך, ואותו אבק שולט על ישראל, והם מושלכים לעפר, עד שיתעלה האור ויאיר היום, ואז ישלטו ישראל ותנתן להם המלכות, כי יהיו קדושי עליון, כמו שאתה אומר, ומלכותא ושלטנא ורבותא וגו'."],[3,"ויאמר שלחני וגו' ברכתני:","ר' יהודה פתח ואמר, מי זאת הנשקפה כמו שחר וגו'. מקרא זה בארוהו ולמדנו. אבל, \u0003מי זאת הנשקפה\u0004 אלו הם ישראל. בזמן שהקב\"ה יקים אותם ויוציאם מן הגלות. אז יפתח להם פתח אור דק מדק וקטן מאד. ואחר כך יפתח להם פתח אחר מעט גדול ממנו עד שהקב\"ה יפתח להם את השערים העליונים הפתוחים לארבע רוחות העולם. פירוש שלא תתגלה ישועתם בבת אחת. אלא בדומה אל \u0003שחר,\u0004 שהולך ואור עד נכון היום. וע\"כ נאמר אז עליהם, מי זאת הנשקפה כמו \u0003שחר\u0004 וגו'."],[4,"וכן כל מה דעביד וכו':","וכן כל מה שעושה הקב\"ה לישראל ולצדיקים שבהם, הכל כן הוא, שמושיעם לאט לאט, ולא בפעם אחת. בדומה לאדם הנתון בחשך. ותמיד בחשך היה משכנו, שבעת שרוצים להאיר לו, צריכים לפתוח לו תחילה, אור קטן כפתחו של מחט, ואחר כך מעט גדול ממנו, וכן בכל פעם יותר, עד שמאירים לו כל האור כראוי."],[5,"כך אינון ישראל וכו':","כך הם ישראל, כמש\"א, מעט מעט אגרשנו מפניך וגו'. וכן למי שבאה לו רפואה, אינה באה בשעה אחת, אלא שבאה מעט מעט עד שמתרפא. אבל לעשו אינו כן, אלא בבת אחת האיר לו, ונאבד ממנו מעט מעט עד שיתחזקו ישראל, ויכריתו אותו מכל, העולם הזה ומהעולם הבא. ומשום שהאיר לו בתחילה בפעם אחת, היה לו כליון מכל, אבל ישראל האור שלהם הולך ואור מעט מעט, עד שיתחזקו, ויאיר להם הקב\"ה לעולם."],[6,"וכלא שאלי לון וכו':","והכל שואלים אליהם ואומרים. \u0003מי זאת הנשקפה כמו שחר,\u0004 שחר, הוא שחרית הבוקר, דהיינו החשכה המתחזקת שמטרם אור הבוקר. וזה הוא אור הדק מדק הנזכר, ואחר כך, \u0003יפה כלבנה,\u0004 כי הלבנה, אורה מרובה יותר משחר. ואחר כך \u0003ברה כחמה,\u0004 אשר אורה חזק ומאיר יותר מלבנה. ואחר כך, \u0003איומה כנדגלות,\u0004 שפירושה, חזקה באור חזק כראוי. \u0003כנדגלות,\u0004 ה\"ס ד' דגלים הכוללים י\"ב שבטים, שהם תכלית מילואה של הנוקבא."],[7,"ת\"ח בעוד וכו':","בוא וראה, בעוד שחשך היום, והאור מכוסה, והבוקר בא להאיר, יאיר מתחילה מעט מעט עד שמתרבה האור כראוי, כן כאשר הקב\"ה יתעורר להאיר לכנסת ישראל, יאיר מתחילה כמו שחר, שהוא שחור, ואחר כך יפה כלבנה, ואח\"כ ברה כחמה, ואח\"כ איומה כנדגלות, כמו שאמרנו."]],[[0,"","וַיֵּאָבֵק אִישׁ עִמּוֹ. מַה זֶּה וַיֵּאָבֵק? (שאמר רבי יהושע בן לוי, מלמד שהעלו אבק ברגליהם עד כסא הכבוד, כתוב כאן בהאבקו עמו, וכתוב (נחום א) אבק רגליו, ואותו מלאך שרו של עשו היה, והוא סמא\"ל, לכן דינו הוא שיעלה אבק רגליו עד כסא הכבוד, שהוא מקום המשפט). רַבִּי שִׁמְעוֹן אָמַר, מִן אָבָק. אָבָק טָפֵל לֶעָפָר. מַה בֵּין עָפָר לְאָבָק? זֶה אָבָק שֶׁנִּשְׁאָר מֵהָאֵשׁ וְלֹא עוֹשֶׂה פֵּרוֹת (בעולם) לְעוֹלָמִים, עָפָר שֶׁכָּל הַפֵּרוֹת יוֹצְאִים מִמֶּנּוּ, וְהוּא כְּלָל שֶׁלְּמַעְלָה וּמַטָּה."],[1,"","אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, מַה זֶּה מֵקִים מֵעָפָר דָּל? אָמַר לוֹ, כְּמַשְׁמָעוֹ, אֲבָל בְּגָוֶן זֶה מֵקִים מֵעָפָר דַּל מִשּׁוּם שֶׁאֵין לוֹ מֵעַצְמוֹ כְּלוּם, וּמֵאוֹתוֹ עָפָר יָצָא דַל שֶׁאֵין בּוֹ כְּלוּם, וּמֵאוֹתוֹ עָפָר כָּל הַפֵּרוֹת וְכָל טוּב הָעוֹלָם יוֹצְאִים מִמֶּנּוּ וּבוֹ נַעֲשִׂים כָּל מַעֲשֵׂי הָעוֹלָם, כְּמוֹ שֶׁכָּתוּב (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. וְשָׁנִינוּ, הַכֹּל הָיָה מִן הֶעָפָר - אֲפִלּוּ גַּלְגַּל חַמָּה, אֲבָל אָבָק לֹא עוֹשֶׂה פֵּרוֹת וְנִצָּנִים (לעולם) לְעוֹלָמִים, וּמִשּׁוּם כָּךְ וַיֵּאָבֵק אִישׁ, שֶׁבָּא בְּאוֹתוֹ אָבָק וְרָכַב עָלָיו כְּדֵי לְקַטְרֵג לְיַעֲקֹב."],[2,"","עַד עֲלוֹת הַשָּׁחַר, שֶׁנֶּעֱבַר שִׁלְטוֹנוֹ וְהִתְחַלֵּף. וְכָךְ הוּא לֶעָתִיד לָבֹא, מִשּׁוּם שֶׁהַגָּלוּת עַכְשָׁו דּוֹמָה לְלַיְלָה, וְהִיא לַיְלָה, וְשׁוֹלֵט אוֹתוֹ אָבָק עַל יִשְׂרָאֵל וְהֵם שׁוֹכְבִים לֶעָפָר (אחר), עַד שֶׁיַּעֲלֶה הָאוֹר וְיָאִיר הַיּוֹם, וְאָז יִשְׁלְטוּ יִשְׂרָאֵל, וְלָהֶם תִּנָּתֵן הַמַּלְכוּת, שֶׁהֵם קְדוֹשִׁים עֶלְיוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ז) וּמַלְכוּת וְשִׁלְטוֹן וּגְדֻלָּה שֶׁמּוֹלֶכֶת תַּחַת כָּל הַשָּׁמַיִם תִּנָּתֵן לְעַם קְדוֹשִׁים עֶלְיוֹנִים. מַלְכוּתוֹ מַלְכוּת עוֹלָם, וְכָל הַשַּׁלִּיטִים לוֹ יַעַבְדוּ וְיִשְׁמְעוּ."],[3,"","וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךְ כִּי אִם בֵּרַכְתָּנִי. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר ו) מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר יָפָה כַלְּבָנָה בָּרָה כַּחַמָּה יָפָה כַּנִּדְגָּלוֹת. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר. אֲבָל מִי זֹאת הַנִּשְׁקָפָה - אֵלּוּ הֵם יִשְׂרָאֵל, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָקִים אוֹתָם וְיוֹצִיאֵם מִן הַגָּלוּת, אָז יִפְתַּח לָהֶם פֶּתַח שֶׁל אוֹר (שהוא) דַּקִּיק קָטָן, וְאַחַר כָּךְ פֶּתַח אַחֵר שֶׁהוּא גָדוֹל מִמֶּנּוּ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִפְתַּח לָהֶם שְׁעָרִים עֶלְיוֹנִים פְּתוּחִים לְאַרְבַּע רוּחוֹת הָעוֹלָם."],[4,"","וְכֵן כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל וְלַצַּדִּיקִים שֶׁבָּהֶם, כָּךְ כֻּלָּם וְלֹא בִּזְמַן אֶחָד. לְאָדָם שֶׁנִּתָּן בַּחֹשֶׁךְ וְדִיּוּרוֹ הָיָה תָּמִיד בַּחֹשֶׁךְ, כְּשֶׁיִּרְצוּ לְהָאִיר לוֹ, צְרִיכִים לִפְתֹּחַ לוֹ אוֹר קָטָן כְּעֵין הַמַּחַט, וְאַחַר כָּךְ גָּדוֹל מִמֶּנּוּ, וְכָךְ בְּכָל פַּעַם עַד שֶׁיָּאִירוּ לוֹ כָּל הָאוֹר כָּרָאוּי."],[5,"","כָּךָ הֵם יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (שמות כג) מְעַט מְעַט אֲגָרֲשֶׁנּוּ מִפָּנֶיךְ עַד אֲשֶׁר תִּפְרֶה וְגוֹ'. וְכֵן לְמִי שֶׁהוּא בָּא לְהֵרָפֵא, אֵינוֹ בְּשָׁעָה אַחַת, אֶלָּא מְעַט מְעַט עַד שֶׁיִּתְחַזֵּק. אֲבָל לְעֵשָׂו לֹא כָּךְ, אֶלָּא בְּפַעַם אַחַת מֵאִיר לוֹ, וְנֶאֱבָד מִמֶּנּוּ מְעַט מְעַט (ולעתיד לבא לאמות עובדי עבודה זרה (ישעיה מב) ה' כגבור יצא) עַד שֶׁיִּתְחַזְּקוּ יִשְׂרָאֵל וְיַשְׁמִידוּ (וישבו) אוֹתוֹ מֵהַכֹּל, מֵהָעוֹלָם הַזֶּה וּמֵהָעוֹלָם הַבָּא. וּמִשּׁוּם שֶׁמֵּאִיר בְּשָׁעָה אַחַת, יִהְיֶה לוֹ הַשְׁמָדָה מֵהַכֹּל. אֲבָל יִשְׂרָאֵל, אוֹר שֶׁלָּהֶם מְעַט מְעַט, עַד שֶׁיִּתְחַזְּקוּ, וְיָאִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים."],[6,"","וְכֻלָּם שׁוֹאֲלִים אוֹתָם וְאוֹמְרִים, מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר, זוֹהִי קַדְרוּת הַבּקֶר, וְזֶהוּ אוֹר דַּקִּיק. וְאַחַר יָפָה כַלְּבָנָה, מִשּׁוּם שֶׁהַלְּבָנָה, הָאוֹר שֶׁלָּהּ מֵאִיר יוֹתֵר מִשַּׁחַר. וְאַחַר בָּרָה כַּחַמָּה, מִשּׁוּם שֶׁאוֹרָהּ חָזָק וּמֵאִיר יוֹתֵר מֵהַלְּבָנָה. וְאַחַר כָּךְ אֲיֻמָּה כַּנִּדְגָּלוֹת, חֲזָקָה בְּאוֹר חָזָק כָּרָאוּי."],[7,"","בֹּא רְאֵה, בְּעוֹד שֶׁנֶּחְשָׁךְ הַיּוֹם וּמִתְכַּסֶּה הָאוֹר וּבָא הַבֹּקֶר, יוּאַר בַּתְּחִלָּה מְעַט מְעַט עַד שֶׁיִּתְרַבֶּה הָאוֹר כָּרָאוּי. שֶׁהֲרֵי כֵּיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְעוֹרֵר לְהָאִיר לָהּ לִכְנֶסֶת יִשְׂרָאֵל, יָאִיר בַּתְּחִלָּה כְּמוֹ שָׁחַר, שֶׁהוּא שָׁחֹר, וְאַחַר כָּךְ יָפָה כַלְּבָנָה, וְאַחַר כָּךְ בָּרָה כַּחַמָּה, וְאַחַר כָּךְ אֲיֻמָּה כַּנִּדְגָּלוֹת, כְּמוֹ שֶׁנִּתְבָּאֵר."]]],[["וְתָּא חֲזֵי, כֵּיוָן דְּאִסְתַּלִיק צַפְרָא, דְּהָא לָא כְּתִיב כִּי בָא הַשָּׁחַר אֶלָּא כִּי עָלָה, דְּהָא בְּזִמְנָא כִּי בָא הַשָּׁחַר, כְּדֵין אִתְתַּקַּף הַהוּא מְמַנָּא וְאַכִּישׁ לֵיהּ לְיַעֲקֹב. בְּגִין דְּהַהוּא מְמַנָּא אַכִּישׁ לְיַעֲקֹב לְמֵיהַב תַּקִּיפוּ לְאִתַתַּקָּפָא לְעֵשָׂו.","וְכַד סָלִיק הַהוּא אוּכְמָא דְּשָׁחַר וְאִתְחֲזֵי אֲתָא נְהוֹרָא וְאִתְתַּקַּף יַעֲקֹב, דְּהָא כְדֵין מָטָא זִמְנֵיהּ לְאִתְנְהָרָא, מַה כְּתִיב וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ כַּאֲשֶׁר עָבַר אֶת פְּנוּאֵל וְהוּא צוֹלֵעַ עַל יְרֵכוֹ. וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ, דְּהָא כְּדֵין זִמְנָא לְאִתְנָהָרָא.","וְהוּא צוֹלֵעַ עַל יְרֵכוֹ. כְּדֵין אִיהוּ רֶמֶז דְּהָא בְּעוֹד דְּיִשְׂרָאֵל בְּגָלוּתָא וְסָבְלִין כְּאֵבִין וְצַעֲרִין וְכַמָּה בִּישִׁין, כַּד אִתְנְהִיר לוֹן יְמָמָא וְיֵיתֵי לוֹן נַיְיחָא, כְּדֵין יִסְתַּכְּלוּן וְיִכְאֲבוּן בְּגַרְמַיְיהוּ מִכַּמָּה בִּישִׁין וְצַעֲרִין דְּסָבְלוּ וְיִתְמְהוּ עֲלַיְיהוּ. בְּגִין כָּךְ וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ. דְּהַהוּא זִמְנָא דְנַיְיחָא, וּכְדֵין וְהוּא צוֹלֵעַ עַל יְרֵכוֹ אִתְכָּאַב וְצָעֵיר גַּרְמֵיהּ עַל מַה דְּעֲבַר.","וְאִיהוּ כַּד אִסְתַּלַּק קַדְרוּתָא דְּשַׁחֲרָא כְּדֵין אִתְתַּקַּף וְאִתְאֲחִיד בֵּיהּ דְּכַד אִתְחַלַּשׁ חֵילֵיהּ, דְּלֵית לֵיהּ שׁוּלְטָנוּתָא אֶלָּא בְּלֵילְיָא, וְיַעֲקֹב שָׁלְטָנוּתֵיהּ בִּימָמָא. וְעַל דָּא אָמַר וַיֹּאמֶר שַׁלְחֵנִי כִּי עָלָה הַשָּׁחַר, דְּהָא אֲנָא בִּרְשׁוּתְךָ קָאִימְנָא, וְהָא אִתְּמָר וְאוּקְמוּהָ:","(על כן לא יאכלו בני ישראל את גיד הנשה וגו', כי נגע בכף ירך יעקב, בגיד הנשה, דאפילו בהנאה אסיר ואפילו ליהביה לכלבא. ואמאי אקרי גיד הנשה. כלומר גיד דאיהו מנשה לבני נשא לפולחנא דמאריהון, ותמן הוא יצר הרע רביע.","כיון דאתדבק עם יעקב לא אשכח אתר דיכיל לאתגברא עליה דיעקב, בגין דכל שייפי גופא סייעי ליעקב, וכלהו הוו תקיפין ולא הוו בהון חולשא, מה עבד, ויגע בכף ירכו בגיד הנשה, בזיניה ביצר הרע דאיהו זיניה ואתריה, ומתמן אתי יצר הרע על בני נשא.","ובגין כך אמרה אורייתא לא יאכלו בני ישראל את גיד הנשה. כמה דאמרו חברייא, בשייפין דבר נש דרמיז לעילא אי טב, טב. ואי ביש, ביש. ובגין כך כל שייפא מתקיף שייפא. ודאי גיד הנשה מתקיף ליצר הרע דהוא זיניה, ובני ישראל לא יאכלו ליה, דלאו אינון מסטריה ומזיניה. אבל עמין עובדי עבודה זרה, יאכלו ליה, דאיהו מסטרא ומזינא דמלאכא דלהון דאיהו סמא\"ל בגין לתקפא לבהון.","בגין דאית בבר נש רמ\"ח שייפין לקבל רמ\"ח פקודין דאורייתא דאינון למעבד אתיהבו, ולקבל רמ\"ח מלאכין דאתלבשת בהון שכינתא ושמא דלהון כשמא דמאריהון.","ואית בבר נש שס\"ה גידין ולקבלהון שס\"ה פקודין דלאו אינון אתיהבו למעבד ולקבל שס\"ה יומי שתא, והא תשעה באב חד מנהון דאיהו לקבל סמא\"ל דאיהו חד מאינון שס\"ה מלאכין (נ\"א יומין), ובגין כך אמרה אורייתא לא יאכלו בני ישראל את גיד הנשה. א\"ת, לאסגאה תשעה באב דלא אכלין ביה ולא שתין.","ובגין כך חזא קודשא בריך הוא כלא ונרמז בהון רמז ליעקב, ויאבק איש עמו, בכל יומי שתא ובכל שייפין דיעקב ולא אשכח בר ההוא גיד הנשה, מיד תשש חיליה דיעקב, וביומי שתא אשכח יום תשעה באב דביה אתתקף ואתגזר דינא עלנא ואתחרב בי מקדשא, וכל מאן דאכיל בתשעה באב כאילו אכיל גיד הנשה). רַבִּי חִיָּיא אָמַר, אִלְּמָלֵא לָא אִתְחַלַּשׁ חֵילָא (נ\"א דאתר) דָא דְּיַעֲקֹב, אִתְקְיַּים יַעֲקֹב לְגַבֵּיהּ וְאִתְבַּר חֵילָא דְעֵשָׂו לְעֵילָא וְתַתָּא.","רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (יחזקאל א׳:כ״ח) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶּעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב הוּא מַרְאֵה דְּמוּת כְּבוֹד יְיָ וָאֶרְאֶה וָאֶפֹּל עַל פָּנַי וְגו'. הַאי קְרָא אִתְּמָר. אֲבָל תָּא חֲזֵי, דְּהָא כְּתִיב, (דברים לה) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמשֶׁה. מַה בֵּין משֶׁה לִשְׁאָר נְבִיאֵי עָלְמָא. משֶׁה אִסְתַּכַּל בְּאַסְפַּקְלַרְיָא דְנָהֲרָא, שְׁאָר נְבִיאֵי לָא הֲווּ מִסְתַּכְּלֵי אֶלָּא בְּאַסְפַּקְלַרְיָא דְּלָא נָהֲרָא. משֶׁה הֲוָה שָׁמַע וְקָאִים עַל רַגְלוֹי, וְחֵילֵיהּ אִתְתַּקַּף, וְהֲוָה יָדַע מִלָּה עַל בּוּרְיֵיהּ, כְּמָה דִכְתִיב, (במדבר י״ב:ח׳) וּמַרְאֶה וְלֹא בְחִידוֹת. שְׁאָר נְבִיאֵי הֲווּ נָפְלֵי עַל אַנְפַּיְיהוּ וְאִתְחַלַּשׁ חֵילָא דִלְהוֹן וְלָא הֲווּ יָכְלֵי לְקָיְימָא עַל בּוּרְיֵיהּ דְּמִלָּה. מַאן גָּרַם לוֹן דָּא בְּגִין דִּכְתִיב כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב וְהוּא צוֹלֵעַ עַל יְרֵכוֹ."],[[0,"ות\"ח כיון וכו':","ובוא וראה כתוב כיון שעלה השחר, לא כתוב, כי בא השחר אלא כי עלה, כי בזמן, שבא השחר, אז מתגבר אותו הממונה של עשו, והקיש את יעקב, כי הממונה ההוא הקיש את יעקב, כדי לתת אומץ לעשו להתגבר."],[1,"וכד סליק וכו':","אבל כאשר אותה שחרית של ה \u0003שחר\u0004 עולה אז בא האור, ויעקב מתגבר, כי אז מגיע זמנו להאיר, מה כתוב, ויזרח לו השמש כאשר וגו', \u0003ויזרח לו השמש,\u0004 כי אז הזמן להאיר."],[2,"והוא צולע על ירכו:","זה הוא רמז, כי בעוד שישראל הם בגלות וסובלים כאבים וצער וכמה רעות, כאשר יאיר להם היום, ותהיה להם מנוחה, יסתכלו אז ויכאב לבם, מכל אלו הרעות והצער שסבלו, ויתמהו עליהם, ועל כן אוה\"כ \u0003ויזרח לו השמש,\u0004 דהיינו השמש של זמן המנוחה, ואז \u0003והוא צולע על ירכו,\u0004 שפירושו הוכאב ונצטער בעצמו על מה שעבר עליו."],[3,"ואיהו כד אסתלק וכו':","והוא, יעקב, כאשר עלתה שחרות הבוקר, אז נתגבר ונאחז בו כי נחלש כחו של המלאך, כי אין לו שליטה אלא בלילה, ויעקב שולט ביום. ועל כן נאמר, ויאמר שלחני כי עלה השחר, כי אני נמצא ברשותך וכבר למדנו ובארוהו."],[4,"על כן לא יאכלו וגו' בגיד הנשה:","ואפילו בהנאה אסור, ואפילו לתת לכלב אסור, ושואל, ולמה נקרא גיד הנשה, ומשיב, כלומר, גיד שהוא מנשה דהיינו מדיח, בני אדם מעבודת בוראם. ושם רובץ היצר הרע."],[5,"וכיון דאתדבק וכו':","וכיון שהמלאך התאבק עם יעקב, לא מצא מקום בגופו שיוכל להתגבר על יעקב, כי כל אברי גופו עזרו ליעקב. כי כולם היו חזקים ולא היתה בהם חולשה, ואין הקליפה נאחזת אלא במקום חסרון וחולשה. מה עשה, ויגע בכף ירכו בגיד הנשה, במינו דהיינו ביצר הרע שהוא מינו, ושם מקומו של היצה\"ר, ומשם בא היצר הרע אל בני אדם. פירוש, כיון שגיד הנשה הוא מקומו של היצר הרע, שהוא מינו של המלאך סמאל, ע\"כ היה יפה כחו להאחז שם."],[6,"ובגין כך אמרה וכו':","ומשום זה אמרה תורה, לא יאכלו בני ישראל את גיד הנשה. כמו שאמרו החברים באבריו של האדם מרומז מה שלמעלה, אם האבר טוב הוא ממשיך טוב, ואם הוא רע ממשיך רע. ועל כן כל אבר שאוכלים מן בעלי חיים מחזק אבר שכנגדו באדם האוכל. ודאי שגיד הנשה מחזק את היצר הרע שהוא מינו, ובני ישראל לא יאכלו אותו, שהם אינם מצדו וממינו, אבל העמים עובדי ע\"ז יאכלו אותו, שהם מצדו וממינו של המלאך שלהם שהוא סמאל, ויחזק את לבם."],[7,"בגין דאית בבר נש וכו':","משום שיש באדם רמ\"ח אברים כנגד רמ\"ח מצות שבתורה, שהם נתנו להעשות, וכנגד רמ\"ח מלאכים, שנתלבשה בהם השכינה, ושמם כשם רבונם."],[8,"ואית בבר נש וכו':","ויש באדם שס\"ה גידים, וכנגדם שס\"ה מצות, שהם לא נתנו להעשות. שגיד הנשה הוא אחד מהם וכנגד שס\"ה ימות השנה דהיינו בתוספת עשרת ימי תשובה, ותשעה באב הוא אחד מהם שהוא כנגד המלאך סמאל, שהוא אחד משס\"ה מלאכים השולטים על שס\"ה ימות השנה. ונמצא ט' באב בשס\"ה ימות השנה, וגיד הנשה בשס\"ה גידים, הם בחינה אחת, ועל כן אמרה תורה לא יאכלו בני ישראל \u0003את\u0004 גיד הנשה, \u0003א\"ת\u0004 הוא לרבות תשעה באב, שאין אוכלים בו ואין שותים. להיותו בחינה אחת עם גיד הנשה."],[9,"ובגין כך חזא וכו':","ומשום זה ראה הקב\"ה הכל, ונרמז בכתוב, רמז ליעקב, \u0003ויאבק איש עמו\u0004, היינו בכל ימות השנה, ובכל אבריו של יעקב, ולא מצא מקום לאחיזה אלא בגיד הנשה ההוא, ומיד תשש כחו של יעקב. ובימות השנה מצא את יום תשעה באב, שבו נתגבר סמאל, ונגזר הדין עלינו, ונחרב בית המקדש. וכל מי שאוכל בתשעה באב, כאלו אוכל גיד הנשה. רבי חייא אומר, אלו לא נחלש כח זה של ירך יעקב, היה יכול לו יעקב, והיה נשבר כחו של עשו, למעלה ולמטה."],[10,"ר' שמעון פתח וכו': ר\"ש פתח ואמר,","כמראה הקשת אשר יהיה וגו' מקרא זה למדנו. אבל בוא וראה, כי כתוב, ולא קם נביא עוד בישראל כמשה. ושואל מה בין משה לשאר נביאי העולם. ומשיב, משה הסתכל בספקלריאה המאירה. שהיא ז\"א, שאר הנביאים, לא היו מסתכלים אלא באספקלריאה שאינה מאירה, שהיא הנוקבא. משה היה שומע הנבואה, ועומד על רגליו, וכחו מתגבר, והיה יודע דבר על בוריו, כמ\"ש ומראה ולא בחידות. שאר הנביאים היו נופלים על פניהם בשעת הנבואה, ונחלש כחם, ולא היו יכולים לעמוד על בירורו של הדבר. מי גרם להם זה, משום שכתוב, כי נגע בכף ירך יעקב והוא צולע על ירכו. פירוש כי הנבואה היא מנו\"ה דז\"א שה\"ס ב' ירכין, וכיון שנפגם הירך, ע\"כ אין נבואתם צלולה כראוי. (ועי' לעיל ב\"א דף קל\"ג אות קמ\"ה ובהמשך)."]],[[0,"","וּבֹא רְאֵה, כֵּיוָן שֶׁעוֹלֶה הַבֹּקֶר, שֶׁהֲרֵי לֹא כָתוּב כִּי בָא הַשַּׁחַר, אֶלָּא כִּי עָלָה, שֶׁהֲרֵי בִּזְמַן כִּי בָא הַשַּׁחַר, אָז הִתְחַזֵּק אוֹתוֹ מְמֻנֶּה וְהִכִּישׁ אֶת יַעֲקֹב, מִשּׁוּם שֶׁאוֹתוֹ מְמֻנֶּה הִכִּישׁ אֶת יַעֲקֹב לָתֵת כֹּחַ לְהִתְחַזֵּק לְעֵשָׂו."],[1,"","וּכְשֶׁעָלָה אוֹתוֹ שָׁחֹר שֶׁל שַׁחַר וְנִרְאָה, בָּא הָאוֹר וְהִתְחַזֵּק יַעֲקֹב, שֶׁהֲרֵי אָז הִגִּיעַ זְמַנּוֹ לִהְיוֹת מוּאָר, מַה כָּתוּב? וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ כַּאֲשֶׁר עָבַר אֶת פְּנוּאֵל וְהוּא צֹלֵעַ עַל יְרֵכוֹ. וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ, שֶׁהֲרֵי אָז הַזְּמַן לִהְיוֹת מוּאָר."],[2,"","וְהוּא צֹלֵעַ עַל יְרֵכוֹ. אָז הוּא רֶמֶז, שֶׁהֲרֵי בְּעוֹד שֶׁיִּשְׂרָאֵל בַּגָּלוּת וְסוֹבְלִים כְּאֵבִים וְצַעַר וְכַמָּה רָעוֹת, כְּשֶׁמֵּאִיר לָהֶם הַיּוֹם וְיָבִיא לָהֶם מְנוּחָה, אָז יִסְתַּכְּלוּ וְיִכְאֲבוּ בְּעַצְמוֹתֵיהֶם מִכַּמָּה רָעוֹת וְצַעַר שֶׁסָּבְלוּ וְיִתְמְהוּ עֲלֵיהֶם, מִשּׁוּם כָּךְ וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ. שֶׁאוֹתוֹ זְמַן הַמְּנוּחָה, וְאָז הוּא צֹלֵעַ עַל יְרֵכוֹ, כּוֹאֵב וּמְצַעֵר עַצְמוֹ עַל מַה שֶּׁעָבַר."],[3,"","וְהוּא, כְּשֶׁעוֹלֶה קַדְרוּת הַשַּׁחַר, אָז מִתְחַזֵּק וְנֶאֱחָז בּוֹ, שֶׁהֲרֵי נֶחֱלָשׁ כֹּחוֹ, שֶׁאֵין לוֹ שִׁלְטוֹן אֶלָּא בַּלַּיְלָה, וְיַעֲקֹב שִׁלְטוֹנוֹ בַּיּוֹם. וְעַל זֶה אָמַר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר, שֶׁהֲרֵי אֲנִי בִּרְשׁוּתְךְ עוֹמֵד, וַהֲרֵי נִתְבָּאֵר וּפֵרְשׁוּהוּ."],[4,"","(על כן לא יאכלו בני ישראל את גיד הנשה וגו', כי נגע בכף ירך י קב בגיד הנשה, שאפלו בהנאה אסור, ואפלו לתת אותו לכלב, ולמה נקרא גיד הנשה? כלומר, גיד שהוא משכיח את בני האדם מעבודת רבונם, ושם רובץ היצר הרע"],[5,"","וכיון שנדבק עם יעקב, לא מצא מקום שיכול להתגבר על יעקב, משום שכל איברי הגוף סיעו ליעקב, וכלם היו חזקים ולא היתה בהם חלשה, מה עשה? ויגע בכף ירכו בגיד הנשה, במינו של יצר הרע שהוא מינו למקומו, ומשם בא יצר הרע על בני האדם,"],[6,"","ולכן אמרה תורה לא יאכלו בני ישראל את גיד הנשה, כמו שאמרו החברים באיברי האדם שרמוז למעלה, אם טוב טוב, ואם רע רע, ולכן כל איבר מחזק איבר, ודאי גיד הנשה מחזק את יצר הרע שהוא מינו, ובני ישראל לא יאכלו אותו, שאינם מצדו וממינו, אבל עמים עובדי עבודה זרה יאכלו אותו, שהוא מצד וממין המלאך שלהם, שהוא סמא\"ל, כדי לחזק לבם,"],[7,"","משום שיש באדם מאתים ארבעים ושמונה איברים כנגד מאתים ארבעים ושמונה מצוות התורה שהם נתנו להעשות, וכנגד מאתים ארבעים ושמונה מלאכים שהתלבשה בהם שכינה והשם שלהם כשם רבונם,"],[8,"","ויש באדם שלש מאות ששים וחמשה גידים, וכנגדם שלש מאות ששים וחמש מצוות שלא נתנו להעשות וכנגד שלש מאות ששים וחמשה ימות השנה, והרי תשעה באב אחד מהם, שהוא כנגד סמא\"ל, שהוא אחד מאותם שלש מאות ששים וחמשה מלאכים (ימים), ולכן אמרה תורה לא יאכלו בני ישראל את גיד הנשה, א\"ת לרבות תשעה באב שלא אוכלים בו ולא שותים,"],[9,"","ולכן ראה הקדוש ברוך הוא הכל, ונרמז בהם רמז ליעקב, ויאבק איש עמו, בכל ימות השנה ובכל איברי י קב, ולא נמצא פרט לאותו גיד הנשה, מיד תשש כח יעקב, ובימות השנה מצא יום תשעה באב שבו התחזק ונגזר דין עלינו ונחרב בית המקדש, וכל מי שאוכל בתשעה באב כאלו אכל את גיד הנשה). רבי חייא אמר, אלמלא לא נחלש כח (של מקום) זה של יעקב, היה מתקים יעקב אליו, ונשבר כח של עשו למעלה ולמטה."],[10,"","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (יחזקאל לא) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב הוּא מַרְאֵה דְּמוּת כְּבוֹד ה' וָאֶרְאֶה וָאֶפֹּל עַל פָּנַי וְגוֹ'. פָּסוּק זֶה נִתְבָּאֵר. אֲבָל בּא רְאֵה, שֶׁהֲרֵי כָּתוּב (דברים לד) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. מַה בֵּין מֹשֶׁה לִשְׁאָר נְבִיאֵי הָעוֹלָם? מֹשֶׁה הִסְתַּכֵּל בְּאַסְפַּקְלַרְיָה הַמְּאִירָה - שְׁאָר הַנְּבִיאִים לֹא הָיוּ מִסְתַּכְּלִים אֶלָּא בְּאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה. מֹשֶׁה הָיָה שׁוֹמֵעַ וְעוֹמֵד עַל רַגְלָיו וְכֹחוֹ מִתְחַזֵּק וְהָיָה יוֹדֵעַ דָּבָר עַל בֻּרְיוֹ, כְּמוֹ שֶׁכָּתוּב (במדבר יב) וּמַרְאֶה וְלֹא בְחִידוֹת - שְׁאָר הַנְּבִיאִים הָיוּ נוֹפְלִים עַל פְּנֵיהֶם וְנֶחֱלַשׁ כֹּחָם וְלֹא הָיוּ יְכוֹלִים לַעֲמֹד עַל בֻּרְיוֹ שֶׁל דָּבָר. מִי גָרַם לָהֶם אֶת זֶה? מִשּׁוּם שֶׁכָּתוּב כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב וְהוּא צֹלֵעַ עַל יְרֵכוֹ."]]],[["וְכָל אִינוּן נְבִיאִין לָא יָכִילוּ לְקָיְימָא עַל מַה דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לֵיהּ לְעֵשָׂו, בַּר עוֹבַדְיָה נְבִיאָה דְּהֲוָה גִיּוֹרָא דְּאָתֵי מִסִּטְרָא דְעֵשָׂו, דָּא קָאִים בְּקִיּוּמֵיהּ עֲלֵיהּ דְּעֵשָׂו וְלָא אִתְחַלַּשׁ חֵילֵיהּ. וְעַל דָּא כָּל שְׁאָר נְבִיאֵי אִתְחַלַּשׁ תּוּקְפַיְיהוּ וְלָא הֲווּ יָכְלִין לְאִתְקָיְימָא לְקַבְּלָא מִלָּה עַל בּוּרְיֵיהּ כְּדְקָא יְאוּת, מַאי טַעְמָא, בְּגִין כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב בְּגִין הַנָּשֶׁה, דְּנָסִּיב וְשָׁאִיב כָּל חֵילָא דְּיַרְכָא, וְעַל דָּא אִתְבַּר חֵילָא דְיַרְכָא וְאִשְׁתָּאַר צוֹלֵעַ עַל יְרֵכוֹ. דְּהָא כָּל נְבִיאִין דְּעַלְמָא לָא יָכִילוּ לְאִדַּבְּקָא וּלְקָיְימָא בֵּיהּ.","תָּא חֲזֵי, נְבִיאִין כֻּלְּהוּ בַּר משֶׁה לָא קָיְימוּ בְּתוּקְפַיְיהוּ כְּדְקָא חָזֵי. וּמַאן דְּלָעֵי בְּאוֹרַיְיתָא וְלֵית מַאן דְּסָמִיךְ לֵיהּ וְלָא אִשְׁתְּכַח מַאן דְּאַטִּיל מְלַאי לְכִיסֵיהּ לְאִתְתַּקְפָא. עַל דָּא אוֹרַיְיתָא קָא מִשְׁתַּכְּחָא בְּכָל דָּרָא וְדָרָא וְאִתְחַלַּשׁ תּוּקְפָא דְאוֹרַיְיתָא כָּל יוֹמָא וְיוֹמָא, בְּגִין דְּלֵית לוֹן לְאִינוּן דְּלָעָאן בָּהּ עַל מַה דְּסָמְכִין, וּמַלְכוּ חַיָּיבָא אִתְתַּקַּף בְּכָל יוֹמָא וְיוֹמָא. תָּא חֲזֵי,","כַּמָּה גָּרִים חוֹבָא דָא, וּבְגִין דְּלֵית (לון) מַאן דְּאַסְמִיךְ לְאוֹרַיְיתָא כְּדְקָא יְאוּת אִינוּן סָמְכִין חַלָּשִׁין, וְגָרְמִין לְאִתְתַּקְפָא לְהַהוּא דְּלֵית לֵיהּ שׁוֹקִין וְרַגְלִין לְקָיְימָא עֲלַיְיהוּ.","פָּתַח וְאָמַר, (בראשית ג׳:י״ד) וַיֹּאמֶר יְיָ אֱלֹהִים אֶל הַנָּחָשׁ כִּי עָשִׂיתָ זֹאת אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגו' עַל גְּחוֹנְךָ תֵּלֵךְ. מַאי עַל גְּחוֹנְךָ תֵּלֵךְ. דְּאִתָּבְרוּ סָמְכִין דִּילֵיהּ וּקְצִיצוּ רַגְלוֹי וְלֵית לֵיהּ עַל מַה דְּקָאִים. כַּד יִשְׂרָאֵל לָא בָּעָאן לְסָמְכָא לֵיהּ לְאוֹרַיְיתָא, אִינוּן יָהֲבִין לֵיהּ סָמְכִין וְשׁוֹקִין לְקָיְימָא וּלְאִתְתַּקְּפָא בְּהוּ.","תָּא חֲזֵי, כַּמָּה עֲקִימוּ וְחַכִּימוּ אִתְחַכַּם בְּהַהוּא לֵילְיָא הַהוּא דְרָכִיב נָחָשׁ לְקֳבְלֵיהּ דְּיַעֲקֹב, דְּהָא אִיהוּ הֲוָה יָדַע דִּכְתִיב, (בראשית כ״ז:כ״ב) הַקּוֹל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו. וְאִי פָּסִיק קָלָא דְיַעֲקֹב כְּדֵין וְהַיָּדַיִם יְדֵי עֵשָׂו. בְּגִין כָּךְ אִסְתַּכַּל לְכָל סִטְרִין לְאַבְאָשָׁא לֵיהּ לְיַעֲקֹב וּלְאַפְסָקָא קָלֵיהּ.","וְחָמָא לֵיהּ תַּקִּיף בְּכֹלָּא. דְּרוֹעִין מִסִּטְרָא דָא וּמִסִּטְרָא דָא דְּאִינוּן תָּקִפִין גּוּפָא דְּאִתְתַּקַּף בֵּינַיְיהוּ, וְחָמָא תּוּקְפָא דְאוֹרַיְיתָא וְאִתְתַּקַּף בְּכֹלָּא, כְּדֵי וַיַּרְא כִּי לא יָכוֹל לוֹ. מָה עֲבַד, מִיָּד וַיִּגַּע בְּכַף יְרֵכוֹ, דְּאִתְחַכַּם לְקֳבְלֵיהּ. אָמַר כֵּיוָן דְּאִתְּבָרוּ סָמְכִין דְּאוֹרַיְיתָא, מִיָּד אוֹרַיְיתָא לָא אִתְתַּקַּף. וּכְדֵין יִתְקַיַּים מַה דְּאָמַר אֲבוּהוֹן, הַקּוֹל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו. (בראשית כ״ז:מ׳) וְהָיָה כַּאֲשֶׁר תָּרִיד וּפָרַקְתָּ עֻלּוֹ מֵעַל צַוָּארֶךָ.","וּבְדָא אִתְחַכַּם לְקֳבְלֵיהּ דְּיַעֲקֹב דְּהָא בְּגִין דְּיִתָּבַר חֵילָא דְאוֹרַיְיתָא אָזִיל וְאִתְתַּקַּף עֵשָׂו. וְכַד חָמָא דְלָא יָכִיל לָהּ לְאוֹרַיְיתָא, כְּדֵין חָלִישׁ תּוּקְפָא דְּאִינוּן דְּסָמְכִין לָהּ, וְכַד לָא יִשְׁתַּכַּח מַאן דְּסָמִיךְ לְאוֹרַיְיתָא, כְּדֵין לָא יְהֵא קוֹל קוֹל יַעֲקֹב וִיהוֹן יָדַיִם יְדֵי עֵשָׂו.","וְכַד חָמָא יַעֲקֹב הָכִי כַּד סָלִיק צַפְרָא, אַתְקִיף (יעקב) בֵּיהּ וְאִתְגַּבַּר עֲלֵיהּ עַד דְּאִיהוּ בְּרִיךְ לֵיהּ וְאוֹדֵי לֵיהּ עַל אִינוּן בִּרְכָאן, וְאָמַר לֵיהּ לא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךָ כִּי אִם יִשְׂרָאֵל, לָאו יַעֲקֹב בְּעֲקִימוּ אֶלָּא בְּגְאוּתָא וְתוּקְפָא דְּלֵית מַאן דְּיָכִיל לָךְ.","וְתָּא חֲזֵי, מֵהַאי נָחָשׁ כַּמָּה חֵילִין מִתְפָּרְשָׁן לְכָל סְטַר וְאִשְׁתַּכָּחוּ בְּעַלְמָא לְגַבֵּי בְּנֵי נָשָׁא. וּבְעִינָן לְקָיְימָא לְהַהוּא גִּיד הַנָּשֶׁה, דְּאַף עַל גַּב דְּקָרִיב בֵּיהּ הַהוּא דְּרָכִיב עַל חִוְיָא קַיָּים אִיהוּ, וְאִתְקְיַּים בְּגַוָּון וְלָא אִתְּבַּר.","וְחֵילָא בְּעִינָן לְאִתְתַּקָּפָא בְּעַלְמָא וּלְאַחֲזָאָה כִּי שָׂרִיתָ עִם אֱלֹהִים וְעִם אֲנָשִׁים וַתּוּכָל. וְכַד חָמֵי דְּהָא לָא אִתְּבַּר וְלָא אִתְאֲכִיל הַהוּא אֲתַר, כְּדֵין אִתְבַּר חֵילֵיהּ וְתוּקְפֵיהּ וְלָא יָכִיל לְאַבְאָשָׁא לִבְנוֹי דְיַעֲקֹב. וְעַל דָּא לָא בְּעִינָן לְמֵיהַב דּוּכְתָּא לִבְרִיָּיתָא דְעַלְמָא לְמֵיכַל לֵיהּ וְלָא לְאִתְאֲכָלָא כְּלָל."],[[0,"וכל אינון נביאין וכו':","וכל אלו הנביאים לא יכלו לעמוד על מה שעתיד הקב\"ה לעשות לעשו, חוץ מעובדיה הנביא, שהיה גר שבא מצד עשו, הוא עמד על בוריו בענין עשו, ולא נחלש כחו, כמ\"ש בספר עובדיה."],[1,"וע\"ד כל שאר וכו':","ועל זה, כל שאר הנביאים נחלש כחם ולא יכלו לעמוד ולקבל דבר על בוריו כראוי. מה הטעם, משום כי נגע בכף ירך יעקב בגיד הנשה, שלקח ושאב כל הכח של הירך, ועל כן נשבר כחו של הירך, ונשאר צולע על ירכו, כי כל נביאי העולם לא יכלו להשיג ולעמוד בו. בוא וראה, כל הנביאים חוץ ממשה לא עמדו בכחם כראוי."],[2,"ומאן דלעי וכו':","ומי שלומד בתורה, ואין מי שיתמוך בו, ולא נמצא מי שיטיל כסף לסחורה לתוך כיסו, לחזקו, על זה נשתכחה התורה בכל דור ודור, ונחלש כחה של התורה בכל יום ויום, כי אין להם לעוסקים בתורה על מה שיסמכו. שז\"ס והוא צולע על ירכו, שאינם נותנים תמיכה וחיזוק לת\"ח שיוכלו לעסוק בתורה. וע\"כ והמלכות הרשעה מתגברת בכל יום ויום. בוא וראה כמה גרם החטא הזה, ומשום שאין מי שיסמוך את התורה שהיא ז\"א, כראוי, נעשו הסומכים דז\"א חלשים, דהיינו נו\"ה דז\"א המכונים סמכין, וגורמים שיתגבר אותו שאין לו שוקים ורגלים לעמוד עליהם. שהוא הנחש הקדמוני."],[3,"פתח ואמר וכו':","פתח ואמר, ויאמר ה' אלקים וגו' על גחונך תלך. ושואל מהו על גחונך תלך. ומשיב, כי נשברו הסומכים שלו ונקצצו רגליו, ואין לו על מה שיעמוד. כך ישראל אם אינם רוצים לסמוך את התורה, דהיינו לפרנס ת\"ח העוסקים בתורה כנ\"ל, הם נותנים לנחש סומכים ושוקים לעמוד ולהתחזק בהם. כי מחסרונות שבקדושה נבנה הס\"א."],[4,"ת\"ח כמה עקימו וכו':","בוא וראה כמה מרמה וערמה התחכם באותו הלילה, אותו רוכב על הנחש, שהוא סמאל, כנגד יעקב. כי הוא היה יודע, שכתוב, הקול קול יעקב והידים ידי עשו, שפירושו, שאם נפסק קולו של יעקב, דהיינו קול התורה, אז ניתן כח אל הידים ידי עשו, משום זה הסתכל לכל הצדדים להרע ליעקב ולהפסיק קול תורתו."],[5,"וחמא ליה תקיף וכו':","וראה אותו חזק בכל הבחינות, ראה הזרועות, מצד זה ומצד זה, דהיינו חסד וגבורה הנקראים אברהם ויצחק שהם חזקים. ראה הגוף, שה\"ס יעקב המיחד ב' הזרועות, שמתחזק ביניהם. וראה כח התורה שלו ושהוא חזק מכל הבחינות, אז וירא כי לא יכול לו. מה עשה, מיד, ויגע בכף ירכו, דהיינו בתומכי התורה, שנתחכם כנגדו, אמר, כיון שנשברו תומכי התורה, מיד לא תוכל התורה להתחזק עוד, ואז יתקיים מה שאמר אביהם, הקול קול יעקב והידים ידי עשו כמ\"ש לעיל, וכן, והיה כאשר תריד ופרקת עלו מעל צוארך."],[6,"ובדא אתחכם וכו':","ובזה נתחכם כנגד יעקב, כי כדי לשבור כח התורה שלו הלך ונתחזק עשו, וכשראה שלא יכול לפגוע בתורתו, אז החליש כחם של אלו התומכים בלומדי התורה, כי כשלא ימצא מי שיתמוך בלומדי התורה, אז לא יהיה \u0003קול קול יעקב,\u0004 ויהיו \u0003הידים ידי עשו.\u0004"],[7,"וכד חמא וכו':","וכאשר ראה יעקב את זה, כשעלה השחר התקיף אותו ונתגבר עליו, עד שהוא ברך אותו והודה לו על הברכות, ואמר לו, לא יעקב יאמר עוד שמך כי אם ישראל, דהיינו לא יעקב, שמורה על מרמה, כמ\"ש ויעקבני זה פעמים, כי אם ישראל, דהיינו בגאוה וגבורה שאין מי שיוכל לך. כי השם ישראל מורה על שררה וגאוה. כמ\"ש כי שרית עם אלקים ואנשים ותוכל."],[8,"ות\"ח מהאי נחש וכו':","ובוא וראה, מנחש זה, כמה חילות מתפרשים לכל צד, ונמצאים בעולם אצל האנשים. וצריכים לקיים את גיד הנשה ההוא, כי אע\"פ שקרב אליו אותו הרוכב על הנחש, שהוא סמאל, הוא קיים, ומתקיים בגוון, ולא נשבר."],[8,"","בכדי להסביר דברים אלו צריכים לבאר תחילה כללות כל המאמר הזה. ונודע כי ש\"ך ניצוצין נפלו בשבירת הכלים בעולם הנקודים, שהם עשר ספירות שבכל אחת מהן נשברו ל\"ב בחינות. דהיינו שמונה מלכים דעת חסד גבורה ת\"ת נצח הוד יסוד ומלכות, ובכל אחד מהם ד' בחי' חו\"ב תו\"מ הרי ל\"ב, ועשר פעמים ל\"ב הם בגי' ש\"ך. וט\"ס ראשונות שבהם, מתבררות ומתקנות ע\"י המאציל, שתקן מהם ד' עולמות אבי\"ע, וע\"י הצדיקים בקיום תורה ומצות, שהם ט' פעמים ל\"ב שבגי' רפ\"ח. אבל ספירה אחרונה מהם שהיא מלכות הכוללת גם היא ל\"ב בחינות, נשארה בתוך הקליפות בלתי מבוררת, ואי אפשר לברר ולתקן אותה בשתא אלפי שני. וע\"כ נקראת ל\"ב האבן, מטעם, שאסור לברר ממנה, אלא אם נשמרים היטב שלא לברר אלא רפ\"ח הניצוצים, הרי במשך שתא אלפי שני, היא מתבררת מאליה, בלי שום מעשה מלמטה, ואז נאמר עליה, והסירותי את ל\"ב האבן מקרבכם. שהוא ל\"ב בחינות שבכלי המלכות הנ\"ל שנשברה, ונתלבשה בקליפות. שהתקון הוא בידי המאציל בלבד, ולא בידי אדם."],[8,"","ונודע שבכל דבר יש עולם שנה נפש. וע\"כ גם בבחינת ל\"ב האבן הזה יש בו \u0003עולם שנה נפש.\u0004 שבבחינת \u0003העולם\u0004 הוא הנחש הקדמוני שסמאל רוכב עליו. ומבחינת \u0003שנה\u0004 היא תשעה באב, ומבחינת \u0003נפש,\u0004 ה\"ס גיד הנשה. וז\"ס \u0003וירא כי לא יכול לו,\u0004 כי יעקב היה שלם מכל רפ\"ח ניצוצים, שכבר תקנם לגמרי, אז ויגע בכף ירכו, דהיינו בגיד הנשה, כי היא עוד לא נבררה כנ\"ל, וע\"כ \u0003ותקע כף ירך יעקב,\u0004 כי כמו שסמאל יש לו כח לרכוב על הנחש, כן יש לו כח על גיד הנשה, כי בחינה אחת הן, זה בעולם וזה בנפש כנ\"ל."],[8,"","וז\"ש (באות ק\"ד) \u0003ויאבק איש עמו, בכל יומי שתא ובכל שייפין דיעקב,\u0004 דהיינו בבחינת \u0003שנה\u0004 ובבחינת \u0003נפש, ולא אשכח בר ההוא גיד הנשה\u0004 וכו' \u0003וביומי שתא אשכח יום תשעה באב,\u0004 שגיד הנשה היא בחינת ל\"ב האבן שב \u0003נפש,\u0004 ותשעה באב הוא בחינת ל\"ב האבן שב \u0003שנה,\u0004 שהם עוד לא נבררו מן הקליפות, וע\"כ נאחז בהם. וז\"ש \u0003וכל מאן דאכיל בתשעה באב כאלו אכיל גיד הנשה,\u0004 כי אכילה ה\"ס בירורים מן הקליפות, וכיון שגיד הנשה הוא בחינת ל\"ב האבן, ע\"כ אוה\"כ \u0003לא יאכלו בני ישראל את גיד הנשה\u0004 וגו', כי אסור לבררו בידי אדם כנ\"ל. ומזה הטעם אסור לאכול בתשעה באב, כי ביום זה שהוא בחינת ל\"ב האבן, אסור הבירור. הרי שאיסור גיד הנשה ואיסור אכילה בת\"ב הם דבר אחד."],[8,"","וז\"ש כאן, \u0003ובעינן לקיימא לההוא גיד הנשה,\u0004 כלומר אע\"פ שאסור לברר אותו ולאכלו, משום שהקליפות נאחזות בו, מכל מקום אנו מצווים לקיימו, עד לעתיד לבא, עד שיתוקן על ידי המאציל, \u0003דאע\"ג דקריב ביה ההוא דרכיב על חויא קיים איהו,\u0004 כי אע\"פ שסמאל נאחז בו לא ביטל אותו בזה, \u0003ואתקיים בגוון ולא אתבר,\u0004 כי אע\"פ שאין לו תקון בעצם מהותו מ\"מ יש לו תקון בגוון שלו, כי גוון שלו שהוא שחור, נכלל בג' גוונים דקדושה שבט\"ס ראשונות, ומקבל מהם הארה ותקון, שיתקיים באופן שיהיה ראוי לבירור לעתיד לבא."],[9,"וחילא בעינן וכו':","וצריכים להרבות כח הקדושה בעולם, ולהראות, כמ\"ש, כי שרית עם אלקים ועם אנשים ותוכל. וכשהוא רואה, שגיד הנשה לא נשבר, כי ממשיכים לו הארה לקיום כנ\"ל, ולא אתאכיל אותו מקום, דהיינו שנשמרו מלאכלו שפירושו בירור, כנ\"ל בדיבור הסמוך, אז נשבר כחו ותוקפו של סמאל, ואינו יכול להרע לבני יעקב. ועל כן אין אנו צריכים ליתן מקום לבריות העולם לאכול אותו ולהנות ממנו."]],[[0,"","וְכָל אוֹתָם נְבִיאִים לֹא יָכְלוּ לַעֲמֹד עַל מַה שֶּׁעָתִיד לַעֲשׂוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא לְעֵשָׂו, פְּרָט לְעוֹבַדְיָה הַנָּבִיא שֶׁהָיָה גֵר, שֶׁבָּא מִצַּד שֶׁל עֵשָׂו - זֶה עָמַד בְּקִיּוּמוֹ עַל עֵשָׂו וְלֹא נֶחֱלַשׁ כֹּחוֹ. וְעַל זֶה כָּל שְׁאָר הַנְּבִיאִים נֶחֱלַשׁ כֹּחָם וְלֹא הָיוּ יְכוֹלִים לַעֲמֹד לְקַבֵּל דָּבָר עַל בֻּרְיוֹ כָּרָאוּי. מָה הַטַּעַם? מִשּׁוּם כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב בְּגִיד הַנָּשֶׁה. שֶׁלָּקַח וְשָׁאַב כָּל כֹּחַ הַיָּרֵךְ, וְעַל זֶה נִשְׁבַּר כֹּחַ הַיָּרֵךְ וְנִשְׁאַר צוֹלֵעַ עַל יְרֵכוֹ, שֶׁהֲרֵי כָּל נְבִיאֵי הָעוֹלָם לֹא יָכְלוּ לְהִדָּבֵק וְלַעֲמֹד בּוֹ."],[1,"","בֹּא רְאֵה, כָּל הַנְּבִיאִים פְּרָט לְמֹשֶׁה לֹא עָמְדוּ בְּכֹחָם כָּרָאוּי, וּמִי שֶׁעוֹסֵק בַּתּוֹרָה וְאֵין מִי שֶׁתּוֹמֵךְ בּוֹ, לֹא נִמְצָא מִי שֶׁמַּטִּיל מְלַאי לְכִיסוֹ לְהִתְחַזֵּק. עַל זֶה הַתּוֹרָה מִשְׁתַּכַּחַת בְּכָל דּוֹר וָדוֹר וְנֶחֱלָשׁ כֹּחַ הַתּוֹרָה כָּל יוֹם וָיוֹם, מִשּׁוּם שֶׁאֵין לָהֶם לְאֵלּוּ שֶׁעוֹסְקִים בַּתּוֹרָה עַל מַה שֶּׁסּוֹמְכִים, וּמַלְכוּת הָרִשְׁעָה מִתְחַזֶּקֶת בְּכָל יוֹם וָיוֹם."],[2,"","בֹּא רְאֵה כַּמָּה גָרַם חֵטְא זֶה, וּמִשּׁוּם שֶׁאֵין (לו) מִי שֶׁיִּתְמֹךְ בַּתּוֹרָה כָּרָאוּי, אוֹתָם עַמּוּדִים חַלָּשִׁים, וְגוֹרְמִים לְהִתְחַזֵּק אֶת אוֹתוֹ שֶׁאֵין לוֹ שׁוֹקַיִם וְרַגְלַיִם לַעֲמֹד עֲלֵיהֶם."],[3,"","פָּתַח וְאָמַר, (בראשית ב) וַיֹּאמֶר ה' אֱלֹהִים אֶל הַנָּחָשׁ כִּי עָשִׂיתָ זֹאת אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגוֹ' עַל גְּחֹנְךְ תֵלֵךְ. מַה זֶּה עַל גְּחֹנְךְ תֵלֵךְ? שֶׁנִּשְׁבְּרוּ הַתּוֹמְכִים שֶׁלּוֹ וְקִצְּצוּ אֶת רַגְלָיו וְאֵין לוֹ עַל מַה שֶּׁיַּעֲמֹד. כְּשֶׁיִּשְׂרָאֵל לֹא רוֹצִים לִתְמֹךְ בַּתּוֹרָה, הֵם נוֹתְנִים לוֹ תּוֹמְכִים וְשׁוֹקַיִם לַעֲמֹד וּלְהִתְחַזֵּק בָּהֶם."],[4,"","בֹּא רְאֵה כַּמָּה עֲקִימוּת וְהִתְחַכְּמוּת הִתְחַכֵּם בְּאוֹתוֹ לַיְלָה אוֹתוֹ הָרוֹכֵב עַל הַנָּחָשׁ כְּנֶגֶד יַעֲקֹב, שֶׁהֲרֵי הוּא הָיָה יוֹדֵעַ שֶׁכָּתוּב (שם כז) הַקֹּל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו, וְאִם פּוֹסֵק קוֹל יַעֲב, אָז וְהַיָּדַיִם יְדֵי עֵשָׂו. לָכֵן הִסְתַּכֵּל לְכָל הַצְּדָדִים לְהָרַע לְיַעֲקֹב וּלְהַפְסִיק קוֹלוֹ."],[5,"","וְרָאָה אוֹתוֹ חָזָק בַּכֹּל; זְרוֹעוֹת מִצַּד זֶה וּמִצַּד זֶה שֶׁהֵם חָזְקֵי הַגּוּף שֶׁמִּתְחַזֵּק בֵּינֵיהֶם, וְרָאָה כֹּחַ הַתּוֹרָה שֶׁהִתְחַזֵּק בַּכֹּל, אָז וַיַּרְא כִּי לֹא יָכֹל לוֹ. מֶה עָשָׂה? מִיָּד - וַיִּגַּע בְּכַף יְרֵכוֹ, שֶׁהִתְחַכֵּם כְּנֶגְדּוֹ. אָמַר, כֵּיוָן שֶׁנִּשְׁבְּרוּ עַמּוּדֵי וְתוֹמְכֵי הַתּוֹרָה, מִיָּד הַתּוֹרָה לֹא מִתְחַזֶּקֶת, אָז יִתְקַיֵּם מַה שֶּׁאָמַר אֲבִיהֶם הַקֹּל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו, (שם) וְהָיָה כַּאֲשֶׁר תָּרִיד וּפָרַקְתָּ עֻלּוֹ מֵעַל צַוָּארֶךְ."],[6,"","וּבָזֶה הִתְחַכֵּם כְּנֶגֶד יַעֲקֹב. שֶׁהֲרֵי מִשּׁוּם שֶׁנִּשְׁבַּר כֹּחַ הַתּוֹרָה, הָלַךְ וְהִתְחַזֵּק עֵשָׂו. וּכְשֶׁרָאָה שֶׁלֹּא יָכֹל לַתּוֹרָה, אָז הֶחֱלִישׁ כֹּחַ אוֹתָם הַתּוֹמְכִים אוֹתָהּ. וּכְשֶׁלֹּא נִמְצָא מִי שֶׁסּוֹמֵךְ אֶת הַתּוֹרָה, אָז לֹא יִהְיֶה קוֹל קוֹל יַעֲקֹב, וְיִהְיוּ הַיָּדַיִם יְדֵי עֵשָׂו."],[7,"","וּכְשֶׁרָאָה יַעֲקֹב כָּךְ כְּשֶׁעָלָה הַבֹּקֶר, הֶחֱזִיק (יעקב) בּוֹ וְהִתְגַּבֵּר עָלָיו, עַד שֶׁהוּא בֵּרַךְ אוֹתוֹ וְהוֹדָה לוֹ עַל אוֹתָן בְּרָכוֹת, וְאָמַר לוֹ, לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךְ כִּי אִם יִשְׂרָאֵל. לֹא יַעֲקֹב בַּעֲקִימוּת, אֶלָּא בְּגַאֲוָה וְכֹחַ, שֶׁאֵין מִי שֶׁיּוּכַל לְךְ."],[8,"","וּבֹא וּרְאֵה, מֵהַנָּחָשׁ הַזֶּה כַּמָּה כֹחוֹת נִפְרָדִים לְכָל צַד וְנִמְצָאִים בָּעוֹלָם אֵצֶל בְּנֵי אָדָם, וְרוֹצִים לְקַיֵּם אוֹתוֹ גִּיד הַנָּשֶׁה. שֶׁאַף עַל גַּב שֶׁקָּרַב אֵלָיו אוֹתוֹ רוֹכֵב עַל נָחָשׁ, עוֹמֵד הוּא וְהִתְקַיֵּם בְּצוּרָה וְלֹא נִשְׁבָּר."],[9,"","וְכֹחַ צְרִיכִים לְהִתְחַזֵּק בָּעוֹלָם וּלְהֵרָאוֹת, כִּי שָׂרִיתָ עִם אֱלֹהִים וְעִם אֲנָשִׁים וַתּוּכָל. וּכְשֶׁרָאָה שֶׁהֲרֵי לֹא נִשְׁבַּר וְלֹא נֶאֱכַל אוֹתוֹ מָקוֹם, אָז נִשְׁבַּר כֹּחוֹ וְחָזְקוֹ וְלֹא יָכֹל לְהָרַע לִבְנֵי יַעֲקֹב, וְעַל זֶה לֹא צְרִיכִים לָתֵת מָקוֹם לִבְרִיּוֹת הָעוֹלָם לֶאֱכֹל אוֹתוֹ וְלֹא לֵהָנוֹת מִמֶּנּוּ כְּלָל."]]],[["רַבִּי יֵיסָא סָבָא דָּרַשׁ, כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב. כְּתִיב הָכָא כִּי נָגַע בְּכַף, וּכְתִיב הָתָם (במדבר י״ט:י״ג) כָּל הַנּוֹגֵעַ בְּמֵת בְּנֶפֶשׁ הָאָדָם (יטמא) וְגו'. מַה לְּהַלָּן מְסָאֲבָא אוּף הָכָא נָמֵי מְסָאֲבָא, דְּסָאִיב הַהוּא אֲתַר, וּמֵאֲתַר מְסָאֲבָא לֵית לָן (לאתתקנא) לְאִתְהֲנָאָה מִנֵּיהּ כְּלַל, כָּל שֶׁכֵּן בְּאֲתַר דְּקָרִיב הַהוּא סְטַר מְסָאֲבָא, וְאוֹרַיְיתָא לָא קָאֲמַר אֶלָּא כִּי נָגַע, וּכְתִיב וַיִּגַּע בְּכַף יְרֵכוֹ, כְּמָה דְאַתְּ אָמֵר, (במדבר י״ט:כ״ב) וְכֹל אֲשֶׁר יִגַּע בּוֹ הַטָּמֵא יִטְמָא, בְּרִיךְ רַחֲמָנָא דְּיָהִיב אוֹרַיְיתָא לְיִשְׂרָאֵל לְמִזְכֵּי בָהּ בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי כְּמָה דִכְתִיב, (משלי ג׳:ט״ז) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד:","וְהוּא עָבַר לִפְנֵיהֶם וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (שמות לה) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר כִּי יְיָ קַנָּא שְׁמוֹ. וְכִי יַעֲקֹב דְּאִיהוּ שְׁלֵימָא דְּאֲבָהָן דְּאִתְבְּרִיר חוּלָקָא שְׁלֵימָתָא לְקוּדְשָׁא בְּרִיךְ הוּא וְאִיהוּ אִתְקְרִיב לְגַבֵּיהּ יַתִּיר, (ס\"א ואשתלים לעילא ולתתא) הֵיךְ סָגִיד לֵיהּ לְהַהוּא רָשָׁע דְּעֵשָׂו דְּאִיהוּ בְּסִטְרָא דְאֵל אַחֵר, וּמַאן דְּסָגִיד לֵיהּ סָגִיד לְאֵל אַחֵר. אִי תֵימָא בְּגִין דְּאָמְרוּ תַּעְלָא בְּעִדָנֵיהּ סָגִיד לֵיהּ, לָאו הָכִי. דְּהָא עֵשָׂו כְּאֵל אַחֵר הֲוָה, וְיַעֲקֹב לא יִסְגוֹד לְהַהוּא סִטְרָא וּלְהַהוּא חוּלָקָא כְּלַל.","(פתח רבי אבא ואמר) אֶלָא כְּתִיב, (שמואל א כ״ה:ו׳) וַאֲמַרְתֶּם כֹּה לֶחָי וְאַתָּה שָׁלוֹם וּבֵיתְךָ שָׁלוֹם וְכָל אֲשֶׁר לְךָ שָׁלוֹם. וְהָא אִתְּמָר דְּאָסִיר (ד\"א ל\"ג ליה) לְאַקְדוּמֵי לְהוּ שְׁלָם לְרַשִּׁיעַיָא, וְכֵיוָן דְּאָסִיר הֵיכִי אַשְׁכַּחְנָא דְּדָוִד אָמַר הַאי קְרָא לְנָבָל, אֶלָּא הָא אוּקְמוּהָ (שמות כג ב) דִּלְקוּדְשָׁא בְּרִיךְ הוּא קָאֲמַר, בְּגִין לְקָשְׁרָא לֵיהּ לְחַי. וְחָשִׁיב נָבָל דְּעֲלֵיהּ קָאֲמַר.","כְּגַוְונָא דָא (בראשית יב) וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, וְכִי לְגַבֵּי דִבְרֵיהּ סְגִיד. אֶלָּא לְאַתְרֵיהּ דִּשְׁכִינְתָּא קָא כָּרַע וְסָגִיד, אוּף הָכָא, וְהוּא עָבַר לִפְנֵיהֶם. מַאי וְהוּא, דָּא שְׁכִינְתָּא עִלָּאָה דְּהֲוָה אָזְלָא קַמֵּיהּ (כרע), וְדָא הוּא נְטִירוּ עִלָּאָה. כֵּיוָן דְּחָמָא יַעֲקֹב, אָמַר, הָא עִידָן לְסָגְדָא לְגַבֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא דְּהֲוָה אָזִיל קַמֵּיהּ.","כָּרַע וְסָגִיד שְׁבַע זִמְנִין עַד גִּשְׁתּוֹ עַד אָחִיו, וְלָא כְּתִיב וַיִּשְׁתַּחוּ לְעֵשָׂו. אֶלָּא כֵּיוָן דְּחָמָא דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אָזַל קַמֵּיהּ, כְּדֵין סָגִיד לְקֳבְלֵיהּ. בְּגִין דְּלָא לְמֵיהַב יְקָר לְמִסְגַד לְאָחֳרָא בַּר מִנִּיהּ, וְכֹלָּא אִיהוּ כְּדְקָא יְאוּת. זַכָּאִין אִינוּן צַדִּיקַיָיא דְּכָל עוֹבָדֵיהוֹן דְּקָא עָבְדֵי בְּגִין יְקָרָא דְמָארֵיהוֹן אִיהוּ, וּבְגִין דְּלָא יִסְטוּן לִימִינָא וְלִשְׂמָאלָא:","וַיָּרָץ עֵשָׂו לִקְרָאתוֹ וַיְחַבְּקֵהוּ וַיִּפֹּל עַל צַוָּארָו. צַוָּארוֹ כְּתִיב חָסֵר. וַיִּשָּׁקֵהוּ וַיִּבְכּוּ. רַבִּי יִצְחָק אָמַר (ישעיהו נ״ז:כ׳) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ כִּי הַשְׁקֵט לֹא יוּכַל וַיִּגְרְשׁוּ מֵימָיו רֶפֶשׁ וָטִיט, הַאי קְרָא אִתְּמָר. וּמִלֵּי דְאוֹרַיְיתָא, כַּמָּה רָזִין עִלָּאִין אִית בְּהוּ מְשַׁנְיָין דָּא מִן דָּא, וְכֹלָּא חַד.","וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ כִּי הַשְׁקֵט לא יוּכָל, דָּא עֵשָׂו דְּכָל עוֹבָדוֹי בִּרְשִׁיעוּ וּבְחִיּוּבָא, דְהָא כַּד אֲתָא לְגַבֵּיהּ דְּיַעֲקֹב, עוֹבָדוֹי לָא הֲווּ בִּשְׁלָם, וַיִּפּוֹל עַל צַוָּארָו, חַד. צַוָּארוֹ דָּא יְרוּשָׁלַ ם דְּאִיהוּ צַוָּארוֹ דְּכָל עָלְמָא. וַיִּפֹּל עַל צַוָּארוֹ, וְלא עַל צַוָּארָיו. בְּגִין דִּתְרֵין זִמְנִין אִתְחָרִיב בֵּי מַקְדְּשָׁא. חַד מִבָּבֶל, וְחַד מִזַּרְעֵיהּ דְּעֵשָׂו, דְּאַפִּיל גַּרְמֵיהּ עֲלֵיהּ זִמְנָא חָדָא וְחָרִיב לֵיהּ. וְעַל דָּא וַיִּפֹּל עַל צַוָּארוֹ חַד.","וַיִּשָּׁ\"קֵהוּ, נָקוּד לְעֵיל, דְּלָא נָשְׁקֵיהּ בִּרְעוּתֵיהּ. וּתְנַן מַאי דִכְתִיב, (משלי כ״ז:ו׳) וְנְעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא, דָּא בִּלְעָם כַּד בָּרִיךְ לוֹן לְיִשְׂרָאֵל. דְהָא לָא בָּרִיךְ לוֹן בִּרְעוּתָא דְלִבָּא. אוּף הָכָא נֶעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא, דָּא עֵשָׂו.","אָמַר רִבִּי יוֹסֵי, כְּתִיב (תהילים ג׳:ח׳) קוּמָה יְיָ הוֹשִׁיעֵנִי אֱלֹהַי כִּי הִכִּיתָ אֶת כָּל אוֹיְבַי לֶחִי שִׁנֵּי רְשָׁעִים שִׁבַּרְתָּ. וּתְנַן אַל תִּקְרֵי שִׁבַּרְתָּ אֶלָּא שִׁרְבַּבְתָּ. דְּהָא אַסְגִּיאוּ שִׁינוֹי וְחָשִׁיב לְנָשְׁכָא לֵיהּ וְכוּ'. וְעַל דָּא וַיִּבְכּוּ, דָּא בָּכֵי וְדָא בָּכֵי, וְאוּקְמוּהָ חַבְרַיָיא."],[[0,"ר' ייסא סבא וכו':","רי\"ס דרש, כי נגע בכף ירך יעקב, כתוב כאן כי \u0003נגע\u0004 בכף, וכתוב שם כל \u0003הנוגע\u0004 במת וגו', מה שם הוא טומאה, אף כאן טומאה, כי סמאל טימא אותו מקום, דהיינו את גיד הנשה, וממקום טמא אין לנו להנות ממנו כלום, ומכל שכן במקום שאותו צד הטומאה, שהוא סמאל, קרב אליו. והתורה אינה אומרת יותר אלא, \u0003כי נגע,\u0004 שכתוב, ויגע בכף ירכו, כמש\"א, וכל אשר יגע בו הטמא יטמא. ללמד שסמאל טימא אותו מקום בנגיעתו, ברוך הרחמן, שנתן תורה לישראל לזכות על ידה בעולם הזה ובעולם הבא. כמ\"ש ארך ימים וגו'."],[1,"והוא עבר לפניהם וגו':","ר' אלעזר פתח ואמר, כי לא תשתחוה לאל אחר וגו', ומקשה, וכי יעקב, שהוא הבחיר שבאבות שנבחר חלק שלם להקב\"ה, ונתקרב לו ביותר, איך השתחוה לאותו רשע עשו, שהוא בצד אל אחר, ומי שמשתחוה לו משתחוה לאל אחר. ואם תאמר שהוא משום שאמרו, השועל שהגיע שעתו השתחוה לו, משל הוא, שיש זמן שהשועל מולך על כל החיות, ואז אע\"פ שהוא הקטן שבחיות, כולם משתחוים לו, וגם כאן \u0003תאמר\u0004 שע\"כ השתחוה יעקב לעשו, מפני שהשעה היתה משחקת לו, אינו כן, כי עשו הוא כאל אחר, ויעקב לעולם לא ישתחוה לאותו הצד ולאותו החלק."],[2,"אלא כתיב וכו':","ומשיב, אלא כתוב, ואמרתם כה לחי ואתה שלום וגו', ומקשה, והרי למדנו, שאסור להקדים שלום לרשעים, ואם אסור איך מצאנו, שדוד אמר את המקרא הזה לנבל, שהיה רשע ואומר, אלא בארוהו, שלהקב\"ה אמר זאת, כדי לקשר את נבל \u0003לחי\u0004 שהוא הקב\"ה. כלומר, שהכתוב ואמרתם כה \u0003לחי\u0004, פירושו שיאמרו כן \u0003לחי\u0004 העולמים, דהיינו אל הקב\"ה. ולא לנבל, ונבל יחשוב שאומר עליו."],[3,"כגוונא דא וכו':","כעין זה וישתחו ישראל על ראש המטה, שקשה, וכי לבנו השתחוה, אלא למקום השכינה היה כורע ומשתחוה, שהיתה בראש המטה. כי השכינה נמצאת למראשותיו של חולה. אף כאן, \u0003והוא\u0004 עבר לפניהם, מהו \u0003והוא,\u0004 זהו השכינה העליונה שהיתה הולכת לפניו, שהיא השמירה העליונה שהיתה משמרתו, כיון שראה אותה יעקב, אמר עתה הגיעה השעה להשתחוות אל הקב\"ה, שהיה הולך לפניו."],[4,"כרע וסגיד וכו':","כרע והשתחוה שבע פעמים עד גשתו עד אחיו, ולא כתוב וישתחו לעשו, אלא כיון שראה שהקב\"ה הולך לפניו, אז השתחוה לנגדו. כדי שלא לתת כבוד להשתחוות לאחר זולתו, והכל הוא כראוי. אשרי הם הצדיקים שכל מעשיהם שעושים הם בשביל כבודו של רבונם, וכדי שלא יטו ימין ושמאל מדרך הישר והאמצעי."],[5,"וירץ עשו לקראתו וגו':","צוארו כתוב חסר \u0003י'.\u0004 וכתוב וישקהו ויבכו. ר' יצחק אמר, והרשעים כים נגרש וגו'. מקרא זה בארוהו. ודברי תורה, יש בהם כמה סודות עליונים המשונים זה מזה, והכל הוא אחד."],[6,"והרשעים","כים נגרש כי השקט לא יוכל, זהו עשו, שכל מעשיו הם ברשעות ובחטא, וכשבא ליעקב לא היו מעשיו בשלמות. ויפול על צוארו היינו צואר אחד, כי חסרה \u0003י',\u0004 ירושלים שהיא הצואר של כל העולם, ואומר הכתוב, ויפול על צוארו, ולא על צואריו עם \u0003י'\u0004, משום ששתי פעמים נחרב בית המקדש, פעם אחת מבבל, ואחת מזרעו של עשו, ונמצא שהפיל עשו את עצמו על ירושלים והחריבה רק פעם אחת. וע\"כ כתוב ויפול על צוארו, אחד, דהיינו בלי \u0003י'\u0004, שמשמעותו, שהחריבה רק פעם אחת."],[7,"וישקהו נקוד לעיל וכו':","וישקהו, מנוקד מלמעלה על האותיות, שזה מרמז, שלא נשקו ברצון. ולמדנו מ\"ש, ונעתרות נשיקות שונא, זהו בלעם, כשברך את ישראל, כי לא ברך אותם ברצון הלב. אף כאן נעתרות נשיקות שונא, זהו עשו."],[8,"אמר רבי יוסי וכו':","אר\"י, כתוב, קומה וגו' שני רשעים שברת, ולמדנו, אל תקרא שברת, אלא שרבבת. שזה נאמר על עשו, שנתרברבו שניו, שחשב לנשוך אותו."]],[[0,"","רַבִּי יֵיסָא הַזָּקֵן דָּרַשׁ, כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב - כָּתוּב כָּאן כִּי נָגַע בְּכַף, וְכָתוּב שָׁם (במדבר יט) כָּל הַנֹּגֵעַ בְּמֵת בְּנֶפֶשׁ הָאָדָם (יטמא). מַה לְּהַלָּן טֻמְאָה - אַף כָּאן גַּם טֻמְאָה, שֶׁטִּמֵּא אוֹתוֹ מָקוֹם, וּמִמָּקוֹם טָמֵא אֵין לָנוּ (להתתקן) לֵהָנוֹת מִמֶּנּוּ כְּלָל. כָּל שֶׁכֵּן בְּמָקוֹם שֶׁקָּרַב אוֹתוֹ צַד הַטֻּמְאָה, וְהַתּוֹרָה לֹא אָמְרָה אֶלָּא כִּי נָגַע, וְכָתוּב וַיִּגַּע בְּכַף יְרֵכוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שם) וְכֹל אֲשֶׁר יִגַּע בּוֹ הַטָּמֵא יִטְמָא. בָּרוּךְ הָרַחֲמָן שֶׁנָּתַן תּוֹרָה לְיִשְׂרָאֵל לִזְכּוֹת בָּהּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (משלי ג) אֹרֶךְ חַיִּים בִּימִינָהּ בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד."],[1,"","וְהוּא עָבַר לִפְנֵיהֶם וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (שמות לד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר כִּי ה' קַנָּא שְׁמוֹ. וְכִי יַעֲקֹב, שֶׁהוּא בְּחִיר הָאָבוֹת, שֶׁנִּבְחַר חֵלֶק שָׁלֵם לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהוּא הִתְקָרֵב אֵלָיו יוֹתֵר (ס\"א ונשלם למעלה ולמטה), אֵיךְ הִשְׁתַּחֲוָה לְאוֹתוֹ עֵשָׂו הָרָשָׁע שֶׁהוּא בְּצַד שֶׁל אֵל אַחֵר, וּמִי שֶׁסּוֹגֵד לוֹ - סוֹגֵד לְאֵל אַחֵר? אִם תֹּאמַר מִשּׁוּם שֶׁאָמְרוּ, שׁוּעָל בִּשְׁעָתוֹ הִשְׁתַּחֲוֵה לוֹ - לֹא כָּךְ, שֶׁהֲרֵי עֵשָׂו כְּמוֹ אֵל אַחֵר הָיָה, וְיַעֲקֹב לֹא יִשְׁתַּחֲוֶה לְאוֹתוֹ צַד וּלְאוֹתוֹ חֵלֶק כְּלָל."],[2,"","(פתח רבי אבא ואמר), אֶלָּא כָּתוּב (שמואל א כה) וַאֲמַרְתֶּם כֹּה לֶחָי וְאַתָּה שָׁלוֹם וּבֵיתְךְ שָׁלוֹם וְכָל אֲשֶׁר לְךְ שָׁלוֹם. וַהֲרֵי נִתְבָּאֵר שֶׁאָסוּר (לו) לְהַקְדִּים שָׁלוֹם לָרְשָׁעִים, וְכֵיוָן שֶׁאָסוּר, אֵיךְ מָצָאנוּ שֶׁדָּוִד אָמַר פָּסוּק זֶה לְנָבָל? אֶלָּא הֲרֵי פֵּרְשׁוּהָ שֶׁאָמַר לַקָּדוֹשׁ- בָּרוּךְ-הוּא כְּדֵי לְקַשֵּׁר אוֹתוֹ לְחַי, וְחָשַׁב נָבָל שֶׁעָלָיו אָמַר."],[3,"","כְּמוֹ זֶה (בראשית מז) וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, וְכִי אֶל בְּנוֹ הוּא הִשְׁתַּחֲוָה? אֶלָּא לִמְקוֹם הַשְּׁכִינָה כָּרַע וְהִשְׁתַּחֲוָה, אַף כָּאן וְהוּא עָבַר לִפְנֵיהֶם. מַה זֶּה וְהוּא? זוֹ שְׁכִינָה עֶלְיוֹנָה שֶׁהָיְתָה הוֹלֶכֶת לְפָנָיו (כרע), וְזוֹהִי שְׁמִירָה עֶלְיוֹנָה. כֵּיוָן שֶׁרָאָה יַעֲקֹב, אָמַר, הִנֵּה זְמַן לְהִשְׁתַּחֲווֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא שֶׁהָיָה הוֹלֵךְ עִמּוֹ."],[4,"","כָּרַע וְהִשְׁתַּחֲוָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו, וְלֹא כָתוּב וַיִּשְׁתַּחוּ לְעֵשָׂו. אֶלָּא כֵּיוָן שֶׁרָאָה שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלֵךְ עִמּוֹ, אָז הִשְׁתַּחֲוָה כְּנֶגְדּוֹ, כְּדֵי שֶׁלֹּא לָתֵת כָּבוֹד לְהִשְׁתַּחֲווֹת לְאַחֵר פְּרָט לוֹ, וְהַכֹּל הוּא כָּרָאוּי. אַשְׁרֵי הַצַּדִּיקִים שֶׁכָּל מַעֲשֵׂיהֶם שֶׁעוֹשִׂים בִּשְׁבִיל כְּבוֹד רִבּוֹנָם הוּא, וּכְדֵי שֶׁלֹּא יִסְטוּ יָמִינָה וּשְׂמֹאלָה."],[5,"","וַיָּרָץ עֵשָׂו לִקְרָאתוֹ וַיְחַבְּקֵהוּ וַיִּפֹּל עַל צַוָּארָו. צַוָּארוֹ כָּתוּב חָסֵר. וַיִּשָּׁקֵהוּ וַיִּבְכּוּ. רַבִּי יִצְחָק אָמַר, (ישעיה נז) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ כִּי הַשְׁקֵט לֹא יוּכַל וַיִּגְרְשׁוּ מֵימָיו רֶפֶשׁ וָטִיט. פָּסוּק זֶה נִתְבָּאֵר. וּבְדִבְרֵי תוֹרָה יֵשׁ כַּמָּה סוֹדוֹת עֶלְיוֹנִים מְשֻׁנִּים זֶה מִזֶּה, וְהַכֹּל אֶחָד."],[6,"","וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ כִּי הַשְׁקֵט לֹא יוּכָל - זֶה עֵשָׂו שֶׁכָּל מַעֲשָׂיו בְּרֶשַׁע וּבְחֵטְא, שֶׁהֲרֵי כְּשֶׁבָּא יַעֲקֹב אֵלָיו, מַעֲשָׂיו לֹא הָיוּ בְשָׁלוֹם. וַיִּפֹּל עַל צַוָּארָו - אֶחָד. צַוָּארוֹ זוֹ יְרוּשָׁלַיִם, שֶׁהִיא צַוָּארוֹ שֶׁל כָּל הָעוֹלָם. וַיִּפֹּל עַל צַוָּארָו וְלֹא עַל צַוָּארָיו, מִשּׁוּם שֶׁפַּעֲמַיִם נֶחֱרַב בֵּית הַמִּקְדָּשׁ - אֶחָד מִבָּבֶל, וְאֶחָד מִזַּרְעוֹ שֶׁל עֵשָׂו, שֶׁהִפִּיל עַצְמוֹ עָלָיו פַּעַם אֶחָד וְהֶחֱרִיבוֹ, וְעַל זֶה וַיִּפֹּל עַל צַוָּארָו - אֶחָד."],[7,"","וַיִּשָּׁ\"קֵהוּ נָקוּד לְמַעְלָה, כִּי לֹא נְשָׁקוֹ בִּרְצוֹנוֹ. וְשָׁנִינוּ, מַה זֶּה שֶׁכָּתוּב (משלי כז) וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא? זֶה בִּלְעָם כְּשֶׁבֵּרַךְ אֶת יִשְׂרָאֵל, שֶׁהֲרֵי לֹא בֵרְכָם בִּרְצוֹן הַלֵּב. אַף כָּאן נַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא - זֶה עֵשָׂו."],[8,"","אָמַר רַבִּי יוֹסֵי, כָּתוּב (תהלים ג) קוּמָה ה' הוֹשִׁיעֵנִי אֱלֹהַי כִּי הִכִּיתָ אֶת כָּל אֹיְבַי לֶחִי שִׁנֵּי רְשָׁעִים שִׁבַּרְתָּ. וְשָׁנִינוּ, אַל תִּקְרֵי שִׁבַּרְתָּ אֶלָּא שִׁרְבַּבְתָּ, שֶׁהֲרֵי גָּדְלוּ שִׁנָּיו וְחָשַׁב לִנְשֹׁךְ אוֹתוֹ וְכוּ'. וְעַל זֶה וַיִּבְכּוּ, זֶה בָּכָה וְזֶה בָּכָה, וּבֵאֲרוּהָ הַחֲבֵרִים."]]],[["תָּא חֲזֵי, כַּמָּה הֲוָה לִבֵּיהּ וּרְעוּתֵיהּ דְּעֵשָׂו לְגַבֵּי דְיַעֲקֹב, דְּהָא אֲפִילּוּ בְּהַהוּא שַׁעְתָּא חָשִׁיב לְאֹרֶךְ זִמְנִין (ס\"א לאורכא דיומין) לְמֶעְבַּד לֵיהּ בִּישִׁין וּלְקַטְרְגָא לֵיהּ, וְעַל דָּא וַיִּבְכּוּ. דָּא הֲוָה בָּכֵי, דְּלָא הֲוָה חָשִׁיב לְאִשְׁתְּזָבָא מִן יְדוֹי. וְדָא הֲוָה בָּכֵי, בְּגִין דְּאֲבוֹי הֲוָה קַיָּים וְלָא יָכִיל לֵיהּ.","אָמַר רִבִּי אַבָּא וַדַּאי אִתְחַלַּשׁ רוּגְזֵיהּ דְּעֵשָׂו בְּשַׁעְתָּא דְחָמָא לֵיהּ לְיַעֲקֹב. מַאי טַעְמָא, בְּגִין דְּהָא אִסְתַּכַּם בַּהֲדֵיהּ הַהוּא מְמַנָּא דְעֵשָׂו. וְעַל דָא לָא יָכִיל עֵשָׂו לְשַׁלְטָאָה בְּרוּגְזֵיהּ, דְּהָכִי כָּל מִלִּין דְּהַאי עַלְמָא תַּלְיָין לְעֵילָא. וְכַד אִסְתַּכְּמוּ לְעֵילָא בְּקַדְמִיתָא אִסְתַּכְּמוּ לְתַתָּא. שָׁלְטָנוּתָא לָאו אִיהוּ לְתַתָּא עַד דְּאִיתְיָהִיב שָׁלְטָנוּתָא לְעֵילָא, וְכֹלָּא דָּא בְּדָא תַלְיָא:","יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ וַאֲנִי אֶתְנַהֲלָה לְאִטִּי וְגו'. אָמַר רִבִּי אֶלְעָזָר, הַיְינוּ דְקָאַמְרִינָן בְּקַדְמִיתָא דְּיַעֲקֹב לָא בָּעָא הַשְׁתָּא אִינוּן בִּרְכָאן קַדְמָאי דְּבָרְכֵיהּ אֲבוֹי. (ס\"א בגין דכתיב, (איכה ג׳:כ״ז) טוב לגבר כי ישא על בנעוריו. וכתיב (משלי ל״א:כ״ה) ותשחק ליום אחרון) וַעֲדַיִין לָא אִתְקַיְימוּ בֵּיהּ אֲפִילּוּ חַד מִנַּיְיהוּ. בְּגִין דְּסָלִיק לוֹן לְסוֹף יוֹמַיָא בְּשַׁעְתָּא דְּאִצְטְרִיכוּ לִבְנוֹי לְגַבֵּי כָּל עַמִּין דְּעַלְמָא.","וּבְגִין כָּךְ בְּשַׁעְתָּא דְּאָמַר עֵשָׂו נִסְעָה וְנֵלֵכָה, וְנִפְלוּג הַאי עַלְמָא כְּחֲדָא וְנִשְׁלוֹט כְּחֲדָא. מַה אָמַר, יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ. יַקְדִּים עֵשָׂו שָׁלְטָנֵיהּ הַשְׁתָּא בְּהַאי עַלְמָא. יַעֲבָר נָא, כְּמָה דְאַתְּ אָמֵר, (מיכה ב׳:י״ג) וַיַּעֲבוֹר מַלְכָּם לִפְנֵיהֶם וַיְיָ בְּרֹאשָׁם, אַקְדִּים אַנְתְּ שׁוּלְטָנוּתָךְ בְּקַדְמִיתָא בְּהַאי עַלְמָא, וַאֲנִי אֶתְנַהֲלָה לְאִטִּי. אֲנָא אֲסַלֵּק גַּרְמִי לְהַהוּא עַלְמָא דְאָתֵי וּלְסוֹף יוֹמַיָא לְאִינוּן יוֹמַיָא דְאָזְלִין לְאַט.","לְרֶגֶל הַמְלָאכָה, מַאן מְלָאכָה. דָּא אַסְפַּקְלַרְיָא דְלָא נָהֲרָא דְּבָהּ אִתְעֲבִיד עֲבִידְתָּא דְעָלְמָא. אֲשֶׁר לִפְנֵי, דָּא הִיא מִן קֳדָם יְיָ בְּכָל אֲתַר. וּלְרֶגֶל הַיְלָדִים, דָא הוּא רָזָא דִכְרוּבִים, לְאַחֲזָאָה רָזָא דִמְהֵימְנוּתָא דְּאִיהוּ אִתְדָּבַּק בְּהוּ.","עַד אֲשֶׁר אָבֹא אֶל אֲדֹנִי שֵׂעִירָה, אֲנָא אֶסְבּוֹל גָּלוּתָא דִילָךְ עַד דְּיֵיתֵי וְיִמְטֵי זִמְנָא דִילִי לְשַׁלְטָאָה עַל הַר עֵשָׂו, כְּמָה דְאַתְּ אָמֵר, (עובדיה א׳:כ״א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו, וּכְדֵין וְהָיְתָה לַיְיָ הַמְלוּכָה:","וְיַעֲקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת עַל כֵּן קָרָא שֵׁם הַמָּקוֹם סֻכּוֹת. רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים קכ״ז:א׳) שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה אִם יְיָ לֹא יִבְנֶה בַּיִת וְגו', אִם יְיָ לא יִשְׁמָר עִיר וְגו'. תָּא חֲזֵי, בְּשַׁעְתָּא דְסָלִיק בִּרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עַלְמָא, אַפִּיק (טו א) מִבּוּצִינָא דְקַרְדִינוּתָא חַד קִטּוּרָא, וְאִתְלְהִיט מִגּוֹ חֲשׁוֹכָא, וְאִשְׁתָּאַר בִּסְלִיקוּ. וְנָחֲתָא לְתַתָּא, הַהִיא חֲשֵׁכָה לָהִיט (ואתלהיט) בְּמֵאָה שְׁבִילִין אוֹרְחִין דְּקִיקִין רַבְרְבָן, וְאִתְעֲבִיד בֵּיתָא דְעַלְמָא.","הַאי בֵּיתָא אִיהוּ גוֹ אֶמְצָעִיתָא דְכֹלָּא, כַּמָּה פִּתְחִין וְאִדְרִין לֵיהּ סְחוֹר סְחוֹר, דּוּכְתִּין עִלָּאִין קַדִּישִׁין, תַּמָּן מְקַנְנֵי צִפֳּרֵי שְׁמַיָא, כָּל חַד וְחַד לְזִינֵיהּ. בְּגַוֵּויהּ נָפִיק חַד אִילָנָא רַבְרְבָא וְתַקִּיף עָפְיֵיהּ וְאִנְבֵּיהּ סַגֵּי, מְזוֹנָא לְכֹלָּא בֵּיהּ. הַהוּא אִילָנָא סָלִיק לַעֲנָנֵי שְׁמַיָא וְאִתְטַמַּר בֵּין תְּלַת טוּרִין, מִתְּחוֹת אִילֵּין תְּלַת טוּרִין נָפִיק, סָלִיק לְעֵילָא נָחִית לְתַתָּא.","הַאי בֵּיתָא אִתְשַׁקְיָיא מִנֵּיהּ, וְגָנִיז בְּגַוֵּויהּ כַּמָּה גִּנְזִין עִלָּאִין דְּלָא אִתְיְדָעוּ, בְּדָא אִתְבְּנֵי הַאי בֵּיתָא וְאִשְׁתַּכְלַל הַהוּא אִילָנָא אִתְגַּלְּיָיא בִּימָמָא, וְאִתְכַּסְּיָא בְּלֵילְיָא, וְהַאי בֵּיתָא שָׁלְטָא בְּלֵילְיָא וְאִתְכַּסְּיָא בִּימָמָא.","בְּשַׁעְתָּא דְּעָאל חֲשׁוֹכָא וְאִתְקַטִּיר בֵּיהּ שָׁלְטָא, וְכָל פִּתְחִין סְתִימִין מִכָּל סִטְרִין, כְּדֵין כַּמָּה רוּחִין פָּרְחִין בַּאֲוִירָא, תְּאִיבִין לְמִנְדַע וּלְמֵיעַל בֵּיהּ, וְעָאלִין בֵּין אִינוּן צִפּוֹרִין, וְנָטְלִין סָהֲדוּתָא, וְשָׁטְיָין וְחָמָאן מַה דְּחָמָאן.","עַד דְּאִתְעַר הַהוּא חֲשׁוֹכָא דְּאִתְקַטִּיר בֵּיהּ, וְאַפִּיק חַד שַׁלְהוֹבָא וּבָטַשׁ בְּכָל פַּטִּישִׁין תַּקִּיפִין, וּפְתַח פִּתְחִין, וּבָקַע טִנָּרִין. סַלְקָא וְנָחֲתָא הַהוּא שַׁלְהוֹבָא, וּבָטַשׁ בְּעַלְמָא, וְאִתְעַר קָלִין לְעֵילָא וְתַתָּא."],[[0,"ועל דא ויבכו וכו':","ועל כן \u0003ויבכו,\u0004 זה בכה וזה בכה, בוא וראה, כמה היה לבו ורצונו של עשו להרע ליעקב, כי אפילו באותה שעה שנשקו, חשב, לכשיארכו הימים, יעשה לו רע ויצור אותו. וע\"כ ויבכו, זה היה בוכה, שלא חשב שינצל ממנו, וזה היה בוכה בשביל שאביו היה חי, ואינו יכול לו להרג אותו."],[1,"אמר ר' אבא וכו':","אר\"א, ודאי הוא שנחלש כעסו של עשו בשעה שראה את יעקב. מהו הטעם, הוא משום שהסכים עמו הממונה של עשו, שהשלים עמו והסכים על הברכות, (כנ\"ל דף ל\"ג אות קי\"ג), וע\"כ לא יכול עשו למשול בכעסו, כי כל הדברים שבעולם הזה תלויים למעלה, וכשמסתכמים למעלה תחילה, מסתכמים גם כן למטה. וכן אין ממשלה למטה, עד שניתנה הממשלה מלמעלה. וכן הכל תלוי זה בזה. שכל הנעשה בעולם הזה, תלוי במה שנעשה מלמעלה."],[2,"יעבר נא אדני וגו':","אמר ר' אלעזר, היינו שאמרנו מכבר, שיעקב לא רצה עתה לקבל אלו הברכות הראשונות שברכו אביו. (לעיל תולדות דף פ\"ו אות ר\"א) ועוד לא נתקיימה בו אפילו אחת מהן, משום שדחה אותן לאחרית הימים, שתוצרכנה אז לבניו להשתמש בהן כנגד כל אומות העולם."],[3,"ובגין כך בשעתא וכו':","ומשום זה, בשעה שאמר עשו \u0003נסעה ונלכה,\u0004 נחלק את העולם הזה בינינו, ונשלוט בו יחד. מה אמר יעקב, יעבר נא אדני לפני עבדו. שפירושו, יקדים עשו שליטתו עתה בעולם הזה \u0003יעבר נא\u0004, הוא לשון קדימה, כמו שאתה אומר, ויעבר מלכם לפניהם וה' בראשם, שיעקב אמר לו, הקדם אתה את שליטתך בתחילה בעולם הזה, \u0003ואני אתנהלה לאטי,\u0004 ואני אעלה את עצמי לעולם ההוא הבא. ולאחרית הימים, לאלו הימים ההולכים \u0003לאט.\u0004"],[4,"לרגל המלאכה:","שואל, איזו מלאכה. ומשיב, זו היא המראה שאינה מאירה שהיא הנוקבא דז\"א, שעל ידה נעשית כל מלאכת העולם. \u0003אשר לפני\u0004, זו, דהיינו הנוקבא, הוא בכל מקום, מלפני הויה, שהוא ז\"א. \u0003ולרגל הילדים,\u0004 הם סוד הכרובים, שה\"ס אפי זוטרי (כמ\"ש לעיל, בהק\"ס הזהר דף י\"ב ד\"ה ביאור ע\"ש) להראות סוד האמונה שהיא הנוקבא, שיעקב נתדבק בה. כי על מוחין אלו מתקיימת הנוקבא. (כמ\"ש שם דף י\"ב ד\"ה ואלמלי ע\"ש)."],[5,"עד אשר אבא וגו':","יעקב אמר לו, אני אסבול הגלות שלך, עד שיבוא ויגיע הזמן שלי לשלוט על הר עשו. כמו שאתה אומר, ועלו מושיעים בהר ציון לשפוט את הר עשו. ואז והיתה לד' המלוכה."],[6,"ויעקב נסע סכותה וגו':","ר' חייא פתח ואמר, שיר המעלות לשלמה וגו', בוא וראה, בשעה שעלה ברצונו של הקב\"ה, שהוא ז\"א, לברוא העולם, דהיינו לבנות את פרצוף הנוקבא הנקראת עולם, הוציא מן ניצוץ הקשה, שה\"ס המסך, קשר אחד, כלומר, שז\"א עלה למ\"ן לאמא, ויצאה שם קומת חסדים על המסך דחירק שלו, שקומה זו ה\"ס קו אמצעי \u0003המקשר\u0004 ב' הקוין ימין ושמאל דבינה זה בזה. וע\"כ נקרא \u0003קטירא\u0004 דהיינו \u0003קשר.\u0004 ונדלק מתוך החשך, שנכלל בקו שמאל שהוא חשך והארתו נבחנת להדלקה, בסוד מאורי האש. והארה זו שהיא הארת החכמה, נשארת בעליה. שמאירה ממטה למעלה, והארת עצמו שהיא חסדים, יורדת למטה. דהיינו שמאירה ממעלה למטה. פירוש. כי בשעה שהקו האמצעי מקשר ב' הקוין ימין ושמאל זה בזה, באופן שיאירו שניהם, הוא מקיים אז הארת השמאל, שתאיר ממטה למעלה, והארת הימין ממעלה למטה, (כנ\"ל ב\"א דף נ\"ח ד\"ה עמודא ע\"ש)."],[6,"ההיא חשכה להיט וכו':","אחר שביאר אופן יציאת הקשר שה\"ס קו אמצעי, ואיך שתיקן הארת שניהם כהלכתם, מבאר עתה איך שקו השמאל, שה\"ס חשך, נכלל בעצמו מכל ג' הקוין, והאציל את הנוקבא. ואומר, החשך ההוא דהיינו קו השמאל לוהט ומאיר במאה שבילים, באורחות דקים מן הדקים, ובאורחות גדולים, ונעשו בית העולם, שמהם נבנות הנוקבא, הנקראת \u0003בית.\u0004"],[6,"","פירוש. יסודות דאו\"א מכונים שבילים, ויסודות ישסו\"ת מכונים אורחות, כמ\"ש לעיל (ב\"א דף רנ\"א ד\"ה נחית) ע\"ש ונודע שקו ימין ה\"ס או\"א המאירים באוירא דכיא, שה\"ס חסדים מכוסים. וקו שמאל ה\"ס ישסו\"ת, המאירים בהארת חכמה בסוד י' דנפיק מאויר ואשתאר אור. (כנ\"ל ב\"א דף י\"א ד\"ה זהר) ולפיכך מכנה את התכללות השמאל בקו ימין, בבחינת \u0003מאה שבילין,\u0004 משום שמקבל מיסודות או\"א המכונים שבילין, ומספר מאה הוא, להיותו מישסו\"ת, שספירותיהם במספר מאות. והארת החכמה שבשמאל הנמשכת מיסודות ישסו\"ת המכונים \u0003אורחות,\u0004 מתחלקת לב' בחינות, א) מטרם שנכלל בקו אמצעי, שנבחן לאורחין דקיקין, מטעם היותם אז סתומים וקפואים. ב) אחר התכללותו בקו אמצעי שנבחן \u0003לאורחין רברבן\u0004, כי אז מאיר בהרחבה רבה. \u0003אורחין דקיקין,\u0004 היינו מקו שמאל עצמו, \u0003רברבן\u0004 היינו מקו אמצעי. ואחר שהחשך, שה\"ס השמאל, נכלל בג' הקוין הללו, נבנית ממנו הנוקבא הנקראת \u0003בית\u0004 של העולם."],[7,"האי ביתא איהו וכו':","הבית ההוא, הוא באמצע הכל, היינו בקו האמצעי של כל השבילים והאורחות הנ\"ל. דהיינו באותם הנבחנים, \u0003לאורחין רברבן,\u0004 כמה פתחים וחדרים יש לה לנוקבא. סביב סביב המקומות העליונים הקדושים, שם מקננות צפרי השמים, כל אחת ואחת למינה."],[7,"","פירוש. נה\"י של הנוקבא מכונים \u0003פיתחין\u0004 וחג\"ת שלה מכונים \u0003אדרין,\u0004 שהם מקבלים מג' הקוין הנכללים משמאל דאמא, המכונים במקורם, \u0003תלת דוכתי,\u0004 (כנ\"ל בראשית א' דף כ' ד\"ה שמא דא כלילא בתלת דוכתי) ע\"ש וז\"ש \u0003כמה פתחין ואדרין ליה, סחור סחור דוכתין עלאין קדישין,\u0004 דהיינו שהפתחין והאדרין מקבלים מתלת דוכתי דאמא, שהם המקומות העליונים הקדושים. \u0003צפרי שמיא,\u0004 היינו מלאכי מעלה."],[7,"בגוויה נפיק חד אילנא וכו':","אחר שביאר בנין הנוקבא, מבאר סדר השפעת ז\"א לנוקבא, ואומר בתוכו יוצא אילן אחד גדול ועצום, שהוא ז\"א, המשפיע לתוך הבית, ענפיו ופירותיו רבים, ומזין לכל בו. דהיינו שיש בו הן השפעת חסדים והן השפעת חכמה, וכל אחד מקבל ממנו את בחינתו. ומפרש יותר, האילן ההוא עולה עד ענני השמים, דהיינו להארת החסדים המכונים עננים, ומתכסה בין שלשה הרים, כמ\"ש, אין הרים אלא אבות. (ש\"ר סט\"ו ד') שה\"ס חג\"ת, שבהם החסדים מתכסים שלא לקבל הארת החכמה. ומתחת שלשת ההרים האלו, דהיינו בנה\"י שמתחת חג\"ת, יוצא, עולה למעלה, ויורד למטה. פירוש, שמתחת החג\"ת, יוצאים ומתגלים החסדים בהארת החכמה, על ידי הקו האמצעי המקיים הימין והשמאל, וז\"ש \u0003נפיק\u0004 שהקו האמצעי יוצא מהכיסוי של חג\"ת, ומקיים הארת ימין ושמאל, באופן שהארת השמאל \u0003סליק לעילא,\u0004 תאיר ממטה למעלה. והארת הימין \u0003נחית לתתא,\u0004 תאיר ממעלה למטה, (כנ\"ל דף ל\"ט ד\"ה ויעקב ע\"ש)."],[8,"האי ביתא אתשקייא וכו':","הבית הזה, שהוא הנוקבא, מקבל מז\"א ב' מיני הארות, א) שהיא נשקית ממנו, דהיינו הארת החכמה המכונה שתיה. ב) שז\"א גונז בתוך הבית הרבה אוצרות עליונים שלא נודעו, דהיינו הארת חסדים מאו\"א המכונים גניזין, והם לא נודעו (כנ\"ל ב\"א דף רמ\"ד ד\"ה וכדין) ובזה נבנה הבית ונשתכלל."],[8,"ההוא אילנא אתגלייא","וכו': האילן ההוא, שהוא ז\"א, מתגלה ביום ומתכסה בלילה. ובית ההוא, שהוא הנוקבא, שולט בלילה ומתכסה ביום."],[8,"","פירוש, כי מבאר תכף לפנינו, אשר גם בלילה, שה\"ס הארת השמאל שהוא חשך, מחמת שהחכמה היא בלי חסדים ואינה יכולה להאיר, נוהג גם כן, ענין יציאת קו אמצעי וענין התכללות שמאל בימין וכן זווג זו\"ן, הכל כמו ביום, שלפי זה יש לשאול מה ההפרש בין יום ללילה. ולפיכך מקדים לבאר, שכל ההפרש הוא רק בשליטה. כי גם בלילה מאירים כל ג' הקוין, וכן ז\"א הוא בזווג עם הנוקבא כמו ביום, אלא שהשליטה היא לנוקבא, וז\"א וכן קו ימין טפלים אליה והם כמו מתכסים, כדי לתת מקום לשליטתה. וז\"ס שהקב\"ה נכנס אז לג\"ע שהוא הנוקבא, כדי להשתעשע וכו' דהיינו להשתעשע עם הארת החכמה שבה, ולפיכך אין הארת החסדים ניכרת והיא חשך ולא אור. והיפוכו ביום, שאז הנוקבא טפלה לז\"א, והארת הנוקבא מתכסה וז\"א שולט, ואינו ניכר אלא הארת החסדים, שהיא מדת ז\"א, ולפיכך הוא יום. אמנם בסדר הבנין וסדר הזווג אין הפרש בין יום ללילה כמו שהולך ומבאר לפנינו."],[9,"בשעתא דעאל חשוכא וכו':","בשעה שבא החשך, והנוקבא נקשרה בו, היא שולטת, ומאירה בחכמה שהיא שליטתה כנ\"ל, וכיון שחסרה חסדים, ע\"כ כל הפתחים שבה סתומים מכל הצדדים. כלומר, שכל האורות נקפאים בתוכה, ואין בה פתח, שדרך שם יתגלה אור כלשהו."],[9,"","פירוש כי מביא למעלה (באות קל\"א) סדר ג' הקוין הנכללים בקו השמאל, המכונים \u0003שבילין ואורחין דקיקין,\u0004 ורברבן, ואומר שם, שמהם נבנית הנוקבא ונשתכללה. ע\"ש. ועתה חוזר ומבאר הדברים הללו בהרחבה, ומסדר אותם בסוד ממשלת הלילה. ותדע שג' הקוין הללו שבשמאל ה\"ס \u0003ג' משמרות הוי הלילה,\u0004 דהיינו ג\"פ ד' שעות, (כנ\"ל ב\"א דף שט\"ז אות תי\"א), כי משמרת ראשונה ה\"ס \u0003שבילין,\u0004 שה\"ס מדת הדין של המלכות הבלתי ממותקת, (כנ\"ל ב\"א בדף רנ\"א ד\"ה נחית ע\"ש). וה\"ס התכללות קו ימין שבו, ומשמרת שניה ה\"ס ד' שעות הלילה האמצעיות, והם בבחינת אורחין, דהיינו המלכות הממותקת, כמ\"ש שם, אבל שתי השעות הראשונות עד חצות לילה, ה\"ס \u0003אורחין דקיקין,\u0004 שהם הארת קו השמאל מבחינתו עצמו, מטרם שנכלל מקו אמצעי. ונקודת החצות ה\"ס ביאת קו אמצעי והתכללותו בשמאל, שאז מקבל בחינת \u0003אורחין רברבן,\u0004 כנ\"ל ובחינה זו נמשכת כל הלילה, ומיוחסת בעיקר למשמרת השלישית, אלא זמן גילויה הוא בחצות לילה."],[9,"","וזה אמרו, \u0003בשעתא דעאל חשוכא,\u0004 היינו בתחילת הלילה, משמרת ראשונה, שאז מכונה \u0003שבילין\u0004 כנ\"ל, \u0003ואתקטיר ביה\u0004, היינו אחר כך בתחילת המשמרת השניה, שאז נקשרה הנוקבא בחשך, שהוא קו שמאל דאמא \u0003ושלטא.\u0004 ואז נבחנת \u0003באורחין דקיקין,\u0004 כי בחינה זו היא מטרם שנגלה הקו האמצעי, וע\"כ \u0003וכל פתחין סתימין מכל סטרין,\u0004 כלומר לא בלבד שפתחי החסדים אינם מאירים, אלא אפילו פתחי החכמה אינם מאירים בה, כי אין החכמה יכולה להאיר בלי התלבשות בחסדים, וזה נמשך ב' שעות עד נקודת החצות."],[9,"כדין כמה רוחין וכו':","אז, בב' שעות ההם, הרבה רוחות של הצדיקים, פורחות באויר ומתאוות לדעת, דהיינו לקבל חכמה, ולהכנס בתוך הנוקבא. והן נכנסות בין אותם הצפרים, ולוקחות שם עדות, דהיינו שמקבלים מוחין דעדן שה\"ס חכמה, ומשוטטות ורואות מה שרואות. ראיה היינו מוחין דחכמה."],[9,"","פירוש, אע\"פ שהפתחים שבנוקבא, סתומים בעת ההיא מכל הצדדים, ששום אור לא נגלה ממנה, עם כל זה זמן קבלת אור החכמה, הוא דוקא בעת ההיא. וע\"כ מדייק הזהר לומר \u0003וכל פתחין סתימין,\u0004 שמשמע, שהיא מלאה מאור, אלא הפתחים סתומים, באופן שאחר כך כשיתעורר בו קו אמצעי, ויפתח הפתחים, יקבלו ממנה הארת החכמה שהיתה סתומה בה בעת ההיא. כי אח\"כ מתמעטת מג\"ר לו\"ק, בסבת קו אמצעי, והארתה שפלה בהרבה, ממה שהיתה בעת ההיא, שעוד לא נכללה בקו אמצעי. וז\"ש \u0003כמה רוחין פרחין באוירא תאיבין למנדע ולמיעל ביה,\u0004 שהן משתוקקות להכנס בנוקבא דוקא בעת שהיא בבחינת אורחין דקיקין, ופתחים סתומים, כי רק אז יש בה החכמה בשלמותה, כנ\"ל. וז\"ש \u0003ועאלין בין אינון צפורין ונטלין סהדותא,\u0004 שבאים בין בחינת הצפרים שבנוקבא, ומקבלין מוחין דעדן, דהיינו דחכמה. \u0003צפורין,\u0004 פירושו בחינת נפש של הנוקבא, (כמ\"ש בתקונים תקון ו' דף כ\"ג.) שכינתא מסטרא דכורסיא, שהיא נשמה, אתקריאת \u0003נשר.\u0004 ומסטרא דנער, שהוא רוח, אתקריאת \u0003יונה\u0004, ומסטרא דאופן, שהיא נפש, היא \u0003צפור\u0004, ומשמיענו הזהר, שאפילו אז אין רוחות הצדיקים יכולות לקבל ממנה מבחינת הרוח שבנוקבא, אלא מבחינת הנפש שבה בלבד, וז\"ש \u0003ועאלין בין אינון צפורין, ונטלין סהדותא,\u0004 ולא למעלה מבחינת הצפרים."],[10,"עד דאתער וכו':","וסתימת הפתחים נמשכת עד שמתעורר אותו החשך, דהיינו קו שמאל דאמא, שהנוקבא נקשרה בו, והוציא שלהבת אחת, כלומר שחשך שבנוקבא, עורר את ז\"א לעלות למ\"ן לאמא, בסוד המסך דחירק שבו, הנבחן \u0003לשלהבת\u0004 ויוצא שם עליו קו אמצעי, שהוא מכה בכל הפטישים החזקים דהיינו הקליפות, ופותח הפתחים הסתומים ובוקע הסלעים."],[10,"","פירוש. ב' פעולות יש כאן, פעולה א) נמשכת מעצם השלהבת, שהיא המסך דחירק, והיינו שממעט ע\"ס דקו שמאל מג\"ר לו\"ק, ועליה אומר, \u0003ובקע טנרין,\u0004 כי הספירות דקו שמאל משולות לסלעים קשים מרוב הדינים שבהן והמסך בוקע אותן, וג\"ס ראשונות שבהן, הוא מרחק מהקו השמאלי, ומניח בו רק ז\"ת שבהן. ופעולה ב) נמשכת מקומת החסדים היוצאת על המסך הזה, ועליה אומר, \u0003ופתח פתחין,\u0004 כי החכמה מתלבשת עתה בחסדים האלו, ומאירה בכל השלמות. ונבחן שכל הפתחים שהיו סתומים נפתחו עתה להאיר בהרחבה. וב' הפעולות הללו מבוארות יפה לעיל (פרשת לך דף י\"ג ד\"ה ונתבאר ע\"ש) וכבר ידעת, שהפעולות הללו נעשות באמצע המשמרת השניה שהיא נקודת החצות. כמ\"ש לעיל בסמוך."],[10,"סלקא ונחתא וכו':","השלהבת הזאת שהיא המסך דחירק, עולה ויורדת, שעולה לאמא ע\"י ז\"א כנ\"ל, ואח\"כ יורדת משם לז\"א עצמו, והוא מכה ומשפיע בעולם, שמוציא על ידה, ע\"י זווג דהכאה, קומת חסדים גם בנוקבא, הנקראת עולם, ונתעוררו קולות, למעלה ולמטה, \u0003קולות\u0004 פירושו קומות החסדים היוצאות על מסך דחירק, כנ\"ל (פ' לך דף ד' ד\"ה בשעתא ע\"ש), והקומות הללו יוצאות למעלה בבינה ולמטה בנוקבא."]],[[0,"","בֹּא רְאֵה כַּמָּה הָיָה לִבּוֹ וּרְצוֹנוֹ שֶׁל עֵשָׂו לְיַעֲקֹב, שֶׁהֲרֵי אֲפִלּוּ בְּאוֹתָהּ שָׁעָה חָשַׁב לְאֹרֶךְ זְמַן (באריכות הימים) לַעֲשׂוֹת לוֹ רָעוֹת וּלְקַטְרֵג לוֹ, וְעַל זֶה וַיִּבְכּוּ. זֶה הָיָה בּוֹכֶה שֶׁלֹּא הָיָה חוֹשֵׁב לְהִנָּצֵל מִיָּדוֹ, וְזֶה הָיָה בּוֹכֶה מִשּׁוּם שֶׁאָבִיו הָיָה קַיָּם וְלֹא יָכוֹל לוֹ."],[1,"","אָמַר רַבִּי אַבָּא, וַדַּאי נֶחֱלַשׁ רָגְזוֹ שֶׁל עֵשָׂו בְּשָׁעָה שֶׁרָאָה אֶת יַעֲקֹב. מָה הַטַּעַם? מִשּׁוּם שֶׁהֲרֵי הִסְכִּים עִמּוֹ אוֹתוֹ מְמֻנֶּה שֶׁל עֵשָׂו, וְעַל זֶה לֹא יָכֹל עֵשָׂו לִשְׁלֹט בְּרָגְזוֹ, שֶׁהֲרֵי כָּל הַדְּבָרִים שֶׁל הָעוֹלָם הַזֶּה תְּלוּיִים לְמַעְלָה, וּכְשֶׁהִסְכִּימוּ לְמַעְלָה בַּתְּחִלָּה - הִסְכִּימוּ לְמַטָּה. הַשִּׁלְטוֹן אֵינוֹ לְמַטָּה עַד שֶׁנִּתָּן הַשִּׁלְטוֹן לְמַעְלָה, וְהַכֹּל תָּלוּי זֶה בָּזֶה."],[2,"","יַעָבָר נָא אֲדנִי לִפְנֵי עַבְדּוֹ וַאֲנִי אֶתְנַהֲלָה לְאִטִּי וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, הַיְנוּ מַה שֶּׁאָמַרְנוּ בַּתְּחִלָּה, שֶׁיַּעֲקֹב לֹא רָצָה עַכְשָׁו אוֹתָן בְּרָכוֹת רִאשׁוֹנוֹת שֶׁבֵּרְכוֹ אָבִיו, (משום שכתוב (איכה ג) טוב לגבר כי ישא על בנעוריו, וכתוב (משלי לא) ותשחק ליום אחרון) וַעֲדַיִן לֹא הִתְקַיְּמוּ בוֹ אֲפִלּוּ אֶחָד מֵהֶם, מִשּׁוּם שֶׁהֶעֱבִיר אוֹתָם לְסוֹף הַיָּמִים בְּשָׁעָה שֶׁיִּצְטָרְכוּ לְבָנָיו מוּל כָּל עַמֵּי הָעוֹלָם."],[3,"","וְלָכֵן בְּשָׁעָה שֶׁאָמַר עֵשָׂו נִסְעָה וְנֵלֵכָה, וּנְחַלֵּק הָעוֹלָם הַזֶּה כְּאֶחָד וְנִשְׁלֹט כְּאֶחָד - מָה אָמַר יַעֲקֹב יַעֲבָר? נָא אֲדנִי לִפְנֵי עַבְדּוֹ. יַקְדִּים עֵשָׂו שִׁלְטוֹנוֹ עַכְשָׁו בָּעוֹלָם הַזֶּה, יַעֲבָר נָא, כְּמוֹ שֶׁנֶּאֱמַר (מיכה ב) וַיַּעֲבֹר מַלְכָּם לִפְנֵיהֶם וַה' בְּרֹאשָׁם, הַקְדֵּם אַתָּה שִׁלְטוֹנְךְ בַּתְּחִלָּה בָּעוֹלָם הַזֶּה - וַאֲנִי אֶתְנַהֲלָה לְאִטִּי, אֲנִי אַעֲלֶה עַצְמִי לְאוֹתוֹ עוֹלָם הַבָּא וּלְסוֹף הַיָּמִים, לְאוֹתָם יָמִים שֶׁהוֹלְכִים לְאַט."],[4,"","לְרֶגֶל הַמְּלָאכָה - אֵיזוֹ מְלָאכָה? זוֹ אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה שֶׁבָּהּ נַעֲשָׂה מַעֲשֵׂה הָעוֹלָם. אֲשֶׁר לְפָנַי - זוֹהִי מִלִּפְנֵי ה' בְּכָל מָקוֹם. וּלְרֶגֶל הַיְלָדִים - זֶהוּ סוֹד שֶׁל הַכְּרוּבִים לְהַרְאוֹת סוֹד הָאֱמוּנָה שֶׁהוּא נִדְבָּק בָּהֶם."],[5,"","עַד אֲשֶׁר אָבֹא אֶל אֲדנִי שֵׂעִירָה - אֲנִי אֶסְבֹּל גָּלוּת שֶׁלְּךְ עַד שֶׁיָּבֹא וְיַגִּיעַ זְמַנִּי לִשְׁלֹט עַל הַר עֵשָׂו, כְּמוֹ שֶׁנֶּאֱמַר (עובדיה א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו, וְאָז וְהָיְתָה לַה' הַמְּלוּכָה."],[6,"","וְיַעָקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת עַל כֵּן קָרָא שֵׁם הַמָּקוֹם סֻכּוֹת. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים קכז) שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה אִם ה' לֹא יִבְנֶה בַיִת וְגוֹ', אִם ה' לֹא יִשְׁמָר עִיר וְגוֹ'. בֹּא רְאֵה, בְּשָׁעָה שֶׁעָלָה בִּרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא עוֹלָם, הוֹצִיא מִתּוֹךְ נִיצוֹץ חָזָק קֶשֶׁר אֶחָד, וְהִתְלַהֵט מִתּוֹךְ הַחֹשֶׁךְ, וְנִשְׁאָר בַּעֲלִיָּה וְיָרַד לְמַטָּה. אוֹתָהּ חֲשֵׁכָה לָהֲטָה (והתלהטה) בְּמֵאָה שְׁבִילִים דְּרָכִים דַּקִּיקִים גְּדוֹלִים, וְנַעֲשָׂה בַּיִת שֶׁל הָעוֹלָם."],[7,"","בַּיִת זֶה הוּא בְּתוֹךְ אֶמְצַע הַכֹּל. כַּמָּה פְתָחִים וַחֲדָרִים לוֹ סָבִיב סָבִיב, מְקוֹמוֹת עֶלְיוֹנִים קְדוֹשִׁים, שָׁם מְקַנְּנוֹת צִפֳּרֵי הַשָּׁמַיִם כָּל אֶחָד וְאֶחָד לְמִינוֹ. בְּתוֹכוֹ יוֹצֵא אִילָן גָּדוֹל אֶחָד וְחָזָק, עֲנָפָיו וּפִרְיוֹ רַב, מָזוֹן לַכֹּל בּוֹ. אוֹתוֹ הָאִילָן עוֹלֶה לְעַנְנֵי הַשָּׁמַיִם, וְנִטְמָן בֵּין שְׁלֹשָׁה הָרִים. מִתַּחַת לִשְׁלֹשֶׁת הֶהָרִים הַלָּלוּ יוֹצֵא, עוֹלֶה לְמַעְלָה וְיוֹרֵד לְמַטָּה."],[8,"","הַבַּיִת הַזֶּה מֻשְׁקֶה מִמֶּנּוּ וְגוֹנֵז בְּתוֹכוֹ כַּמָּה גְנָזִים עֶלְיוֹנִים שֶׁלֹּא נוֹדְעוּ, בָּזֶה נִבְנֶה בַּיִת זֶה וְנִתְקָן. אוֹתוֹ הָאִילָן מִתְגַּלֶּה בַּיּוֹם וּמִתְכַּסֶּה בַּלַּיְלָה. וְהַבַּיִת זֶה שׁוֹלֵט בַּלַּיְלָה וּמִתְכַּסֶּה בַּיּוֹם."],[9,"","בְּשָׁעָה שֶׁנִּכְנָס הַחֹשֶׁךְ וְנִקְשָׁר בּוֹ שׁוֹלֵט, וְכָל הַפְּתָחִים סְתוּמִים מִכָּל הַצְּדָדִים. אָז כַּמָּה רוּחוֹת פּוֹרְחוֹת בָּאֲוִיר, תְּאֵבוֹת לָדַעַת וּלְהִכָּנֵס בּוֹ, וְנִכְנָסוֹת בֵּין אוֹתָן צִפֳּרִים, וְלוֹקְחוֹת עֵדוּת, וְשָׁטוֹת וְרוֹאוֹת מַה שֶּׁרוֹאוֹת."],[10,"","עַד שֶׁמִּתְעוֹרֵר אוֹתוֹ חֹשֶׁךְ שֶׁנִּקְשַׁר בּוֹ, וּמוֹצִיא שַׁלְהֶבֶת אַחַת, וּמַכֶּה בְּכָל הַפַּטִּישִׁים הַחֲזָקִים, וּפוֹתֵחַ פְּתָחִים וּבוֹקֵעַ סְלָעִים. עוֹלָה וְיוֹרֶדֶת אוֹתָהּ שַׁלְהֶבֶת וּמַכָּה בָּעוֹלָם וּמְעוֹרֶרֶת קוֹלוֹת לְמַעְלָה וּלְמַטָּה."]]],[["כְּדֵין חַד כָּרוֹזָא סָלִיק, וְאִתְקַטִּיר בַּאֲוִירָא, וְקָרֵי, הַהוּא אֲוִירָא נָפְקָא מִגּוֹ עַמּוּדָא דַּעֲנָנָא דְּמַדְבְּחָא פְּנִימָאָה, וְכַד נַפְקָא אִתְפַּשַּׁט בְּאַרְבַּע סִטְרֵי עָלְמָא. אֶלֶף אַלְפִין קָיְימִין מִסִּטְרָא דְאִיהוּ שְׂמָאלָא, וְרִבּוֹא רִבְוָון קָיְימִין מִסִּטְרָא דְאִיהוּ יָמִינָא, וְכָרוֹזָא קָאִים בְּקִיּוּמֵיהּ. קָרֵא בְחָיִל וְאַכְרִיז, כְּדֵין כַּמָּה אִינוּן דִּמְתַקְּנִי שִׁירָתָא וּפָלְחִין פּוּלְחָנָא, וּתְרֵין פִּתְחִין פְּתִיחוּ. חַד לִסְטַר דָּרוֹמָא, וְחַד לִסְטַר צָפוֹן.","סָלְקָא הַאי בֵיתָא וְאִתְיְהִיבַת וְאִתְקַטְּרַת בֵּין תְּרֵין סִטְרִין, וְשִׁירִין מְזַמְּרָן וְתוּשְׁבְּחָן סָלְקִין. כְּדֵין עָאל מַאן דְּעָאל בִּלְחִישָׁא, וּבֵיתָא מִתְלַהֲטָא בְּשִׁית נְהוֹרִין, נָהֲרִין זִיוָא לְכָל סְטַר, וְנַהֲרִין דְּבוּסְמָא נָפְקִין. וְאִתְשַׁקְיָין כָּל חֵיוַת בְּרָא, כְּמָה דְאַתְּ אָמֵר (תהילים ק״ד:י״א) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם וְגו'. וְזָמְרִין עַד דְּסָלְקָא צַפְרָא. וְכַד סָלְקָא צַפְרָא כְּדֵין כֹּכְבַיָא וּמַזָּלֵי שְׁמַיָא וְחֵילֵיהוֹן כֻּלְּהוֹן מְשַׁבְּחָן וְאָמְרֵי שִׁירָתָא, כְּמָה דְאַתְּ אָמֵר, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלהִים.","תָּא חֲזֵי (תהילים קכ״ז:א׳) אִם ה' לא יִבְנְה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ. אִם יְיָ לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. אִם יְיָ וְגו' דָּא מַלְכָּא עִלָּאָה, דְּאִיהוּ בּוֹנֶה לְהַאי בֵּיתָא תָּדִיר וְאַתְקִין לֵיהּ, אֵימָתַי, כַּד סָלְקִין רְעוּתִין פּוּלְחָנִין מִתַּתָּא כְּדְקָא יְאוּת.","אִם יְיָ לֹא יִשְׁמָר עִיר, אֵימָתַי, בְּשַׁעְתָּא דְּאִתְחַשְׁכָא לֵילְיָא, וְסִטְרִין מְזַיְינִין שָׁרָאן וְשָׁטָאן בְּעַלְמָא, וּפִתְחִין סְתִימִין, וְאִתְנְטִיר מִכָּל סִטְרִין דְּלָא יִקְרַב בֵּיהּ עָרֵל וּמְסָאֲבָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ב:א׳) לֹא יוֹסִיף יָבֹא בָךְ עוֹד עָרֵל וְטָמֵא, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לוֹן מֵעַלְמָא.","מַאן עָרֵל וּמַאן טָמֵא. אֶלָא כֹּלָּא חַד, עָרֵל וְטָמֵא. דָּא הוּא דְּאִתְפַּתָּא בֵּיהּ וְאָזִיל אֲבַתְרֵיהּ אָדָם וְאִנְתְּתֵיהּ, וְגָרִימוּ מוֹתָא לְכָל עַלְמָא. וְאִיהוּ דְּמַסְאִיב הַאי בֵּיתָא, עַד הַהוּא זִמְנָא דְּיַעֲבַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵעַלְמָא. בְגִין כָּךְ אִם יְיָ לֹא יִשְׁמָר עִיר, שָׁוְא וַדַּאי.","תָּא חֲזֵי, וְיַעֲקֹב נָסַע סֻכֹּתָה, אִתְנְטִיל לְקֳבְלָא חוּלָקֵיהּ דִּמְהֵימְנוּתָא. מַה כְּתִיב לְעֵילָא, וַיָּשָׁב בַּיּוֹם הַהוּא עֵשָׂו לְדַרְכּוֹ שֵׂעִירָה, וּכְתִיב וְיַעֲקֹב נָסַע סֻכֹּתָה. אֶלָּא כָּל חַד אִתְפְּרַשׁ לְסִטְרָא דִילֵיהּ, עֵשָׂו לְסִטְרָא דְשֵׂעִיר. מַאן שֵׂעִיר, דָּא הִיא אִשָּׁה זָרָה אֵל נִכָר. וְיַעֲקֹב נָסַע סֻכֹּתָה, דָּא מְהֵימְנוּתָא עִלָּאָה.","וַיִּבֶן לוֹ בָיִת, כְּמָה דְאַתְּ אָמֵר, (ישעיה ב) בֵּית יַעֲקֹב. אָמַר רִבִּי אֶלְעָזָר, דְּאַתְקִין תְּפִלַּת עַרְבִית כְּדְקָא יְאוּת. וּלְמִקְנִהוּ עָשָׂה סֻכֹּת, שְׁאָר סֻכֹּת לְנַטְרָא לוֹן וְדָא הוּא חוּלָקֵיהּ.","וּכְדֵין וַיָּבֹא יַעֲקֹב שָׁלֵם. שָׁלֵם מִכֹּלָּא וְאוּקְמוּהָ. וּכְתִיב, (תהילים ע״ו:ג׳) וַיְהִי בְשָׁלֵם סֻכּוֹ וְגו' וְאוּקְמוּהָ, וְכֹלָּא רָזָא חָדָא. כְּדֵין אִתְחַבֵּר עִמֵּיהּ מְהֵימְנוּתָא כַּד הֲוָה שְׁלִים כַּד אִתְעֲטַר בְּדוּכְתֵּיהּ דְּאִתְחֲזֵי לֵיהּ. וּכְדֵין הַאי סֻכָּה אִתְעַטְּרַת בַּהֲדֵיהּ, דְּהֲוָה שְׁלִים מֵאֲבָהָן, דְּהֲוָה שְׁלִים מִבְּנוֹי, וְדָא הוּא שָׁלֵם. שָׁלֵם לְעֵילָא שָׁלֵם לְתַתָּא, שָׁלֵם בִּשְׁמַיָא שָׁלֵם בְּאַרְעָא. שָׁלֵם לְעֵילָא דְּאִיהוּ כְּלָלָא דְּאֲבָהָן, תִּפְאֶרֶת יִשְׂרָאֵל. שָׁלֵם לְתַתָּא בִּבְנוֹי קַדִּישִׁין. שְׁלִים בִּשְׁמַיָא, שְׁלִים בְּאַרְעָא, וּכְדֵין וַיְהִי בְשָׁלֵם סֻכּוֹ וְאוּקְמוּהָ. מִיָּד מַה כְּתִיב וַתֵצֵא דִינָה בַת לֵאָה, וְאוּקְמוּהָ חַבְרַיָיא.","תָּא חֲזֵי, כַּמָּה דַרְגִין וְסִטְרִין מִתְפָּרְשָׁן לְעֵילָא וְכֻלְּהוּ מְשַׁנְיָין דָּא מִן דָּא. חֵיוָון מְשַׁנְיָין אִלֵּין מֵאִלֵּין, אִלֵּין מְקַטְרְגִין לְשַׁלְּטָאָה עַל אִלֵּין וּלְמִטְרַף טַרְפִין כָּל חַד וְחַד לְזִינֵיהּ.","מִסִּטְרָא דְרוּחָא מְסָאֲבָא כַּמָּה דַרְגִּין מִתְפָּרְשִׁין, וְכֻלְּהוּ כָּמַן לְקַטְרְגָא אִלֵּין לָקֳבֵיל אִלֵּין, דְּהָא כְּתִיב (דברים כ״ב:י׳) לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו, דְּכַד קָא מִתְחַבְּרָן מְקַטְרְגֵי עַלְמָא.","וְתָּא חֲזֵי, תִּיאוּבְתָּא דְדַרְגִין מְסָאֲבִין לָאו אִיהוּ אֶלָּא לְקַטְרְגָא בְּסִטְרִין קַדִּישִׁין. יַעֲקֹב דְּאִיהוּ קַדִּישָׁא, כֻּלְּהוּ כָּמַן לֵיהּ וְקִטְרְגוּ בַּהֲדֵיהּ. בְּקַדְמִיתָא נָשְׁכֵיהּ חִוְיָא, כְּמָה דְאַתְּ אָמֵר וַיִּגַּע בְּכַף יֻרִכוֹ, הַשְׁתָּא נָשְׁכֵיהּ חֲמוֹר."],[[0,"כדין חד כרוזא וכו':","אז עולה כרוז אחד ומתקשר באויר וקורא. האויר ההוא יוצא מתוך עמוד הענן של המזבח הפנימי. וכאשר יוצא הוא מתפשט בארבע רוחות העולם. אלף אלפים נמצאים בו מצד שהוא שמאל, ורבוא רבבות נמצאים בו מצד שהוא ימין. ואז הכרוז עומד על קיומו, וקורא בכח ומכריז. אז רבים הם המתקנים שירה ועובדים עבודה. ושני פתחים פתוחים בה, אחד לצד דרום להארת החסדים ואחד לצד צפון, להארת החכמה."],[0,"","פירוש. הארת החכמה מטרם שנשלמה נקראת \u0003כרוז.\u0004 כי אחר שנשלמה, דהיינו בהתלבשות החסדים שבזווג של יום, היא נקראת \u0003דבור.\u0004 שהוא על שם שהדבור מגלה הארת החכמה שבמוחין, אבל בלילה היא נקראת \u0003כרוז.\u0004 כי עודה אינה בשלמות להקרא \u0003דבור\u0004, כי \u0003דברי\u0004 חכמים בנחת נשמעים, \u0003וכרוז\u0004 נשמע בהרמת קול חזק, שמורה על הדינים המעורבים בו. אמנם בין כרוז ובין דבור, אינם נשמעים אלא בהתלבשותם בחסדים הנקראים \u0003קול.\u0004"],[0,"","וז\"ש \u0003כדין,\u0004 היינו בחצות לילה, \u0003חד כרוזא סליק\u0004 דהיינו הארת החכמה, \u0003ואתקטיר באוירא\u0004 שמתלבש בחסדים שנקראים אויר, ואז \u0003וקרי,\u0004 ואז אפשר לו לקרות ולהכריז, מה שאין כן מטרם שנתלבש בחסדים, אין לו קול, ואי אפשר לו להכריז."],[0,"","והנה יש ב' מיני חסדים א) הנמשכים מאו\"א עלאין, שהם ג\"ר ממש אע\"פ שמכוסים מחכמה, ונקראים \u0003אוירא דכיא.\u0004 ב) חסדים הנמשכים מישסו\"ת, שהם מחוסרי ג\"ר, כל עוד שהי' אינה יוצאת מאויר שלהם, וע\"כ הם מכונים \u0003אוירא סתם,\u0004 כלומר שאינם טהורים, כי מורגש בהם חסרון החכמה. ולפיכך זו\"ן, כל עוד שאין בהם הארת החכמה, נבחנים החסדים שממשיכים, שהם מבחינת ישסו\"ת, דהיינו שמחוסרי ג\"ר, אבל אחר שיש בזו\"ן הארת החכמה נבחנים החסדים שממשיכים, שהם מבחינת או\"א עלאין, דהיינו, שהם בחינת ג\"ר ואוירא דכיא."],[0,"","וז\"ש, \u0003ההוא אוירא,\u0004 האויר הזה, דהיינו אור החסדים שהתלבש בו הכרוז, \u0003נפקא מגו עמודא דעננא דמדבחא פנימאה.\u0004 אמא עלאה מכונה מזבח הפנימי, ואור החסדים מכונה עמוד הענן, ואומר, שחסדים אלו, שהכרוז, שה\"ס הארת חכמה, נתלבש בהם, נמשכים מאבא ואמא עלאין, המכונה המזבח הפנימי, כלומר, שהם בחינת \u0003אוירא דכיא.\u0004 והוא מטעם, שכבר יש כאן הארת החכמה בסוד הכרוז עצמו, שאז נמשכים החסדים בבחינת אוירא דכיא מאו\"א כנ\"ל. \u0003וכד נפקא אתפשט בארבע סטרי עלמא,\u0004 דהיינו שמתפשט בחו\"ב תו\"מ שבנוקבא, המכונות ארבע רוחות העולם."],[0,"","ועשר הספירות דישסו\"ת, שמשם יוצא הקו השמאלי בהארת החכמה, אחר שה \u0003י'\u0004 יוצאת \u0003מאויר\u0004 שלהם ונשאר \u0003אור,\u0004 נבחנות בסוד אלפים. ועשר הספירות דאו\"א עלאין, שמשם נמשכים החסדים, נבחנות לריבוא. וז\"ש \u0003אלף אלפין קיימין מסטרא דאיהו שמאלא,\u0004 כי מבחינה זו היא נמשכת מישסו\"ת שע\"ס שלה ה\"ס אלף. \u0003ורבוא רבוון קיימין מסטרא דאיהו ימינא\u0004 כי מבחינת החסדים שבימין נמשכת מאו\"א עלאין שע\"ס שלהם הם בסוד רבוא. ואז \u0003וכרוזא קאים בקיומיה,\u0004 מאחר שכלול מחסדים דאו\"א. \u0003קרא בחיל ואכריז,\u0004 כי אחר שנכלל הכרוז בחסדים, המכונה קול, כנ\"ל הוא יכול לקרות בכח ולהכריז."],[1,"סלקא האי ביתא וכו':","אחר שכבר נבנתה הנוקבא לצרכה עצמה מג' הקוין הנכללים בשמאל, כמו שנתבאר, היא עולה לזווג לז\"א לקבל בשביל אחרים, ואומר שבית זה, שהוא הנוקבא. עולה וניתן ונתקשר בין ב' צדדים, ימין ושמאל דז\"א, ושרים שירים, ותשבחות עולים מתחתונים, דהיינו שמעלים מ\"ן לזווג זו\"ן, אז נכנס מי שנכנס, דהיינו ז\"א, בלחש, דהיינו שהנוקבא נמצאת בחוסר קול שהוא חסדים, אע\"פ שקבלה כבר חסדים לצורך בנינה עצמה, נחשבת עוד לשמאל בלי ימין כדי להשפיע לאחרים. שז\"ס שהזווג הוא בלחש וכן בלילה בלי אור. כי אז ז\"א משפיע לה אור החסדים שה\"ס קול, והבית, שהוא הנוקבא, מתלהט בששה אורות החסדים, חג\"ת נה\"י, המאירים זיו לכל צד, שה\"ס חסדים הנכללים מחכמה, ונהרות בשם יוצאים ממנה שה\"ס הארת החכמה הנכללת מחסדים, ונשקים כל חיות השדה, כמש\"א, ישקו כל חיתו שדי וגו'. ומזמרים עד שעלה הבקר. וכשעלה אור הבקר, אז הככבים והמזלות שמים וצבאם, כולם משבחים ואומרים שירה, כמש\"א, ברן יחד ככבי בקר ויריעו \u0003כל\u0004 בני אלקים."],[1,"","פירוש. כי הארת הזווג מסוד הלילה, אע\"פ שיש בו חסדים, מ\"מ השליטה היא להארת החכמה, וע\"כ מקבלים אז רק חיות השדה, שהם נמשכים מאחורים של הנוקבא, וע\"כ הם מזמרים, אבל הנמשכים מבחינת פנים של הנוקבא מקבלים ממנה רק בבקר. ואז כל המדרגות שבבי\"ע מזמרות, הן הנמשכות מפנים והן הנמשכות מאחורים. שזסו\"ה ויריעו \u0003כל\u0004 בני אלקים. שכולם מזמרים."],[2,"תא חזי אם ה' וכו':","בוא וראה, כתוב, אם ה' לא יבנה בית וגו'. \u0003אם ה',\u0004 זהו המלך העליון, שהוא ז\"א, שהוא בונה תמיד, דהיינו בסוד זווג דלא פסיק, את הבית הזה, שהוא הנוקבא, ומתקן אותו. ומתי משפיע לה מזווג דלא פסיק, ואומר, שהוא בעת שעולים כונות העבודה, מלמטה כראוי. פירוש. בעת שהתחתונים מעלים מ\"ן לזווג הזה, אז עולים זו\"ן לאו\"א, והם בזווג דלא פסיק כמוהם."],[3,"אם ה' לא ישמר עיר:","מתי הוא זה. הוא בשעה שנחשך הלילה ובחינות מזוינות של הס\"א, שורות ומשוטטות בעולם, והפתחים סתומים, ואז הוי\"ה, שה\"ס קו אמצעי מעלה מ\"ן מסוד המסך דחירק וממשיך קו אמצעי ונפתחים הפתחים (כנ\"ל באות קל\"ה) שעל ידי זה, נשמר מכל הצדדים שלא יקרב אל הקדוש, ערל וטמא, כמש\"א, לא יוסיף יבא בך עוד ערל וטמא, כי עתיד הקב\"ה להעבירם מן העולם."],[3,"","ביאור הדברים. כי נתבאר לעיל בסמוך (דף מ\"א ד\"ה עד דאתער) שב' פעולות הן בקו אמצעי, עד שמיחד ב' הקוין ימין ושמאל זה בזה. א) שממשיך קומת חסדים על המסך, ב) שממעט את ג\"ר דקו שמאל, שאין השמאל נכנע עד שיבא ויתחבר עם הימין, זולת על ידי ב' הפעולות הללו כמ\"ש באורך (לעיל פ' לך דף י\"ג ד\"ה ונתבאר, ע\"ש, ואין להכפיל דברים) ועליהן אומר הכתוב, \u0003אם ה' לא יבנה בית שוא עמלו בוניו בו,\u0004 זו היא פעולה א', כי \u0003הוי\"ה\u0004 ה\"ס ז\"א, ואם לא היה ממשיך ריבוי החסדים ע\"י הקו האמצעי לבנות הנוקבא המכונית \u0003בית,\u0004 לא היה נכנע הקו השמאל להתיחד עם הימין, ושוא עמלו בוניו בו. והכתוב, אם ה' לא ישמר עיר וגו' סובב על פעולה ב) שהיא התמעטות ג\"ר דקו שמאל, שבזה שההוא ממעט ג\"ר דקו שמאל מעבירים אחיזת הסטרא אחרא מן הקו השמאל שבנוקבא, (כמ\"ש לעיל פרשת וירא דף קי\"ב ד\"ה וזה, וע\"ש גם בדף קי\"ג ד\"ה וההוא מקטרגא) ונמצא \u0003שהעיר,\u0004 שה\"ס הנוקבא, נשמר מן הערל וטמא, עי\"ז, שז\"א מעלה את המסך דחירק, וממעט הג\"ר דקו שמאל, שאז אין להם מה לינק עוד מן השמאל שלה, ונעברים ונפרדים ממנה. וע\"ז כתוב, אם ה' לא ישמר עיר שוא שקד שומר."],[4,"מאן ערל וכו':","ושואל, מי הוא ערל ומי הוא טמא. ומשיב, אלא ערל וטמא הכל אחד. וזה הוא שנתפתו בו והלכו אחריו אדם ואשתו וגרמו מות לכל העולם, דהיינו הנחש הקדמוני. והוא המטמא אותו הבית, שהוא הנוקבא, עד הזמן ההוא שיעבירו הקב\"ה מן העולם, שהוא הנוקבא, ומשום זה, אם ה' לא ישמר עיר שוא בודאי שקד שומר. כמ\"ש לעיל."],[5,"ת\"ח ויעקב נסע סכתה:","נסע אל בינה, דהיינו שהעלה מ\"ן ממסך דחירק. לקבל חלקה של האמונה, שהיא הנוקבא. מה כתוב למעלה, וישב ביום ההוא עשו לדרכו שעירה. וכתוב ויעקב נסע סכתה, כי כל אחד נפרד אל הצד שלו, עשו לצד של \u0003השעיר,\u0004 מי הוא שעיר, זה הוא אשה זרה אל נכר, ויעקב נסע סכתה, זו היא האמונה העליונה, דהיינו בינה. כלומר שהעלה מ\"ן ממסך דחירק אל הבינה, כדי להמשיך משם קו אמצעי בשביל לבנות הנוקבא. על דרך שנתבאר לעיל."],[6,"ויבן לו בית:","הוא כמו שאתה אומר בית יעקב, שפירושו הנוקבא. אמר ר' אלעזר שתקן תפלת ערבית, שהיא הנוקבא, כראוי לה. דהיינו שהמשיך לה חסדים מאו\"א עלאין (כנ\"ל באות קל\"ח) \u0003ולמקנהו עשה סכת,\u0004 היינו סוכות אחרות, כדי לשמור אותם, וזה הוא חלקו."],[6,"","פירוש. כי אותן ב' הפעולות הנ\"ל מבוארות בכתוב הזה. כי פעולה א) שהיא ריבוי החסדים מבוארת בכתוב \u0003ויבן לו בית,\u0004 שתקונו ובנינו הם בהמשכת החסדים כנ\"ל. וה\"ס אם ה' לא יבנה בית וגו' כנ\"ל. ופעולה ב) שהיא מיעוט הג\"ר מקו שמאל לשמרו מערל וטמא. כנ\"ל, הוא בכתוב \u0003ולמקנהו עשה סכת,\u0004 כי סכה היא מלשין מסך, שהמשיך המסך דחירק למעט הג\"ר דקו שמאל, וה\"ס הכתוב אם ה' לא ישמר עיר כנ\"ל וז\"ש \u0003שאר סכת לנטרא לון,\u0004 לשמרם מערל וטמא כמ\"ש לעיל."],[7,"וכדין, ויבא יעקב שלם:","שהיה שלם מכל, הן מחכמה והן מחסדים. ובארוהו. וכתוב, ויהי בשלם סכו וגו' ובארוהו, והכל סוד אחד, דהיינו השגת השלמות על ידי קו אמצעי הן לז\"א הנקרא \u0003יעקב,\u0004 והן ל \u0003סכו\u0004 שהיא הנוקבא. כי אז כשהוא שלם נתחבר עמו האמונה שהיא הנוקבא, וכשהוא מתעטר במקום הראוי לו, דהיינו בקו אמצעי, אז גם סוכה זו, שהיא הנוקבא, מתעטרת עמו, ונאמר גם עליה, ויהי בשלם סכו, כי היה שלם מאבות, היה שלם מבניו, וזה הוא נחשב לשלם, שאז הוא שלם למעלה ושלם למטה, שלם בשמים ושלם בארץ. ומפרש דבריו, שלם למעלה שהוא בז\"א, הוא להיותו הכולל של האבות שהוא תפארת ישראל הכולל לאברהם ויצחק, שהם חסד וגבורה. שלם למטה, בנוקבא, היא בבניו הקדושים, שהם י\"ב השבטים שהם המרכבה של הנוקבא, ונמצא, שהוא שלם בשמים שהוא ז\"א, וע\"כ נאמר עליו ויבא יעקב שלם. ושלם בארץ שהיא הנוקבא, ואז נאמר עליה, ויהי בשלם סכו. ובארוהו."],[8,"מיד מה כתיב ותצא דינה וגו':","ובארוהו החברים. בוא וראה, הרבה מדרגות ובחינות מתפרדות למעלה, אלו לקדושה ואלו לס\"א בסו\"ה זה לעומת זה עשה אלקים וגו'. וכולן הן משונות אלו מאלו, מהן לחסד ומהן לדינים. חיות משונות אלו מאלו. אלו מצירים לשלוט על אלו, ולטרף טרף, כל אחד ואחד למינו."],[9,"מסטרא דרוח מסאבא וכו':","מצד רוח הטומאה מתפרדות הרבה מדרגות, וכולן אורבות לצרור על הקדושה, אלו לעומת אלו, שכתוב, לא תחרוש בשור ובחמור יחדיו, כי כשמתחברים הם מחריבים העולם."],[10,"ותא חזי תיאובתא וכו':","ובוא וראה, תאותם של מדרגות הטומאה אינה אלא לצרור את המדרגות הקדושות. יעקב שהיה קדוש, כנ\"ל שכתוב עליו ויבא יעקב שלם וגו', כולן ארבו עליו וצררו לו. בתחילה נשכו נחש, כמו שאתה אומר, ויגע בכף ירכו. שנאמר על שרו של עשו, שהוא רוכב על נחש, עתה נשכו חמור, דהיינו שכם בן חמור שהוא ימין דקליפה."]],[[0,"","וְאָז כָּרוֹז אֶחָד עוֹלֶה וְנִקְשָׁר בָּאֲוִיר וְקוֹרֵא. אוֹתוֹ אֲוִיר יוֹצֵא מִתּוֹךְ עַמּוּד עָנָן שֶׁל הַמִּזְבֵּחַ הַפְּנִימִי, וּכְשֶׁיּוֹצֵא מִתְפַּשֵּׁט לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. אֶלֶף אֲלָפִים עוֹמְדִים מִצַּד שֶׁהוּא שְׂמֹאל, וְרִבּוֹא רְבָבוֹת עוֹמְדִים מִצַּד שֶׁהוּא יָמִין, וְהַכָּרוֹז עוֹמֵד בְּקִיּוּמוֹ, קוֹרֵא בְחַיִל וּמַכְרִיז. אָז כַּמָּה אוֹתָם שֶׁמְּתַקְּנִים שִׁירָה וְעוֹבְדִים עֲבוֹדָה, וּשְׁנֵי פְתָחִים נִפְתָּחִים, אֶחָד לְצַד דָּרוֹם וְאֶחָד לְצַד צָפוֹן."],[1,"","עוֹלֶה הַבַּיִת הַזֶּה וְנִתָּן וּמִתְקַשֵּׁר בֵּין שְׁנֵי צְדָדִים, וְשִׁירִים מְזַמְּרִים וְתִשְׁבָּחוֹת עוֹלוֹת. אָז נִכְנָס מִי שֶׁנִּכְנָס בְּלַחַשׁ, וְהַבַּיִת מִתְלַהֵט בְּשִׁשָּׁה אוֹרוֹת מְאִירִים זִיו לְכָל צַד, וְנַהֲרוֹת בְּשָׂמִים יוֹצְאִים וּמַשְׁקִים כָּל חַיּוֹת הַשָּׂדֶה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם וְגוֹ', וּמְזַמְּרִים עַד עֲלוֹת הַבֹּקֶר. וּכְשֶׁעוֹלֶה הַבּקֶר, אָז כּוֹכָבִים וּמַזְּלוֹת הַשָּׁמַיִם וְחֵילוֹתֵיהֶם, כֻּלָּם מְשַׁבְּחִים וְאוֹמְרִים שִׁירָה, כְּמוֹ שֶׁנֶּאֱמַר (איוב לח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים."],[2,"","בֹּא רְאֵה, (תהלים קכז) אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. אִם ה' וְגוֹ' - זֶה הַמֶּלֶךְ הָעֶלְיוֹן שֶׁהוּא בּוֹנֶה אֶת הַבַּית הַזֶּה תָּמִיד וּמְתַקֵּן אוֹתוֹ. אֵימָתַי? כְּשֶׁעוֹלִים הָרְצוֹנוֹת וְהָעֲבוֹדוֹת מִלְּמַטָּה כָּרָאוּי."],[3,"","אִם ה' לֹא יִשְׁמָר עִיר, אֵימָתַי? בְּשָׁעָה שֶׁנֶּחְשָׁךְ הַלַּיְלָה וְהַצְּדָדִים הַמְזֻיָּנִים שׁוֹרִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְהַפְּתָחִים סְתוּמִים, וְנִשְׁמָר מִכָּל הַצְּדָדִים שֶׁלֹּא יִתְקָרֵב בּוֹ עָרֵל וְטָמֵא, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נב) לֹא יוֹסִיף לָבֹא בָךְ עוֹד עָרֵל וְטָמֵא, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירָם מִן הָעוֹלָם."],[4,"","מִי עָרֵל וּמִי טָמֵא? אֶלָּא הַכֹּל אֶחָד עָרֵל וְטָמֵא. זֶהוּ שֶׁהִתְפַּתָּה בּוֹ וְהָלַךְ אַחֲרָיו אָדָם וְאִשְׁתּוֹ וְגָרְמוּ מָוֶת לְכָל הָעוֹלָם, וְהוּא הַמְטַמֵּא אֶת הַבַּיִת הַזֶּה עַד אוֹתוֹ זְמַן שֶׁיַּעֲבִירוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הָעוֹלָם. מִשּׁוּם כָּךְ אִם ה' לֹא יִשְׁמָר עִיר, שָׁוְא וַדַּאי."],[5,"","בֹּא רְאֵה, וְיַעֲקֹב נָסַע סֻכֹּתָה, נָסַע כְּנֶגֶד חֶלְקוֹ שֶׁל הָאֱמוּנָה. מַה כָּתוּב לְמַעְלָה? וַיָּשָׁב בַּיּוֹם הַהוּא עֵשָׂו לְדַרְכּוֹ שֵׂעִירָה, וְכָתוּב וְיַעֲקֹב נָסַע סֻכֹּתָה. אֶלָּא כָּל אֶחָד נִפְרַד לַצַּד שֶׁלּוֹ - עֵשָׂו לַצַּד שֶׁל שֵׂעִיר, מַה זֶּה שֵׂעִיר? זוֹ אִשָּׁה זָרָה, אֵל נֵכָר. וְיַעֲקֹב נָסַע סֻכֹּתָה, זוֹ הָאֱמוּנָה הָעֶלְיוֹנָה."],[6,"","וַיִּבֶן לוֹ בָּיִת, כְּמוֹ שֶׁנֶּאֱמַר (שם) בֵּית יַעֲקֹב. אָמַר רַבִּי אֶלְעָזָר, שֶׁתִּקֵּן תְּפִלַּת עַרְבִית כָּרָאוּי. וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת, שְׁאָר סֻכּוֹת לִשְׁמֹר אוֹתָם, וְזֶהוּ חֶלְקוֹ."],[7,"","וְאָז וַיָּבא יַעֲקֹב שָׁלֵם - שָׁלֵם מֵהַכֹּל, וּבֵאֲרוּהוּ. וְכָתוּב (תהלים עו) וַיְהִי בְשָׁלֵם סֻכּוֹ וְגוֹ', וּבֵאֲרוּהוּ, וְהַכֹּל סוֹד אֶחָד. אָז הִתְחַבְּרָה עִמּוֹ הָאֱמוּנָה כְּשֶׁהָיָה שָׁלֵם, כְּשֶׁהִתְעַטֵּר בַּמָּקוֹם שֶׁרָאוּי לוֹ, וְאָז סֻכָּה זוֹ הִתְעַטְּרָה עִמּוֹ, שֶׁהָיָה שָׁלֵם מֵהָאָבוֹת, שֶׁהָיָה שָׁלֵם מִבָּנָיו, וְזֶהוּ שָׁלֵם, שָׁלֵם לְמַעְלָה שָׁלֵם לְמַטָּה, שָׁלֵם בַּשָּׁמַיִם שָׁלֵם בָּאָרֶץ. שָׁלֵם לְמַעְלָה - שֶׁהוּא כְּלַל הָאָבוֹת, תִּפְאֶרֶת יִשְׂרָאֵל. שָׁלֵם לְמַטָּה - בְּבָנָיו הַקְּדוֹשִׁים. שָׁלֵם בַּשָּׁמַיִם שָׁלֵם בָּאָרֶץ. וְאָז וַיְהִי בְשָׁלֵם סֻכּוֹ, וּבֵאֲרוּהוּ. מִיָּד מַה כָּתוּב? וַתֵּצֵא דִינָה בַּת לֵאָה, וּבֵאֲרוּהוּ הַחֲבֵרִים"],[8,"","בֹּא רְאֵה כַּמָּה דְרָגוֹת וּצְדָדִים נִפְרָדִים לְמַעְלָה, וְכֻלָּם מְשֻׁנִּים זֶה מִזֶּה, חַיּוֹת מְשֻׁנּוֹת אֵלּוּ מֵאֵלּוּ, אֵלֶּה מְקַטְרְגִים לִשְׁלֹט עַל אֵלֶּה וְלִטְרֹף טֶרֶף כָּל אֶחָד וְאֶחָד לְמִינוֹ."],[9,"","מִצַּד שֶׁל רוּחַ הַטֻּמְאָה כַּמָּה דְרָגוֹת נִפְרָדוֹת, וְכֻלָּם אוֹרְבִים לְקַטְרֵג אֵלֶּה כְּנֶגֶד אֵלֶּה, שֶׁהֲרֵי כָּתוּב (דברים כב) לֹא תַחֲר!שׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו, שֶׁכְּשֶׁמִּתְחַבְּרִים, מְקַטְרְגִים עוֹלָם."],[10,"","וּבֹא וּרְאֵה, תְּשׁוּקַת הַדְּרָגוֹת הַטְּמֵאוֹת אֵינָהּ אֶלָּא לְקַטְרֵג בַּצְּדָדִים הַקְּדוֹשִׁים. יַעֲקֹב, שֶׁהוּא קָדוֹשׁ, כֻּלָּם אָרְבוּ לוֹ וְקִטְרְגוּ עִמּוֹ. בַּתְּחִלָּה נְשָׁכוֹ נָחָשׁ, כְּמוֹ שֶׁנֶּאֱמַר וַיִּגַּע בְּכַף יְרֵכוֹ. עַכְשָׁו נְשָׁכוֹ חֲמוֹר."]]],[["תַּמָּן אִיהוּ קָאִים לְגַבֵּי חִוְיָא, הַשְׁתָּא שִׁמְעוֹן וְלֵוִי דְאָתוּ מִסִּטְרָא דְּדִינָא קַשְׁיָא קָיְימוּ לְגַבֵּיהּ דְּחֲמוֹר וְשַׁלִּיטוּ עֲלוֹי בְּכָל סִטְרִין וְאִתְכַּפְיָא קַמַּיְיהוּ. כְּמָה דְאַתְּ אָמֵר וְאֶת חֲמוֹר וְאֶת שְׁכֶם בְּנוֹ הָרְגוּ לְפִי חָרֶב. וְשִׁמְעוֹן דְּהֲוָה (שור) מַזָּלֵיהּ (איהו) שׁוֹר, אֲתָא עַל חֲמוֹר וְקִטְרֵג בֵּיהּ, בְּגִין דְּלָא יִתְחַבְּרוּן כְּחֲדָא, וְאִשְׁתַּכַּח אִיהוּ מְקַטְרְגָא דִילֵיהּ.","וְכֻלְּהוּ אָתֵי לְקַטְרְגָא לֵיהּ לְיַעֲקֹב וְאִשְׁתְּזִיב, וּלְבָתַר אִיהוּ שַׁלִּיט עֲלַיְיהוּ. לְבָתַר אֲתָא שׁוֹר וְאִשְׁתַּלִים בַּחֲמוֹרִים דְּכֻלְּהוּ מִסִּטְרָא דְּחֲמוֹר. יוֹסֵף דְּאִיהוּ שׁוֹר, וּמִצְרַיִם דְּאִינוּן חֲמוֹרִים דִּכְתִיב בְּהוּ (יחזקאל כ״ג:כ׳) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם.","וְעַל דָּא לְבָתַר בְּנֵי יַעֲקֹב נָפְלוּ בֵּין אִינוּן חֲמוֹרִים, בְּגִין דְּאִזְדַּוַּוג שׁוֹר בַּהֲדַיְיהוּ, וְנָשְׁכוּ לוֹן גַּרְמַיָיא וּבִשְׂרָא. עַד דְּאִתְעַר לֵוִי כְּמִלְקַדְּמִין וּבַדַּר לְאִינוּן חֲמוֹרִים (ס\"א דאזדווגו) לְכַפְיָא לוֹן וְתָבַר תּוּקְפֵהוֹן מֵעַלְמָא, וְאַפִּיק לְשׁוֹר מִתַּמָּן. הֲדָא הוּא דִכְתִיב, (שמות י״ג:י״ט) וַיִּקַּח משֶׁה אֶת עַצְמוֹת יוֹסֵף עִמּוֹ.","תָּא חֲזֵי, כַּד אֲתָא שִׁמְעוֹן בְּקַדְמִיתָא עַל הַהוּא חֲמוֹר, אִתְעַר עֲלֵיהוֹן דַּם דְּאִתְגַּזָּרוּ, וּלְבָתַר וַיַּהַרְגוּ כָּל זָכָר. כְּגַוְונָא דָא עֲבַד קוּדְשָׁא בְּרִיךְ הוּא עַל יְדָא דְּלֵוִי, דָּא משֶׁה. בְּאִינוּן חֲמוֹרִים בְּמִצְרַיִם. בְּקַדְמִיתָא דַּם, וּלְבָתַר (שמות י״ג:ט״ו) וַיַּהֲרֹג יְיָ כָּל בְּכוֹר בְּאֶרֶץ מִצְרַיִם וְגו'. הָכָא בְּהַאי חֲמוֹר כְּתִיב, וְאֶת כָּל חֵילָם וְאֶת כָּל טַפָּם וְאֶת כָּל בְּהֶמְתָּם וְגו'. הָתָם בְּאִינוּן חֲמוֹרִים כְּתִיב, (שמות י״ב:ל״ה) כְּלֵי כֶסֶף וּכְלֵי זָהָב וּשְׂמָלוֹת, וּכְתִיב, (שמות י״ב:ל״ח) וְגַם עֵרֶב רַב עָלָה אִתָּם וְצֹאן וּבָקָר וְגו'.","וְשִׁמְעוֹן וְלֵוִי, דָּא קָאִים לְגַבֵּי הַאי חֲמוֹר, וְדָא קָאִים לְגַבֵּי כָּל אִינוּן חֲמוֹרִים, כֻּלְּהוּ בָּעוּ לְאִשְׁתַּתְּפָא בַּהֲדֵיהּ דְּיַעֲקֹב קַדִּישָׁא וְאִתְתַּקְּנוּ לְנַשְׁכָא לֵיהּ, וְאִיהוּ בִּבְנוֹי קָאִים לְגַבַּיְיהוּ וְכַיִּיף לוֹן תְּחוֹתֵיהּ.","הַשְׁתָּא דְעֵשָׂו נָשִׁיךְ לֵיהּ וְלִבְנוֹי, מַאן יָקוּם לְגַבֵּיהּ, יַעֲקֹב וְיוֹסֵף. דָּא מִסִּטְרָא דָא וְדָא מִסִּטְרָא דָא. דִּכְתִיב, (עובדיה א׳:י״ח) וְהָיָה בֵּית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לְקַשׁ וְגו':","וַיִּסָּעוּ וַיְהִי חִתַּת אֱלהִים עַל הֶעָרִים אֲשֶׁר סְבִיבוֹתֵיהֶם וְלֹא רָדְפוּ אַחֲרֵי בְּנֵי יַעֲקֹב. אָמַר רִבִּי יוֹסֵי כֻּלְּהוּ הֲווּ מִתְכַּנְּשֵׁי, וְכַד הֲווּ חַגְרֵי זַיְינֵי קְרָבָא הֲווּ מְרַתְּתֵי וְשַׁבְקִין לוֹן, וּבְגִין כָּךְ וְלא רָדְפוּ אַחֲרִי בְּנֵי יַעֲקֹב:","הָסִירוּ אֶת אֱלהֵי הַנֵּכָר וְגו'. הָסִירוּ אֶת אֱלהֵי הַנֵּכָר, אִלֵּין אִינוּן דְּנָטְלוּ מִשְּׁכֶם מָאנֵי כַּסְפָּא וְדַהֲבָא דְּהֲוָה חָקִיק עֲלַיְיהוּ טַעֲוָא דִלְהוֹן. רִבִּי יְהוּדָה אָמַר, טַעֲוָון הֲווּ מִכַּסְפָּא וְדַהֲבָא. וְיַעֲקֹב אַטְמִין לוֹן תַּמָּן, בְּגִין דְּלָא יִתְהַנּוּן מִסִּטְרָא דְּעֲבוֹדָה זָרָה, דְּאָסִיר לֵיהּ לְבַר נָשׁ לְאִתְהַנֵּי מִנֵּיהּ לְעָלְמִין.","רִבִּי יְהוּדָה וְרִבִּי חִזְקִיָּה הֲווּ אָזְלֵי בְּאָרְחָא, אָמַר רִבִּי חִזְקִיָּה לְרִבִּי יְהוּדָה, מַאי דִכְתִיב, (שמואל ב י״ב:ל׳) וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם מֵעַל רֹאשׁוֹ וּמִשְׁקָלָהּ כִּכַּר זָהָב וְאֶבֶן יְקָרָה וַתְּהִי עַל רֹאשׁ דָּוִד. וְתָנִינָן, שִׁקּוּץ בְּנֵי עַמּוֹן מִלְכֹּם שְׁמֵיהּ. וְדָא הוּא עֲטֶרֶת מַלְכָּם. מַאי טַעֲמָא וַתְּהִי עַל רֹאשׁ דָּוִד. וּמַאי טַעְמָא כְּתִיב שִׁקּוּץ. דְּהָא בִּשְׁאָר טַעֲוָון עַמְּמַיָא עוֹבְדֵי עֲבוֹדָה זָרָה כְּתִיב אֱלֹהֵי הָעַמִּים, אֱלֹהִים אֲחֵרִים, אֵל נֵכָר, אֵל אַחֵר, וּבְהַאי אָמַר שִׁקּוּץ חַד.","אָמַר לֵיהּ, וּבְכָל טַעֲוָון עַמְּמַיָיא עוֹבְדֵי עֲבוֹדָה זָרָה הָכִי קָרָא לוֹן קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִיב, (דברים כג) וַתִּרְאוּ אֶת שִׁקּוּצֵיהֶם וְאֶת גִּלּוּלֵיהֶם. וּמַה דְּאָמַר וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם, דְּאִיהוּ מִלְכּוֹם, הָכִי הוּא וַדַּאי. אֶלָּא אִיתַּי הַגִּתִּי עַד דְּלָא אִתְגְיַּיר, כְּדֵין אִיהוּ תָּבַר לָהּ לְהַהוּא עֲטֶרֶת דְּאִיהוּ מִלְכּוֹם, הַהוּא דִיוּקְנָא דְּחֲקִיק עֲלָהּ וּפָגִים לָהּ. כְּדֵין אִיהוּ עֲבַד לָהּ הֵיתֵּר לְאִתְהַנֵּי מִנָּהּ וְהֲוַת עַל רֵישֵׁיהּ. וְתָּא חֲזֵי, שִׁקּוּץ בְּנֵי עַמּוֹן, חַד חִוְיָא בְּסוּרְטָא הֲוָה חָקִיק עַל הַהוּא כִּתְרָא, וּבְגִין כָּךְ אִקְרֵי שִׁקּוּץ זוּהֲמָא.","רִבִּי יִצְחָק אָמַר, הָסִירוּ אֶת אֱלהֵי הַנֵּכָר, אִלֵּין שְׁאָר נָשִׁין דְּהֲווּ מַיְיתֵי בְּגַוַּיְיהוּ כָּל נְבַזְבְּזָן דִּלְהוֹן. וְעַל דָּא כְּתִיב וַיִּתְּנוּ אֶל יַעֲקֹב אֶת כָּל אֱלֹהֵי הַנִּכָר. אִלֵּין נָשִׁין, כָּל נְבַזְבְּזָן וְכָל טַעֲוָון דְּדַהֲבָא וְכַסְפָּא. וַיִּטְמוֹן אוֹתָם יַעֲקֹב, בְּגִין דְּלָא יִתְהַנּוּן מִסִּטְרָא דְּעֲבוֹדָה זָרָה כְּלָל."],[[0,"תמן איהו קאים וכו':","שם כשהנחש נשכו, עמד הוא עצמו לנגד הנחש, עתה כשנשכו החמור, שמעון ולוי שבאים מצד הדין הקשה, עמדו לנגד החמור, ושלטו עליו מכל הצדדים ונכנע לפניהם. כמש\"א, ואת חמור ואת שכם בנו הרגו לפי חרב. ושמעון שמזלו היה שור, דהיינו גבורה ושמאל דקדושה, בא על חמור, שהוא ימין דקליפה וצרר אותו, כדי שלא יתחברו שור וחמור דקליפה יחד, ונמצא ששמעון הוא הכנגד שלו ולא יעקב."],[1,"וכלהו אתי לקטרגא וכו':","וכולם באו לצרור את יעקב, וניצל מהם, ואחר כך שלט הוא עליהם. ואחרי זה בא שור, שהוא יוסף, ונשלם בחמורים, שהם המצרים שמלך עליהם, שהיו כולם מצד קליפת החמור. ומפרש יוסף הוא שור, ומצרים הם חמורים, שכתוב עליהם, אשר בשר חמורים בשרם."],[2,"ועל דא לבתר וכו':","ועל כן, אחר כך נפלו בני יעקב בין אלו החמורים, דהיינו המצרים משום שנתחבר שור עמהם, שהוא יוסף, והיו בהם שור וחמור יחדיו, ונשכו לישראל עצם ובשר, כטבע החמור שנושך ושובר עצם, עד שנתעורר לוי כמקודם לכן, ופזר את החמורים האלו, דהיינו שהפריד בין שור וחמור, כדי להכניעם, ושבר כחם מן העולם והוציא השור משם, זהו שכתוב, ויקח משה את עצמות יוסף עמו, משה הוא לוי, ויוסף הוא השור שנתחבר עמהם."],[3,"ת\"ח כד אתא וכו':","בוא וראה, מקודם לכן, כשבא שמעון על החמור להלחם עמו, העיר עליהם \u0003דם,\u0004 שנמולו, ואחר כך ויהרגו כל זכר. כעין זה עשה הקב\"ה על ידי לוי, זה משה בחמורים האלו שהם המצרים, מתחילה הביא עליהם מכת \u0003דם,\u0004 ואחר כך, ויהרג ה' כל בכור בארץ מצרים וגו'. כאן בחמור הזה אבי שכם. כתוב ואת כל חילם ואת כל טפם וגו' ואת כל בהמתם, שנאמר את צאנם ואת בקרם ואת חמוריהם ואת אשר בעיר ואת אשר בשדה לקחו, ושם באלו החמורים, שהם המצרים, כתוב, כלי כסף וכלי זהב ושמלות, שהם כנגד, ואת כל חילם שבכאן. וכתוב, וגם ערב רב עלה אתם, שהם כנגד, ואת כל טפם, שבכאן, וצאן ובקר וגו', שהם כנגד, את צאנם ואת בקרם וגו', שבכאן."],[4,"ושמעון ולוי וכו':","ושמעון ולוי, זה, שמעון, קם כנגד חמור זה אבי שכם שלא היה מחובר עם שור, וזה לוי, קם כנגד כל החמורים כולם. דהיינו אפילו כנגד החמורים המחוברים בשור, כמו המצרים כנ\"ל."],[4,"","פירוש. כי שמעון הוא גבורה ובחינת שור, וע\"כ היה הוא, הכנגד של חמור דקליפה, שהוא ימין, והיה יכול להכניעו. אבל לקליפת החמור שבמצרים לא היה יכול להכניעם, משום שהם היו מחוברים בשור, שקבלו כח מיוסף שהיה מולך עליהם. וע\"כ רק לוי, דהיינו משה הבא משבט לוי, שהוא בחינת ת\"ת (כנ\"ל פ' ויצא דף ס\"ט ד\"ה מאי) הכלול ימין ושמאל ביחד, היה כחו יפה להכניע אותם החמורים שבמצרים, ולא שמעון, שהיה בו שמאל בלבד."],[4,"כלהו בעו לאשתתפא וכו':","כולם רצו להזדקק אל יעקב ותקנו עצמם לנשוך אותו, והוא עמד כנגדם בבניו, והכניעם תחתיו."],[5,"השתא דעשו וכו':","שואל,עתה, בגלות האחרונה, שעשו נושך אותו ואת בניו, מי יקום כנגדו. ואומר, יעקב ויוסף יעמדו כנגדו, זה מצד זה, וזה מצד זה, דהיינו יעקב מצד ימין ויוסף מצד שמאל. שכתוב והיה בית יעקב אש, ובית יוסף להבה, ובית עשו לקש וגו'."],[6,"ויסעו ויהי חתת אלקים וגו':","אמר ר' יוסי, כולם היו מתאספים להלחם, וכאשר חגרו כלי הקרב, היו מרתתים ועזבו אותם. ועל כן, ולא רדפו אחר בני יעקב."],[7,"הסירו את אלהי הנכר:","אלו הם מה שלקחו משכם, כלי כסף וזהב שהיה חקוק עליהם אלהי הנכר שלהם, ר' יהודה אומר, אלהים אחרים היו עושים מכסף וזהב, ולא כלים שחקוקה עליהם צורת גלולים. ויעקב הטמין אותם שם, כדי שלא יהנו מצד עבודה זרה. שאסור לו לאדם להנות ממנו לעולם."],[8,"רבי יהודה ורבי חזקיה וכו':","ר\"י ור\"ח היו הולכים בדרך, אר\"ח לר\"י, מהו שכתוב ויקח את עטרת \u0003מלכם\u0004 מעל ראשו וגו', ולמדנו שהשקוץ של בני עמון שמו \u0003מלכם\u0004 וזה הוא שכתוב עטרת \u0003מלכם,\u0004 ושואל לפי\"ז, מה הטעם ותהי על ראש דוד. ומה הטעם שכתוב בו \u0003שקוץ\u0004, שהרי בשאר אלהי העמים עובדי ע\"ז, כתוב בהם, אלהי העמים, אלהים אחרים, אל נכר, אל אחר, ובזה, בע\"ז מלכם, אומר \u0003שקוץ\u0004 בלבד."],[9,"א\"ל ובכל וכו':","והשיב לו, כל אלהי העמים עובדי עבודה זרה, קורא אותם הקב\"ה כן. שכתוב, ותראו את שקוציהם ואת גלוליהם. ולאו דוקא מלכום, ומה שאמר הכתוב, ויקח את עטרת מלכם שהוא הע\"ז מלכם, ששאל איך נתעטר בה דוד, כן הוא ודאי, שהיתה ע\"ז, אלא איתי הגתי, בעוד שהיה עכו\"ם, מטרם שנתגייר, שבר מן אותה העטרת, שהיא הע\"ז מלכם, את הצורה שהיתה חקוקה עליהם, ובטל אותה, ובזה עשה אותה התר שיהיה מותר להנות ממנה, וע\"כ שם אותה דוד על ראשו."],[9,"","פירוש. שיש כח לעובד ע\"ז לפסול את הע\"ז שלו, ואז מותרת בהנאה לישראל. אמנם לאחר שנתגייר אם פוגם ופוסל הע\"ז שעבד מכבר, אינו מתיר אותה בהנאה, כי אז דינו כישראל, ולפיכך אומר הזהר, שאיתי הגתי ביטל אותה מטרם שנתגייר, ויצאה מכלל ע\"ז, וע\"כ מותר היה לדוד לשים אותה על ראשו."],[9,"ותא חזי וכו':","ובוא וראה, שקוץ בני עמון היה נחש אחד חקוק בחקיקה עמוקה על אותה העטרת, ומשום זה נקרא בשם \u0003שקוץ,\u0004 שפירושו זוהמא. וזהו ישוב ב' על הקושיא שהקשה לו ר\"ח, למה דוקא ע\"ז זו נקראת שקוץ."],[10,"רבי יצחק אמר וכו':","רי\"א, הסירו את אלהי הנכר, אלו הן נשים אחרות, שלקחו בשבי, שהיו מביאים עמהם כל עדייהם, ועל זה כתוב, ויתנו אל יעקב את כל אלהי הנכר, שהם הנשים, וכל עדייהם, וכל אלהי זהב וכסף. ויטמון אותם יעקב, היינו את הכסף והזהב, כדי שלא יהנו מצד ע\"ז כלום."]],[[0,"","שָׁם הוּא עוֹמֵד אֵצֶל הַנָּחָשׁ. עַכְשָׁו שִׁמְעוֹן וְלֵוִי, שֶׁבָּאוּ מִצַּד הַדִּין הַקָּשֶׁה, עָמְדוּ כְּלַפֵּי הַחֲמוֹר וְשָׁלְטוּ עָלָיו בְּכָל הַצְּדָדִים וְנִכְפָּה לִפְנֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר וְאֶת חֲמוֹר וְאֶת שְׁכֶם בְּנוֹ הָרְגוּ לְפִי חָרֶב. וְשִׁמְעוֹן שֶׁהָיָה (שור), מַזָּלוֹ (הוא) שׁוֹר, בָּא עַל חֲמוֹר וְקִטְרֵג בּוֹ כְּדֵי שֶׁלֹּא יִתְחַבְּרוּ כְאֶחָד, וְנִמְצָא שֶׁהוּא מְקַטְרֵג שֶׁלּוֹ."],[1,"","וְכֻלָּם בָּאִים לְקַטְרֵג לְיַעֲקֹב, וְהוּא נִצָּל, וְאַחַר כָּךְ הוּא שׁוֹלֵט עֲלֵיהֶם. אַחַר כָּךְ בָּא שׁוֹר וְנִשְׁלָם בַּחֲמוֹרִים שֶׁכֻּלָּם מִצַּד הַחֲמוֹר - יוֹסֵף שֶׁהוּא שׁוֹר, וּמִצְרַיִם שֶׁהֵם חֲמוֹרִים, שֶׁכָּתוּב בָּהֶם (יחזקאל כג) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם."],[2,"","וְעַל זֶה אַחַר כָּךְ בְּנֵי יַעֲקֹב נָפְלוּ בֵּין אוֹתָם חֲמוֹרִים, מִשּׁוּם שֶׁהִזְדַּוֵּג שׁוֹר עִמָּם וְנָשְׁכוּ אוֹתָם עֲצָמוֹת וּבָשָׂר, עַד שֶׁהִתְעוֹרֵר לֵוִי כְּמוֹ מִקֹּדֶם וּפִזֵּר אוֹתָם הַחֲמוֹרִים (שהזדוגו) לִכְפּוֹת אוֹתָם, וְשָׁבַר כֹּחָם מֵהָעוֹלָם, וְהוֹצִיא אֶת הַשּׁוֹר מִשָּׁם. זֶהוּ שֶׁכָּתוּב (שמות יג) וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף עִמּוֹ."],[3,"","בֹּא רְאֵה, כְּשֶׁבָּא שִׁמְעוֹן בַּהַתְחָלָה עַל אוֹתוֹ חֲמוֹר, הִתְעוֹרֵר עֲלֵיהֶם דָּם שֶׁנִּמּוֹלוּ, וְאַחַר כָּךְ וַיַּהַרְגוּ כָּל זָכָר. כְּמוֹ זֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי לֵוִי, זֶה מֹשֶׁה, בְּאוֹתָם חֲמוֹרִים בְּמִצְרַיִם. בַּתְּחִלָּה דָּם, אַחַר כָּךְ (שם) וַיַּהֲרֹג ה' כָּל בְּכוֹר בְּאֶרֶץ מִצְרַיִם וְגוֹ'. כָּאן בַּחֲמוֹר הַזֶּה כָּתוּב, וְאֶת כָּל חֵילָם וְאֶת כָּל טַפָּם וְאֶת כָּל בְּהֶמְתָּם וְגוֹ'. שָׁם בְּאוֹתָם חֲמוֹרִים כָּתוּב, (שם) כְּלֵי כֶסֶף וּכְלֵי זָהָב וּשְׂמָלֹת, וְכָתוּב (שם) וְגַם עֵרֶב רַב עָלָה אִתָּם וְצֹאן וּבָקָר וְגוֹ'."],[4,"","וְשִׁמְעוֹן וְלֵוִי - זֶה עוֹמֵד אֵצֶל הַחֲמוֹר הַזֶּה, וְזֶה עוֹמֵד אֵצֶל כָּל אוֹתָם חֲמוֹרִים. כֻּלָּם רָצוּ לְהִשְׁתַּתֵּף עִם יַעֲקֹב הַקָּדוֹשׁ וְנִתְקְנוּ לִנְשֹׁךְ אוֹתוֹ, וְהוּא בְּבָנָיו עוֹמֵד לְגַבֵּיהֶם וְכוֹפֶה אוֹתָם תַּחְתָּיו."],[5,"","עַכְשָׁו שֶׁעֵשָׂו נָשַׁךְ אוֹתוֹ וְאֶת בָּנָיו, מִי יָקוּם מוּלוֹ? יַעֲקֹב וְיוֹסֵף, זֶה מִצַּד זֶה וְזֶה מִצַּד זֶה, שֶׁכָּתוּב (עובדיה א) וְהָיָה בֵּית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לְקַשׁ וְגוֹ'."],[6,"","וַיִּסָּעוּ וַיְהִי חִתַּת אֱלֹהִים עַל הֶעָרִים אֲשֶׁר סְבִיבוֹתֵיהֶם וְלֹא רָדְפוּ אַחֲרֵי בְּנֵי יַעֲקֹב. אָמַר רַבִּי יוֹסֵי, כֻּלָּם הָיוּ מִתְכַּנְּסִים, וּכְשֶׁהָיוּ חוֹגְרִים כְּלֵי זַיִן לַקְּרָב, הָיוּ מְרַתְּתִים וְעוֹזְבִים אוֹתָם, וְלָכֵן לֹא רָדְפוּ אַחֲרֵי בְּנֵי יַעֲקֹב."],[7,"","הָסִירוּ אֶת אֱלֹהֵי הַנֵּכָר וְגוֹ'. הָסִירוּ אֶת אֱלֹהֵי הַנֵּכָר - אֵלֶּה הֵם שֶׁנָּטְלוּ מִשְּׁכֶם כְּלֵי כֶסֶף וְזָהָב שֶׁהָיָה חָקוּק עֲלֵיהֶם עֲבוֹדָה זָרָה שֶׁלָּהֶם. רַבִּי יְהוּדָה אָמַר, עֲבוֹדָה זָרָה הָיוּ מִכֶּסֶף וְזָהָב, וְיַעֲקֹב הִטְמִין אוֹתָם שָׁם כְּדֵי שֶׁלֹּא יֵהָנוּ מִצַּד שֶׁל עֲבוֹדָה זָרָה, שֶׁאָסוּר לְאָדָם לֵהָנוֹת מִמֶּנָּה לְעוֹלָמִים."],[8,"","רַבִּי יְהוּדָה וְרַבִּי חִזְקִיָּה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי חִזְקִיָּה לְרַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (שמואל ב יב) וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם מֵעַל רֹאשׁוֹ וּמִשְׁקָלָהּ כִּכַּר זָהָב וְאֶבֶן יְקָרָה וַתְּהִי עַל רֹאשׁ דָּוִד. וְשָׁנִינוּ, שִׁקּוּץ בְּנֵי עַמּוֹן מִלְכֹּם שְׁמוֹ, וְזֶהוּ עֲטֶרֶת מַלְכָּם. מָה הַטַּעַם וַתְּהִי עַל רֹאשׁ דָּוִד, וּמָה הַטַּעַם כָּתוּב שִׁקּוּץ, שֶׁהֲרֵי בִּשְׁאָר אֱלֹהֵי הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה כָּתוּב אֱלֹהֵי הָעַמִּים, אֱלֹהִים אֲחֵרִים, אֵל נֵכָר, אֵל אַחֵר, וּבָזֶה אָמַר שִׁקּוּץ אֶחָד."],[9,"","אָמַר לוֹ, וּבְכָל אֱלֹהֵי הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה כָּךְ קָרָא לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (דברים כג) וַתִּרְאוּ אֶת שִׁקּוּצֵיהֶם וְאֶת גִּלּוּלֵיהֶם. וּמַה שֶּׁאָמַר וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם, שֶׁהוּא מִלְכּוֹם - כָּךְ הוּא וַדַּאי. אֶלָּא אִתַּי הַגִּתִּי, עַד שֶׁלֹּא הִתְגַּיֵּר, אָז הוּא שָׁבַר אֶת אוֹתָהּ עֲטֶרֶת שֶׁל אוֹתוֹ מִלְכּוֹם, אוֹתָהּ דְּמוּת שֶׁחֲקוּקָה עָלֶיהָ וּפָגַם אוֹתָהּ, אָז הוּא עָשָׂה אוֹתָהּ הֶתֵּר לֵהָנוֹת מִמֶּנָּה, וְהָיְתָה עַל רֹאשׁוֹ. וּבֹא וּרְאֵה, שִׁקּוּץ בְּנֵי עַמּוֹן, נָחָשׁ אֶחָד בַּחֲקִיקָה עֲמֻקָּה הָיָה חָקוּק עַל אוֹתוֹ כֶּתֶר, וְלָכֵן נִקְרָא שִׁקּוּץ, זֻהֲמָא."],[10,"","רַבִּי יִצְחָק אָמַר, הָסִירוּ אֶת אֱלֹהֵי הַנֵּכָר - אֵלּוּ שְׁאָר נָשִׁים שֶׁהָיוּ מְבִיאוֹת בְּתוֹכָן כָּל עֲדָיֵיהֶן, וְעַל זֶה כָּתוּב וַיִתְּנוּ אֶל יַעֲקֹב אֶת כָּל אֱלֹהֵי הַנֵּכָר, אֵלּוּ נָשִׁים וְכָל עֲדָיִים וְכָל עֲבוֹדָה זָרָה שֶׁל זָהָב וָכֶסֶף. וַיִּטְמֹן אוֹתָם יַעֲקֹב, כְּדֵי שֶׁלֹּא יֵהָנוּ מִצַּד שֶׁל עֲבוֹדָה זָרָה כְּלָל."]]],[["תָּא חֲזֵי, דְּיַעֲקֹב גְּבַר שְׁלִים בְּכֹלָּא הֲוָה, וְהֲוָה מִתְדַּבַּק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. מַה כְּתִיב, וְנָקוּמָה וְנַעֲלֲה בֵּית אֵל וְאֶעֱשֶׂה שָׁם מִזְבֵּחַ לָאֵל הָעוֹנֶה אוֹתִי בְּיוֹם צָרָתִי וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי, מִיָּד וַיִּתְּנוּ אֶל יַעֲקֹב. מִכָּאן דְּבָעֵי בַּר נָשׁ לְשַׁבָּחָא לְקוּדְשָׁא בְּרִיךְ הוּא וּלְאוֹדָאָה לֵיהּ עַל נִסִּין וְעַל טָבָאן דְּעֲבַד עִמֵּיהּ, הֲדָא הוּא דִכְתִיב וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי.","תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב וְנָקוּמָה וְנַעֲלֶה בֵּית אֵל וְגו', אַכְלִיל בְּנוֹי בַּהֲדֵיהּ. וּלְבָתַר כְּתִיב וְאֶעֱשֶׂה שָׁם מִזְבֵּחַ וְלָא כְּתִיב וְנַעֲשֶׂה. דְּאַפִּיק לוֹן מִכְּלָלָא דָא, מַאי טַעְמָא, בְּגִין דְּעֲלֵיהּ הֲוָה מִלָּה. יַעֲקֹב אַתְקִין תְּפִלַּת עַרְבִית, וַדַּאי. וְאִיהוּ עֲבַד מַדְבְּחָא וְעֲלֵיהּ הֲוָה מִלָּה, וּבְגִין דְּאִיהוּ עָבַר כָּל אִינוּן עָקְתִין מִן יוֹמָא דְעָרַק קַמֵּיהּ דְּאֲחוּהָ. דִּכְתִיב וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי, וְאִינוּן אָתוּ לְבָתַר לְעַלְמָא. וְעַל דָּא לָא אָעִיל לוֹן בַּהֲדֵיהּ.","רִבִּי אֶלְעָזָר אָמַר, מִכָּאן מַאן דְּיִתְעֲבִיד לֵיהּ נִסָּא, אִיהוּ בָּעֵי לְאוֹדָאָה. מַאן דְּאָכִיל נַהֲמָא בְּפָתוֹרָא, אִיהוּ בָּעֵי לְבָרְכָא, וְלָא אָחֳרָא דְּלָא אָכִיל מִידִי:","וַיִּבֶן שָׁם מִזְבֵּחַ וְגו', תָּא חֲזֵי, כְּתִיב וַיִּבֶן שָׁם מִזְבֵּחַ, וְלָא כְּתִיב (בהני מדבחן) דְּאַסִּיק עֲלֵיהּ נִסְכִין וְעֲלָוָון, אֶלָּא בְּגִין דְּאַתְקִין הַהוּא דַרְגָּא דְּאִתְחֲזֵי לְאִתְתַּקְּנָא. מִזְבֵּחַ לַיְיָ, לְאַתְקָנָא דַּרְגָּא תַּתָּאָה לְחַבְּרָא לֵיהּ בְּדַרְגָּא עִלָּאָה, וְעַל דָּא וַיִּבֶן שָׁם מִזְבֵּחַ דָּא דַרְגָּא תַּתָּאָה. לַיְיָ דָּא דַרְגָּא עִלָּאָה. וַיִּקְרָא לַמָּקוֹם אֵל בֵּית אֵל, שְׁמָא דָא כִּשְׁמָא עִלָּאָה. בְּגִין דְּכַד אִתְנַהֲרָא כְּדֵין כְּאִמָּה בִּתָּהּ וְכֹלָּא חַד.","כִּי שָׁם נִגְלוּ אֵלָיו הָאֱלהִים, בְּגִין דְּאִינוּן לָא אִשְׁתַּכָּחוּ אֶלָּא בִּשְׁכִינְתָּא, דְּהָא שִׁבְעִין הֲווּ דְּאִינוּן מִשְׁתַּכְּחֵי תָּדִיר בַּהֲדֵי שְׁכִינְתָּא, וְשִׁבְעִין קַתַּדְרָאֵי סַחֲרָנִיהּ דִּשְׁכִינְתָּא. וְעַל דָּא כִּי שָׁם נִגְלוּ אֵלָיו הָאֱלֹהִים בְּאַתְרָא דָא דְּאִתְגַּלְּיָא, דְּהָא כְּתִיב וְהִנֵּה יְיָ נִצָּב עָלָיו:","וַיַּעַל מֵעָלָיו אֱלֹהִים בַּמָּקוֹם אֲשֶׁר דִּבֶּר אִתּוֹ, רִבִּי שִׁמְעוֹן אָמַר, מִכָּאן דְּאִתְעֲבִיד רְתִיכָא קַדִּישָׁא בַּהֲדֵי אֲבָהָן. וְתָּא חֲזֵי, יַעֲקֹב אִיהוּ רְתִיכָא קַדִּישָׁא עִלָּאָה דְּקַיְימָא לְאַנְהָרָא לְסִיהֲרָא, וְאִיהוּ רְתִיכָא בִּלְחוֹדוֹי. הֲדָא הוּא דִכְתִיב וַיַּעַל מֵעָלָיו אֱלהִים.","פָּתַח וְאָמַר, (דברים ד׳:ז׳) כִּי מִי גּוֹי גָדוֹל אֲשֶׁר לוֹ אֱלֹהִים קְרוֹבִים אֵלָיו כַּיְיָ אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו. תָּא חֲזֵי, כַּמָּה אִינוּן חֲבִיבִין יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּלֵית לָךְ עַם וְלִישָׁן בְּכָל עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה דְּעַלְמָא דְּאִית לֵיהּ אֱלָהָא דְּיִשְׁמַע לוֹן, כְּמָה דְקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְקַבְּלָא צְלוֹתְהוֹן וּבָעוּתְהוֹן דְּיִשְׂרָאֵל בְּכָל שַׁעְתָּא דְאִצְטְרִיךְ לוֹן לְמִשְׁמַע צְלוֹתָא דְאִינוּן בָּעָאן, בְּגִין הַהוּא דַרְגָּא דִלְּהוֹן.","תָּא חֲזֵי, יַעֲקֹב, קָרֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, יִשְׂרָאֵל. דִּכְתִיב לא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ. וַיִּקְרָא אֶת שְׁמוֹ, מַאן וַיִּקְרָא, דָּא שְׁכִינְתָּא. כְּמָה דְאַתְּ אָמֵר וַיִּקְרָא אֶל משֶׁה. וַיֹּאמֶר לוֹ אֱלֹהִים.","לְעֵיל אוֹקִימְנָא יִשְׂרָאֵל דְּהָא אִשְׁתְּלִּים בְּכֹלָּא כְּדְקָא יְאוּת, וּכְדֵין אִסְתַּלַּק בְּדַרְגֵּיהּ וְאִשְׁתְּלִים בִּשְׁמָא דָא, וְעַל דָּא וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל וְהָא אִתְּמָר.","רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי בְּאָרְחָא, אָמַר רִבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר, וַדַּאי הָא דְּאֲמַרְתְּ דְּיַעֲקֹב שְׁלֵימָא דְּאֲבָהָן אִיהוּ, וְאִיהוּ אָחִיד לְכָל סִטְרִין, וְקָרָא שְׁמֵיהּ יִשְׂרָאֵל, וּכְתִיב לא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ. וּכְתִיב וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל. אַמַּאי אַהֲדַר קוּדְשָׁא בְּרִיךְ הוּא וְקָרָא לֵיהּ יַעֲקֹב בְּכַמָּה זִמְנִין, וְכֹלָּא קָרוּן לֵיהּ יַעֲקֹב כְּמִלְּקַדְּמִין. אִי הָכִי, מַהוּ וְלא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב.","אָמַר לֵיהּ, שַׁפִּיר קָא אֲמַרְתְּ. פָּתַח וְאָמַר, (ישעיהו מ״ב:י״ג) יְיָ כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה, הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, כַּגִּבּוֹר יֵצֵא, גִּבּוֹר מִבָּעֵי לֵיהּ. כְּאִישׁ מִלְחָמוֹת, אִישׁ מִלְחָמוֹת מִבָּעֵי לֵיהּ."],[[0,"תא חזי דיעקב וכו':","בוא וראה, שיעקב אדם שלם היה בכל, והיה מתדבק בהקב\"ה. מה כתוב, ונקומה ונעלה בית אל וגו'. מיד כתוב ויתנו אל יעקב וגו'. מכאן שאדם צריך לשבח את הקב\"ה ולהודות לו על הנסים ועל הטוב שעשה עמו. זהו שכתוב, ויהי עמדי בדרך אשר הלכתי."],[1,"ת\"ח בקדמיתא וכו':","בוא וראה, בתחילה כתוב, \u0003ונקומה ונעלה בית אל,\u0004 בלשון רבים, שהכליל בניו עמו ואחר כך כתוב, \u0003ואעשה שם מזבח,\u0004 בלשון יחיד, ולא כתוב ונעשה. שהוציא אותם, מכלל זה. מהו הטעם, הוא, משום שעל עצמו בלבד היה הדבר, יעקב ודאי התקין תפלת ערבית, שהיא תקון הנוקבא, והוא עשה את המזבח, שהוא תקון הנוקבא, ועליו היה הדבר, ולא על בניו. ומשום שהוא עבר כל אלו הצרות מיום שברח מפני אחיו, שכתוב, ויהי עמדי בדרך אשר הלכתי, אבל הם באו אחר כך לעולם, אחר שכבר נפטר מצרות אלו, לפיכך לא הכניסם עמו בתקון המזבח, אלא אמר ואעשה שם מזבח וגו'."],[2,"רבי אלעזר אמר וכו':","רא\"א, מכאן נשמע, שמי שנעשה לו הנס הוא צריך להודות, מי שאכל לחם על השלחן הוא צריך לברך, ולא אחר שלא אכל מאומה. כי על כן אמר יעקב ואעשה שם מזבח ולא אמר ונעשה, כנ\"ל."],[3,"ויבן שם מזבח וגו':","בוא וראה, כתוב, \u0003ויבן שם מזבח\u0004, ולא כתוב שהעלה עליו נסכים ועולות. אלא משום שפירושו הוא, שתקן את המדרגה ההיא הראויה להתתקן. \u0003מזבח לה',\u0004 היינו לתקן את המדרגה התחתונה שהיא הנוקבא לחבר אותה עם המדרגה העליונה שהיא ז\"א. ועל כן \u0003ויבן שם מזבח,\u0004 זה הוא המדרגה התחתונה, שהיא הנוקבא, \u0003להוי\"ה,\u0004 זה הוא המדרגה העליונה, שהיא ז\"א. \u0003ויקרא למקום אל בית אל,\u0004 השם הזה שנתן לנוקבא, הוא כשם של העליונה, שהיא בינה, משום שכאשר האירה הנוקבא מז\"א, נעשתה אז הבת, שהיא הנוקבא, כאמה, שהיא בינה, וע\"כ קרא אותה יעקב בשם \u0003אל\u0004 שהוא שם אמא והכל אחד."],[4,"כי שם נגלו אליו האלקים:","שפירושו מלאכים, כי אמר נגלו ולא נגלה. והוקשה לו, איזה טעם הוא זה, על מה שקרא למזבח אל בית אל. וז\"ש משום שהם אינם נמצאים אלא בשכינה, כי שבעים מלאכים הם הנמצאים תמיד עם השכינה (כנ\"ל וירא אות רס\"ח) ושבעים כסאות הם סביב השכינה, וע\"כ כשיש גילוי המלאכים יש גילוי השכינה. ועל כן אומר הכתוב, כי שם \u0003נגלו\u0004 אליו האלקים, במקום זה \u0003הנגלה,\u0004 דהיינו בנוקבא, כי כתוב \u0003והנה ה' נצב עליו,\u0004 דהיינו על הסולם שהוא הנוקבא, (כנ\"ל ויצא דף כ\"ט ד\"ה בגיני כך ע\"ש) פירוש, שמקודם לכן כתוב והנה מלאכי אלקים עולים ויורדים בו, הרי שגילוי המלאכים בא עם גילוי השכינה. ולפיכך קרא יעקב שם המזבח \u0003אל בית אל,\u0004 דהיינו על גילוי השכינה, ותלה זה בגילוי המלאכים."],[5,"ויעל מעליו אלקים וגו':","ר' שמעון אמר, מכאן, שיעקב נעשה מרכבה קדושה לה'. ביחד עם האבית, ובוא וראה, יעקב הוא מרכבה קדושה עליונה לז\"א. העומד להאיר אל הלבנה, שהיא הנוקבא, והוא מרכבה בלבדו, משום שהוא כולל בעצמו את האבות, שהם חסד וגבורה, כי ת\"ת כולל חו\"ג. וזהו שכתוב, \u0003ויעל מעליו אלקים.\u0004 כמי שיוצא ממרכבתו."],[6,"פתח ואמר, כי מי גדול וכו':","בוא וראה, כמה חביבים ישראל לפני הקב\"ה, שאין לך אומה ולשון בכל אומות העולם עובדי ע\"ז, שיהיו להם אלהים שיקבלו תפלתם, כמו שעתיד הקב\"ה לקבל תפלתם ובקשתם של ישראל בכל שעה שצריכים לקבלת התפלה, שהם מתפללים רק בשביל המדרגה שלהם, שהיא השכינה. כלומר בכל שעה שתפלתם היא לתקון השכינה."],[7,"תא חזי, יעקב וכו':","בוא וראה, יעקב, הקב\"ה קראו ישראל, כלומר השכינה, שכתוב לא יקרא שמך וגו' ויקרא את שמו וגו', על מי כתוב ויקרא. זה הוא השכינה, כמש\"א ויקרא אל משה, שכתוב ויקרא עם א' זעירא, שהיא השכינה. וכן בתחילת הדברים כתוב, \u0003ויאמר לו אלקים\u0004 שהוא השם של השכינה."],[8,"לעיל אוקימנא וכו':","לעיל (תולדות דף ע\"ז אות קס\"ז קס\"ח קס\"ט) ביארנו, את השם ישראל, כי נשלם בכל כראוי, ואז נתעלה במדרגתו ונשלם בשם הזה, ועל כן, ויקרא את שמו ישראל. וכבר נתבאר."],[9,"ר' אלעזר ור' יוסי וכו':","ר\"א ור\"י היו הולכים בדרך. אר\"י לר' אלעזר, ודאי הוא מה שאמרת, שיעקב הבחיר שבאבות הוא, והוא כולל כל הצדדים, דהיינו שהוא כולל ימין ושמאל, וע\"כ קרא שמו ישראל, וכתוב לא יקרא שמך עוד יעקב כי אם ישראל יהיה שמך, וכתוב ויקרא את שמו ישראל, וקשה, למה חזר הקב\"ה וקרא אותו יעקב הרבה פעמים. והכל קוראים אותו יעקב כמו בתחילה, וא\"כ מהו, ולא יקרא שמך עוד יעקב."],[10,"א\"ל שפיר קא אמרת וכו'",": והשיב לו, יפה אמרת, כלומר, שקושיתו יפה היא. פתח ואמר, ה' כגבור יצא כאיש מלחמות וגו', מקרא זה בארוהו, אבל בוא וראה, כתוב \u0003כגבור יצא,\u0004 גבור היה צריך לומר, \u0003כאיש מלחמות\u0004, איש מלחמות היה צריך לומר."]],[[0,"","בֹּא רְאֵה שֶׁיַּעֲקֹב אִישׁ שָׁלֵם בַּכֹּל הָיָה, וְהָיָה נִדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ- הוּא. מַה כָּתוּב? וְנָקוּמָה וְנַעֲלֶה בֵּית אֵל וְאֶעֱשֶׂה שָּׁם מִזְבֵּחַ לָאֵל הָעֹנֶה אֹתִי בְּיוֹם צָרָתִי וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי. מִיָּד - וַיִּתְּנוּ אֶת יַעֲקֹב. מִכָּאן שֶׁצָּרִיךְ הָאָדָם לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהוֹדוֹת לוֹ עַל נִסִּים וְעַל טוֹבוֹת שֶׁעָשָׂה עִמּוֹ, זֶהוּ שֶׁכָּתוּב וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי."],[1,"","בֹּא רְאֵה, בַּהַתְחָלָה כָּתוּב וְנָקוּמָה וְנַעֲלֶה בֵּית אֵל וְגוֹ', הִכְלִיל בָּנָיו עִמּוֹ, וְאַחַר כָּךְ כָּתוּב וְאֶעֱשֶׂה שָּׁם מִזְבֵּחַ, וְלֹא כָתוּב וְנַעֲשֶׂה, שֶׁהוֹצִיא אוֹתָם מִכְּלַל זֶה. מָה הַטַּעַם? מִשּׁוּם שֶׁעָלָיו הָיָה הַדָּבָר. יַעֲקֹב תִּקֵּן תְּפִלַּת עַרְבִית וַדַּאי, וְהוּא עָשָׂה מִזְבֵּחַ וְעָלָיו הָיָה הַדָּבָר, וּמִשּׁוּם שֶׁהוּא עָבַר כָּל אוֹתָן צָרוֹת מִיּוֹם שֶׁבָּרַח מִלִּפְנֵי אָחִיו, שֶׁכָּתוּב וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי, וְהֵם בָּאוּ אַחַר כָּךְ לָעוֹלָם, וְעַל זֶה לֹא הִכְנִיס אוֹתָם עִמּוֹ."],[2,"","רַבִּי אֶלְעָזָר אָמַר, מִכָּאן מִי שֶׁנַּעֲשָׂה לוֹ נֵס, צָרִיךְ לְהוֹדוֹת. מִי שֶׁאוֹכֵל לֶחֶם בְּשֻׁלְחָן, הוּא צָרִיךְ לְבָרֵךְ, וְלֹא אַחֵר שֶׁלֹּא אָכַל דָּבָר."],[3,"","וַיִּבֶן שָׁם מִזְבֵּחַ וְגוֹ'. בֹּא רְאֵה, כָּתוּב וַיִּבֶן שָׁם מִזְבֵּחַ, וְלֹא כָתוּב (באלו המזבחות) שֶׁהֶעֱלָה עָלָיו נְסָכִים וְעוֹלוֹת, אֶלָּא מִשּׁוּם שֶׁתִּקֵּן אוֹתָהּ דַּרְגָּה הָרְאוּיָה לְהִתְתַּקֵּן. מִזְבֵּחַ לַה', לְתַקֵּן דַּרְגָּה תַּחְתּוֹנָה לְחַבְּרָהּ בְּדַרְגָּה עֶלְיוֹנָה, וְעַל זֶה וַיִּבֶן שָׁם מִזְבֵּחַ - זוֹ דַּרְגָּה תַּחְתּוֹנָה. לַה' - זוֹ דַּרְגָּה עֶלְיוֹנָה. וַיִּקְרָא לַמָּקוֹם אֵל בֵּית אֵל - שֵׁם זֶה כַּשֵּׁם הָעֶלְיוֹן, מִשּׁוּם שֶׁכְּשֶׁהֵאִירָה מֵהָאֵם, אָז כְּאִמָּהּ בִּתָּהּ וְהַכֹּל אֶחָד."],[4,"","כִּי שָׁם נִגְלוּ אֵלָיו הָאֱלֹהִים - מִשּׁוּם שֶׁהֵם לֹא נִמְצָאִים אֶלָּא בַּשְּׁכִינָה, שֶׁהֲרֵי שִׁבְעִים הָיוּ שֶׁהֵם נִמְצָאִים תָּמִיד עִם הַשְּׁכִינָה, וְשִׁבְעִים קָתֶדְרָאוֹת סְבִיב הַשְּׁכִינָה, וְעַל זֶה כִּי שָׁם נִגְלוּ אֵלָיו הָאֱלֹהִים, בְּמָקוֹם זֶה שֶׁהִתְגַּלָּה, שֶׁהֲרֵי כָּתוּב וְהִנֵּה ה' נִצָּב עָלָיו."],[5,"","וַיַּעַל מֵעָלָיו אֱלֹהִים בַּמָּקוֹם אֲשֶׁר דִּבֶּר אִתּוֹ. רַבִּי שִׁמְעוֹן אָמַר, מִכָּאן שֶׁנַּעֲשָׂה מֶרְכָּבָה קְדוֹשָׁה עִם הָאָבוֹת. וּבא וּרְאֵה, יַעֲקֹב הוּא מֶרְכָּבָה קְדוֹשָׁה עֶלְיוֹנָה שֶׁעוֹמֶדֶת לְהָאִיר לַלְּבָנָה, וְהוּא מֶרְכָּבָה לְבַדּוֹ. זֶהוּ שֶׁכָּתוּב וַיַּעַל מֵעָלָיו אֱלֹהִים."],[6,"","פָּתַח וְאָמַר, (דברים ד) כִּי מִי גוֹי גָּדוֹל אֲשֶׁר לוֹ אֱלֹהִים קְרֹבִים אֵלָיו בְּכָל קָרְאֵנוּ. אֵלָיו בֹּא רְאֵה כַּמָּה הֵם חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֵין לְךְ עַם וְלָשׁוֹן בְּכָל הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁבָּעוֹלָם שֶׁיֵּשׁ לוֹ אֱלוֹהַּ שֶׁיִּשְׁמַע אוֹתָם כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְזֻמָּן לְקַבֵּל תְּפִלּוֹת וּבַקָּשׁוֹת שֶׁל יִשְׂרָאֵל בְּכָל שָׁעָה שֶׁהֵם צְרִיכִים לְהַשְׁמִיעַ תְּפִלָּה שֶׁהֵם רוֹצִים בִּשְׁבִיל אוֹתָהּ דַּרְגָּה שֶׁלָּהֶם."],[7,"","בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לְיַעֲקֹב יִשְׂרָאֵל, שֶׁכָּתוּב לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ, וַיִּקְרָא אֶת שְׁמוֹ. מִי וַיִּקְרָא? זוֹ שְׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר וַיִּקְרָא אֶל מֹשֶׁה. וַיֹּאמֶר לוֹ אֱלֹהִים,"],[8,"","לְמַעְלָה בֵּאַרְנוּ שֶׁהֲרֵי נִשְׁלַם בַּכֹּל כָּרָאוּי, וְאָז הִתְעַלָּה בְדַרְגָּתוֹ וְנִשְׁלַם בְּשֵׁם זֶה, וְעַל זֶה וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל, וַהֲרֵי נִתְבָּאֵר."],[9,"","רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבֵּי אֶלְעָזָר, וַדַּאי מַה שֶּׁאָמַרְתָּ שֶׁיַּעֲקֹב בְּחִיר הָאָבוֹת הוּא, וְהוּא אָחוּז לְכָל הַצְּדָדִים, וְקָרָא שְׁמוֹ יִשְׂרָאֵל, וְכָתוּב לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ, וְכָתוּב וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל, לָמָּה חָזַר הַקָּדוֹשׁ בָּרוּךְ הוּא וְקָרָא לוֹ יַעֲקֹב בְּכַמָּה פְעָמִים, וְהַכֹּל קָרְאוּ לוֹ יַעֲקֹב כְּמוֹ מִקֹּדֶם? אִם כָּךְ, מַה זֶּה וְלֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב?"],[10,"","אָמַר לוֹ, יָפֶה אָמַרְתָּ. פָּתַח וְאָמַר, (ישעיה מב) ה' כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה, פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל בּא רְאֵה, כַּגִּבּוֹר יֵצֵא? גִּבּוֹר צָרִיךְ לִכְתֹּב! כְּאִישׁ מִלְחָמוֹת? אִישׁ מִלְחָמוֹת צָרִיךְ לִכְתֹּב!"]]],[["אֶלָּא הָא אִתְּמָר יְיָ בְּכָל אֲתַר רַחֲמֵי אִיהוּ, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא, יְיָ שְׁמֵיהּ אִיהוּ, דִּכְתִיב, (ישעיהו מ״ב:ח׳) אֲנִי יְיָ הוּא שְׁמִי, וְחָמִינָן דִּלְזִמְנִין אִתְקְרֵי שְׁמֵיהּ אֱלהִים וְהוּא דִינָא בְּכָל אֲתַר. אֶלָּא בְּזִמְנָא דְאַסְגִיאוּ זַכָּאִין בְּעַלְמָא, יְיָ שְׁמֵיהּ וְאִתְקְרֵי בִּשְׁמָא דְרַחֲמֵי. וּבְזִמְנָא דְאַסְגִיאוּ חַיָּיבִין בְּעַלְמָא, אֱלֹהִים שְׁמֵיהּ וְאִתְקְרֵי בִּשְׁמָא דֵּאֱלהִים. כָּךְ בְּזִמְנָא דְיַעֲקֹב לָא הֲוָה בֵּין שָׂנְאִין וְלָא הֲוָה בְּאַרְעָא אָחֳרָא, קָרֵי לֵיהּ יִשְׂרָאֵל. וְכַד הֲוָה בֵּין שָׂנְאִין, אוֹ בְּאַרְעָא אָחֳרָא קָרֵי לֵיהּ יַעֲקֹב.","אָמַר לֵיהּ, עֲדַיִין לָא אִתְיַישְׁבָא מִלָּה. דִּכְתִיב לֹא יִקָּרֵא, וְהָא אֲנַן קָרִינָן לֵיהּ. וּמַאי דַאֲמַרְתְּ דְּכַד הֲוָה בֵּין שָׂנְאִין אוֹ בְּאַרְעָא אָחֳרָא קָרֵי לֵיהּ יַעֲקֹב. תָּא חֲזֵי, כְּתִיב, (בראשית ל״ז:א׳) וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנַעַן, וְהָא לָא הֲוָה בְּאַרְעָא אָחֳרָא.","אָמַר לֵיהּ, הָא בְּקַדְמִיתָא אִתְּמָר, כְּמָה דְקוּדְשָׁא בְּרִיךְ הוּא לְזִמְנִין אִתְקְרֵי יְיָ, וּלְזִמְנִין אִתְקְרֵי אֱלֹהִים. הָכִי נָמֵי לְזִמְנִין אִקְרֵי יִשְׂרָאֵל וּלְזִמְנִין אִקְרֵי יַעֲקֹב וְכֹלָּא בְּדַרְגִּין יְדִיעָן. וּמַה דְּאִתְּמָר לא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב, לְאִתְיַשְּׁבָא בִּשְׁמָא דָא.","אָמַר לֵיהּ, אִי הָכִי, הָא כְּתִיב, (בראשית י״ז:ה׳) וְלֹא יִקָּרֵא עוֹד אֶת שִׁמְךָ אַבְרָם וְהָיָה שִׁמְךָ אַבְרָהָם. אָמַר לֵיהּ, הָתָם כְּתִיב וְהָיָה. וְעַל דָּא קָיְימָא בְּהַהוּא שְׁמָא. אֲבָל הָכָא לָא כְּתִיב וְהָיָה, אֶלָּא כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ. וְלָא כְּתִיב וְהָיָה שִׁמְךָ יִשְׂרָאֵל, וְאֲפִילּוּ בְּזִמְנָא חָדָא סַגֵּי לֵיהּ, כָּל שֶׁכֵּן דִּלְזִמְנִין כָּךְ וּלְזִמְנִין כָּךְ. וְכַד אִתְעַטְּרוּ בְּנוֹי בְּכֹהֲנֵי וְלֵיוָאֵי וְאִסְתַּלְּקוּ בְּדַרְגִּין עִלָּאִין, כְּדֵין אִתְעַטַּר בִּשְׁמָא דָא תָּדִיר.","עַד דְּהֲווּ אָזְלֵי, אָמַר לֵיהּ רִבִּי יוֹסֵי לְרִבִּי אֶלְעָזָר, הָא אִתְּמָר דְּכַד מִיתַת רָחֵל נָטְלָא בֵּיתָא מַאן דְּאִצְטְרִיךְ לְאִתְתַּקְּנָא בִּתְרֵיסַר שִׁבְטִין כְּדְקָא יְאוּת. אַמַּאי מִיתַת רָחֵל מִיָּד, אָמַר לֵיהּ, הָא לְמֶהֱוֵי שְׁכִינְתָּא מִתְעַטְּרָא כְּדְקָא יְאוּת וּלְמֶהֱוֵי אֵם הַבָּנִים שְׂמֵחָה וּבֵיהּ שַׁרְיָא (לעילא) לְנַטְלָא בֵּיתָא וּלְאִתְתַּקָּנָא. וְעַל דָּא בִּנְיָמִין הוּא תָּדִיר בְּמַעֲרָב וְלָא בְסִטְרָא אָחֳרָא.","וּבֵיהּ שַׁרְיָא לְאִתְתַּקְּנָא בִּתְרֵיסַר שִׁבְטִין, וּבֵיהּ שַׁרְיָא מַלְכוּתָא דִרְקִיעָא לְאִשְׁתְּמוֹדְעָא בְּאַרְעָא. וְרָזָא דָּא, בְּכָל שֵׁירוּתָא דְּאַתְיָא לְאִשְׁתְּמוֹדְעָא בְּקַשְׁיוּ אִיהוּ, וְעַל דָּא אִית בָּהּ דִּינָא דְמוֹתָא וּמִתַּמָּן אִתְיַשְּׁבַת.","הָכָא כַּד בָּעָא לְאִתְתַּקְּנָא וּלְנַטְלָא בֵּיתָא אִתְעֲבִיד דִּינָא בְּרָחֵל וּבָתַר כֵּן אִתְתַּקְּנַת לְאִתְיַשְּׁבָא. כַּד בָּעָא לְאִשְׁתְּמוֹדְעָא מַלְכוּתָא בְּאַרְעָא שַׁרְיָא בְּדִינָא. וְלָא אִתְיַשְּׁבַת מַלְכוּתָא בְּדוּכְתָא כְּדְקָא יְאוּת עַד דְּאִתְעַר דִּינָא בִּשָׁאוּל לְפוּם עוֹבָדוֹי, וּלְבָתַר אִתְיַשְּׁבַת מַלְכוּתָא וְאִתְתַּקְּנַת.","תָּא חֲזֵי, כָּל שֵׁירוּתָא תַּקִּיף וּלְבָתַר נַיְיחָא. בְּרֹאשׁ הַשָּׁנָה שֵׁירוּתָא תַּקִּיף. דְּכָל עַלְמָא אִתְדָּן כָּל חַד וְחַד לְפוּם עוֹבָדוֹי, וּלְבָתַר נַיְיחָא סְלִיחָה וְכִפּוּרֵי. בְּגִין דְּשֵׁירוּתָא אִיהוּ מִשְׂמָאלָא וְעַל דָּא דִּינוֹי תַּקִּיפִין, וּלְבָתַר אִתְעַר יָמִינָא וְעַל דָּא הֲוֵי נַיְיחָא.","וּלְזִמְנָא דְאָתֵי זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְעָרָא בְּנַיְיחָא עַל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וּלְבָתַר יִתְתַּקַּף עֲלַיְיהוּ בְּדִינָא קַשְׁיָא. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ב:י״ג) יְיָ כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה יָרִיעַ אַף יַצְרִיחַ עַל אוֹיְבָיו יִתְגַּבָּר. יְיָ בְּקַדְמִיתָא דְּאִיהוּ רַחֲמֵי, וּלְבָתַר כַּגִּבּוֹר וְלָא גִבּוֹר. וּלְבָתַר כְּאִישׁ מִלְחָמוֹת וְלֹא אִישׁ מִלְחָמוֹת. לְבָתַר אִתְגְּלִי תּוּקְפָא עֲלַיְיהוּ וְיִתְתַּקַּף לְשֵׁיצָאָה לוֹן, דִּכְתִיב יָרִיעַ אַף יַצְרִיחַ עַל אוֹיְבָיו יִתְגַּבָּר. וּכְתִיב, (זכריה י״ד:ג׳) וְיָצָא יְיָ וְנִלְחַם בַּגּוֹיִם הָהֵם כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב. וּכְתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֶאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגו':","וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה וַתִּקְרָא שְׁמוֹ בֶּן אוֹנִי וְאָבִיו קָרָא לוֹ בִּנְיָמִן. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (נחום א׳:ז׳) טוֹב יְיָ לְמָעוֹז בְּיוֹם צָרָה וְיֹדֵעַ חֹסֵי בוֹ. זַכָּאָה חוּלָקֵיהּ דְּבַר נָשׁ דְּאִתְתַּקַּף בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּתוּקְפָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ תּוּקְפָא, וְאוּקְמוּהָ טוֹב יְיָ, כְּמָה דְאַתְּ אָמֵר (תהילים קמ״ה:ט׳) טוֹב יְיָ לַכֹּל. לְמָעוֹז, דָּא הוּא תּוּקְפָא דְּאִית בֵּיהּ יְשׁוּעוֹת. דִּכְתִיב, (תהילים כ״ח:ח׳) וּמָעוֹז יְשׁוּעוֹת מְשִׁיחוֹ הוּא. בְּיוֹם צָרָה, בְּיוֹמָא דְעָקוּ דְּעָקִין שְׁאָר עַמִּין לְיִשְׂרָאֵל."],[[0,"אלא הא אתמר וכו':","ומשיב, אלא הרי למדנו, \u0003הוי\"ה\u0004 בכל מקום שהוא, הוא רחמים בודאי, והקב\"ה, הוי\"ה הוא שמו, שכתוב, אני הוי\"ה הוא שמי. ואנו רואים שלפעמים נקרא שמו \u0003אלקים\u0004, שהוא דין בכל מקום שהוא. אלא בשעה שמתרבים צדיקים בעולם, שמו \u0003הוי\"ה,\u0004 ונקרא בשם הרחמים, ובשעה שרשעים מתרבים בעולם, שמו \u0003אלקים,\u0004 ונקרא בשם אלקים. כך, בזמן שיעקב לא היה בין שונאים, ולא היה בחוץ לארץ קוראים לו ישראל, וכשהיה בין שונאים או בחוץ לארץ קוראים לו יעקב."],[1,"א\"ל עדיין וכו':","אמר לו עוד לא נתיישב הדבר, שכתוב לא יקרא, ואנו קוראים, ומה שתאמר שבזמן שהיה בין שונאים או בחוץ לארץ קוראים לו יעקב, בוא וראה, שכתוב וישב \u0003יעקב\u0004 בארץ מגורי אביו בארץ כנען, והוא לא היה בחוץ לארץ. ומ\"מ כתוב השם יעקב."],[2,"א\"ל הא בקדמיתא וכו':","והשיב לו הרי אמרתי בתחילה, כמו שהקב\"ה לפעמים נקרא הוי\"ה ולפעמים נקרא אלקים, דהיינו לפי המדרגה כנ\"ל, כן, לפעמים נקרא ישראל ולפעמים נקרא יעקב, והכל הוא לפי מדרגות ידועות. פירוש, כשיש לו מדרגות ג\"ר וראש נקרא ישראל, וכשהוא ו\"ק בלי ראש, הוא נקרא יעקב. ומה שנאמר לא יקרא שמך עוד יעקב פירושו, שלא ישאר בשם הזה יעקב, אלא שיהיו לו ב' שמות יעקב וישראל, לפי המדרגה."],[3,"א\"ל אי הכי הא וכו'.","א\"ל, אם כן, הרי כתוב, ולא יקרא עוד את שמך אברם והיה שמך אברהם, ואין הפירוש שיקרא בב' השמות אברם ואברהם, אלא אברהם לבד. אמר לו, שם כתוב \u0003והיה\u0004 שמך אברהם, ועל כן נשאר בשם הזה, אבל כאן לא כתוב \u0003והיה,\u0004 אלא \u0003כי אם\u0004 ישראל יהיה שמך, ולא כתוב \u0003והיה\u0004 שמך ישראל, שעל פי המשמעות הזו, הרי די אפילו שיקרא פעם אחת בשם ישראל, ומכל שכן שנקרא לפעמים יעקב ולפעמים ישראל, ודאי הוא שמקוים הכתוב כי אם ישראל יהיה שמך. וכאשר נתעטרו בניו בכהנים ולויים ונתעלו במדרגות עליונות, אז נתעטר בשם \u0003ישראל\u0004 תמיד."],[4,"עד דהוו אזלי וכו':","בעוד שהיו הולכים, אמר לו ר' יוסי לר' אלעזר, הרי למדנו, כשמתה רחל, מי שהיתה צריכה להתקן בי\"ב שבטים, לקחה את הבית, דהיינו השכינה, ושואל, למה מתה רחל מיד, כלומר, מה זה תלוי במיתת רחל. אמר לו, הוא, כדי שתהיה השכינה מתעטרת כראוי, דהיינו שתשיג מוחין דג\"ר, ותהיה אם הבנים שמחה, כלומר, רחל מתה כדי ששכינה תתאה, רחל, ושכינה עלאה, לאה, תהיינה לפרצוף אחד, שאז שכינה תתאה, משגת ג\"ר, ושכינה עלאה שהיא אם הבנים, היא שמחה בתקון י\"ב השבטים ומה שלאה לא מתה, עי' לעיל (ויצא דף צ\"ט ד\"ה ואי) ובו, בבנימין, התחילה השכינה לקחת הבית ולהתקן. כי היא בחינת יסוד מי\"ב השבטים, וע\"כ היא הראשונה לתקון השכינה. ועל כן בנימין הוא תמיד במערב, בדגלים. כי יסוד הוא בחינת מערב, ולא בצד אחר."],[5,"וביה שריא לאתתקנא וכו':","ובו, בבנימין, מתחלת השכינה להתקן בי\"ב השבטים, ובו מתחילה מלכות שמים להתודע בארץ, כי המלך הראשון בישראל, שאול היה, שהוא מבניו, והוא סוד, שכל התחלה הבאה להתודע, בקושיות היא באה, וע\"כ יש בה דין של מות, ואחר זה, היא מתישבת ומתקיימת."],[6,"הכא כד בעא וכו':","כאן, כשרצתה השכינה להתתקן ולקחת הבית, בתקון י\"ב השבטים, נעשה הדין ברחל, כי מתה, ואחר זה, נתתקנה להתישב, כנ\"ל. כן כשרצתה המלכות להתודע בארץ, התחילה בדין, ולא נתישבה המלכות במקומה כראוי, עד שנתעורר הדין בשאול לפי מעשיו, שנהרג בהרי הגלבוע, ולאחר כך נתישבה המלכות בדוד, ונתתקנה."],[7,"ת\"ח כל שירותא תקיף וכו':","בוא וראה. כל התחלה קשה, ואח\"כ באה הרוחה. בראש השנה, ההתחלה קשה, שכל העולם נידון כל אחד ואחד לפי מעשיו, ואחר כך הרוחה, סליחה וכפרה. דהיינו ביום הכפרים וסוכות. והוא משום שההתחלה היא בבחינת השמאל, וע\"כ דיניו קשים, ואחר זה נתעורר הימין, כמ\"ש שמאלו תחת לראשי, ואחר כך וימינו תחבקני, ועל כן נעשתה הרוחה."],[8,"ולזמנא דאתי זמין וכו':","ובאומות העולם הוא להיפך מזה, כי לעתיד לבא, עתיד הקב\"ה להתעורר בשלוה מתחילה על האומות האחרות עכו\"ם, ואחר כך יתגבר עליהם בדין קשה. וזהו שכתוב, הוי\"ה כגבור יצא וגו', מתחילה \u0003הוי\"ה,\u0004 שהוא רחמים, ואחר כך \u0003כגבור,\u0004 ולא גבור ממש, ואחר כך \u0003כאיש מלחמות,\u0004 ולא איש מלחמות ממש, ולאחר כך מתגלה הגבורה עליהם ויתגבר לכלותם, שכתוב יריע אף יצריח על אויביו יתגבר. וכתוב ויצא ה' ונלחם וגו'. וכתוב מי זה בא מאדום וגו'."],[9,"ויהי בצאת נפשה וגו':","ר' יהודה פתח ואמר, טוב ה' למעוז וגו', אשרי חלקו של אדם המתגבר בהקב\"ה, משום שמעוזו של הקב\"ה הוא מעוז, ובארוהו. \u0003טוב ה',\u0004 הוא כמו שאתה אומר, טוב ה' לכל. \u0003למעוז,\u0004 זה הוא מעוז שיש בו ישועות, שכתוב, ומעוז ישועות משיחו הוא. \u0003ביום צרה\u0004, ביום של צרה, שהאומות האחרות מציקות לישראל."]],[[0,"","אֶלָּא הֲרֵי נִתְבָּאֵר, ה' בְּכָל מָקוֹם זֶה רַחֲמִים, וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא, שְׁמוֹ הוּא ה', שֶׁכָּתוּב (ישעיה מב) אֲנִי ה' הוּא שְׁמִי. וְרָאִינוּ שֶׁלִּפְעָמִים נִקְרָא שְׁמוֹ אֱלֹהִים, וְהוּא דִין בְּכָל מָקוֹם. אֶלָּא בִּזְמַן שֶׁמִּתְרַבִּים הַצַּדִּיקִים בָּעוֹלָם, ה' שְׁמוֹ, וְנִקְרָא בְּשֵׁם הָרַחֲמִים. וּבִזְמַן שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם, אֱלֹהִים שְׁמוֹ, וְנִקְרָא בְּשֵׁם אֱלֹהִים. כָּךְ בִּזְמַן שֶׁיַּעֲקֹב לֹא הָיָה בֵּין שׂוֹנְאִים וְלֹא הָיָה בְּאֶרֶץ אַחֶרֶת, קָרָא לוֹ יִשְׂרָאֵל. וְכַאֲשֶׁר הָיָה בֵּין שׂוֹנְאִים אוֹ בְּאֶרֶץ אַחֶרֶת, קָרָא לוֹ יַעֲקֹב."],[1,"","אָמַר לוֹ, עֲדַיִן לֹא הִתְיַשֵּׁב הַדָּבָר שֶׁכָּתוּב לֹא יִקָּרֵא, וַהֲרֵי אָנוּ קוֹרְאִים לוֹ. וּמַה שֶּׁאָמַרְתָּ שֶׁכְּשֶׁהָיָה בֵּין שׂוֹנְאִים אוֹ בְּאֶרֶץ אַחֶרֶת קָרָא לוֹ יַעֲקֹב - בּא רְאֵה, כָּתוּב (בראשית לז) וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן, וַהֲרֵי לֹא הָיָה בְּאֶרֶץ אַחֶרֶת?"],[2,"","אָמַר לוֹ, הֲרֵי בַּתְּחִלָּה נֶאֱמַר כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לִפְעָמִים נִקְרָא ה' וְלִפְעָמִים נִקְרָא אֱלֹהִים, כָּךְ גַּם לִפְעָמִים נִקְרָא יִשְׂרָאֵל וְלִפְעָמִים נִקְרָא יַעֲקֹב, וְהַכֹּל בִּדְרָגוֹת יְדועוֹת. וּמַה שֶּׁנֶּאֱמַר לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב, לְהִתְיַשֵּׁב בְּשֵׁם זֶה."],[3,"","אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב (שם יז) וְלֹא יִקָּרֵא עוֹד אֶת שִׁמְךְ אַבְרָם וְהָיָה שִׁמְךְ אַבְרָהָם. אָמַר לוֹ, שָׁם כָּתוּב וְהָיָה, וְעַל זֶה עוֹמֵד בְּאוֹתוֹ שֵׁם, אֲבָל כָּאן לֹא כָתוּב וְהָיָה, אֶלָּא כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ, וְלֹא כָתוּב וְהָיָה שִׁמְךְ יִשְׂרָאֵל, וַאֲפִלּוּ בְּפַעַם אַחַת מַסְפִּיק לוֹ, כָּל שֶׁכֵּן שֶׁלִּפְעָמִים כָּךְ וְלִפְעָמִים כָּךְ. וּכְשֶׁהִתְעַטְּרוּ בָנָיו בְּכֹהֲנִים וּלְוִיִּם וְהִתְעַלּוּ בִּדְרָגוֹת עֶלְיוֹנוֹת, אָז הִתְעַטֵּר בְּשֵׁם זֶה תָּמִיד."],[4,"","עַד שֶׁהָיוּ הוֹלְכִים, אָמַר לוֹ רַבִּי יוֹסֵי לְרַבִּי נִתְבָּאֵר, הֲרֵי נִתְבָּאֵר שֶׁכְּשֶׁמֵּתָה רָחֵל, נָטְלָה הַבַּיִת מִי שֶׁצָּרִיךְ לְהִתַּקֵּן בִּשְׁנֵים עָשָׂר שְׁבָטִים כָּרָאוּי. לָמָּה מֵתָה רָחֵל מִיָּד? אָמַר לוֹ, הֲרֵי לִהְיוֹת שְׁכִינָה מִתְעַטֶּרֶת כָּרָאוּי וְלִהְיוֹת אֵם הַבָּנִים שְׂמֵחָה, וּבוֹ שׁוֹרָה (למעלה) לִטֹּל הַבַּיִת וּלְהִתַּקֵּן. וְעַל זֶה בִּנְיָמִין הוּא תָּמִיד בַּמַּעֲרָב וְלֹא בְּצַד אַחֵר."],[5,"","וּבוֹ שׁוֹרָה לְהִתַּקֵּן בִּשְׁנֵים עָשָׂר שְׁבָטִים, וּבוֹ שׁוֹרָה מַלְכוּת הָרָקִיעַ לְהִוָּדַע בָּאָרֶץ. וְסוֹד זֶה, שֶׁכָּל הַתְחָלָה שֶׁבָּאָה לְהִתְוַדֵּעַ, הִיא בְקַשְׁיוּת, וְעַל זֶה יֵשׁ בָּהּ דִּין שֶׁל מָוֶת וּמִשָּׁם מִתְיַשֶּׁבֶת."],[6,"","כָּאן כְּשֶׁרוֹצָה לְהִתְתַּקֵּן וְלִטֹּל הַבַּיִת, נַעֲשָׂה דִין בְּרָחֵל, וְאַחַר כָּךְ הִתְתַּקְּנָה לְהִתְיַשֵּׁב. כְּשֶׁרָצָה לְהוֹדִיעַ מַלְכוּת בָּאָרֶץ, שׁוֹרֶה בְּדִין, וְלֹא מִתְיַשֶּׁבֶת הַמַּלְכוּת בְּמָקוֹם כָּרָאוּי עַד שֶׁמִּתְעוֹרֵר דִּין בְּשָׁאוּל לְפִי מַעֲשָׂיו, וְאַחַר כָּךְ הִתְיַשְּׁבָה הַמַּלְכוּת וְנִתְקְנָה."],[7,"","בֹּא רְאֵה, כָּל הַתְחָלָה קָשָׁה וְאַחַר כָּךְ נוֹחָה. בְּרֹאשׁ הַשָּׁנָה הַהַתְחָלָה קָשָׁה, שֶׁכָּל הָעוֹלָם נִדּוֹן כָּל אֶחָד וְאֶחָד לְפִי מַעֲשָׂיו, וְאַחַר כָּךְ נוֹחָה, סְלִיחָה וְכִפּוּרִים. מִשּׁוּם שֶׁהָרֵאשִׁית הִיא מִשְּׂמֹאל, וְעַל זֶה דִּינָיו קָשִׁים, וְאַחַר כָּךְ מִתְעוֹרֵר הַיָּמִין, וְעַל זֶה נַעֲשֵׂית נוֹחָה."],[8,"","וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְעוֹרֵר בְּשַׁלְוָה עַל שְׁאָר עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְאַחַר כָּךְ יִתְחַזֵּק עֲלֵיהֶם בְּדִין קָשֶׁה. זֶהוּ שֶׁכָּתוּב (ישעיה מב) ה' כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה יָרִיעַ אַף יַצְרִיחַ עַל אֹיְבָיו יִתְגַּבָּר. ה' בַּתְּחִלָּה, שֶׁהוּא רַחֲמִים, וְאַחַר כָּךְ כַּגִּבּוֹר וְלֹא גִבּוֹר, וְאַחַר כָּךְ כְּאִישׁ מִלְחָמוֹת וְלֹא אִישׁ מִלְחָמוֹת, אַחַר כָּךְ יִתְגַּלֶּה הַחֹזֶק עֲלֵיהֶם וְיִתְחַזֵּק לְהַשְׁמִיד אוֹתָם, שֶׁכָּתוּב יָרִיעַ אַף יַצְרִיחַ עַל אֹיְבָיו יִתְגַּבָּר, וְכָתוּב (זכריה יד) וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב, וְכָתוּב (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'."],[9,"","וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה וַתִּקְרָא שְׁמוֹ בֶּן אוֹנִי וְאָבִיו קָרָא לו בִנְיָמִין. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (נחום א) טוֹב ה' לְמָעוֹז בְּיוֹם צָרָה וְיֹדֵעַ חֹסֵי בוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל הָאִישׁ שֶׁמִּתְחַזֵּק בַּקָּדוֹשׁ-בָּרוּךְ- הוּא, בִּשְׁבִיל שֶׁהַחֹזֶק שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא חֹזֶק, וּבֵאֲרוּהוּ טוֹב ה', כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמה) טוֹב ה' לַכֹּל. לְמָעוֹז - זֶהוּ חֹזֶק שֶׁיֵּשׁ בּוֹ יְשׁוּעוֹת, שֶׁכָּתוּב (שם כח) וּמָעוֹז יְשׁוּעוֹת מְשִׁיחוֹ הוּא. בְּיוֹם צָרָה - בְּיוֹם שֶׁל מְצוּקָה שֶׁמְּצִיקִים שְׁאָר הָעַמִּים לְיִשְׂרָאֵל"]]],[["תָּא חֲזֵי, מַה כְּתִיב (משלי כ״ד:י׳) הִתְרַפִּיתָ בְּיוֹם צָרָה צַר כֹּחֶכָה. מַאי הִתְרַפִּיתָ. מַאן דְּאִתְרַפֵּי יְדוֹי מִקוּדְשָׁא בְּרִיךְ הוּא דְּלָא לְאִתְתַּקְּפָא בֵּיהּ. וְהֵיךְ יִתְקַף בַר נָשׁ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, יַתְקִיף בְּאוֹרַיְיתָא. דְּכָל מַאן דְּאִתְתַּקַּף בְּאוֹרַיְיתָא, אִתְתַּקַּף בְּאִילָנָא דְחַיֵּי. כִּבְיָכוֹל יָהַב תּוּקְפָא לִכְנֶסֶת יִשְׂרָאֵל לְאִתְתַּקְפָא.","וְאִי הוּא יִתְרַפֵּי מֵאוֹרַיְיתָא, מַה כְּתִיב הִתְרַפִּיתָ. אִי אִיהוּ אִתְרַפֵּי מִן אוֹרַיְיתָא בְּיוֹם צָרָה צַר כֹּחֶכָה, בְּיוֹמָא דְיֵיתֵי לֵיהּ עָקוּ, כִּבְיָכוֹל דָּחִיק לָהּ לִשְׁכִינְתָּא דְּאִיהוּ חֵילָא דְעַלְמָא.","דָבָר אַחֵר צַר כֹּחֶכָה, תָּא חֲזֵי, בְּשַׁעְתָּא דְבַר נָשׁ אִתְרַפֵּי מֵאוֹרַיְיתָא וְאָזִיל בְּאָרְחָא דְלָא כַשְׁרָא, כַּמָּה בַּעֲלֵי דְבָבוּ זְמִינִין לֵיהּ לִמֶהֱוֵי לֵיהּ קַטֵּיגוֹרִין בְּיוֹמָא דְעָקוּ. וְאֲפִילּוּ נִשְׁמָתֵיהּ דְּבַר נָשׁ דְּאִיהוּ חֵילָא וְתוּקְפָא דִילֵיהּ אִיהוּ מָארֵי דְבָבוּ לְקֳבְלֵיהּ, דִּכְתִיב צַר כֹּחֶכָה, בְּגִין דְּאִיהוּ צַר לְגַבֵּיהּ. אָמַר רִבִּי אַבָּא בְּשַׁעְתָּא דְבַר נָשׁ אָזִיל בְּאָרְחֵי דְאוֹרַיְיתָא וְכָל אָרְחוֹי מִתְתַּקְּנָן כְּדְקָא יְאוּת, כַּמָּה סָנֵיגוֹרִין קָיְימִין עֲלֵיהּ לְאַדְכָּרָא לֵיהּ לְטַב.","פָּתַח וְאָמַר, (איוב ל״ג:כ״ג-כ״ד) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ וַיְחֻנְּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר. הַנֵּי קְרָאֵי אִית לְאִסְתַּכָּלָא בְּהוּ, וְכִי לָא אִתְגְּלִי כֹּלָּא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ צָרִיךְ לְמַלְאכָא דְּיֵימָא קַמֵּיהּ טַב אוֹ בִישׁ.","אֶלָּא וַדַּאי אִצְטְרִיךְ. דְּכַד אִית לֵיהּ לְבַר נָשׁ סַנֵּיגוֹרִין לְאַדְכָּרָא זְכוּ דִידֵיהּ קַמֵּיהּ, וְלָא אִית לֵיהּ (לבר נש) קַטֵּיגוֹרִין, כְּדֵין וַיְחֻנְּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר.","תָּא חֲזֵי, בְּהַאי קְרָא תִּשְׁכַּח בְּרִירָא דְמִלָּה, כְּתִיב אִם יֵשׁ עָלָיו מַלְאָךְ, אִי לָא כְּתִיב יַתִּיר יָאוֹת הוּא. אֲבָל מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף כְּתִיב, וּמַאן אִיהוּ. דָּא הוּא מַלְאָךְ דִּמְמַנָּא עִמֵּיהּ דְּבַר נָשׁ בִּסְטַר שְׂמָאלָא, דִּכְתִיב, (תהילים צ״א:ז׳) יִפֹּל מִצִּדְךָ אֶלֶף, וְדָא הוּא סִטְרָא דִשְׂמָאלָא, דִּכְתִיב בַּתְרֵיהּ וּרְבָבָה מִימִינֶךָ.","אֲבָל אֶחָד מִנִּי אֶלֶף, דָּא הוּא יֵצֶר הָרָע, דְּאִיהוּ אֶחָד מֵאִנּוּן (דאיהו) אֶלֶף דְּהֲווּ לִסְטַר שְׂמָאלָא. בְּגִין דְּאִיהוּ סָלִיק לְעֵילָא וְנָטִיל רְשׁוּ. וְעַל דָּא אִי בַר נָשׁ אָזִיל בְּאֹרַח קְשׁוֹט, הַהוּא יֵצֶר הָרָע אִיהוּ עֶבֶד לוֹ. כְּמָה דְאִתְּמָר דִּכְתִיב, (משלי י״ב:ט׳) טוֹב נִקְלֶה וְעֶבֶד לוֹ. כְּדֵין אִיהוּ סָלִיק וְאִתְעֲבִיד סַנֵּיגוֹרָא, וְאָמַר קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, זְכוּ עֲלֵיהּ דְּבַר נָשׁ. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אָמַר, פְּדָעֵהוּ מֵרֶדֶת שָׁחַת.","וְעִם כָּל דָּא לָא אַהֲדַר בְּרֵיקַנְיָא, בְּגִין דְּאִתְיְהִיב לֵיהּ אָחֳרָא לְשַׁלְטָאָה עֲלוֹי וְלִיטּוֹל נִשְׁמָתֵיהּ מִנֵּיהּ. בְּגִין דְּאַקְדִּים חוֹבוֹי דְּהַהוּא בַּר נָשׁ וְאִיהוּ כֹּפֶר עַל הַאי. הֲדָא הוּא דִכְתִיב מָצָאתִי כֹּפֶר, לְמִפְדֵי לֵיהּ.","דָבָר אַחֵר מָצָאתִי כֹפֶר. הַהוּא זְכוּ דְּאֲמַרְתְּ אִיהוּ עֲלֵיהּ כֹּפֶר לְמִפְדֵי לֵיהּ דְּלָא יֵחוֹת לַגֵּיהִנֹּם וְלָא יְמוּת. וְעַל דָּא מִבָּעֵי לֵיהּ לְבַר נָשׁ לְמֵיהַךְ בְּאֹרַח קְשׁוֹט וּבְגִין דִּיְהֵא לֵיהּ הַהוּא קַטֵּיגוֹרָא, סַנֵּיגוֹרָא.","כְּגַוְונָא דָא יִשְׂרָאֵל בְּיוֹמָא דְכִפּוּרֵי, דְּיַהֲבֵי לֵיהּ שָׂעִיר וְאִתְעַסִּיקוּ בַּהֲדֵיהּ. עַד דְּאִתְהֲדַר עֶבֶד לְהוּ וְסָלִיק וְסָהִיד סַהֲדוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִתְעֲבִיד לְהוּ סַנֵּיגוֹרָא. וְעַל דָּא אָמַר שְׁלמֹה, (משלי כ״ה:כ״א) אִם רָעֵב שׂנַאֲךָ הַאֲכִילֵהוּ לֶחֶם וְאִם צָמֵא הַשְׁקֵהוּ מַיִם. וְעַל הַאי יֵצֶר הָרָע אִתְּמָר.","וּבְגִין דָּא בְּיוֹם צָרָה, כַּד בַר נָשׁ אִתְרַפֵּי מֵאוֹרַיְיתָא, כִּבְיָכוֹל דָּחִיק לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בַּהֲדֵיהּ דְּהַהוּא יֵצֶר הָרָע דְּאִיהוּ אִתְעֲבִיד קַטֵּיגוֹרָא. צַר כֹּחֶכָה. צַר כֹּחַ כֹּ\"ה, בְּגִין דְּאִתְקָרֵב קַמֵּיהּ לְקַטְרְגָא וְאִתְחַלַּשׁ חֵילָא.","תָּא חֲזֵי, טוֹב יְיָ לְמָעוֹז בְּיוֹם צָרָה, מַאי בְּיוֹם צָרָה. דָּא יַעֲקֹב כַּד אֲתָא עֲלֵיהּ עֵשָׂו לְקַטְרְגָא לֵיהּ. וְיוֹדֵעַ חוֹסֵי בוֹ, כַּד אֲתָא עֲלֵיהּ עָקוּ דְדִינָא. וְתָּא חֲזֵי, לֵית מְקַטְרְגָא אִשְׁתַּכַּח עֲלֵיהּ דְּבַר נָשׁ אֶלָּא בְּזִמְנָא דְסַכָּנָה."],[[0,"תא חזי מה וכו':","בוא וראה, מה כתוב, התרפית ביום צרה צר כחכה. שואל, מהו התרפית. ואומר, מי שידיו מתרפות מן הקב\"ה, שלא להתגבר בו. ואיך יתגבר האדם בהקב\"ה, היינו שיתגבר בתורה. כי כל מי שמתגבר בתורה הוא מתגבר בעץ החיים, כביכול הוא נותן כח לכנסת ישראל שהיא השכינה, להתחזק."],[1,"ואי הוא יתרפי וכו':","ואם הוא מתרפה מתורה, מה כתוב: \u0003התרפית,\u0004 אם הוא מתרפה מתורה, \u0003ביום צרה צר כחכה,\u0004 ביום שתבוא לו הצרה, כביכול הוא דוחק את השכינה, שהיא כחו של העולם. פירוש, \u0003כחכה\u0004 היא נוטריקון כח-כה, אשר \u0003כה\u0004 הוא שם השכינה, ודורש, \u0003צר כח-כה,\u0004 שמצר \u0003כח\u0004 השכינה הנקראת \u0003כה.\u0004"],[2,"ד\"א צר כחכה וכו':","פירוש אחר בכתוב, צר כחכה. בוא וראה בשעה שאדם מתרפה מתורה והולך בדרך שאינו כשר, כמה אויבים עתידים להיות מצירים לו ביום צרה, ואפילו נשמתו של האדם, שהיא כחו ותוקפו, נעשית אויבת לנגדו, שכתוב \u0003צר כחכה,\u0004 כי נעשית צר ואויב לו. ודורש \u0003צר כחכה,\u0004 כמו שהיה כתוב \u0003צר כחך,\u0004 שרומז על הנשמה, שהיא כחו של האדם."],[3,"אמר ר' אבא בשעתא וכו':","אר\"א, בשעה שהאדם הולך בדרכי התורה וכל דרכיו מתוקנים כראוי, כמה מליצים ישרים עומדים לו להזכירו לטוב, פתח ואמר, אם יש עליו מלאך מליץ וגו'. במקראות הללו, יש להסתכל בהם, וכי הכל לא גלוי לפני הקב\"ה, והוא צריך למלאך שיאמר לפניוטוב או רע."],[4,"אלא ודאי אצטריך וכו':","ומשיב, אלא ודאי שהוא נצרך למלאך, אע\"פ שיודע הכל, והוא כדי לעורר רחמים, כי כשיש לו לאדם מליצים טובים להזכיר לפני הקב\"ה את זכויותיו, ואין לו מלמד חובה, אז, ויחוננו ויאמר פדעהו מרדת שחת מצאתי כפר."],[5,"ת\"ח בהאי קרא וכו':","בוא וראה, במקרא הזה תמצא בירורו של הדבר, כתוב, \u0003אם יש עליו מלאך,\u0004 אם לא היה כתוב יותר, היה טוב, אבל כתוב, \u0003מלאך מליץ אחד מני אלף,\u0004 וא\"כ צריכים לדעת מי הוא, ואומר זה הוא המלאך, הממונה להיות עם האדם לצד שמאלו, שכתוב, יפול מצדך \u0003אלף,\u0004 וזה הוא צד שמאל, כי כתוב אחריו, \u0003ורבבה מימינך,\u0004 משמע \u0003שמצדך\u0004 שכתוב מקודם לכן, הוא צד שמאל."],[6,"אבל אחד וכו':","אבל אחד מני אלף זהו היצר הרע, שהוא אחד מן אותם אלף המזיקים, שהם לצד שמאל, כי הוא עולה למעלה ונוטל רשות, ואח\"כ יורד וממית ועל כן אם האדם הולך בדרך אמת, אותו היצר הרע נעשה לו לעבד, שאמרו (לעיל דף ה' אות י\"ז) שכתוב, טוב נקלה ועבד לו. אז הוא עולה ונעשה מליץ יושר, ואומר לפני הקב\"ה זכות על האדם. אז אומר הקב\"ה פדעהו מרדת שחת."],[7,"ועם כל דא לא וכו':","ועם כל זה, אין היצר הרע חוזר ריקם, כי ניתן לו אדם אחר במקומו לשלוט עליו, ולקחת נשמתו ממנו, משום שהקדימו עונותיו של האדם ההוא. ונתפש עליהם. והוא נעשה כפר על האדם שנצל. וז\"ש \u0003מצאתי כפר\u0004 לפדות אותו."],[8,"ד\"א מצאתי כפר וכו':","פירוש אחר על \u0003מצאתי כפר,\u0004 שהקב\"ה אמר אל המלאך, אותה הזכות שאמרת על האדם, היא תהיה עליו לכפר, לפדותו, שלא ירד לגיהנם ולא ימות. ועל כן צריך האדם ללכת בדרך אמת, כדי שמלמד החובה, יתהפך להיות לו למלמד זכות."],[9,"כגוונא דא וכו':","כעין זה, ישראל ביום הכפורים, שנותנים לו ליצר הרע, שהוא ס\"מ, שעיר, דהיינו השעיר לעזאזל, ומתעסקים עמו עד שנעשה להם עבד, ועולה ואומר עדות לפני הקב\"ה ונעשה להם למליץ טוב (כנ\"ל וירא דף קי\"ד אות שפ\"ה) ועל זה אמר שלמה, אם רעב שנאך האכילהו לחם וגו'. ועל היצר הרע הזה נאמר הכתוב."],[10,"ובגין דא ביום צרה וכו':","ומשום זה, \u0003ביום צרה,\u0004 כשהאדם מתרפה מתורה, כביכול, דוחף את הקב\"ה אל היצר הרע, הנעשה מקטרג על האדם, לשמוע קטרוגו וא\"כ הוא, יום צרה, ואז נאמר, \u0003צר כחכה\u0004 שהוא נוטריקון, \u0003צר כ\"ח כ\"ה\u0004 שמצר כח השכינה שנקראת כ\"ה, משום שהיצה\"ר מתקרב לפני הקב\"ה לקטרג, ונחלש כחה של השכינה, מחמת הקטרוג."],[11,"תא חזי, טוב ה' למעוז ביום צרה:","שואל, מהו ביום צרה. ואומר, זה הוא יעקב בעת שבא עשו לקטרג עליו. \u0003ויודע חוסי בו,\u0004 היינו כשבאה עליו צרת הדין של מיתת רחל כמו שמבאר לפנינו."]],[[0,"","בֹּא רְאֵה מַה כָּתוּב, (משלי כד) הִתְרַפִּיתָ בְּיוֹם צָרָה צַר כֹּחֶכָה. מַה זֶּה הִתְרַפִּיתָ? מִי שֶׁמַּרְפֶּה יָדָיו מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא לְהִתְחַזֵּק בּוֹ. וְאֵיךְ יַחֲזִיק הָאָדָם בַּקָּדוֹשׁ-בָּרוּךְ-הוּא? יַחֲזִיק בַּתּוֹרָה. שֶׁכָּל מִי שֶׁמַּחֲזִיק בַּתּוֹרָה, מַחֲזִיק בְּעֵץ הַחַיִּים, כִּבְיָכוֹל נוֹתֵן חֹזֶק לִכְנֶסֶת יִשְׂרָאֵל לְהִתְחַזֵּק."],[1,"","וְאִם הוּא יִתְרַפֶּה מֵהַתּוֹרָה מַה כָּתוּב? הִתְרַפִּיתָ. אִם הוּא הִתְרַפֶּה מִן הַתּוֹרָה - בְּיוֹם צָרָה צַר כֹּחֶכָה. בְּיוֹם שֶׁתָּבֹא לוֹ מְצוּקָה, כִּבְיָכוֹל דּוֹחֵק אֶת הַשְּׁכִינָה שֶׁהִיא כֹּחוֹ שֶׁל הָעוֹלָם."],[2,"","דָּבָר אַחֵר צַר כֹּחֶכָה - בּא רְאֵה, בְּשָׁעָה שֶׁבֶּן אָדָם מִתְרַפֶּה מִן הַתּוֹרָה וְהוֹלֵךְ בְּדֶרֶךְ לֹא כְשֵׁרָה, כַּמָּה בַּעֲלֵי רִיב זְמִינִים לוֹ לִהְיוֹת לוֹ קָטֵגוֹרִים בְּיוֹם צָרָה. וַאֲפִלּוּ נִשְׁמַת הָאָדָם, שֶׁהִיא כֹּחַ וְחֹזֶק שֶׁלּוֹ, הִיא יְרִיבָה שֶׁלּוֹ כְּנֶגְדּוֹ, שֶׁכָּתוּב צַר כֹּחֶכָה, מִשּׁוּם שֶׁהוּא צַר אֵלָיו. אָמַר רַבִּי אַבָּא, בְּשָׁעָה שֶׁבֶּן אָדָם הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה וְכָל דְּרָכָיו מְתֻקָּנוֹת כָּרָאוּי, כַּמָּה סָנֵגוֹרִים עוֹמְדִים עָלָיו לְהַזְכִּירוֹ לְטוֹב."],[3,"","פָּתַח וְאָמַר, (איוב לג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר. בַּפְּסוּקִים הַלָּלוּ יֵשׁ לְהִתְבּוֹנֵן, וְכִי לֹא גָלוּי הַכֹּל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא צָרִיךְ מַלְאָךְ שֶׁיּאמַר לְפָנָיו טוֹב אוֹ רַע?"],[4,"","אֶלָּא וַדַּאי שֶׁצָּרִיךְ, שֶׁכַּאֲשֶׁר יֵשׁ לָאָדָם סָנֵגוֹרִים לְהַזְכִּיר זְכוּת שֶׁלּוֹ לְפָנָיו וְאֵין לוֹ (לאדם) קָטֵגוֹרִים, אָז וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר."],[5,"","בֹּא רְאֵה, בַּפָּסוּק הַזֶּה תִּמְצָא בֵּרוּר הַדָּבָר. כָּתוּב אִם יֵשׁ עָלָיו מַלְאָךְ. אִם לֹא כָתוּב יוֹתֵר - יָפֶה הוּא. אֲבָל מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף כָּתוּב, וּמִיהוּ? זֶהוּ הַמַּלְאָךְ הַמְמֻנֶּה עִם הָאָדָם בְּצַד שְׂמֹאל, שֶׁכָּתוּב (תהלים צא) יִפֹּל מִצִּדְּךְ אֶלֶף, וְזֶהוּ צַד שְׂמֹאל, שֶׁכָּתוּב אַחֲרָיו וּרְבָבָה מִימִינֶךְ."],[6,"","אֲבָל אֶחָד מִנִּי אָלֶף, זֶהוּ יֵצֶר יֵצֶר הָרָע, שֶׁהוּא אֶחָד מֵאוֹתָם (שהוא) אֶלֶף שֶׁהָיוּ לְצַד שְׂמֹאל, מִשּׁוּם שֶׁהוּא עוֹלֶה לְמַעְלָה וְנוֹטֵל רְשׁוּת. וְעַל זֶה, אִם בֶּן אָדָם הוֹלֵךְ בְּדֶרֶךְ אֱמֶת, אוֹתוֹ יֵצֶר הָרָע הוּא עֶבֶד לוֹ כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (משלי יב) טוֹב נִקְלֶה וְעֶבֶד לוֹ, אָז הוּא עוֹלֶה וְנַעֲשֶׂה סָנֵגוֹר, וְאוֹמֵר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא זְכוּת עַל הָאָדָם, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר, פְּדָעֵהוּ מֵרֶדֶת שַׁחַת."],[7,"","וְעִם כָּל זֶה לֹא חוֹזֵר רֵיקָם, מִשּׁוּם שֶׁנּוֹתְנִים לוֹ אַחֵר לִשְׁלֹט עָלָיו וְלִטֹּל מִמֶּנּוּ אֶת נִשְׁמָתוֹ, מִשּׁוּם שֶׁהִקְדִּים חֲטָאֵי אוֹתוֹ הָאִישׁ וְהוּא כֹּפֶר עַל זֶה. זֶהוּ שֶׁכָּתוּב מָצָאתִי כֹפֶר, לִפְדּוֹת אוֹתוֹ."],[8,"","דָּבָר אַחֵר מָצָאתִי כֹפֶר - אוֹתָהּ זְכוּת שֶׁאָמַרְתָּ, הִיא עָלָיו כֹּפֶר לִפְדּוֹת אוֹתוֹ שֶׁלֹּא יֵרֵד לַגֵּיהִנֹּם וְלֹא יָמוּת. וְלָכֵן צָרִיךְ לָאָדָם לָלֶכֶת בְּדֶרֶךְ אֱמֶת כְּדֵי שֶׁיִּהְיֶה לוֹ הַקָּטֵגוֹר סָנֵגוֹר."],[9,"","כְּמוֹ זֶה יִשְׂרָאֵל בְּיוֹם הַכִּפּוּרִים שֶׁנּוֹתְנִים לוֹ שָׂעִיר וּמִתְעַסְּקִים עִמּוֹ עַד שֶׁהוֹפֵךְ לִהְיוֹת לָהֶם עֶבֶד, וְעוֹלֶה וּמֵעִיד עֵדוּת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנַעֲשֶׂה לָהֶם סָנֵגוֹר. וְעַל זֶה אָמַר שְׁלֹמֹה הַמֶּלֶךְ, (שם כה) אִם רָעֵב שֹׂנַאֲךְ הַאֲכִילֵהוּ לָחֶם וְאִם צָמֵא הַשְׁקֵהוּ מָיִם, וְעַל הַיֵּצֶר הָרָע הַזֶּה זֶה נֶאֱמַר."],[10,"","וּמִשּׁוּם זֶה בְּיוֹם צָרָה, כְּשֶׁבֶּן אָדָם מִתְרַפֶּה מִן הַתּוֹרָה, כִּבְיָכוֹל דּוֹחֵק אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עִם אוֹתוֹ יֵצֶר הָרָע שֶׁהוּא נַעֲשֶׂה קָטֵגוֹר. צַר כֹּחֶכָה - צַר כֹּחַ כֹּה, מִשּׁוּם שֶׁהִתְקָרֵב לְפָנָיו לְקַטְרֵג וְנֶחֱלַשׁ הַכֹּחַ."],[11,"","בֹּא רְאֵה, טוֹב ה' לְמָעוֹז בְּיוֹם צָרָה, מַה זֶה בְּיוֹם צָרָה? זֶה יַעֲקֹב כְּשֶׁבָּא עָלָיו עֵשָׂו לְקַטְרְגוֹ. וְיוֹדֵעַ חוֹסֵי בוֹ, כְּשֶׁבָּאָה עָלָיו צָרַת דִּינָה. וּבֹא וּרְאֵה, אֵין הַמְקַטְרֵג נִמְצָא עַל הָאָדָם אֶלָּא בִּשְׁעַת סַכָּנָה."]]],[["וְתָּא חֲזֵי, בְּגִין דְּיַעֲקֹב אַחַר נִדְרֵיהּ דְּנָדִיר קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִתְתַּקַּף דִּינָא עַל יְדָא דִּמְקַטְרְגָא דְּקַטְרִיג עֲלֵיהּ דְּיַעֲקֹב, וּבָעָא דִינָא בְּשַׁעְתָּא דְסַכָּנָה דְּהֲוַת רָחֵל בָּהּ. אָמַר קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְהָא יַעֲקֹב נָדַר נִדְרֵיהּ וְלָא שָׁלִים, וְהָא אִיהוּ תַּקִּיף מִכֹּלָּא בְּעוּתְרָא וּבִבְנִין בְּכָל מַה דְּאִצְטְרִיךְ. וְלָא שָׁלִים נִדְרֵיהּ דְּנָדַר קַמָּךְ וְלָא נָסַבְתְּ עוֹנָשָׁא מִנֵּיהּ. מִיָּד וַתֵּלֶד רָחֵל וַתְּקַשׁ בְּלִדְתָּהּ. מַאי וַתְּקַשׁ. דְּאִתְקַשֵּׁי דִינָא לְעֵילָא גַּבֵּי מַלְאַךְ הַמָּוֶת.","וְאִתְעַנַּשׁ יַעֲקֹב בְּהַאי. מַאי טַעְמָא, בְּגִין דִּכְתִיב (משלי כ״ב:כ״ז) וְאִם אֵין לְךָ לְשַׁלֵּם לָמָּה יִקַּח מִשְׁכָּבְךָ מִתַּחְתֶּיךָ. וְעַל דָּא מִיתַת רָחֵל וְאִתְמָסַר דִּינָא עַל יְדָא דְּמַלְאַךְ הַמָּוֶת.","וְתָּא חֲזֵי, בְּשַׁעְתָּא דְּאֲתָא עֵשָׂו, מָה עֲבַד. וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשׁוֹנָה וְאֶת לֵאָה וִילָדֶיהָ אַחֲרוֹנִים וְאֶת רָחֵל וְאֶת יוֹסֵף אַחֲרוֹנִים. מַאי טַעְמָא, בְּגִין דְּדָחִיל עֲלָה דְרָחֵל, דְּלָא יִסְתַּכַּל הַהוּא רָשָׁע בְּשַׁפִּירוּ דִילָהּ וְלָא יְקַטְרֵג לֵיהּ עֲלָהּ.","תוּ מַה כְּתִיב, וַתִּגַּשְׁנָה הַשְׁפָחוֹת הֵנָּה וְיַלְדֵיהֶן וַתִּשְׁתַּחֲוֶיןָ וַתִּגַּשׁ גַּם לֵאָה וִילָדֶיהָ וַיִּשְׁתַּחֲווּ, נָשִׁין מִקַּמֵּי גוּבְרִין. אֲבָל בְּרָחֵל מַה כְּתִיב וְאַחַר נִגַּשׁ יוֹסֵף וְרָחֵל, וְיוֹסֵף מִקַּמֵי אִמֵּיהּ וְאִיהוּ חָפָּא עֲלָהּ, וְעַל דָּא כְּתִיב, (בראשית מ״ט:כ״ב) בֶּן פּוֹרָת יוֹסֵף בֶּן פּוֹרָת עֲלֵי עָיִן. דְּאַסְגֵי גוּפֵיהּ וְחָפָּא עַל אִמֵּיהּ. עֲלֵי עָיִן, עֲלֵי עֵינָא דְהַהוּא רָשָׁע.","וְהָכָא אִתְעֲנָשַׁת עַל יְדָא דְּיֵצֶר הָרָע דְּקִטְרֵג בְּשַׁעְתָּא דְסַכָּנָה, וְאִתְעַנַּשׁ יַעֲקֹב עַל נִדְרָא דְּלָא שָׁלִים, וְדָא קַשְׁיָא לֵיהּ לְיַעֲקֹב מִכָּל עָקוּ דַּעֲבְרוּ עֲלֵיהּ. וּמְנָלָן דִּבְגִינֵיהּ דְּיַעֲקֹב הֲוָה, דִּכְתִיב, (בראשית מ״ח:ז׳) מֵתָה עָלַי רָחֵל. עָלַי וַדַּאי, עַל דְּאֲחָרִית נִדְרִי.","רִבִּי יוֹסֵי אָמַר, כְּתִיב, (משלי כז) קִלְּלַת חִנָּם לֹא תָבֹא. וְאוּקְמוּהָ לוֹ בְּוי\"ו, דְּאִי קִלְּלַת צַדִּיקָא הִיא, אֲפִילּוּ דְּלָא אִתְכַּוַּן בָּהּ, כֵּיוָן דְּנָפְקָא מִפּוּמֵיהּ נָטַל לָהּ הַהוּא יֵצֶר הָרָע וְקִטְרֵג בָּהּ בְּשַׁעְתָּא דְסַכָּנָה.","יַעֲקֹב אָמַר, (בראשית ל״א:ל״ב) עִם אֲשֶׁר תִּמְצָא אֶת אֱלֹהֶיךָ לא יִחְיֶה. וְאַף עַל גַּב דְּאִיהוּ לָא הֲוָה יָדַע, נָטִיל לָהּ לְהַהִיא מִלָּה הַהוּא שָׂטָן דְּאִשְׁתַּכַּח גַּבַּיְיהוּ תָּדִיר בִּבְנִי נָשָׁא. וְעַל דָּא תָּנִינָן, לְעוֹלָם לֹא יִפְתַּח בַּר נָשׁ פּוּמֵיהּ לְשִׂטְנָא, בְּגִין דְּנָטִיל הַהִיא מִלָּה וְקִטְרֵג בָּהּ לְעֵילָא וְתַתָּא. כָּל שֶׁכֵּן מִלָּה דְחָכָם אוֹ מִלָּה דְצַדִּיקָא, וְעַל תְּרֵין אִלֵּין אִתְעֲנָשַׁת רָחֵל:","וַיְהִי (קנהב) בְּצֵאת נַפְשָׁהּ כִּי מֵתָה. אָמַר רִבִּי אַבָּא וְכִי כֵּיוָן דְּאָמַר וַיְהִי בְּצֵאת נַפְשָׁהּ לָא יְדַעְנָא כִּי מֵתָה. אֶלָא אִצְטְרִיךְ בְּגִין דְּלָא אַהֲדָרַת לְגוּפָא יַתִּיר, וּמִיתַת רָחֵל מִיתַת גּוּפָא, בְּגִין דְּאִית בְּנִי נָשָׁא דְּנָפְקֵי נִשְׁמָתַיְיהוּ וְאַהַדְרָן לְאַתְרַיְיהוּ וּכְּמָה דְאַתְּ אָמֵר, (שמואל א ל) וַתָּשָׁב נַפְשׁוֹ (לפנינו בקרא רוחו. ובדפוס ירושלים איתא גם בזוה\"ק ותשב רוחו אליו) אֵלָיו, (בראשית מ״ב:כ״ח) וַיֵּצֵא לִבָּם, (שיר השירים ה׳:ו׳) נַפְשִׁי יָצְאָה בְּדַבְּרוֹ. (מלכים א י״ז:י״ז) לא נוֹתְרָה בּוֹ נְשָׁמָה. אֲבָל הַאי נָפְקַת נִשְׁמָתָהּ וְלָא אִתְהַדָּרַת לְאַתְרָהּ וּמִיתַת רָחֵל.","וַתִּקְרָא שְׁמוֹ בֶּן אוֹנִי. דְּקַשְׁיוּ דְדִינָא דְּאִתְגְּזַר עֲלָהּ. וְיַעֲקֹב אַהֲדַר לֵיהּ וְקָשִׁיר לֵיהּ לְימִינָא, בְּגִין דְּמַעֲרָב אִצְטְרִיךְ לְקָשְׁרָא לֵיהּ לִימִינָא, וְאַף עַל גַּב דְּאִיהוּ בֶּן אוֹנִי סִטְרָא דְדִינָא קַשְׁיָא, בֶּן יָמִין אִיהוּ, דְּהָא בִּימִינָא אִתְקַשְּׁרַת.","וְאִתְקְבָרַת בְּאָרְחָא כְּמָה דְאִתְּמָר. הַאי אִתְגַּלְּיָא מִיתָתָהּ וּקְבוּרָתָהּ, אֲבָל לֵאָה לָא אִתְגַּלְּיָא מִיתָתָהּ וּקְבוּרָתָהּ. וְאַף עַל גַּב דְּהַנֵּי אַרְבַּע אִמָּהָן רָזָא אִית לוֹן וְהָא אוּקְמוּהָ:","וַיַּצֶּב יַעֲקֹב מַצֵּבָה עַל קְבוּרָתָהּ, אָמַר רִבִּי יוֹסֵי, מַאי טַעְמָא. בְּגִין דְּלָא אִתְכַּסְיָא אַתְרָהּ עַד יוֹמָא דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָיא מֵתַיָיא. כְּמָה דְאִתְּמָר עַד הַיּוֹם, עַד הַהוּא יוֹמָא מַמָּשׁ.","רִבִּי יְהוּדָה אָמַר, עַד יוֹמָא דְּתֵהְדַר שְׁכִינְתָּא בְּגָלוּתְהוֹן דְּיִשְׂרָאֵל בְּהַהוּא אֲתַר, כְּמָה דְאַתְּ אָמֵר, (ירמיהו ל״א:י״ז) וְיֵשׁ תִּק2וה לְאַחֲרִיתֵךְ נְאֻם יְיָ וְשָׁבוּ בָנִים לִגְבוּלָם. וְדָא אוֹמָאָה דְּאוֹמֵי לָהּ קוּדְשָׁא בְּרִיךְ הוּא. וּזְמִינִין יִשְׂרָאֵל כַּד יְתוּבוּן מִן גָּלוּתָא, לְקָיְימָא עַל הַהִיא קְבוּרָה דְרָחֵל וּלְמִבְכֵּי תַּמָּן. כְּמָה דְאִיהִי בָּכַאת עַל גָּלוּתְהוֹן דְּיִשְׂרָאֵל. וְעַל דָּא כְּתִיב, (ירמיהו ל״א:ט׳) בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם וְגו'. וּכְתִיב, (ירמיהו ל״א:ט׳) כִּי יֵשׁ שָׂכָר לִפְעוּלָתֵךְ. וּבְהַהִיא שַׁעְתָּא זְמִינַת רָחֵל דְּאִיהִי בְאָרְחָא לְמֶחֱדֵי בְּהוּ בְּיִשְׂרָאֵל וְעִם שְׁכִינְתָּא וְאוּקְמוּהָ חַבְרַיָּיא:"],[[0,"ותא חזי לית מקטרגא וכו':","ובוא וראה, אין המקטרג על האדם נמצא, אלא בשעת סכנה. ובוא וראה, משום שיעקב איחר לשלם את נדרו שנדר לפני הקב\"ה, נתגבר הדין על יעקב, על ידי המקטרג, שתבע עליו דין בשעת הסכנה, שרחל היתה בה. אמר לפני הקב\"ה, והרי יעקב נדר נדר ולא שלם, והרי הוא גדול מכל בעושר ובבנים ובכל מה שצריך, ולא שלם הנדר שנדר לפניך, ולא קבלת עונש ממנו. מיד \u0003ותלד רחל ותקש בלדתה,\u0004 כי נתקשה עליו הדין למעלה, אצל מלאך המות."],[1,"ואתענש יעקב בהאי וכו':","שואל, ונענש יעקב בזה, מהו הטעם. ואומר, משום שכתוב, ואם אין לך לשלם למה יקח משכבך מתחתיך. ועל כל מתה רחל, ונעשה הדין על ידי מלאך המות."],[2,"ותא חזי בשעתא וכו':","ובוא וראה, בשעה שבא עשו, מה עשה יעקב, וישם את השפחות ואת ילדיהן וגו', מהו הטעם, הוא, משום, שהיה מפחד על רחל, שלא יסתכל אותו רשע ביפיה, ולא יצר אותו עליה."],[3,"תו מה כתיב וכו':","עוד, מה כתוב, ותגשן השפחות הנה וילדיהן וגו', שהנשים היו לפני האנשים, אבל ברחל מה כתוב, ואחר נגש יוסף ורחל, שיוסף היה לפני אמו, והוא חפה והסתיר אותה. ועל כן כתוב בן פורת יוסף וגו', שהגדיל גופו וחפה על אמו. \u0003עלי עין,\u0004 על עינו של אותו רשע, שלא יסתכל בה."],[4,"והכא אתענשת וכו':","וכאן נענשה רחל על ידי היצר הרע שקטרג בשעת הסכנה, ונענש יעקב על נדרו שלא שלם. וזה היה קשה לו ליעקב יותר מכל הצרות שעברו עליו. ומאין לנו שבשביל יעקב היתה מיתת רחל, כי כתוב, מתה \u0003עלי\u0004 רחל, \u0003עלי\u0004 ודאי היה הדבר, משום שאחרתי לשלם את נדרי."],[5,"ר' יוסי אמר כתיב וכו':","רי\"א, כתוב, קללת חנם \u0003לא\u0004 תבא, ובארוהו, \u0003לו\u0004 עם \u0003ו'.\u0004 דהיינו כמו שהיה כתוב, קללת חנם לו תבא, להורות, שאם קללת צדיק הוא, אפילו שלא נתכוון כלל לקלל, כיון שיצאה הקללה מפיו מקבל אותה היצר הרע, ומקטרג עמה בשעת הסכנה."],[6,"יעקב אמר וכו':","יעקב אמר, עם אשר תמצא את אלהיך לא יחיה. ואע\"פ שהוא לא ידע שרחל גנבתם, קבל הדבר אותו השטן הנמצא תמיד אצל בני אדם, ובשעת הסכנה קטרג עליו כנ\"ל. וע\"כ למדנו, לעולם לא יפתח אדם פה לשטן, משום שלוקח אותה המלה ומקטרג עמה למעלה ולמטה, וכל שכן אם המלה יצאה מפה של חכם או צדיק. ועל שנים אלו נענשה רחל: א) משום שאחר לשלם את נדרו. ב) משום הקללה שהוציא מפיו."],[7,"ויהי בצאת נפשה כי מתה:","אמר ר' אבא, וכי כיון שאמר, ויהי בצאת נפשה, איני יודע שמתה, ולמה נאמר כי מתה. ומשיב, אלא שנצרך לומר כי מתה, להורות שהנפש לא חזרה יותר אל הגוף, ומתה רחל מיתת הגוף. כי יציאת הנפש, אינה מורה עדיין על מיתת הגוף, משום שיש בני אדם, שיצאה נשמתם וחזרה אח\"כ למקומה, וכש\"א, ותשב נפשו אליו. ויצא לבם. נפשי יצאה בדברו. לא נותרה בו נשמה. אבל זו, רחל, יצאה נשמתה ולא חזרה למקומה, ומתה רחל."],[8,"ותקרא שמו בן אוני:","על שם קשי הדין שנגזר עליה. ויעקב חזר וקשר אותו בימין דהיינו בחסדים, משום שצריכים לקשור את המערב שהוא הנוקבא, בימין, ואע\"פ שהוא בן אוני של הנוקבא, שהוא צד הדין הקשה שבה, מ\"מ בן ימין הוא, כי הנוקבא נקשרה בימין. וע\"כ קרא אותו בנימין, דהיינו בן ימין, כי קשר את רחל בימין שהוא חסדים."],[9,"ואתקברת באורחא וכו':","והיא נקברה בדרך, כמו שבארוהו (לעיל ויצא דף צ\"ט אות רמ\"ג) כי זו, רחל, נתגלו מיתתה וקבורתה כי נקברה בדרך שהוא מקום גלוי, אבל לאה לא נתגלו מיתתה וקבורתה. ואע\"פ שארבע האמהות, יש להן סוד, וכבר בארוהו."],[10,"ויצב יעקב מצבה על קבורתה","וגו' \u0003עד היום:\u0004 אמר ר' יוסי, מה הטעם שאומר הכתוב עד היום, ואומר שהוא משום שלא נתכסה מקום קבורתה עד אותו \u0003היום\u0004 שעתיד הקב\"ה להחיות המתים. כמו שנאמר, \u0003עד היום,\u0004 עד אותו היום ממש, דהיינו יום תחיית המתים."],[11,"רבי יהודה אמר וכו':","רי\"א, עד היום, מורה, עד היום שתחזיר השכינה מגלות את ישראל במקום ההוא של קבורת רחל, כמש\"א, ויש תקוה לאחריתך וגו', והיא שבועה שנשבע לה הקב\"ה לשכינה. ועתידים ישראל, בעת שיחזרו מן הגלות, לעמוד על קבורת רחל ולבכות שם, כמו שהיא בכתה על גלות ישראל. ועל זה כתוב, בבכי יבואו ובתחנונים אובילם וגו', וכתוב, כי יש שכר לפעולתך. ובאותה שעה עתידה רחל, שהיא בדרך, לשמוח עם ישראל ועם השכינה. ובארוהו החברים."]],[[0,"","וּבֹא וּרְאֵה, מִשּׁוּם שֶׁיַּעֲקֹב אֵחַר נִדְרוֹ שֶׁנָּדַר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הִתְחַזֵּק הַדִּין עַל יְדֵי הַמְקַטְרֵג שֶׁקִּטְרֵג עַל יַעֲקֹב, וְרָצָה דִּין בִּשְׁעַת הַסַּכָּנָה שֶׁהָיְתָה בָּהּ בְּרָחֵל. אָמַר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי יַעֲקֹב נָדַר נִדְרוֹ וְלֹא שִׁלֵּם, וַהֲרֵיהוּ חָזָק מֵהַכֹּל בְּעֹשֶׁר וּבְבָנִים וּבְכָל מַה שֶּׁצָּרִיךְ, וְלֹא שִׁלֵּם נִדְרוֹ שֶׁנָּדַר לְפָנֶיךְ, וְלֹא לָקַחְתָּ מִמֶּנּוּ עֹנֶשׁ. מִיָּד? - וַתֵּלֶד רָחֵל וַתְּקַשׁ בְּלִדְתּהּ. מַה זֶּה וַתְּקַשׁ? שֶׁהִתְקַשָּׁה הַדִּין לְמַעְלָה אֵצֶל מַלְאָךְ הַמָּוֶת."],[1,"","וְנֶעֱנַשׁ יַעֲקֹב בָּזֶה, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (משלי כב) וְאִם אֵין לְךְ לְשַׁלֵּם לָמָּה יִקַּח מִשְׁכָּבְךְ מִתַּחְתֶּיךְ, וְעַל זֶה מֵתָה רָחֵל וְנִמְסַר הַדִּין עַל יְדֵי מַלְאַךְ הַמָּוֶת."],[2,"","וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁבָּא עֵשָׂו, מֶה עָשָׂה? וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשֹׁנָה וְאֶת לֵאָה וִילָדֶיהָ אַחֲרֹנִים וְאֶת רָחֵל וְאֶת יוֹסֵף אַחֲרֹנִים. מָה הַטַּעַם? מִשּׁוּם שֶׁפָּחַד עַל רָחֵל שֶׁלֹּא יִסְתַּכֵּל אוֹתוֹ רָשָׁע בְּיָפְיָהּ וְלֹא יְקַטְרֵג לוֹ עָלֶיהָ."],[3,"","עוֹד מַה כָּתוּב? וַתִּגַּשְׁנָה הַשְּׁפָחוֹת הֵנָּה וְיַלְדֵיהֶן וַתִּשְׁתַּחֲוֶיןָ וַתִּגַּשׁ גַּם לֵאָה וִילָדֶיהָ וַיִּשְׁתַּחֲווּ. נָשִׁים מִלִּפְנֵי גְבָרִים. אֲבָל בְּרָחֵל מַה כָּתוּב? וְאַחַר נִגַּשׁ יוֹסֵף וְרָחֵל, יוֹסֵף מִלִּפְנֵי אִמּוֹ, וְהוּא כִסָּה עָלֶיהָ, וְעַל זֶה כָּתוּב (בראשית מט) בֵּן פֹּרָת יוֹסֵף בֵּן פֹּרָת עֲלֵי עָיִן, שֶׁהִגְדִּיל גּוּפוֹ וְכִסָּה עַל אִמּוֹ. עֲלֵי עָיִן - עֲלֵי עַיִן שֶׁל אוֹתוֹ רָשָׁע."],[4,"","וְכָאן נֶעֶנְשָׁה עַל יְדֵי הַיֵּצֶר הָרָע שֶׁקִּטְרֵג בִּשְׁעַת הַסַּכָּנָה, וְנֶעֱנַשׁ יַעֲקֹב עַל נֶדֶר שֶׁלֹּא שִׁלֵּם, וְזֶה קָשֶׁה לְיַעֲקֹב מִכָּל הַצָּרוֹת שֶׁעָבְרוּ עָלָיו. וּמִנַּיִן לָנוּ שֶׁמִּשּׁוּם יַעֲקֹב זֶה הָיָה? שֶׁכָּתוּב (שם מח) מֵתָה עָלַי רָחֵל, עָלַי וַדַּאי, עַל שֶׁאֵחַרְתִּי נִדְרִי."],[5,"","רַבִּי יוֹסֵי אָמַר, כָּתוּב (משלי כז) קִלְלַת חִנָּם לֹא תָבֹא, וּבֵאֲרוּהוּ לוֹ בְּוָא\"ו. שֶׁאִם קִלְלַת צַדִּיק הִיא, אֲפִלּוּ שֶׁלֹּא הִתְכַּוֵּן בָּהּ, כֵּיוָן שֶׁיָּצְאָה מִפִּיו נָטַל אוֹתָהּ אוֹתוֹ יֵצֶר הָרָע וְקִטְרֵג בָּהּ בִּשְׁעַת הַסַּכָּנָה."],[6,"","יַעָקֹב אָמַר (בראשית לא) עִם אֲשֶׁר תִּמְצָא אֶת אֱלֹהֶיךְ לֹא יִחְיֶה. וְאַף עַל גַּב שֶׁהוּא לֹא הָיָה יוֹדֵעַ, נָטַל אוֹתוֹ דָבָר אוֹתוֹ שָׂטָן שֶׁנִּמְצָא תָמִיד אֵצֶל בְּנֵי אָדָם. וְעַל זֶה שָׁנִינוּ, לְעוֹלָם לֹא יִפְתַּח אָדָם פִּיו לַשָּׂטָן, מִשּׁוּם שֶׁנּוֹטֵל אוֹתוֹ הַדִּבּוּר וּמְקַטְרֵג בּוֹ לְמַעְלָה וּלְמַטָּה, כָּל שֶׁכֵּן מִלָּה שֶׁל חָכָם אוֹ מִלָּה שֶׁל צַדִּיק, וְעַל שְׁנֵי אֵלֶּה נֶעֶנְשָׁה רָחֵל."],[7,"","וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה. אָמַר רַבִּי אַבָּא, וְכִי כֵּיוָן שֶׁאָמַר וַיְהִי בְּצֵאת נַפְשָׁהּ לֹא יָדַעְנוּ כִּי מֵתָה? אֶלָּא צָרִיךְ מִשּׁוּם שֶׁלֹּא חָזְרָה לְגוּפָהּ יוֹתֵר, וּמֵתָה רָחֵל מִיתַת הַגּוּף, מִשּׁוּם שֶׁיֵּשׁ בְּנֵי אָדָם שֶׁנִּשְׁמָתָם יוֹצֵאת וְחוֹזֶרֶת לִמְקוֹמָהּ, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ל) וַתָּשָׁב רוּחוֹ (נפשו) אֵלָיו, (בראשית מב) וַיֵּצֵא לִבָּם, (שיר ה) נַפְשִׁי יָצְאָה בְּדַבְּרוֹ, (מלכים א יז) לֹא נוֹתְרָה בּוֹ נְשָׁמָה. אֲבָל זוֹ יָצְאָה נִשְׁמָתָהּ וְלֹא חָזְרָה לִמְקוֹמָהּ וּמֵתָה רָחֵל."],[8,"","וַתִּקְרָא שְׁמוֹ בֶּן אוֹנִי, הַקַּשְׁיוּת שֶׁל הַדִּין שֶׁנִּגְזַר עָלֶיהָ. וְיַעֲקֹב הֶחֱזִיר אוֹתוֹ וְקָשַׁר אוֹתוֹ לְיָמִין, מִשּׁוּם שֶׁאֶת הַמַּעֲרָב צָרִיךְ לְקָשְׁרוֹ לְיָמִין. וְאַף עַל גַּב שֶׁהוּא בֶּן אוֹנִי, צַד שֶׁל הַדִּין הַקָּשֶׁה - בֵּן יָמִין הוּא, שֶׁהֲרֵי בְּיָמִין הִתְקַשְּׁרָה,"],[9,"","וְנִקְבְּרָה בַּדֶּרֶךְ כְּמוֹ שֶׁנִּתְבָּאֵר, הֲרֵי הִתְגַּלְּתָה מִיתָתָהּ וּקְבוּרָתָהּ, אֲבָל לֵאָה לֹא הִתְגַּלְּתָה מִיתָתָהּ וּקְבוּרָתָהּ, וְאַף עַל גַּב שֶׁאַרְבַּע הָאִמָּהוֹת הַלָּלוּ סוֹד יֵשׁ לָהֶם, וּבֵאֲרוּהוּ."],[10,"","וַיַּצֶב יַעֲקֹב מַצֵּבָה עַל קְבוּרָתָהּ. אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא הִתְכַּסָּה מְקוֹמָהּ עַד הַיּוֹם שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת מֵתִים, כְּמוֹ שֶׁנֶּאֱמַר עַד הַיּוֹם, עַד אוֹתוֹ יוֹם מַמָּשׁ."],[11,"","רַבִּי יְהוּדָה אָמַר, עַד יוֹם שֶׁתַּחֲזֹר שְׁכִינָה מִגָּלוּת יִשְׂרָאֵל בְּאוֹתוֹ מָקוֹם, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) וְיֵשׁ תִּקְוָה לְאַחֲרִיתֵךְ נְאֻם ה' וְשָׁבוּ בָנִים לִגְבוּלָם. וְזוֹ שְׁבוּעָה שֶׁנִּשְׁבַּע לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, וַעֲתִידִים יִשְׂרָאֵל כְּשֶׁיָּשׁוּבוּ מֵהַגָּלוּת לַעֲמֹד עַל אוֹתָהּ קְבוּרַת רָחֵל וְלִבְכּוֹת שָׁם, כְּמוֹ שֶׁהִיא בָּכְתָה עַל גָּלוּת יִשְׂרָאֵל, וְעַל זֶה כָּתוּב (שם) בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם וְגוֹ', וְכָתוּב (שם) כִּי יֵשׁ שָׂכָר לִפְעֻלָּתֵךְ. וּבְאוֹתָהּ שָׁעָה עֲתִידָה רָחֵל, שֶׁהִיא בַּדֶּרֶךְ, לִשְׂמֹחַ בְּיִשְׂרָאֵל וְעִם הַשְּׁכִינָה, וּבֵאֲרוּהוּ הַחֲבֵרִים."]]],[["וַיְהִי בִּשְׁכֹּן יִשְׂרָאֵל בָּאָרֶץ הַהִיא וַיֵּלֶךְ רְאוּבֵן וַיִּשְׁכַּב אֶת בִּלְהָה פִּלֶּגֶשׁ אָבִיו וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְּנֵי יַעֲקֹב שְׁנֵים עָשָׂר. רִבִּי אֶלְעָזָר אָמַר, וַיְהִי בִּשְׁכֹּן יִשְׂרָאֵל בָּאָרֶץ הַהִיא, דְּהָא לֵאָה וְרָחֵל מִיתוּ, וְנָטְלָא בֵּיתָא מַאן דְּנָטִיל.","וְכִי סַלְקָא דַעְתָּךְ דִּרְאוּבֵן אָזִיל וְשָׁכִיב בַּהֲדָהּ דְּבִלְהָה. אֶלָּא, כָּל יוֹמָא דְּלֵאָה וְרָחֵל שְׁכִינְתָּא שַׁרְיָיא עֲלַיְיהוּ. וְהַשְׁתָּא דְמִיתוּ, שְׁכִינְתָּא לָא אִתְפְּרָשַׁת מִן בֵּיתָא, וְשַׁרְיָא בְּבֵיתָא בְּמִשְׁכְּנָא דְבִלְהָה. וְאַף עַל גַּב דִּשְׁכִינְתָא בַּעְיָא לְנַטְלָא בֵּיתָא כְּדְקָא יָאוֹת, אִלְמָלֵא יַעֲקֹב לָא אִשְׁתַּכַּח בְּזִוּוּגָא דְּכַר וְנוּקְבָא, לָא שַׁרְיָא שְׁכִינְתָּא בְּאִתְגַּלְּיָא בְּבֵיתָא. וְעַל דָּא קָיְימָא שְׁכִינְתָּא בְּמַשְׁכְּנָא דְבִלְהָה. וְאָתָא רְאוּבֵן וּבְגִין דְּחָמָא דְבִלְהָה יָרְתָא אַתְרָא דְאִמֵּיהּ, אֲזַל וּבִלְבֵּל עַרְסָא. וְעַל דְּקָיְימָא שְׁכִינְתָּא עֲלָהּ, כְּתִיב בֵּיהּ וַיִּשְׁכַּב אֶת בִּלְהָה.","רַבִּי יֵיסָא אָמַר, דְּנָאִים עַל הַהוּא עַרְסָא וְלָא חַיִּישׁ לִיקָרָא דִשְׁכִינְתָּא. וּבְגִין כָּךְ לָא אִתְפְּגִים מֵחוּשְׁבָּנָא דְשִׁבְטִין וְאָתָא קְרָא וְעֲבִיד חוּשְׁבְּנָא. בְּגִין כָּךְ כְּתִיב, בְּכוֹר יַעֲקֹב רְאוּבֵן. וְאִיהוּ עָבִיד קְרָא רֵישָׁא דְּכָל שִׁבְטִין.","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְגו', כָּל אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא כֻּלְּהוּ יְשָׁרִים וְאָרְחוֹי קְשׁוֹט, וּבְנִי עַלְמָא לָא יָדְעִין וְלָא מַשְׁגִּיחִין עַל מַה אִינוּן קָיְימִין. וְעַל דָּא וְצַדִּיקִים יֵלְכוּ בָם, בְּגִין דְּאִינוּן יָדְעִין אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא וּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, אִיהוּ יָדַע וְאָזִיל בְּהוּ דְּלָא סָטֵי לִימִינָא וְלִשְׂמָאלָא.","וּפוֹשְׁעִים יִכָּשְׁלוּ בָם, אִלֵּין אִינוּן חַיָּיבִין דְּלָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְלָא מִסְתַּכְּלָן בְּאָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא וְלָא יָדְעִין לְאָן אוֹרְחֵי אָזְלִין. וּבְגִין דְּלָא יָדְעֵי לְאִסְתַּכְּלָא וְלא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, אִינוּן כָּשְׁלֵי בְּהוּ בְּאִינוּן אָרְחוֹי בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי.","תָּא חֲזֵי, כָּל בַּר נָשׁ דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, כַּד נָפִיק מֵהַאי עַלְמָא נִשְׁמָתֵיהּ סָלְקָא בְּאִינוּן אָרְחִין וּשְׁבִילִין (דאינון באורייתא) דְּאוֹרַיְיתָא. וְאִינוּן אָרְחִין וּשְׁבִילִין דְּאוֹרַיְיתָא יְדִיעָן אִינוּן, וְאִינוּן דְּיָדְעֵי אָרְחוֹי דְאוֹרַיְיתָא בְּהַאי עַלְמָא יַהֲכוּן בְּהוּ בְּהַהוּא עַלְמָא כַּד יִפְקוּן מֵהַאי עַלְמָא.","וְאִי לָא אִשְׁתַּדָּלוּ בְּאוֹרַיְיתָא בְּהַאי עַלְמָא וְלָא יָדְעִין אָרְחִין וּשְׁבִילִין, כַּד יִפְקוּן מֵהַאי עַלְמָא לָא יִנְדְּעוּן לְמֵיהַךְ בְּאִינוּן אָרְחִין וּשְׁבִילִין וְכָשְׁלִין בְּהוֹן. כְּדֵין יְהַךְ בְּאָרְחִין אָחֳרָנִין דְּלָאו אִינוּן אָרְחִין דְּאוֹרַיְיתָא, וְיִתְעָרוּן לֵיהּ בְּכַמָּה דִינִין וְאִתְעַנַּשׁ בְּהוּ.","וּמַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא מַה כְּתִיב, (משלי ו׳:כ״ב) בְּשָׁכְבְּךָ תִּשְׁמֹר עָלֶיךָ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ. בְּשָׁכְבְּךָ בְּקִבְרָא, אוֹרַיְיתָא תִּצּוֹר עָלֶיךָ מִדִּינָא דְּהַהוּא עָלְמָא. וְהֱקִיצוֹתָ, כַּד קוּדְשָׁא בְּרִיךְ הוּא יִתְעַר רוּחִין וְנִשְׁמָתִין לְאַחַיָּיא מֵתַיָיא כְּדֵין הִיא תְּשִׂיחֶךָ, הִיא תְּהֵא סַנֵּיגוֹרְיָא עַל גּוּפָא, בְּגִין דִּיקוּמוּן אִינוּן גּוּפִין דְּאִשְׁתַּדְּלוּ בְאוֹרַיְיתָא כִּדְּקָא יָאוֹת. וְאִלֵּין אִינוּן דִּיקוּמוּן בְּקַדְמִיתָא לְחַיֵּי עָלְמָא, כְּמָה דְאַתְּ אָמֵר, (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנִי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְגו'. וְאִלֵּין אִינוּן לְחַיֵּי עוֹלָם, בְּגִין דְּאִתְעַסְּקוּ בְּחַיֵּי עוֹלָם דְּאִיהִי אוֹרַיְיתָא.","וְתָּא חֲזֵי, כָּל אִינוּן דְּאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא, הַהוּא גּוּפָא יִתְקַיַּים וְאוֹרַיְיתָא תָּגִין עֲלֵיהּ. מַאי טַעְמָא, בְּגִין דִּבְהַהִיא שַׁעְתָּא יִתְעַר קוּדְשָׁא בְּרִיךְ הוּא חַד רוּחָא דְּכָלִיל מֵאַרְבַּע רוּחִין, וְהַהוּא רוּחָא דְּכָלִיל מֵאַרְבַּע רוּחִין, אִזְדַּמַּן לְכָל אִינוּן דְּאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא לַאֲחָיָיא לוֹן בְּהַאי רוּחָא בְּגִין דְּיִתְקַיַים לְעָלְמִין.","וְאִי תֵימָא, הָא כְּתִיב (יחזקאל ל״ז:ט׳) מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, אַמַּאי לָא אִתְקַיְימוּ, דְּהָא כֻּלְּהוּ מִיתוּ כְּמִלְּקַדְמִין. תָּא חֲזֵי, הַהוּא זִמְנָא דְּאוֹקִים קוּדְשָׁא בְּרִיךְ הוּא עַל יְדָא דִיחֶזְקֵאל אִינוּן מֵתַיָיא, הַהוּא (זמני דאתא) רוּחָא אַף עַל גַּב דְּהֲוָה מֵאַרְבַּע רוּחַיָּיא, לָא נָחִית לְקָיְימָא לוֹן בְּקִיּוּמָא, אֶלָּא לְאַחֲזָאָה דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָיא מֵתַיָיא בְּהַהוּא גַוְונָא וּלְקַיְימָא לוֹן בְּרוּחָא דְּאִתְכְּלִיל בְּהַאי גַוְונָא. וְאַף עַל גַּב דְּאַהֲדָרוּ גַּרְמִין בְּהַהִיא שַׁעְתָּא כְּמָה דְהֲוָה. קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאַחֲזָאָה לְכָל עַלְמָא דְּאִיהוּ זַמִּין לַאֲחָיָיא מֵתַיָיא (מה כתיב, (ישעיהו כ״ו:י״ט) יחיו מתיך נבלתי יקומון. על דא ההוא רוחא דזמין לנחתא בהו בצדיקיא) (נ\"א ועל דא ההוא רוחא דזמין לנחתא בהו בצדיקיא. מה כתיב מארבע רוחות באי הרוח, רוחא דאתכלילת בארבע), בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְקַיְימָא לְהוּ קִיּוּמָא שְׁלִים בְּעַלְמָא כְּדְקָא יְאוּת. וְאִינוּן דְּאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא בְּהַאי עַלְמָא, הִיא קָיְימָא עֲלֵיהּ דְּבַר נָשׁ וְאִתְעֲבִידַת סַנִּיגוֹרְיָא קַמֵּי דְקוּדְשָׁא בְּרִיךְ הוּא."],[[0,"ויהי בשכון ישראל בארץ וגו':","ר' אלעזר אמר, ויהי בשכון ישראל בארץ ההיא היינו השכינה הנקראת ארץ, כי לאה ורחל מתו, וקבל הבית מי שקיבל, דהיינו השכינה (כנ\"ל דף נ\"ג אות קע\"ג ע\"ש)."],[1,"וכי סלקא דעתך וכו':","ושואל, הכי יעלה על דעתך, שראובן הלך ושכב עם בלהה. ומשיב, אלא כל זמן שלאה ורחל היו חיות, השכינה שרתה עליהם, ועתה שמתו, לא נפרדה השכינה מן הבית, ושרתה בבית משכנה של בלהה. ושואל, ואע\"פ שהשכינה היתה צריכה לקבל הבית דהיינו להתחבר עם יעקב כראוי, אחר מיתת רחל כנ\"ל, ואיך נאמר שהשכינה שרתה במשכנה של בלהה. ומשיב, אם לא היה יעקב בזווג דכר ונוקבא, לא היתה השכינה שורה בגלוי בבית, ולפיכך עמדה השכינה במשכנה של בלהה שהיה שם בזווג דכר ונוקבא."],[2,"ואתא ראובן וכו':","ובא ראובן, ואחר שראה שבלהה ירשה מקום אמו, הלך ובלבל המטה, שלקח מטתו של יעקב משם, ומשום שהשכינה היתה עליה, כתוב בו, וישכב את בלהה, ר' ייסא אמר, שישן על אותה המטה, ולא חרד לכבוד השכינה. וע\"כ מעלה עליו הכתוב כאילו שכב עמה. ומשום זה שלא חטא, לא נגרע ראובן מחשבון י\"ב השבטים, וע\"כ מיד בא הכתוב ועשה חשבון, שאמר ויהיו בני יעקב שנים עשר. ומשום זה כתוב מיד, בכור יעקב ראובן, שעשהו הכתוב ראש לכל השבטים."],[3,"ר' יהודה פתח וכו':","ר\"י פתח ואמר, כי ישרים דרכי ה' וגו', כל דרכיו של הקב\"ה כולם ישרים, ודרכיו אמת, ובני העולם אינם יודעים ואינם משגיחים על מה הם עומדים. ועל כן צדיקים ילכו בם, משום שיודעים דרכיו של הקב\"ה ועוסקים בתורה, שכל מי שעוסק בתורה, הוא יודע והולך בהם בדרכי התורה, ואינו סר לימין ולשמאל."],[4,"ופושעים יכשלו בם:","אלו הם הרשעים שאינם עוסקים בתורה ואינם מסתכלים בדרכיו של הקב\"ה, ואינם יודעים לאן הדרכים הולכים. ומשום שאינם יודעים להסתכל, ואינם עוסקים בתורה, הם נכשלים בהם, בדרכי התורה, בעולם הזה ובעולם הבא."],[5,"ת\"ח כל בר נש וכו':","בוא וראה, כל אדם העוסק בתורה, כשנפטר מן העולם הזה, נשמתו עולה באורחות ושבילים של התורה. ואלו האורחות והשבילים של התורה הם ידועים, ואותם היודעים דרכי התורה בעולם הזה, הולכים בהם בעולם ההוא אחר שיפטרו מהעולם הזה."],[6,"ואי לא אשתדלו וכו':","ואם אינם עוסקים בתורה בעולם הזה, ואינם יודעים האורחות והשבילים של התורה, כשיצאו מהעולם הזה, לא ידעו ללכת באלו האורחות והשבילים והם נכשלים בהם, ואז ילך בדרכים אחרים שאינם דרכי התורה ויתעוררו עליו הרבה דינים, והוא נענש בהם."],[7,"ומאן דאשתדל וכו':","ומי שעוסק בתורה מה כתוב, בשכבך תשמור עליך והקיצות היא תשיחך, \u0003בשכבך,\u0004 בקבר, התורה תשמור עליך מן הדין של העולם ההוא. \u0003והקיצות,\u0004 כאשר הקב\"ה יעורר רוחות ונשמות להחיות המתים, אז, \u0003היא תשיחך,\u0004 היא תהיה מליצה טובה על הגוף, כדי שאלו הגופים שעסקו בתורה יקומו כראוי. ואלו הם שיקומו מתחילה לחיי עולם, (כמ\"ש לעיל חיי שרה דף נ\"ג אות קע\"ב ע\"ש) כמו שאתה אומר, ורבים מישני אדמת עפר יקיצו אלה לחיי עולם וגו'. ואלו הם לחיי עולם, משום שעסקו בחיי עולם, שהוא התורה."],[8,"ותא חזי כל וכו':","ובוא וראה, כל אלו שעסקו בתורה, הגוף שלהם יתקיים והתורה תגן עליו. מהו הטעם, הוא משום שבאותה שעה, יעורר הקב\"ה רוח אחד שכלול מארבעה רוחות שהם חו\"ב תו\"מ ואותו הרוח הכלול מארבעה רוחות מזדמן לכל אלו שעסקו בתורה להחיותם ברוח הזה, כדי שיתקיימו לעולם."],[9,"ואי תימא וכו':","ואם תאמר, הרי כתוב במתים שהחיה יחזקאל, מארבע רוחות באי הרוח, למה לא נתקיימו, והרי כולם מתו כבתחילה ולא הועיל להם הרוח הזה הכלול מד' הרוחות שיתקיימו לעולם, ומשיב, בוא וראה, באותה שעה שהחיה הקב\"ה המתים על ידי יחזקאל, אותו הרוח, אע\"פ שהיה כלול מארבע רוחות, מלכתחילה לא ירד להחיותם שיתקיימו לעולם, אלא להראות שעתיד הקב\"ה להחיות מתים באותו הדרך, ולהחיותם ברוח הנכלל באופן הזה, דהיינו מד' רוחות, ואע\"פ שהעצמות חזרו בשעה ההיא למה שהיו, הקב\"ה רצה רק להראות לכל העולם שהוא עתיד להחיות המתים, אשר עתיד הקב\"ה להחיותם אז בקיום שלם בעולם, כראוי. ואלו העוסקים בתורה בעולם הזה, התורה עומדת להם אז, ונעשית מליצה טובה לפני הקב\"ה."]],[[0,"","וַיְהִי בִּשְׁכֹּן יִשְׂרָאֵל בָּאָרֶץ הַהִיא וַיֵּלֶךְ רְאוּבֵן וַיִּשְׁכַּב אֶת בִּלְהָה פִּילֶגֶשׁ אָבִיו וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְנֵי יַעֲקֹב שְׁנֵים עָשָׂר. רַבִּי אֶלְעָזָר אָמַר, וַיְהִי בִּשְׁכֹּן יִשְׂרָאֵל בָּאָרֶץ הַהִיא, שֶׁהֲרֵי לֵאָה וְרָחֵל מֵתוּ, וְנָטְלָה הַבַּיִת מִי שֶׁנָּטְלָה."],[1,"","וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁרְאוּבֵן הָלַךְ וְשָׁכַב עִם בִּלְהָה? אֶלָּא בְּכָל זְמַנָּן שֶׁל לֵאָה וְרָחֵל, שְׁכִינָה שָׁרְתָה עֲלֵיהֶן, וְעַכְשָׁו שֶׁמֵּתוּ, שְׁכִינָה לֹא נִפְרְדָה מֵהַבַּיִת, וְשׁוֹרָה בַּבַּיִת בַּמִּשְׁכָּן שֶׁל בִּלְהָה. וְאַף עַל גַב שֶׁשְּׁכִינָה רָצְתָה לִטֹּל הַבַּיִת כָּרָאוּי, אִלְמָלֵא יַעֲקֹב לֹא נִמְצָא בְּזִוּוּג זָכָר וּנְקֵבָה, לֹא שׁוֹרָה שְׁכִינָה בְּגִלּוּי בַּבַּיִת, וְעַל זֶה עָמְדָה שְׁכִינָה בְּמִשְׁכַּן בִּלְהָה. וּבָא רְאוּבֵן, מִשּׁוּם שֶׁרָאָה שֶׁבִּלְהָה יָרְשָׁה מְקוֹם אִמּוֹ, הָלַךְ וּבִלְבֵּל הַמִּטָּה, וְעַל שֶׁעָמְדָה שְׁכִינָה עָלֶיהָ כָּתוּב בּוֹ וַיִּשְׁכַּב אֶת בִּלְהָה."],[2,"","רַבִּי יֵיסָא אָמַר, שֶׁיָּשַׁן עַל אוֹתָהּ מִטָּה וְלֹא חָשַׁשׁ לִכְבוֹד הַשְּׁכִינָה, וּמִשּׁוּם כָּךְ לֹא נִפְגַּם מֵחֶשְׁבּוֹן הַשְּׁבָטִים, וּבָא הַפָּסוּק וְעָשָׂה חֶשְׁבּוֹן, מִשּׁוּם כָּךְ כָּתוּב בְּכוֹר יַעֲקֹב רְאוּבֵן, וְהַפָּסוּק עָשָׂה אוֹתוֹ רֹאשׁ לְכָל הַשְּׁבָטִים."],[3,"","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ' - כָּל דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כֻּלָּם יְשָׁרִים וְדַרְכֵי אֱמֶת, וּבְנֵי הָעוֹלָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים עַל מָה הֵם עוֹמְדִים. וְעַל זֶה וְצַדִּיקִים יֵלְכוּ בָם - מִשּׁוּם שֶׁהֵם יוֹדְעִים דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, הוּא יוֹדֵעַ וְהוֹלֵךְ בָּהֶם שֶׁלֹּא סוֹטֶה יָמִינָה וּשְׂמֹאלָה."],[4,"","וּפֹשְׁעִים יִכָּשְׁלוּ בָם - אֵלֶּה הֵם הָרְשָׁעִים שֶׁלֹּא מִשְׁתַּדְּלִים בַּתּוֹרָה וְלֹא מִסְתַּכְּלִים בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא יוֹדְעִים לְאָן הַדְּרָכִים הוֹלְכוֹת, וּמִשּׁוּם שֶׁלֹּא יוֹדְעִים לְהִסְתַּכֵּל וְלֹא מִשְׁתַּדְּלִים בַּתּוֹרָה, הֵם נִכְשָׁלִים בָּהֶם בְּאוֹתָם דְּרָכָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[5,"","בֹּא רְאֵה, כָּל אָדָם שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, נִשְׁמָתוֹ עוֹלָה בְּאוֹתָם דְּרָכִים וּשְׁבִילִים (שהם בתורה) שֶׁל הַתּוֹרָה, וְאוֹתָם דְּרָכִים וּשְׁבִילִים שֶׁל הַתּוֹרָה הֵם יְדוּעִים, וְאוֹתָם שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה בָּעוֹלָם הַזֶּה יֵלְכוּ בָהֶם בְּאוֹתוֹ עוֹלָם, כְּשֶׁיֵּצְאוּ מִן הָעוֹלָם הַזֶּה."],[6,"","וְאִם לֹא הִשְׁתַּדְּלוּ בַּתּוֹרָה בָּעוֹלָם הַזֶּה וְלֹא יוֹדְעִים דְּרָכִים וּשְׁבִילִים, כְּשֶׁיֵּצְאוּ מִן הָעוֹלָם הַזֶּה לֹא יֵדְעוּ לָלֶכֶת בְּאוֹתָם דְּרָכִים וּשְׁבִילִים, וְנִכְשָׁלִים בָּהֶם. וְאָז יֵלֵךְ בִּדְרָכִים אֲחֵרוֹת שֶׁאֵינָן דַּרְכֵי הַתּוֹרָה, וְיִתְעוֹרְרוּ אֵלָיו בְּכַמָּה דִינִים וְיֵעָנֵשׁ בָּהֶם."],[7,"","וּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה מַה כָּתוּב? (משלי ו) בְּשָׁכְבְּךְ תִּשְׁמֹר עָלֶיךְ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ. בְּשָׁכְבְּךְ - בַּקֶּבֶר, הַתּוֹרָה תִּשְׁמֹר עָלֶיךְ מִדִּין אוֹתוֹ הָעוֹלָם. וַהֲקִיצוֹתָ - כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יְעוֹרֵר רוּחוֹת וּנְשָׁמוֹת לְהַחֲיוֹת מֵתִים, אָז הִיא תְשִׂיחֶךְ, הִיא תִהְיֶה סָנֵגוֹר עַל הַגּוּף בִּשְׁבִיל שֶׁיָּקוּמוּ אוֹתָם גּוּפִים שֶׁהִשְׁתַּדְּלוּ בַּתּוֹרָה כָּרָאוּי, וְאֵלֶּה הֵם שֶׁיָּקוּמוּ בַּתְּחִלָּה לְחַיֵּי עוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְגוֹ'. וְאֵלֶּה הֵם לְחַיֵּי עוֹלָם, מִשּׁוּם שֶׁהִתְעַסְּקוּ בְּחַיֵּי עוֹלָם שֶׁהִיא הַתּוֹרָה."],[8,"","וּבֹא רְאֵה, כָּל אֵלּוּ שֶׁהִשְׁתַּדְּלוּ בַּתּוֹרָה, אוֹתוֹ הַגּוּף יִתְקַיֵּם וְהַתּוֹרָה תָּגֵן עָלָיו, מָה הַטַּעַם? מִשּׁוּם שֶׁבְּאוֹתָהּ שָׁעָה יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ אַחַת שֶׁכְּלוּלָה מֵאַרְבַּע רוּחוֹת, וְאוֹתָהּ רוּחַ הַכּוֹלֶלֶת אַרְבַּע רוּחוֹת תִּזְדַּמֵּן לְכָל אוֹתָם שֶׁהִשְׁתַּדְּלוּ בַּתּוֹרָה לְהַחֲיוֹתָם בְּרוּחַ זוֹ בִּשְׁבִיל שֶׁיִּתְקַיֵּם לְעוֹלָמִים."],[9,"","וְאִם תֹּאמַר, הֲרֵי כָּתוּב (יחזקאל לז) מֵאַרְבַּע רוּחוֹת בּאִי הָרוּחַ, לָמָּה לֹא הִתְקַיְּמוּ, שֶׁהֲרֵי כֻּלָּם מֵתוּ כְּמִקֹּדֶם? בֹּא רְאֵה, אוֹתוֹ זְמַן שֶׁהֵקִים הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי יְחֶזְקֵאל אוֹתָם הַמֵּתִים, אוֹתוֹ (זמן העתיד) רוּחַ, אַף עַל גַּב שֶׁהָיָה מֵאַרְבַּע רוּחוֹת, לֹא יָרַד לְקַיְּמָם בְּקִיּוּם, אֶלָּא לְהַרְאוֹת שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת מֵתִים בְּאוֹתָהּ צוּרָה וּלְקַיְּמָם בָּרוּחַ שֶׁנִּכְלְלָה בְּצוּרָה זוֹ. וְאַף עַל גַּב שֶׁחָזְרוּ הָעֲצָמוֹת בְּאוֹתָהּ שָׁעָה כְּמוֹ שֶׁהָיָה, הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְהַרְאוֹת לְכָל הָעוֹלָם שֶׁהוּא עָתִיד לְהַחֲיוֹת מֵתִים (מה כתוב? (ישעיה כו) יחיו מתיך נבלתי יקומון, על זה אותה רוח שעתידה לרדת בהם צדיקים) (ס\"א ועל זה אותה רוח שעתידה לרדת בהם צדיקים מה כתוב? מארבע רוחות באי הרוח, רוח שנכללה בארבע), מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְקַיֵּם אוֹתָם קִיּוּם שָׁלֵם בָּעוֹלָם כָּרָאוּי, וְאוֹתָם שֶׁהִשְׁתַּדְּלוּ בַּתּוֹרָה בָּעוֹלָם הַזֶּה, הִיא עוֹמֶדֶת עַל הָאָדָם וְנַעֲשֵׂית סָנֵגוֹרְיָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."]]],[["רִבִּי שִׁמְעוֹן אָמַר, כָּל אִינוּן מִלִּין דְּאוֹרַיְיתָא וְכָל הַהִיא אוֹרַיְיתָא דְּאִשְׁתַּדַּל בָּהּ בַּר נָשׁ בְּהַאי עָלְמָא, אִינוּן מִלִּין וְהַהִיא אוֹרַיְיתָא קָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וַאֲמָרַת קַמֵיהּ וְהִיא אֲרִימַת קָלִין וְלָא אִשְׁתַּכָּכַת. וּלְהַהוּא זִמְנָא אִיהִי תָשִׂיחַ וְתֵימָא כְּפוּם דְאִתְדָּבַּק בַּר נָשׁ וְאִשְׁתְּדָּל בְּהַאי עַלְמָא, וְעַל דָּא אִינוּן יְקוּמוּן בְּקִיּוּמָא שְׁלִים לְחַיֵּי עַלְמָא כְּדְקָאֲמָרָן. וּבְגִין כָּךְ (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְצַדִּיקִים יֵלְכוּ בָם וּפוֹשְׁעִים יִכָּשְׁלוּ בָם.","רַבִּי חִיָּיא פָּתַח וְאָמַר, (שמואל א ב׳:כ״ב) וְעֵלִי זָקֵן מְאֹד וְשָׁמַע אֵת כָּל אֲשֶׁר יַעֲשׂוּן בָּנָיו לְכָל יִשְׂרָאֵל וְאֵת אֲשֶׁר יִשְׁכְּבֻן אֶת הַנָּשִׁים הַצֹּבְאוֹת פֶּתַח אֹהֶל מוֹעֵד. וְכִי סַלְקָא דַעְתָּךְ דְּכֹהֲנֵי יְיָ דְּיַעַבְדוּן עֲבִידְתָּא דָא. וְהָא מִקַּדְמַת דְּנָא אִתְּמָר וּפְרִישַׁת אוֹרַיְיתָא הַהוּא חוֹבָא דִלְהוֹן דִּכְתִיב, (שמואל א ב׳:י״ז) כִּי נִאֲצוּ הָאֲנָשִׁים אֶת מִנְחַת יְיָ. וּכְתִיב וּמִשְׁפַּט הַכֹּהֲנִים מֵאֵת הָעָם כָּל אִישׁ זוֹבֵחַ זֶבַח וְגו'. וּכְתִיב גַּם בְּטֶרֶם יַקְטִירוּן אֶת הַחֵלֶב וּבָא נַעַר הַכֹּהֵן וְאָמַר לָאִישׁ הַזּוֹבֵחַ תְּנָה לִצְלוֹת לַכֹּהֵן וְגו'. וּכְתִיב וְאָמַר לוֹ כִּי עַתָּה תִּתֵּן וְאִם לֹא לָקַחְתִּי בְּחָזְקָה. וְעַל דָּא וַתְּהִי חַטַּאת הַנְּעָרִים גְּדוֹלָה מְאֹד וְגו'. וְכָל דָּא לָא הֲווּ נָטְלִין אֶלָּא מֵאִינוּן חוּלָקִין דְּהֲווּ לְהוּ לְכַהֲנֵי לְמֵיכַל מִנֵּיהּ, וְעַל דְּהֲוָה קָלִיל קָרְבָּנָא בְּעֵינַיְיהוּ אִתְעֲנָשׁוּ. וְהָכָא אָמַר אֵת אֲשֶׁר יִשְׁכְּבוּן אֶת הַנָּשִׁים הַצּוֹבְאוֹת.","(אלא) חַס וְשָׁלוֹם דְּהֲווּ עָבְדוּ עֲבֵירָה דָא, כָּל שֶׁכֵּן בְּאַתְרָא קַדִּישָׁא הַהוּא, דְּלָא יְקוּמוּן כָּל יִשְׂרָאֵל וְיִקְטְלוּן לְהוֹן. אֶלָּא בְּגִין דְּהֲווּ מְעַכְּבֵי לוֹן לְאָעֳלָא לְמַקְדְּשָׁא, וּמָחָאן בִּידֵהוֹן דְּלָא לְאָעֳלָא לְמִצְלֵי צְלוֹתָא עַד דְּקוּרְבָּנַיָא אִתְעֲבִידוּ בְּגִין דְּאִינוּן לָא מַיְיתִין קָרְבָּנִין לְמֵיטַל חוּלָקָא מִנַּיְיהוּ, וּבְגִין כָּךְ מְעַכְּבִין לוֹן. וּבְגִין כָּךְ אִינוּן נָשִׁים הֲווּ בָּעָאן מִנַּיְיהוּ לְאַעֳלָא תַּמָּן. וְעַל דָּא כְּתִיב אֵת אֲשֶׁר יִשְׁכְּבוּן אֶת הַנָּשִׁים, דִּמְעַכְּבֵי לוֹן כִּדְקָאֲמָרָן.","כְּגַוְונָא דָא וַיִּשְׁכַּב אֶת בִּלְהָה. חַס וְשָׁלוֹם דְּאִיהוּ שָׁכַב עִמָּהּ, אֶלָּא בְּגִין דְּעָכַּב לָהּ לְשַׁמָּשָׁא בַּאֲבוֹי שִׁמּוּשָׁא דְמִצְוָה, וְדָא הוּא בִּלְבּוּלָא דְעַרְסָא. וְעֲבַד לָקֳבֵיל שְׁכִינְתָּא עֲבִידְתָּא דָא, דְּבְּכָל אֲתַר דְּשִׁמּוּשָׁא דְמִצְוָה אִשְׁתַּכַּח, שְׁכִינְתָּא שַׁרְיָא עַל הַהוּא אֲתַר וְאִשְׁתַּכַּח תַּמָּן. וּמַאן דְּגָרִים לְעַכָּבָא שִׁמּוּשָׁא דְמִצְוָה גָּרִים דְּיִסְתַּלַּק שְׁכִינְתָּא מֵעַלְמָא. וְעַל דָּא כְּתִיב (בראשית מ״ט:ד׳) כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךָ אָז חִלַּלְתָּ יְצוּעִי עָלָה. וּבְגִין דָּא כְּתִיב, וַיִּשְׁכַּב אֶת בִּלְהָה פִּלֶגֶשׁ אָבִיו וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְּנִי יַעֲקֹב שְׁנֵים עָשָׂר. כֻּלְּהוּ הֲווּ בְּמִנְיָינָא וְלָא גָרַע מִזְּכוּתָא דִלְהוֹן כְּלוּם.","רִבִּי אֶלְעָזָר אָמַר, מַאי טַעֲמָא בְּקַדְמִיתָא יִשְׂרָאֵל וּלְבָתַר יַעֲקֹב. דִּכְתִיב, וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְּנֵי יַעֲקֹב שְׁנֵים עָשָׂר. אֶלָּא כַּד אֲתָא רְאוּבֵן וּבִלְבֵּל הַהוּא עַרְסָא אָמַר וּמַה תְּרֵיסַר שִׁבְטִין הֲווּ לֵיהּ לְאַבָּא לְקַיְימָא בְּעַלְמָא וְלָא יַתִּיר, וְהַשְׁתָּא בָּעֵי לְאוֹלָדָא בְּנִין דִּילְמָא אֲנַן פְּגִימִין דְּאִיהוּ בָּעֵי לְאוֹלָדָא אָחֳרָנִין כְּמִלְּקַדְמִין. מִיָּד בִּלְבֵּל הַהוּא עַרְסָא, וְאִתְעַכַּב הַהוּא שִׁמּוּשָׁא. כְּאִילּוּ עֲבַד קְלָנָא לְגַבֵּי שְׁכִינְתָּא דְּשַׁרְיָא עַל הַהוּא עַרְסָא. וְעַל דָּא כְּתִיב וַיִּשְׁמַע יִשְׂרָאֵל, דְּהָא בִּשְׁמָא דָא אִסְתַּלַּק גּוֹ תְּרֵיסַר דְּאִתְכַּסְיָין דְּאִינוּן תְּרֵיסַר נַהֲרִי אֲפַרְסְמוֹנָא דַכְיָא.","וַיִּהְיוּ בְּנִי יַעֲקֹב שְׁנֵים עָשָׂר, אִלֵּין תְּרֵיסַר שִׁבְטִין דִּשְׁכִינְתָּא אִתְתַּקָּנַת בְּהוּ. וּמַאן אִינוּן, אִלֵּין דְּאוֹרַיְיתָא אַהֲדָרַת וְעָבִיד לוֹן חוּשְׁבְּנָא כְּמִלְּקַדְּמִין. כֻּלְּהוּ קַדִּישִׁין, כֻּלְּהוּ אִתְחַזְיָין לְגַבֵּי שְׁכִינְתָּא לְאִסְתַּכָּלָא בִּקְדוּשָׁה דְמָארֵיהוֹן. דְּאִילּוּ עֲבַד הַהוּא עוֹבָדָא לָא יֵיתֵי רְאוּבֵן בְּמִנְיָינָא."],[[0,"ר\"ש אמר וכו':","רש\"א, כל אלו המלות שבתורה וכל התורה ההיא, דהיינו השכל שבה, שעסק בה האדם בעולם הזה, אלו המלות ואותה התורה, עומדת תמיד לפני הקב\"ה, ואומרת לפניו, ומרימה קולות ואינה משתככת. ולעת ההיא, בתחיית המתים, היא תשיח ותאמר, כפי שנתדבק בה האדם ועסק בה בעולם הזה, ועל כן הם יקומו בקיום שלם לחיי עולם, כמו שאמרנו. ומשום זה, כי ישרים דרכי ה' וצדיקים ילכו בם ופושעים יכשלו בם."],[1,"ר' חייא פתח וכו':","ר\"ח פתח ואמר, ועלי זקן וגו' אשר ישכבון את הנשים וגו', ושואל, הכי יעלה על דעתך על כהני ה', שיעשו מעשה זה, והרי מקודם לכן נאמר, והתורה פרשת החטא שלהם, שכתוב, כי נאצו וגו' ואם לא לקחתי בחזקה. ועל זה אומר הכתוב, ותהי חטאת הנערים גדולה מאד. ומה גם שלא היו לוקחים אלא מאותם החלקים שהיו להם, לכהנים, לאכול מהם, ועל שהיה הקרבן קל בעיניהם נענשו, שמשמע שהיו צדיקים שמדקדקים עמהם מאד, וכאן אומר, את אשר ישכבון את הנשים הצובאות, שעשו עבירה חמורה כל כך."],[2,"אלא ח\"ו דהוו וכו':","ומשיב, אלא חס ושלום, שהיו עושים עבירה זו, ומכל שכן במקום הקדוש ההוא, שלא יקומו ישראל ויהרגו אותם. אלא משום שהיו מעכבים את הנשים מלהכנם למקדש, והיו מוחים בידיהן, שלא להכנס להתפלל תפלה מטרם שהקרבנות נעשו, כי משום שהן לא הביאו הקרבנות לקחת חלק מהם על כן היו מעכבים אותן. ומשום זה שהנשים בקשו להכנס שמה, אל המקדש, והם עכבו אותן, על כן כתוב \u0003את אשר ישכבון את הנשים,\u0004 דהיינו שעכבו אותן מלהכנס לבית המקדש, כמו שאמרנו."],[3,"כגוונא דא וישכב את בלהה:","חס ושלום ששכב עמה, אלא שעכב אותה מלשמש עם אביו שמוש של מצוה. וזהו בלבול המטה. (האמור לעיל באות ר\"ה). ונבחן, וכנגד השכינה עשה המעשה הזה, כי בכל מקום, שנמצא שמוש של מצוה, שורה השכינה על המקום ההוא ונמצאת שם. ומי שגורם לעכב שמוש של מצוה, גורם להסתלקות השכינה מן העולם. ועל כן כתוב, כי עלית משכבי אביך וגו'. ועל כן כתוב, וישכב את בלהה וגו'. ויהיו בני יעקב שנים עשר, ללמד, שכולם היו במנין, ולא נגרע מזכותם מאומה."],[4,"רבי אלעזר אמר וכו':","רא\"א, מה הטעם שמתחילה ישראל, ואחר כך יעקב שכתוב, וישמע \u0003ישראל\u0004 ויהיו בני \u0003יעקב\u0004 שנים עשר. ומשיב, אלא כשבא ראובן ובלבל את המטה, אמר, ומה זה, הרי י\"ב שבטים היו לו לאבי לקיים בעולם ולא יותר, ועתה הוא רוצה עוד להוליד בנים, וכי פגומים אנחנו, שהוא רוצה להוליד אחרים במקומנו כבתחילה. מיד בלבל המטה, ונעכב אותו השמוש, ונחשב, כאלו עשה בזיון כלפי השכינה, ששרתה על אותה המטה. ועל כן כתוב וישמע ישראל, כי בשם הזה נתעלה תוך י\"ב מדרגות שנתכסו, שהן י\"ב נהרות אפרסמון טהור. פי' ששם ישראל הוא למעלה מחזה דז\"א ששם ד' ספירות חו\"ב תו\"מ שבכל אחת ג' קוין שה\"ס י\"ב נהרי אפרסמון טהור. והם נתכסו, כי מחזה ולמעלה ה\"ס חסדים מכוסים. ויעקב היה רוצה להוליד עוד י\"ב בנים מבחי' י\"ב שבשם ישראל, שהם חסדים מכוסים. ונמצא ראובן שבלבל יצועי אביו, פגם בבחינת י\"ב שבשם ישראל, ולא כלום בי\"ב דיעקב שכבר היו ונשלמו, וע\"כ כתוב \u0003וישמע ישראל\u0004 אבל בני יעקב היו י\"ב שלמים."],[5,"ויהיו בני יעקב וגו':","אלו הם י\"ב השבטים שהשכינה נתקנה בהם, ומי הם, הם אלו שהתורה חזרה ועשתה להם חשבון כבתחילה, כמקדם חטאו של ראובן, כולם קדושים כולם ראויים אל השכינה להסתכל בקדושת רבונם. כי אלו עשה ראובן אותו מעשה לא היה בא במספר השבטים."]],[[0,"","רַבִּי שִׁמְעוֹן אָמַר, כָּל אוֹתָם דִּבְרֵי תוֹרָה וְכָל אוֹתָהּ תּוֹרָה שֶׁהִשְׁתַּדֵּל בָּהּ הָאָדָם בָּעוֹלָם הַזֶּה, אוֹתָם דְּבָרִים וְאוֹתָהּ תּוֹרָה עוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאוֹמֶרֶת לְפָנָיו, וְהִיא מְרִימָה קוֹלוֹת וְלֹא שׁוֹכֶכֶת, וּלְאוֹתוֹ זְמַן הִיא תָשִׂיחַ וְתֹאמַר כְּפִי שֶׁהִתְדַּבֵּק בָּהּ הָאָדָם וְהִשְׁתַּדֵּל בָּהּ בָּעוֹלָם הַזֶּה, וְעַל זֶה הֵם יָקוּמוּ בְּקִיּוּם שָׁלֵם לְחַיֵּי עוֹלָם, כְּמוֹ שֶׁאָמַרְנוּ, וּמִשּׁוּם כָּךְ (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּיקִים יֵלְכוּ בָם וּפֹשְׁעִים יִכָּשְׁלוּ בָּם."],[1,"","רַבִּי חִיָּיא פָּתַח וְאָמַר, (שמואל א ב) וְעֵלִי זָקֵן מְאֹד וְשָׁמַע אֵת כָּל אֲשֶׁר יַעֲשׂוּן בָּנָיו לְכָל יִשְׂרָאֵל וְאֵת אֲשֶׁר יִשְׁכְּבֻן אֶת הַנָּשִׁים הַצֹבְאוֹת פֶּתַח אֹהֶל מוֹעֵד. וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁכֹּהֲנֵי ה' יַעֲשׂוּ מַעֲשֶׂה זֶה, וַהֲרֵי מִקֹּדֶם לְכָךְ נֶאֱמַר וּפֵרְשָׁה תוֹרָה אוֹתוֹ הַחֵטְא שֶׁלָּהֶם, שֶׁכָּתוּב (שם) כִּי נִאֲצוּ הָאֲנָשִׁים אֵת מִנְחַת ה', וְכָתוּב וּמִשְׁפַּט הַכֹּהֲנִים מֵאֵת הָעָם כָּל אִישׁ זבֵחַ זֶבַח וְגוֹ', וְכָתוּב גַּם בְּטֶרֶם יַקְטִרוּן אֶת הַחֵלֶב וּבָא נַעַר הַכֹּהֵן וְאָמַר לָאִישׁ הַזֹּבֵחַ תְּנָה בָשָׂר לִצְלוֹת לַכֹּהֵן וְגוֹ', וְכָתוּב וְאָמַר לוֹ כִּי עַתָּה תִתֵּן וְאִם לֹא לָקַחְתִּי בְחָזְקָה, וְעַל זֶה וַתְּהִי חַטַּאת הַנְּעָרִים גְּדלָה מְאֹד וְגוֹ', וְכָל זֶה לֹא הָיוּ נוֹטְלִים אֶלָּא מֵאוֹתָם חֲלָקִים שֶׁהָיוּ לַכֹּהֲנִים לֶאֱכֹל מֵהֶם, וְעַל שֶׁהָיָה הַקָּרְבָּן קַלִּיל בְּעֵינֵיהֶם נֶעֶנְשׁוּ, וְכָאן אָמַר אֵת אֲשֶׁר יִשְׁכְּבֻן אֶת הַנָּשִׁים הַצֹבְאוֹת"],[2,"","אֶלָּא? חַס וְחָלִילָה שֶׁהָיוּ עוֹשִׂים עֲבֵרָה זוֹ, כָּל שֶׁכֵּן בְּאוֹתוֹ מָקוֹם קָדוֹשׁ, שֶׁלֹּא יָקוּמוּ כָּל יִשְׂרָאֵל וְיַהַרְגוּ אוֹתָם. אֶלָּא מִשּׁוּם שֶׁהָיוּ מְעַכְּבִים אוֹתָם לְהִכָּנֵס לַמִּקְדָּשׁ וּמוֹחִים בִּידֵיהֶם שֶׁלֹּא לְהִכָּנֵס לְהִתְפַּלֵּל תְּפִלָּה עַד שֶׁהַקָּרְבָּנוֹת נַעֲשׂוּ, מִשּׁוּם שֶׁהֵן לֹא מְבִיאוֹת קָרְבָּנוֹת לִטֹּל חֵלֶק מֵהֶם, וּמִשּׁוּם כָּךְ מְעַכְּבִים אוֹתָן, וּמִשּׁוּם כָּךְ אוֹתָן נָשִׁים הָיוּ מְבַקְשׁוֹת מֵהֶם לְהִכָּנֵס לְשָׁם, וְעַל זֶה כָּתוּב אֵת אֲשֶׁר יִשְׁכְּבֻן אֶת הַנָּשִׁים, שֶׁמְּעַכְּבִים אוֹתָן כְּמוֹ שֶׁאָמַרְנוּ."],[3,"","כְּמוֹ זֶה וַיִּשְׁכַּב אֶת בִּלְהָה. חַס וְשָׁלוֹם שֶׁהוּא שָׁכַב עִמָּהּ, אֶלָּא מִשּׁוּם שֶׁעִכֵּב אוֹתָהּ לְשַׁמֵּשׁ עִם אָבִיו שִׁמּוּשׁ שֶׁל מִצְוָה, וְזֶה הוּא בִּלְבּוּל הַמִּטָּה, וְעָשָׂה כְּנֶגֶד הַשְּׁכִינָה הַמַּעֲשֶׂה הַזֶּה. שֶׁבְּכָל מָקוֹם שֶׁשִּׁמּוּשׁ מִצְוָה נִמְצָא, שְׁכִינָה שׁוֹרָה עַל אוֹתוֹ מָקוֹם וְנִמְצֵאת שָׁם, וּמִי שֶׁגּוֹרֵם לְעַכֵּב שִׁמּוּשׁ שֶׁל מִצְוָה, גּוֹרֵם שֶׁתִּסְתַּלֵּק שְׁכִינָה מִן הָעוֹלָם, וְעַל זֶה כָּתוּב (בראשית מט) כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךְ אָז חִלַּלְתָּ יְצוּעִי עָלָה. וּמִשּׁוּם זֶה כָּתוּב וַיִּשְׁכַּב אֶת בִּלְהָה פִּילֶגֶשׁ אָבִיו וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְנֵי יַעֲקֹב שְׁנֵים עָשָׂר. כֻּלָּם הָיוּ בַּמִּנְיָן, וְלֹא נִגְרְעָה מִזְּכוּת שֶׁלָּהֶם כְּלוּם."],[4,"","רַבִּי אֶלְעָזָר אָמַר, מָה הַטַּעַם בַּתְּחִלָּה יִשְׂרָאֵל וְאַחַר כָּךְ יַעֲקֹב, שֶׁכָּתוּב וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְנֵי יַעֲקֹב שְׁנֵים עָשָׂר? אֶלָּא כְּשֶׁבָּא רְאוּבֵן וּבִלְבֵּל אוֹתָהּ מִטָּה, אָמַר: וּמַה שְּׁנֵים עָשָׂר שְׁבָטִים הָיוּ לְאַבָּא בָּעוֹלָם וְלֹא יוֹתֵר, וְעַכְשָׁו רוֹצֶה לְהוֹלִיד בָּנִים, אוּלַי אָנוּ פְּגוּמִים שֶׁהוּא רוֹצֶה לְהוֹלִיד אֲחֵרִים כְּמוֹ מִקֹּדֶם. מִיָּד בִּלְבֵּל אוֹתָהּ מִטָּה וְהִתְעַכֵּב אוֹתוֹ שִׁמּוּשׁ כְּאִלּוּ עָשָׂה קָלוֹן לַשְּׁכִינָה שֶׁשָּׁרְתָה עַל אוֹתָהּ מִטָּה, וְעַל זֶה כָּתוּב וַיִּשְׁמַע יִשְׂרָאֵל, שֶׁהֲרֵי בְּשֵׁם זֶה הִתְעַלָּה תּוֹךְ שְׁנֵים עָשָׂר שֶׁהִתְכַּסּוּ, שֶׁהֵם שְׁנֵים עָשָׂר נַהֲרוֹת אֲפַרְסְמוֹן זַךְ."],[5,"","וַיִּהְיוּ בְנֵי יַעֲקֹב שְׁנֵים עָשָׂר - אֵלּוּ שְׁנֵים עָשָׂר שְׁבָטִים שֶׁהַשְּׁכִינָה הִתְתַּקְּנָה בָהֶם, וּמִי הֵם? אֵלּוּ שֶׁהַתּוֹרָה חָזְרָה וְעָשְׂתָה לָהֶם חֶשְׁבּוֹן כְּמוֹ מִקֹּדֶם, כֻּלָּם קְדוֹשִׁים, כֻּלָּם רְאוּיִים לַשְּׁכִינָה לְהִסְתַּכֵּל בִּקְדֻשַּׁת רִבּוֹנָם. שֶׁאִלּוּ עָשָׂה אוֹתוֹ מַעֲשֶׂה, לֹא יָבֹא רְאוּבֵן בַּמִּנְיָן."]]],[["וְעִם כָּל דָּא אִתְעֲנַשׁ דְּאִתְנְטִיל בְּכוֹרָתֵיהּ מִנֵּיהּ וְאִתְיְהִיב לְיוֹסֵף כְּמָה דְאַתְּ אָמֵר, (דברי הימים א ה׳:א׳) וּבְנֵי רְאוּבֵן בְּכוֹר יִשְׂרָאֵל כִּי הוּא הַבְּכוֹר וּבְחַלְּלוֹ יְצוּעֵי אָבִיו נִתְּנָה בְּכוֹרָתוֹ לְיוֹסֵף. תָּא חֲזֵי, (דניאל ב׳:כ׳) לֶהוֵא שְׁמֵהּ דִּי אֱלָהָא מְבָרַךְ מִן עָלְמָא וְעַד עָלְמָא דִּי כָּל מַעְבְּדוֹהִי קְשׁוֹט וְאָרְחָתֵיהּ דִּין, וְכָל מַה דְּאִיהוּ עָבִיד כֹּלָּא אִיהוּ בְּחָכְמְתָא עִלָּאָה.","תָּא חֲזֵי, כַּמָּה גָרִים עוֹבָדָא דְבַר נָשׁ, דְּהָא כָּל מַאי (מאן) דְאִיהוּ עָבִיד, כֹּלָּא אִתְרְשִׁים וְקָיְימָא קַמֵּי דְקוּדְשָׁא בְּרִיךְ הוּא. דְּהָא יַעֲקֹב בְּשַׁעְתָּא דְעָאל לְגַבָּהּ דְלֵאָה, כָּל הַהוּא לֵילְיָא רְעוּתֵיהּ וְלִבֵּיהּ הֲוָה בְּרָחֵל, דְּחָשִׁיב דְּרָחֵל אִיהִי. וּמֵהַהוּא שִׁמּוּשָׁא וְטִפָּה קַדְמָאָה וּמֵהַהוּא רְעוּתָא אִתְעֲבָרַת לֵאָה וְאוּקְמוּהָ. דְּהָא אִלְמָלֵא דְיַעֲקֹב לָא יָדַע לָא יִסְתַּלִּיק רְאוּבֵן בְּחוּשְׁבָּנָא. וְעַל דָּא לָא אִסְתַּלַּק בִּשְׁמָא יְדִיעָא אֶלָּא שְׁמֵיהּ סְתָם רְאוּבֵן.","וְעִם כָּל דָּא אַהֲדַר עוֹבָדָא לְאַתְרֵיהּ, כְּמָה דְהַהוּא רְעוּתָא קַדְמָאָה אִתְעֲבִידַת בְּרָחֵל, הַהוּא רְעוּתָא אִתְהַדָּרַת בָּהּ. דְּהָא בְּכוֹרָתֵיהּ אַהֲדָרַת לְיוֹסֵף בּוּכְרָא דְרָחֵל, אֲתַר דִּרְעוּתָא הֲוַת בְּרָחֵל וְכֹלָּא סָלִיק בְּאַתְרֵיהּ. בְּגִין דְּכָל עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא כֻּלְּהוּ קְשׁוֹט וּזְכוּ.","רִבִּי חִזְקִיָּה אַשְׁכְּחֵיהּ יוֹמָא חַד לְרַבִּי יוֹסֵי דְּהֲוָה מִסְטְמִיט סַפְסִינָא גוֹ קִטְרֵי דְנוּרָא וְהֲוָה סָלִיק קִטּוֹרָא דִּתְנָנָא לְעֵילָא. אָמַר לֵיהּ, אִלּוּ קִטּוּרָא דִּתְנָנָא דְקָרְבָּנָא דְּהֲוָה סָלִיק עַל גַּבֵּי מַדְבְּחָא הֲוָה סָלִיק תָּדִיר כִּי הַאי גַוְונָא, לָא שַׁרְיָא רוּגְזָא בְּעַלְמָא וְיִשְׂרָאֵל לָא אִתְגְּלִי מֵעַל אַרְעָא.","פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שיר השירים ג׳:ו׳) מִי זֹאת עֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל. מִי זֹאת עוֹלָה. תָּא חֲזֵי, בְּזִמְנָא דְהֲווּ יִשְׂרָאֵל אָזְלֵי בְּמַדְבְּרָא, שְׁכִינְתָּא אָזְלָא קַמַּיְיהוּ וְאִינְהוּ הֲווּ אָזְלֵי אֲבַתְרָהּ. דִּכְתִיב, (שמות י״ג:כ״א) וַיְיָ הוֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן לַנְחוֹתָם הַדֶּרֶךְ וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם וְגו'. וּבְגִין כָּךְ כְּתִיב, (ירמיה ב) כֹּה אָמַר יְיָ זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלוֹתַיִךְ לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר וְגו'.","וּשְׁכִינְתָּא הֲוַת אָזְלָא וְכֻלְּהוּ עֲנָנֵי יְקָר בַּהֲדָהּ. וְכַד הֲוָה שְׁכִינְתָּא נָטְלָא, הֲווּ נָטְלִין. כְּמָה דִכְתִיב, (שמות מ׳:ל״ו) וּבְהֵעָלוֹת הֶעָנָן מֵעַל הָאֹהֶל וְאַחֲרֵי כֵן יִסְּעוּ בְּנִי יִשְׂרָאֵל וְגו'. וְכַד אִיהִי סָלְקָא הַהוּא עֲנָנָא סָלְקָא עַד לְעֵילָא, וְכָל בְּנֵי עַלְמָא חָמָאן וְשָׁאֲלֵי וְאָמְרֵי, מִי זֹאת עוֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן.","הַהוּא עֲנָנָא דִּשְׁכִינְתָּא אִתְחַזְיָא עָשָׁן, מַאי טַעֲמָא אִיהִי עָשָׁן. בְּגִין דְּנוּרָא דְּאַדְלִיק אַבְרָהָם וְיִצְחָק בְּרֵיהּ הֲוָה אָחִיד בָּהּ וְלָא אַעֲדֵי מִינָהּ. וְכַד אִתְאַחְדַת הַהוּא נוּרָא בְּגַוָּוהּ הֲוָה סָלִיק עֲנָנָא (נ\"א תננא).","וְעִם כָּל דָּא, מְקֻטֶּרֶת מֹר וּלְבוֹנָה. מַאי מְקֻטֶּרֶת, מִתְקַטְרָא בִּתְרֵין סִטְרִין אָחֳרָנִין, עֲנָנָא דְאַבְרָהָם לִימִינָא, עֲנָנָא דְיִצְחָק לִשְׂמָאלָא. מִכֹּל אַבְקַת רוֹכֵל, דָּא יַעֲקֹב.","דָּבָר אַחֵר דָּא יוֹסֵף הַצַּדִּיק, בְּגִין דַּאֲרוֹנָא דְיוֹסֵף הֲוָה אָזִיל לְגַבֵּיהּ, אַמַּאי רוֹכֵל, בְּגִין דְּהֲוָה רָכִיל לַאֲחוֹי לְגַבֵּיהּ דְּאֲבוֹי. דָּבָר אַחֵר אַמַּאי רוֹכֵל, אֶלָּא מַה חֶנְוָנִי דָא קְטִירֵי דְּקוּסְטְרֵי וְאַבְקֵי דְפוּלְמֵי כֻּלְּהוּ בִּידֵיהּ. הָכִי נָמֵי יוֹסֵף, אִיהוּ קִיּוּמָא דְאוֹרַיְיתָא בְּגִין דְּאִיהוּ קִיֵּים לָהּ, בְּגִין דְּכָל פִּקּוּדֵי אוֹרַיְיתָא מִתְקַשְּׁרָן בִּנְטִירוּ דִּבְרִית קַדִּישָׁא.","וְעַל דָּא שְׁכִינְתָא מִתְקַטְּרָא בְּאַבְרָהָם יִצְחָק וְיַעֲקֹב וְיוֹסֵף, כְּחֲדָא אִינוּן וְדִיוּקְנָא חָדָא לְהוּ. הֲדָא הוּא דִּכְתִיב, (בראשית ל״ז:ב׳) אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף. וּבְגִין כָּךְ מִכֹּל אַבְקַת רוֹכֵל, בְּגִין דְּמֵאֲתַר דְּנַהֲרָא דְּנָגִיד וְנָפִיק אִשְׁתַּקְיָיא כֹּלָּא וּנְהִירוּ כָּל אַנְפִּין.","וְתָּא חֲזֵי, כַּד הֲווּ יִשְׂרָאֵל בְּאַרְעָא וְהֲווּ מַקְרִיבִין קָרְבָּנִין, כֻּלְּהוּ הֲווּ מִתְקָרְבִין לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יָאוֹת, וְכַד קָרְבָּנָא אִתְעֲבִיד וּתְנָנָא סָלִיק בְּאֹרַח מֵישַׁר, כְּדֵין הֲווּ יָדְעֵי דִּתְנָנָא דְּמַדְבְּחָא אַדְלִיק בּוֹצִינָא דְּאִתְחַזְּיָא לְאַדְלָקָא, וְכָל אַנְפִּין נְהִירִין וּבוֹצִינִין דָּלְקִין."],[[0,"ועם כל דא אתענש וכו':","ועם כל זה נענש ראובן, שנלקחה ממנו הבכורה וניתנה ליוסף. כמו שאתה אומר, ובני ראובן בכור ישראל כי הוא הבכור וגו'. בוא וראה יהי שמו של האלקים מבורך מן העולם ועד העולם, שכל פעולותיו אמת, ודרכיו דין, וכל מה שהוא עושה הכל הוא בחכמה העליונה."],[1,"ת\"ח כמה גרים וכו':","בוא וראה, כמה גורם מעשה בני אדם, כי כל מה שהאדם עושה, הכל נרשם ועומד לפני הקב\"ה. כי יעקב, בשעה שבא אל לאה, כל אותו הלילה רצונו ולבו היו ברחל, כי חשב שהיא רחל, ומשמוש הזה, מטפה ראשונה ומאותו הרצון נתעברה לאה. ובארוהו, אלו לא היה כך שלא היה יודע יעקב שהיא לאה אלא שכן היה יודע שהיא לאה והיה מחשב ברחל, לא היה עולה ראובן בחשבון השבטים, כי היה ח\"ו בן תמורה. אלא בשוגג היה, ועל כן לא נתעלה בשם ידוע, אלא שמו סתם ראובן, פירוש, שהוא נוטריקון \u0003ראו-בן\u0004 סתם, בלי שם."],[2,"ועם כל דא וכו':","ועם כל זה חזר המעשה למקומו, שכמו שהרצון הראשון נפעל ברחל, הרצון הזה חזר אליה, כי בכורתו חזרה ליוסף בכור רחל, למקום שהרצון היה שם, שהיא רחל. והכל בא למקומו כי כל מעשיו של הקב\"ה, כולם אמת וצדק."],[3,"רבי חזקיה אשכחיה וכו':","רבי חזקיה פגש פעם את ר' יוסי, וראה שהיתה נשמטת ויוצאת חתיכת בשר מן הסיר שלו לתוך להב האש, ותמרות העשן היו מתאבכות ועולות למעלה, מטפטוף השומן. אמר לו, אלו תמרות העשן מן הקרבן, שהיו עולות על המזבח, היו עולות תמיד כעשן הזה, לא היה רגז על העולם, וישראל לא היו גולים מארצם."],[4,"פתח ר' יוסי וכו':","פתח ר\"י ואמר, מי זאת עולה מן המדבר כתמרות עשן וגו'. \u0003מי זאת עולה,\u0004 מה פירושו, ואומר, בוא וראה, בזמן שישראל היו הולכים במדבר, השכינה היתה הולכת לפניהם, והם היו הולכים אחריה, שכתוב וה' הולך לפניהם וגו'. ומשום זה כתוב \u0003כה\u0004 אמר וגו' לכתך \u0003אחרי\u0004 במדבר וגו'. הרי שהשכינה הלכה לפניהם והם הלכו אחריה. שזה רומז שהיו מקבלים מאחורים שלה כמ\"ש להלן בסמוך."],[5,"ושכינתא הות אזלא וכו':","והשכינה היתה הולכת וכל ענני כבוד עמה. וכשהשכינה נסעה היו נוסעים ישראל, כמו שכתוב, ובהעלות הענן מעל האהל וגו', וכשהיא עלתה, עלה הענן עד למעלה, וכל בני העולם רואים, ושואלים ואומרים, מי זאת עולה מן המדבר כתימרות עשן."],[6,"ההוא עננא דשכינתא וכו':","הענן ההוא שהשכינה נראתה בו, היה עשן. מה הטעם שהיה עשן, הוא, משום שהאש שהדליק אברהם ויצחק בנו, היתה אוחזת בה ולא הרפתה ממנה. וכשהאש ההיא היתה נאחזת בה היתה מעלה עשן."],[6,"","פירוש. כשקו השמאל דבינה מאיר בלי ימין, אז הארתו כאש אוכלת. וכשהשכינה בסוד בנין אחורים היא עולה ומלבשת את קו שמאל דבינה. ואז היא נדלקת באש הזה. וז\"ש \u0003דנורא דאדליק אברהם ויצחק בריה הוה אחיד בה,\u0004 כי יצחק ה\"ס קו שמאל דבינה, שאברהם המשיך אותו, ומטרם שנכלל בימין היה כאש אוכלת, והשכינה נדלקה באש הזה בזמן היותה בבנין אחורים. ובעת תקון השכינה שהיא מקבלת מוחין השלמים דפנים בפנים, כשמשפעת הארת החכמה, היא משפעת בכלים הללו, שהם כאש אוכלת, שקבלה מקו שמאל דבינה בעת היותה במוחין דאחורים. (כנ\"ל בהקדמת ספר הזהר דף י\"ב ד\"ה ואלמלי ע\"ש.) וז\"ש \u0003ולא אעדי מינה,\u0004 שאש זו אינה סרה מהנוקבא גם בהיותה במוחין דפנים. דהיינו שהיא משפיעה על ידם הארת החכמה, וז\"ש \u0003וכד אתאחדת ההוא נורא בגווה\u0004 דהיינו בעת שהיא משפעת הארת חכמה, \u0003הוה סליק תננא,\u0004 כי מעוררת אז כלים דאחורים שהם כאש אוכלת ומעלים עשן."],[7,"ועם כל דא וכו':","ועם כל זה, \u0003מקטרת מר ולבונה\u0004 מהו מקטרת, היינו שהיא מתקשרת בב' הצדדים האחרים הממותקים ונכללים זה בזה, שהם ענן של אברהם שהוא לימין וענן דיצחק שהוא לשמאל. \u0003מכל אבקת רוכל,\u0004 זה יעקב. כלומר שהיתה מתקשרת בג' הקוין, מר: זהו קו ימין אברהם. לבנה: זהו קו שמאל יצחק. מכל אבקת רוכל: זהו קו אמצעי הכולל שניהם, ע\"כ מכונה רוכל, שבידו מר ולבנה."],[8,"דבר אחר מכל וכו':","פירוש אחר. אבקת רוכל זה יוסף הצדיק. משום שארונו של יוסף, שהוא יסוד היה הולך אצלה. ולמה נקרא רוכל, משום שאמר \u0003רכילות,\u0004 על אחיו לפני אביו."],[8,"דבר אחר אמאי רוכל וכו':","פירוש אחר למה נקרא \u0003רוכל.\u0004 אלא כמו החנוני הזה שמצרורות עצי בשמים עד אבקות עלים מריחים, הכל בידו, כן יוסף הוא הקיום של התורה, כי הוא קיים אותה, משום שכל מצוות התורה מקושרות בשמירת ברית הקודש ויוסף שמר את ברית הקודש."],[9,"דבר אחר מכל וכו':","פירוש אחר. אבקת מתקשרת באברהם, ביצחק, ביעקב וביוסף, שהם כאחד וצורה אחת להם, וזהו שכתוב אלה תולדות יעקב יוסף. ומשום זה כתוב מכל אבקת רוכל, כי מן המקום שהנהר נמשך ויוצא, דהיינו יסוד שהוא יוסף, מושקים כולם, ופני הכל מאירים."],[9,"קטירי,","פירושו צרורות. \u0003קוסטרי,\u0004 פירושו עצי בשמים הנקראים \u0003קשט\u0004 בסימני הקטרת. וכל נקראים \u0003כשרתא\u0004 (ברכות מג.). \u0003פולמי,\u0004 הוא כמו פילון (שבת סב:) שפירושו \u0003עלים מריחים.\u0004"],[10,"ות\"ח כד הוו וכו':","ובוא וראה, כשישראל היו בארץ, והיו מקריבים קרבנות, היו נקרבים כולם להקב\"ה כראוי, וכשהקרבן נעשה והעשן עלה בדרך ישר, אז היו יודעים שעשן המזבח הדליק הנר הראוי להדליק, ופני הכל מאירים והנרות דולקים."],[10,"נרות,","פירושו, הספירות של הנוקבא, שה\"ס מאורי האש (כמ\"ש לעיל בראשית א' אות קכ\"ח, וע\"ש בסולם. ולעיל בראשית ב' דף קנ\"ה אות רס\"ג)."]],[[0,"","וְעִם כָּל זֶה נֶעֱנַשׁ שֶׁנִּטְּלָה מִמֶּנּוּ בְּכוֹרָתוֹ וְנִתְּנָה לְיוֹסֵף, כְּמוֹ שֶׁנֶּאֱמַר (דה\"א ה) וּבְנֵי רְאוּבֵן בְּכוֹר יִשְׂרָאֵל כִּי הוּא הַבְּכוֹר וּבְחַלְּלוֹ יְצוּעֵי אָבִיו נִתְּנָה בְּכֹרָתוֹ (לבני) לְיוֹסֵף. בֹּא רְאֵה, (דניאל ב) שֶׁיִּהְיֶה שֵׁם הָאֵל מְבֹרָךְ מִן הָעוֹלָם וְעַד הָעוֹלָם. שֶׁכָּל מַעֲשָׂיו אֱמֶת וּדְרָכָיו דִּין, וְכָל מַה שֶּׁהוּא עוֹשֶׂה, הַכֹּל הוּא בְחָכְמָה עֶלְיוֹנָה."],[1,"","בֹּא רְאֵה כַּמָּה גוֹרֵם מַעֲשֵׂה אָדָם, שֶׁהֲרֵי כָּל מִי (מה) שֶׁהוּא עוֹשֶׂה, נִרְשָׁם וְעוֹמֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהֲרֵי יַעֲקֹב, בְּשָׁעָה שֶׁנִּכְנַס לְלֵאָה, כָּל אוֹתוֹ הַלַּיְלָה הָיָה רְצוֹנוֹ וְלִבּוֹ בְּרָחֵל, שֶׁחָשַׁב שֶׁהִיא רָחֵל, וּמֵאוֹתוֹ שִׁמּוּשׁ וְטִפָּה רִאשׁוֹנָה וּמֵאוֹתוֹ רָצוֹן הִתְעַבְּרָה לֵאָה, וּבֵאֲרוּהוּ, שֶׁהֲרֵי אִלְמָלֵא שֶׁיַּעֲקֹב לֹא יָדַע, לֹא יַעֲלֶה רְאוּבֵן בַּחֶשְׁבּוֹן. וְעַל זֶה לֹא הִתְעַלָּה בְּשֵׁם יָדוּעַ, אֶלָּא שְׁמוֹ סְתָם רְאוּבֵן."],[2,"","וְעִם כָּל זֶה חָזַר מַעֲשָׂיו לִמְקוֹמוֹ, כְּמוֹ שֶׁאוֹתוֹ רָצוֹן רִאשׁוֹן נַעֲשָׂה בְּרָחֵל, אוֹתוֹ רָצוֹן חָזַר בָּהּ, שֶׁהֲרֵי בְּכוֹרָתוֹ חָזְרָה לְיוֹסֵף בְּכוֹר רָחֵל, מָקוֹם שֶׁהָרָצוֹן הָיָה בְּרָחֵל, וְהַכֹּל עוֹלֶה לִמְקוֹמוֹ, מִשּׁוּם שֶׁכָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא אֱמֶת וּזְכוּת."],[3,"","רַבִּי חִזְקִיָּה מָצָא יוֹם אֶחָד אֶת רַבִּי יוֹסֵי שֶׁהָיְתָה נִשְׁמֶטֶת חֲתִיכַת בָּשָׂר לְתוֹךְ לַהֲבוֹת הָאֵשׁ, וְהָיָה עוֹלֶה קִטּוֹר הֶעָשָׁן לְמַעְלָה. אָמַר לוֹ, אִלּוּ קִטּוֹר הֶעָשָׁן שֶׁל הַקָּרְבָּן שֶׁהָיָה עוֹלֶה עַל גַּבֵּי הַמִּזְבֵּחַ הָיָה עוֹלֶה תָמִיד כְּמוֹ זֶה, לֹא שׁוֹרֶה רֹגֶז בָּעוֹלָם, וְיִשְׂרָאֵל לֹא הָיוּ גוֹלִים מֵעַל הָאָרֶץ."],[4,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שיר ג) מִי זֹאת עֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל. מִי זֹאת עֹלָה? בֹּא רְאֵה, בִּזְמַן שֶׁהָיוּ יִשְׂרָאֵל הוֹלְכִים בַּמִּדְבָּר, הַשְּׁכִינָה הָלְכָה לִפְנֵיהֶם, וְהֵם הָלְכוּ אַחֲרֶיהָ, שֶׁכָּתוּב (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן לַנְחֹתָם הַדֶּרֶךְ וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם וְגוֹ'. וְלָכֵן כָּתוּב (ירמיה ב) כֹּה אָמַר ה' זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלֹתָיִךְ לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר וְגוֹ'."],[5,"","וּשְׁכִינָה הָיְתָה הוֹלֶכֶת וְכָל עַנְנֵי הַכָּבוֹד עִמָּהּ. וּכְשֶׁהָיְתָה שְׁכִינָה נוֹסַעַת, הָיוּ נוֹסְעִים, כַּכָּתוּב (במדבר ט) וּלְפִי הֵעָלוֹת הֶעָנָן מֵעַל הָאֹהֶל וְאַחֲרֵי כֵן יִסְעוּ בְּנֵי יִשְׂרָאֵל וְגוֹ'. וּכְשֶׁהִיא עוֹלָה, אוֹתוֹ עָנָן עוֹלֶה עַד לְמַעְלָה, וְכָל בְּנֵי הָעוֹלָם רוֹאִים וְשׁוֹאֲלִים וְאוֹמְרִים, מִי זֹאת עֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן."],[6,"","אוֹתוֹ עָנָן שֶׁל הַשְּׁכִינָה שֶׁנִּרְאָה עָשָׁן. מָה הַטַּעַם הִיא עָשָׁן? מִשּׁוּם שֶׁהָאֵשׁ שֶׁהִדְלִיקוּ אַבְרָהָם וְיִצְחָק בְּנוֹ הָיְתָה אֲחוּזָה בָּהּ וְלֹא זָזָה מִמֶּנָּה, וְכַאֲשֶׁר נֶאֶחְזָה אוֹתָהּ הָאֵשׁ בְּתוֹכָהּ, הָיְתָה עוֹלָה עָנָן (נ\"א עשן)."],[7,"","וְעִם כָּל זֶה, מְקֻטֶּרֶת מֹר וּלְבוֹנָה. מַה זֶּה מְקֻטֶּרֶת? מִתְקַשֶּׁרֶת בִּשְׁנֵי צְדָדִים אֲחֵרִים, עָנָן שֶׁל אַבְרָהָם לְיָמִין, עָנָן שֶׁל יִצְחָק לִשְׂמֹאל. מִכֹּל אַבְקַת רוֹכֵל - זֶה יַעֲקֹב."],[8,"","דָּבָר אַחֵר - זֶה יוֹסֵף הַצַּדִּיק, מִשּׁוּם שֶׁאֲרוֹנוֹ שֶׁל יוֹסֵף הָיָה הוֹלֵךְ אֵלָיו. לָמָּה רוֹכֵל? מִשּׁוּם שֶׁהָיָה רָכִיל אֶת אֶחָיו לְאָבִיו. דָּבָר אַחֵר לָמָּה רוֹכֵל - אֶלָּא מַה חֶנְוָנִי זֶה שֶׁצְּרוֹרוֹת עֲצֵי בְשָׂמִים וְאַבְקוֹת עָלִים מְרִיחִים כֻּלָּם בְּיָדוֹ - כָּךְ גַּם יוֹסֵף, הוּא קִיּוּם הַתּוֹרָה, מִשּׁוּם שֶׁהוּא קִיֵּם אוֹתָהּ, מִשּׁוּם שֶׁכָּל מִצְווֹת הַתּוֹרָה קְשׁוּרוֹת לִשְׁמִירַת בְּרִית קֹדֶשׁ."],[9,"","וְלָכֵן שְׁכִינָה קְשׁוּרָה לְאַבְרָהָם יִצְחָק וְיַעֲקֹב וְיוֹסֵף, כְּאֶחָד הֵם, וּדְמוּת אַחַת לָהֶם. זֶהוּ שֶׁכָּתוּב (בראשית לז) אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף. וּמִשּׁוּם כָּךְ מִכֹּל אַבְקַת רוֹכֵל, מִשּׁוּם שֶׁמִּמָּקוֹם שֶׁהַנָּהָר שֶׁשׁוֹפֵעַ וְיוֹצֵא, הַכֹּל מֻשְׁקִים וְכָל הַפָּנִים מְאִירוֹת."],[10,"","וּבֹא וּרְאֵה, כְּשֶׁהָיוּ יִשְׂרָאֵל בָּאָרֶץ וְהָיוּ מַקְרִיבִים קָרְבָּנוֹת, כֻּלָּם הָיוּ מִתְקָרְבִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא כָּרָאוּי, וּכְשֶׁקָּרְבָּן נַעֲשָׂה וְהֶעָשָׁן עוֹלֶה בְּדֶרֶךְ יָשָׁר, אָז הָיוּ יוֹדְעִים שֶׁעֲשַׁן הַמִּזְבֵּחַ הִדְלִיק מְנוֹרָה שֶׁרְאוּיָה לְהִדָּלֵק, וְכָל הַפָּנִים מְאִירוֹת וְהַמְּנוֹרוֹת דּוֹלְקוֹת."]]],[["וּמִיּוֹמָא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא לֵית לָךְ יוֹמָא וְיוֹמָא דְּלֵית בֵּיהּ זְעִימוּ וְרוּגְזָא. כְּמָה דְאַתְּ אָמֵר, (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם, וְאִתְפָּרַשׁ חֶדְוָה מֵעֵילָא וּמִתַּתָּא. וְיִשְׂרָאֵל אָזְלִין בְּגָלוּתָא וְאִינוּן בִּרְשׁוּ דְּטַעֲוָון אָחֳרָנִין. וּכְדֵין אִתְקְיַּים קְרָא דִּכְתִיב, (דברים כ״ח:ל״ו) וְעָבַדְתָּ שָׁם אֱלֹהִים אֲחֵרִים.","וְכָל דָּא לָמָּה, בְּגִין דִּכְתִיב, (דברים כ״ח:מ״ז) תַּחַת אֲשֶׁר לא עָבַדְתָּ אֶת יְיָ אֱלֹהֶיךָ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרוֹב כֹּל. מַאי מֵרוֹב כֹּל. הָכָא מֵרוֹב כֹּל, וְהָתָם בְּחֹסֶר כֹּל.","עַד דְּיִתְעַר קוּדְשָׁא בְּרִיךְ הוּא וְיִפְרוֹק לוֹן מִבֵּינִי עַמְמַיָא, כְּמָא דְאַתְּ אָמֵר, (דברים ל׳:ג׳) וְשָׁב יְיָ אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְרִחַמְךָ וְשָׁב וְקִבֶּצְךָ מִכָּל הָעַמִּים אֲשֶׁר הֶפִיצְךָ יְיָ אֱלהֶיךָ שָׁמָּה. וּכְתִיב אִם יִהְיֶה נִדַּחֲךָ בִּקְצֵה הַשָּׁמַיִם מִשָּׁם יְקַבֶּצְךָ וְגו':","וְאֵלֶּה תּוֹלְדוֹת עֵשָׂו הוּא אֱדוֹם. תָּא חֲזֵי, בְּחַיֵּי יִצְחָק לָא אִתְמַנּוּן בְּנוֹי דְעֵשָׂו כְּמָה דְּאִתְמַנּוּן בְּנוֹי דְיַעֲקֹב, דְּהָא עַד לָא מִית יִצְחָק אִתְמַנּוּן. אֲבָל בְּעֵשָׂו מַה כְּתִיב וַיִּגְוַע יִצְחָק וַיָּמָת וַיֵּאָסֶף אֶל עַמָּיו זָקֵן וּשְׂבַע יָמִים וַיִּקְבְּרוּ אֹתוֹ עֵשָׂו וְיַעֲקֹב בָּנָיו. בַּתְרֵיהּ מַה כְּתִיב וְאֵלֶּה תּוֹלְדוֹת עֵשָׂו הוּא אֱדוֹם. מַאי טַעְמָא, בְּגִין דְּהָא בְּחוּלָקֵיהּ וּבְאַחְסַנְתֵיהּ וְעַדְבֵיהּ לָאו אִיהוּ, אֶלָּא יַעֲקֹב וּבְנוֹי. וּבְגִין כָּךְ יַעֲקֹב וּבְנוֹי אִינוּן חוּלָקֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא וְעָאלִין בְּחוּשְׁבְּנָא. אֲבָל עֵשָׂו דְּלָאו אִיהוּ בְּחוּלָקָא דְּבִסְטַר דִּמְהֵימְנוּתָא, עָבִיד חוּשְׁבְּנֵיהּ לְבָתַר דְּמִית יִצְחָק, וְאִתְפְּרַשׁ חוּלָקֵיהּ לְאֲתַר אָחֳרָא.","תָּא חֲזֵי, לְבָתַר דְּמִית יִצְחָק, וְעֵשָׂו אִתְפָּרַשׁ לְסִטְרֵיהּ, מַה כְּתִיב וַיִקַּח עֵשָׂו אֶת נָשָׁיו וְגו' מִפְּנֵי יַעֲקֹב אָחִיו. דְּשָׁבַק לֵיהּ לְיַעֲקֹב קֶרֶן וְרֶיוַח שִׁעְבּוּדָא דְמִצְרַיִם, וְאַרְעָא. וְזַבִּין לֵיהּ חוּלָקֵיהּ מִן מְעַרְתָּא דְכָפֶלְתָּא, וְאֲזַל לֵיהּ מִן אַרְעָא וּמִן מְהֵימְנוּתָא וּמֵחוּלָקֵיהּ, דְּאֲזַל לֵיהּ מִכֹּלָּא.","תָּא חֲזֵי, כַּמָּה הֲוָה חוּלָקֵיהּ דְּיַעֲקֹב טָבָא בְּכֹלָּא. בְּגִין דְּלָא אִשְׁתָּאַר עֵשָׂו בַּהֲדֵיהּ וְאִתְפְּרַשׁ מִנֵּיהּ וְאֲזַל לֵיהּ לְחוּלָקֵיהּ וּלְעַדְבֵיהּ, וְאִשְׁתָּאַר יַעֲקֹב אָחִיד בְּאַחְסָנַת אֲבוֹי וּבְאַחְסָנַת אַבְהָתוֹי. וְעַל דָּא וַיֵּלֶךְ אֶל אֶרֶץ מִפְּנֵי יַעֲקֹב אָחִיו. מַאי מִפְּנֵי יַעֲקֹב אָחִיו. דְּלָא בָּעָא חוּלָקֵיהּ וְאַחְסַנְתֵּיהּ וְעַדְבָא דִמְהֵימְנוּתָא דִילֵיהּ. זַכָּאָה חוּלָקֵיהּ דְּיַעֲקֹב עֲלֵיהּ כְּתִיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ:","וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. רַבִּי יֵיסָא פָּתַח וְאָמַר, (עובדיה א׳:ב׳) הִנֵּה קָטָן נְתַתִּיךָ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד. תָּא חֲזֵי, כַּד עֲבַד קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, וּפָלַג אַרְעָא לְשִׁבְעָה תְּחוּמֵי פְּלִיגִין לָקֳבֵיל שִׁבְעִין רַבְרְבִין מְמַנָּן, וְקוּדְשָׁא בְּרִיךְ הוּא פָּלִיג לוֹן לְשִׁבְעִין עַמִין כָּל חַד וְחַד כְּדְקָא חָזֵי לֵיהּ, כְּמָה דְאַתְּ אָמֵר, (דבהם לכ) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם בְּהַפְרִידוֹ בְּנֵי אָדָם יַצֵב גְּבוּלוֹת עַמִים.","וּמִכֻּלְּהוּ רַבְרְבָן מְמַנָּן דְּאִתְמַסְרוּ לִשְׁאָר עַמִין לָא אִית בְּהוּ בָּזוּי קַמֵּיהּ כִּמְמַנָּא דְעֵשָׂו. מַאי טַעֲמָא, בְּגִין דְּסִטְרָא דְעֵשָׂו סִטְרָא מְסָאֲבָא אִיהוּ, וְסִטְרָא דִמְסָאֲבָא אִיהוּ קְלָנָא קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא. מֵאִינוּן דַּרְגִּין זְעִירִין דְּבָתַר רֵיחַיָא סְרִיקְתָּא דְּקוֹסְטְרֵי סוּמְקֵי קָא אַתְיָא, וְעַל דָּא הִנֵּה קָטָן נְתַתִּיךָ בַּגּוֹיִם, בָּזוּי אַתָּה מְאֹד. דִּכְתִיב, (בראשית ג׳:י״ד) עַל גְּחוֹנְךָ תֵּלֵךְ וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךָ. מְאֹד, כְּמָה דְאַתְּ אָמֵר אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וּמִכָּל חַיַּת הַשָּׂדֶה.","תָּא חֲזֵי, בְּדַרְגִּין תַּתָּאִין אִית דַּרְגִּין עַל דַּרְגִּין, כֻּלְּהוּ מְשַׁנְיָין דָּא מִן דָּא, וְכֻלְּהוּ דַרְגִּין קַפְטִירִין אִלֵּין, וּקְשִׁירִין אִלֵּין בְּאִלֵּין, וּמַלְכוּ אִתְפָּרַשׁ דָּא מִן דָּא, וּמַלְכוּ אִתְקַשַּׁר בְּמַלְכוּ. דָּא עֲיִּיל, וְדָא סָלִיק, אֲחִידָן בְּקִשְׁרָא חָדָא.","הַהוּא קִשְׁרָא מִשְׁחָתָא חָדָא לֵיהּ, וּתְלַת קִשְׁרִין לְהַהִיא מִשְׁחָתָא. בְּכָל קִשְׁרָא וְקִשְׁרָא חַד עִטְּרָא, וּבְכָל עִטְּרָא וְעִטְּרָא חַד קַפְסוֹרָא","וְאִתְמַנָּא בְּעִטּוּרָא דִלְעֵילָא, וְאִתְמַנָּא וְנָחִית לְתַתָּא, עַד דְּאִתְקַשְּׁרוּ בֵּיהּ כֹּכְבַיָא וּמַזָּלֵי. כָּל חַד וְחַד אִתְפְּרַשׁ בֵּיהּ חַד כֹּכָבָא וְחַד מַזָּלָא, וְכָל כֹּכְבַיָא זְמִינִין אִינוּן בְּאִינוּן דַּרְגִּין דִּלְעֵילָא. וְעַל דָּא כָּל דַּרְגָּא וְדַרְגָּא אִתְעַטַּר בְּאַתְרִין יְדִיעָן כְּדְקָא חָזֵי."],[[0,"ומיומא דאתחריב וכו':","ומיום שנחרב בית המקדש, אין לך יום ויום שאין בו זעם ורוגז, כמו שאתה אומר, ואל זועם בכל יום. והוסרה השמחה מלמעלה ומלמטה, וישראל הולכים בגלות, והם ברשות אלהים אחרים. ואז מתקיים המקרא שכתוב, ועבדת שם אלהים אחרים."],[1,"וכל דא למה וכו'",": ושואל, וכל זה למה הגיע לישראל. ומשיב, משום שכתוב, תחת אשר לא עבדת את ה' אלקיך בשמחה ובטוב לבב מרוב כל. ושואל, מהו \u0003מרוב כל.\u0004 ומשיב, כאן מרוב כל, ושם בחסר כל."],[1,"","פירוש, היסוד נקרא \u0003כל\u0004 בסו\"ה כי \u0003כל\u0004 בשמים ובארץ. וכשישראל היו בארץ היה היסוד מאיר להם וז\"ש \u0003הכא,\u0004 דהיינו בארץ, נאמר \u0003מרוב כל,\u0004 כי היסוד, ה\"ס נהרא דנגיד ונפיק אשתקיא כלא ונהירו כל אנפין (כנ\"ל באות רכ\"ח) \u0003והתם\u0004 דהיינו בחוץ לארץ, בגלות, נאמר \u0003בחסר כל,\u0004 שאין היסוד מאיר שם וע\"כ ועבדת את אויביך וגו'. שנאמר, ועבדת את אויביך אשר ישלחנו ה' בך ברעב ובצמא ובעירום ובחסר כל."],[2,"עד דיתער וכו':","עד שיתעורר הקב\"ה ויגאל אותנו מבין העמים. כמש\"א, ושב ה' אלקיך את שבותך וגו' וכתוב אם יהיה נדחך וגו'."],[3,"ואלה תולדות עשו וגו':","בוא וראה, בחיי יצחק לא נמנו בניו של עשו כמו שנמנו בניו של יעקב, שנמנו מטרם מיתת יצחק, אבל בעשו מה כתוב, ויגוע יצחק וגו', אחריו מה כתוב, ואלה תולדות עשו הוא אדום. ולא נמנו בחיי יצחק, מה הטעם, הוא משום שבחלקו ונחלתו וגורלו של יצחק אינם אלא יעקב ובניו. ומשום זה יעקב ובניו שהם חלקו של הקב\"ה, נכנסו בחשבון, אבל עשו שהוא אינו בחלקו של צד האמונה, עשה הכתוב חשבונו לאחר שמת יצחק, שאז נפרד חלקו מקדושה למקום אחר."],[4,"ת\"ח לבתר וכו':","בוא וראה, אחר שמת יצחק, ועשו נפרד אל הצד שלו, מה כתוב, ויקח עשו את נשיו וגו' מפני יעקב אחיו. כי הניח ליעקב את הקרן ואת הריוח, הניח לו את שעבוד מצרים שהוא הקרן, וגם את הריוח משעבוד מצרים שהוא ירושת הארץ, ומכר לו חלקו שבמערת המכפלה, והלך לו מן הארץ ומן האמונה, ומחלקו, שהלך לו ונסתלק מכל."],[5,"ת\"ח כמה הוה וכו':","בוא וראה, כמה היה חלקו של יעקב טוב בכל, אשר עשו לא נשאר עמו, ונפרד ממנו והלך לו לחלקו וגורלו, ונשאר יעקב אוחז בנחלת אביו ונחלת אבותיו. ועל כן כתוב, וילך אל ארץ מפני יעקב אחיו. ושואל, מהו שכתוב מפני יעקב אחיו. ומשיב, שלא רצה חלקו ונחלתו וגורל האמונה של יעקב. אשרי חלקו של יעקב, עליו כתוב, כי חלק ה' עמו יעקב חבל נחלתו."],[6,"ואלה המלכים אשר מלכו וגו':","רבי ייסא פתח ואמר, הנה קטן נתתיך בגוים בזוי אתה מאד. בוא וראה, כשעשה הקב\"ה את העולם, וחלק את הארץ לשבעה גבולות, מחולקים כנגד שבעים השרים הממונים על אומות העולם, שה\"ס חצוניות, וה\"ס חג\"ת נהי\"ם שכל אחת כלולה מעשר, והם ע'. והקב\"ה חלק אותם ע' ממונים לשבעים אומות, כל אחד ואחד כראוי לו, כמ\"ש בהנחל עליון גוים בהפרידו בני אדם יצב גבולות עמים למספר בני ישראל."],[7,"ומכלהו רברבן וכו':","ומכל השרים הממונים שנמסרו לכל האומות אין בזוי לפני הקב\"ה, כממונה של עשו. מהו הטעם, משום שהצד של עשו הוא צד הטומאה, וצד הטומאה הוא בזיון לפני הקב\"ה ומאלו המדרגות הקטנות שלאחר הריחים, ומן הריקנות שבמדות האדומות, בא שרו של עשו, ועל כן הנה קטן נתתיך וגו'. שכתוב, על גחונך תלך וגו'. \u0003מאד,\u0004 כמש\"א ארור אתה מכל הבהמה וגו'."],[7,"","פירוש. \u0003ריחים ורכב,\u0004 ה\"ס נצח והוד המכונים שחקים שטוחנות מן לצדיקים שנצח מכונה רכב, והוד ריחים. ומכונים כן, משום שיש בהוד בחינת הדין הקשה, שמשם נתקן המסך דמנעולא, וע\"כ הכל נטחן עליו, ומשם הצדיקים מעלים מ\"ן. (כמ\"ש בתע\"ס בשיעור י\"ג דף א' ל\"ה ד\"ה תרין ע\"ש). ונודע שהדין אינו פועל למעלה ממקום מציאותו, אלא רק למטה ממקום מציאותו. ולפיכך המדרגות שהם אחר הריחים, שה\"ס הוד דז\"א, נפעלות מן הדין הקשה שבריחים, ואינן יכולות לקבל גדלות, והן בקטנות. גם נודע שהמדרגות הנמשכות מקו שמאל, בשעה שמאיר ממעלה למטה, הן בריקנות מכל אור, משום שהנוקבא נבחנת אז לימא דקאפו. (כנ\"ל ב\"א דף רמ\"ז אות ש\"ב ע\"ש בסולם). ואלו ב' החסרונות נמצאים בשרו של עשו."],[7,"","וז\"ש \u0003מאינון דרגין זעירין דבתר ריחיא,\u0004 ששרו של עשו בא מהבחינות הקטנות הנוהגות במדרגות שלאחר הריחים, מפאת הדין הקשה שנמצא שם כנ\"ל, וע\"כ הוא קטן. ועוד מן \u0003סריקתא דקוסטרי סומקי קא אתיא,\u0004 כי הוא בא מקו שמאל, בעת שמאיר ממעלה למטה, והוא חכמה בלי חסדים, שאז כל המדרגות הנמשכות משם הו בריקנות, וז\"ש \u0003ועל דא הנה קטן נתתיך\u0004 וגו'. שב' דברים אומר הכתוב עליו, א) \u0003הנה קטן נתתיך בגוים,\u0004 והוא להיותו נמשך \u0003מדרגין זעירין דבתר ריחיא.\u0004 ב) \u0003בזוי אתה מאד,\u0004 והוא להיותו נמשך מקו שמאל, והוא בבחינת \u0003סריקתא דקוסטרי סומקי,\u0004 שקו השמאל נמשך מבינה, שנבחנת לגוון אדום כנודע, ולהיותו בריקנות נבחן לבזוי, והוא ג\"כ בחינת הנחש הקדמוני, שנאמר עליו, על גחונך תלך ועפר תאכל וגו'. כי להיותו מאחר הריחים נקצצו לו הרגלים מכח הדין הקשה אשר שם, ונתקלל \u0003על גחונך תלך.\u0004 ולהיותו משמאל הוא בריקנות, ונתקלל \u0003ועפר תאכל כל ימי חייך.\u0004 ואמרו, \u0003מאד,\u0004 אצל עשו, שנאמר, בזוי אתה \u0003מאד\u0004, הוא ג\"כ בדומה לנחש שנתקלל, ארור אתה מכל הבהמה ומכל חית השדה."],[7,"","ודע שקוטב כל המאמר הזה, הוא לבאר הטעם, למה מלכו מלכי אדום לפני מלך מלך לבני ישראל. וזה נודע, שהקטן נתתקן תחילה ואחר כך הגדול, ולפי\"ז היה צריך שיעקב יתתקן תחילה ואחר כך עשו, ולא להיפך, כי הכתוב אומר ויקרא את עשו בנו הגדול. ויעקב הוא הקטן. וזהו שהזהר בא לבאר לפנינו, שמבחינת השורשים של יעקב ועשו, נבחן עשו לקטן ויעקב גדול ממנו. וע\"כ מביא הכתוב הנה קטן נתתיך בגוים, וכמו שיתבאר עוד לפנינו."],[8,"ת\"ח בדרגין תתאין וכו':","בוא וראה, במדרגות התחתונות דהיינו המדרגות שמחזה ולמטה דזו\"ן ששם החסדים מתגלים בחכמה. יש מדרגות על מדרגות, וכולן משונות זו מזו. וכל המדרגות הן פרודות, וגם מקושרות אלו באלו, באופן שהמלכיות מכל המדרגות נפרדות זו מזו, וגם מלכות מתקשרת במלכות. ומפרש הטעם, משום שהסדר הוא, זה נכנס וזה עולה, ונמצאים מאוחדים בקשר אחד. פירוש, שאור החסדים \u0003נכנס\u0004 ע\"י מסך דחירק שבקו אמצעי. ואז אור החכמה שבשמאל \u0003עולה\u0004 ומאיר ממטה למעלה, וע\"כ \u0003מאוחדים\u0004 כל שלשת הקוין \u0003בקשר אחד\u0004 של הקו האמצעי. (כמ\"ש לעיל ב\"א דף ט\"ו ד\"ה ההיא ע\"ש). כי לולא אור החסדים שבקו ימין לא האירה החכמה שבשמאל, ולולא הקו האמצעי לא היו מתלבשים הימין והשמאל זב\"ז, ונמצאים שלשתם מקושרים זב\"ז. וענין הפרודות שבהם יתבאר לפנינו."],[9,"ההוא קשרא וכו':","הקשר ההוא דהיינו מסך דחירק יש לו קומה אחת, דהיינו קומת קו אמצעי, היוצאת על מסך דחירק, ושלשה קשרים יש באותה הקומה. כי קו אמצעי כולל בתוכו כל שלשת הקוין. ובכל קשר וקשר יש עטרה אחת, דהיינו ג\"ר המכונות עטרה, בסו\"ה בעטרה שעטרה לו אמו וגו'. ובכל עטרה ועטרה כח שליטה אחת. דהיינו כח המסך דמנעולא שה\"ס המלכות דצמצום א', המשמש בג\"ר דכל מדרגה. (כנ\"ל בהקדמת הזהר דף נ\"ה ד\"ה וטעם. עש\"ה)."],[10,"ואתמנא בעטורא דלעילא וכו':","ונתמנה כח השליטה ההיא, דהיינו המנעולא כנ\"ל, בעיטור שלמעלה, דהיינו בג\"ר המדרגה, ששם נקבע מקומו, כנ\"ל בדבור הסמוך, וגם נתמנה לרדת למטה, לו\"ק המדרגה, עד שנקשרו בו הכוכבים והמזלות. וכל אחד ואחד, דהיינו כל כח שליטה שיש בכל אחת מג' העטרות הנ\"ל, יש בו ככב אחד ומזל אחד. וכל הככבים מתיחסים למדרגות שלמעלה, וכל המזלות למדרגות של מטה, ועל כן כל מדרגה ומדרגה מתעטרת במקומות ידועים כראוי לכל אחת."],[10,"","ביאור הדברים. \u0003מזל,\u0004 פירושו, קיבוץ ככבים המקושרים זה בזה, ומהלך אחד משותף לכולם. \u0003ככבים,\u0004 מורה, שאינם מקושרים זה בזה, וכל אחד פונה לדרכו. ונתבאר לעיל בסמוך, סוד הקשר של הספירות, שהוא מטעם, שאין החכמה מאירה בלי חסדים שבימין, ואין החכמה מקבלת החסדים שבימין, זולת על ידי הכרעת הקו האמצעי, ונמצאים שלשתם צריכים זה לזה ומקושרים זה בזה. ולפי\"ז כל סבת הקשר הוא, משום אור החכמה, שאינו יכול להאיר בלי חסדים, וע\"כ נוהג זה רק בו\"ק של כל מדרגה, ששם מאיר המפתחא, שה\"ס עטרת יסוד, וה \u0003י'\u0004 יוצאת מ \u0003אויר,\u0004 ונתגלה שם \u0003אור\u0004 החכמה, מה שאין כן בג\"ר של כל מדרגה, ששם שולט כח המנעולא, שה\"ס המלכות דצמצום א', ואין ה \u0003א'\u0004 יוצאת מ \u0003אויר\u0004 שלהן (כנ\"ל בהקדמת הזהר דף נ\"ה ד\"ה וטעם עש\"ה) והחסדים מכוסים ונעלמים מחכמה, אם כן אין שום סבה לקו האמצעי שיצטרך לקשר הספירות זו בזו. ולפיכך הן נבחנות לפרודות. ומטעם זה הספירות שבו\"ק המדרגה, שהן מקושרות זו בזו, מכונות \u0003מזל\u0004, שהככבים שבו מקושרים זה בזה, כנ\"ל. והספירות שבג\"ר המדרגה, מכונות \u0003כוכבים\u0004 דהיינו שנפרדות זו מזו כמו כוכבים נפרדים. וזסו\"ה ופניהם וכנפיהם פרודות מלמעלה, (יחזקאל א') כי מחוברות למטה בו\"ק, ופרודות מלמעלה בג\"ר כמו שנתבאר. ותבין שאין הפירוש, שאין תיקון קוין בג\"ר, כי אין משהו בו\"ק שלא יהיה מקובל מג\"ר, אלא המדובר הוא בענין השליטה בלבד, כלומר שאין שום שליטה לכח הקישור אשר שם, ודומה כמו שאינו. וע\"כ נקראות ככבים."],[10,"","ומ\"ש, שכח השליטה של המנעולא, הוא בג\"ר של המדרגה, היינו רק עיקר מציאותו, אבל הארתו מתפשטת ויורדת בו\"ק של המדרגה. וזה אמרו, \u0003ואתמנא בעטורא דלעילא\u0004 שכח השליטה של המנעולא נתמנה בג\"ר המדרגה, והיינו עיקר מציאותו. \u0003ואתמנא ונחית לתתא,\u0004 שמבחינת הארתו יורד ומאיר למטה בו\"ק המדרגה. עד \u0003דאתקשרו ביה ככביא ומזלי,\u0004 כי נכללו בו ג\"ר המכונות ככבים, וו\"ק המכונות מזלות, כנ\"ל, אלא מציאותו היא בככבים והארתו במזלות. \u0003כל חד וחד אתפרש ביה חד ככבא וחד מזלא.\u0004 כלומר שלאו דוקא כח השליטה שבשמאל נוהג בו כוכב ומזל, אלא אפילו כח השליטה שבימין שכולו חסדים, מ\"מ נוהג גם בו כוכב ומזל, שמבחינת כוכב אין בו התכללות חכמה, ומבחינת מזל יש בו התכללות מחכמה. \u0003וכל ככביא זמינין אינון באינון דרגין דלעילא,\u0004 מפרש, שהכוכבים מתיחסים לג\"ר המדרגה, ומתוכו נשמע, שהמזלות מתיחסים לו\"ק של המדרגה, כמבואר לעיל. \u0003ועל דא כל דרגא ודרגא אתעטר באתרין ידיען כדקא חזי,\u0004 וע\"כ יש ב' מינים של ג\"ר, א) מבחינת חסדים, המקובלים מג\"ר המדרגה, שה\"ס אוירא דכיא. ב) מבחינת חכמה, המקובלות מו\"ק של המדרגה. והרי יש ב' מיני עיטור, וכל מדרגה מתעטרת לפי בחינתה הראויה לה."]],[[0,"","וּמִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ אֵין לְךְ יוֹם וָיוֹם שֶׁאֵין בּוֹ זַעַם וְרֹגֶז, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם, וּפָרְשָׁה הַחֶדְוָה מִלְמַעְלָה וּמִלְּמַטָּה, וְיִשְׂרָאֵל הוֹלְכִים בַּגָּלוּת, וְהֵם בְּרָשׁוּת שֶׁל עֲבוֹדוֹת זָרוֹת אֲחֵרוֹת, וְאָז הִתְקַיֵּם הַפָּסוּק שֶׁכָּתוּב (דברים כח) וְעָבַדְתָּ שָּׁם אֱלֹהִים אֲחֵרִים."],[1,"","וְכָל זֶה לָמָּה? מִשּׁוּם שֶׁכָּתוּב (שם) תַּחַת אֲשֶׁר לֹא עָבַדְתָּ אֶת ה' אֱלֹהֶיךְ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרֹב כֹּל. מַה זֶּה מֵרֹב כֹּל? כָּאן מֵרֹב כֹּל, וְשָׁם מֵחֹסֶר כֹּל."],[2,"","עַד שֶׁיִּתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא וְיִפְדֶּה אוֹתָם מִבֵּין הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (שם ל) וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְרִחֲמֶךְ וְשָׁב וְקִבֶּצְךְ מִכָּל הָעַמִּים אֲשֶׁר הֱפִיצְךְ ה' אֱלֹהֶיךְ שָׁמָּה. וְכָתוּב אִם יִהְיֶה נִדַּחֲךְ בִּקְצֵה הַשָּׁמָיִם מִשָּׁם יְקַבֶּצְךְ וְגוֹ'."],[3,"","וְאֵלֶּה תֹּלְדוֹת עֵשָׂו הוּא אֱדוֹם. בֹּא רְאֵה, בְּחַיֵּי יִצְחָק לֹא נִמְנוּ בְּנֵי עֵשָׂו כְּמוֹ שֶׁנִּמְנוּ בְּנֵי יַעֲקֹב, שֶׁהֲרֵי עַד שֶׁלֹּא מֵת יִצְחָק הֵם נִמְנוּ, אֲבָל בְּעֵשָׂו מַה כָּתוּב? וַיִּגְוַע יִצְחָק וַיָּמָת וָיֵּאָסֶף אֶל עַמָּיו זָקֵן וּשְׂבַע יָמִים וַיִּקְבְּרוּ אֹתוֹ עֵשָׂו וְיַעֲקֹב בָּנָיו. אַחֲרָיו מַה כָּתוּב? וְאֵלֶּה תֹּלְדוֹת עֵשָׂו הוּא אֱדוֹם. מָה הַטַּעַם? מִשּׁוּם שֶׁאֵינוֹ בְּחֶלְקוֹ וּבִירֻשָּׁתוֹ וּבְגוֹרָלוֹ, אֶלָּא יַעֲקֹב וּבָנָיו. וְלָכֵן יַעֲקֹב וּבָנָיו הֵם חֶלְקוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִכְנָסִים בַּחֶשְׁבּוֹן. אֲבָל עֵשָׂו שֶׁאֵינוֹ בַּחֵלֶק שֶׁל צַד הָאֱמוּנָה, עָשָׂה חֶשְׁבּוֹנוֹ אַחַר שֶׁמֵּת יִצְחָק, וְנִפְרַד חֶלְקוֹ לְמָקוֹם אַחֵר."],[4,"","בֹּא רְאֵה, אַחֲרֵי שֶׁמֵּת יִצְחָק וְעֵשָׂו נִפְרַד לַצַּד שֶׁלּוֹ, מַה כָּתוּב? וַיִּקַּח עֵשָׂו אֶת נָשָׁיו וְגוֹ' מִפְּנֵי יַעֲקֹב אָחִיו. שֶׁהִשְׁאִיר לְיַעֲקֹב קֶרֶן וְרֶוַח שִׁעְבּוּד מִצְרַיִם, וְהָאָרֶץ, וּמָכַר לוֹ חֶלְקוֹ בִּמְעָרַת הַמַּכְפֵּלָה, וְהָלַךְ לוֹ מִן הָאָרֶץ וּמִן הָאֱמוּנָה וּמֵחֶלְקוֹ, שֶׁהָלַךְ לוֹ מֵהַכֹּל."],[5,"","בֹּא רְאֵה כַּמָּה הָיָה חֶלְקוֹ שֶׁל יַעֲקֹב טוֹב בַּכֹּל מִשּׁוּם שֶׁלֹּא נִשְׁאַר עֵשָׂו עִמּוֹ וְנִפְרַד מִמֶּנּוּ וְהָלַךְ לוֹ לְחֶלְקוֹ וּלְגוֹרָלוֹ, וְנִשְׁאַר יַעֲקֹב אָחוּז בִּירֻשַּׁת אָבִיו וּבִירֻשַּׁת אֲבוֹתָיו. וְעַל זֶה וַיֵּלֶךְ אֶל אֶרֶץ מִפְּנֵי יַעֲקֹב אָחִיו. מַה זֶּה מִפְּנֵי יַעֲקֹב אָחִיו? שֶׁלֹּא רָצָה חֶלְקוֹ וִירֻשָּׁתוֹ וְגוֹרַל הָאֱמוּנָה שֶׁלּוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל יַעֲקֹב, עָלָיו כָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ."],[6,"","וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. רַבִּי יֵיסָא פָּתַח וְאָמַר, (עובדיה א) הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד. בֹּא רְאֵה, כְּשֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם וְחִלֵּק אֶת הָאָרֶץ לְשִׁבְעָה תְּחוּמֵי חֲלָקִים כְּנֶגֶד שִׁבְעִים מְמֻנִּים גְּדוֹלִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חִלֵּק אוֹתָם לְשִׁבְעִים עַמִּים, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם בְּהַפְרִידוֹ בְּנֵי אָדָם יַצֵּב גְּבֻלֹת עַמִּים."],[7,"","וּמִכָּל הַמְמֻנִּים הַגְּדוֹלִים שֶׁנִּמְסְרוּ לִשְׁאָר הָעַמִּים אֵין בָּהֶם בָּזוּי לְפָנָיו כַּמְמֻנֶּה שֶׁל עֵשָׂו, מָה הַטַּעַם? מִשּׁוּם שֶׁהַצַּד שֶׁל עֵשָׂו הוּא צַד הַטֻּמְאָה, וְצַד הַטֻּמְאָה הוּא קָלוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָן דְּרָגוֹת קְטַנּוֹת שֶׁאַחַר הָרֵיחַיִם, שֶׁבָּא מֵהָרֵיקָנוּת שֶׁל הַמִּדּוֹת הָאֲדֻמּוֹת, וְעַל זֶה הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד, שֶׁכָּתוּב (בראשית ג) עַל גְּחֹנְךְ תֵלֵךְ וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ. מְאֹד, כְּמוֹ שֶׁנֶּאֱמַר אַתָּה מִכָּל הַבְּהֵמָה וּמִכֹּל חַיַּת הַשָּׂדֶה."],[8,"","בֹּא רְאֵה, בַּדְּרָגוֹת הַתַּחְתּוֹנוֹת יֵשׁ דְּרָגוֹת עַל דְּרָגוֹת, כֻּלָּם מְשֻׁנִּים זֶה מִזֶּה, וְכָל הַדְּרָגוֹת נִפְרָדוֹת הֵן, וּקְשׁוּרוֹת אֵלֶּה בְאֵלֶּה, וּמַלְכוּת נִפְרֶדֶת זֶה מִזֶּה, וּמַלְכוּת קְשׁוּרָה בְמַלְכוּת, זֶה נִכְנָס וְזֶה עוֹלֶה, אֲחוּזִים בְּקֶשֶׁר אֶחָד."],[9,"","לְאוֹתוֹ קֶשֶׁר יֵשׁ קוֹמָה אַחַת, וּשְׁלֹשָׁה קְשָׁרִים לְאוֹתָהּ קוֹמָה. בְּכָל קֶשֶׁר וְקֶשֶׁר עֲטָרָה אַחַת, וּבְכָל עֲטָרָה וַעֲטָרָה שְׁלִיטָה אַחַת,"],[10,"","וְהִתְמַנָּה בָּעִטּוּר שֶׁלְּמַעְלָה, וְהִתְמַנָּה וְיָרַד לְמַטָּה, עַד שֶׁהִתְקַשְּׁרוּ בוֹ כּוֹכָבִים וּמַזָּלוֹת. כָּל אֶחָד וְאֶחָד נִפְרָד בּוֹ כּוֹכָב אֶחָד וּמַזָּל אֶחָד, וְכָל הַכּוֹכָבִים מְזֻמָּנִים הֵם בְּאוֹתָן דְּרָגוֹת שֶׁלְּמַעְלָה. וְעַל זֶה כָּל דַּרְגָּה וְדַרְגָּה מִתְעַטֶּרֶת בִּמְקוֹמוֹת יְדוּעִים כָּרָאוּי."]]],[["וְכַד מִתְפָּרְשָׁן דַּרְגִּין אִשְׁתַּכַּח קִטּוּרָא דְּפוּסְתָּקָא, עַד דְּאִתְקַשְּׁרָא בְּסִטְרָא דְּאִתְחֲזֵי לוֹן, וְסִטְרֵי דְדַרְגֵי מְסָאֲבֵי דְּאִינוּן בִּסְטַר שְׂמָאלָא כֻּלְּהוּ מִתְפָּרְשָׁן לְכַמָּה אָרְחִין וּשְׁבִילִין מִסִּטְרֵי גְּבוּרָן סוּמְקָן. וּבְגִין כָּךְ תַּלְיָין גְּבוּרָן לְתַתָּא לְאֶלֶף אַלְפִין וְרִבּוֹ רִבְבָן, וְעַל דָּא הִנֵּה קָטָן נְתַתִּיךָ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד כִּדְקָאֲמָרָן.","תָּא חֲזֵי, וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם. בְּאֶרֶץ, בְּסִטְרָא דְדַרְגָּא דִּילֵיהּ דְּאִיהוּ דַּרְגָּא דְעֵשָׂו. דִּכְתִיב עֵשָׂו הוּא אֱדוֹם, וְכֻלְּהוּ קָאָתוּ מִסִּטְרָא דְרוּחַ מְסָאֲבָא. לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל, בְּגִין דְּאִינוּן דַּרְגִּין דְּקַיָּימִין בֵּי תַּרְעֵי לְתַתָּא קַדְמָאי. וּבְגִין כָּךְ אָמַר יַעֲקֹב, יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ. בְּגִין דַּרְגִּין דִּילֵיהּ קַדְמָאִין אִינוּן לְאָעֳלָא. וּבְגִין כָךְ לִפְנֵי מְלָךְ מֶלֶךְ לִבְנִי יִשְׂרָאֵל. דְּעַד כְּעָן לָא מָטָא זִמְנָא דְּמַלְכוּ שְׁמַיָא לְשַׁלְטָאָה וּלְאִתְאַחֲדָא בִּבְנִי יִשְׂרָאֵל. וּבְגִין כָּךְ אָמַר יַעֲבָר נָא אֲדֹנִי לִפְנִי עַבְדּוֹ.","וְכַד שְׁלִימוּ אִלֵּין דַּרְגִּין בְּקַדְמִיתָא, לְבָתַר אִתְעַר מַלְכוּ שְׁמַיָא לְשַׁלְטָאָה עַל תַּתָּאֵי. וְכַד שָׁרָא, שָׁרָא בִּזְעִירָא דְּכָל שִׁבְטִין דְּאִיהוּ בִּנְיָמִין. כְּמָה דְאַתְּ אָמֵר, (תהילים ס״ח:כ״ח) שָׁם בִּנְיָמִין צָעִיר רוֹדֵם וְגו'. וּבֵיהּ שָׁארֵי לְאַתְעָרָא מַלְכוּתָא, לְבָתַר אֲתָא מַלְכוּתָא בְּאַתְרֵיהּ וְאִתְקְיַּים בַּהֲדֵיהּ דְּלָא תַעֲדֵי לְעָלְמִין.","רִבִּי חִיָּיא פָּתַח וְאָמַר, (ישעיהו מ״ה:א׳) וְעַתָּה שְׁמַע יַעֲקֹב עַבְדִּי וְיִשְׂרָאֵל בָּחַרְתִּי בוֹ. כֹּה אָמַר יְיָ עֹשֶׂךָ וְיֹצֶרְךָ מִבֶּטֶן יַעַזְרֶךָּ אַל תִּירָא עַבְדִּי יַעֲקֹב וִישֻׁרוּן בָּחַרְתִּי בוֹ. תָּא חֲזֵי, כַּמָּה אַבְטַח לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל בְּכַמָּה אֲתַר (ד\"א ל\"ג בגין) לְמִזְכֵּי לְהוּ לְעַלְמָא דְאָתֵי, דְּהָא לָא אִתְרָעֵי לְחוּלָקֵיהּ לְכָל עַם וְלִישָׁן בַּר לְיִשְׂרָאֵל בִּלְחוֹדוֹי. וּבְגִין כָּךְ יָהַב לוֹן אוֹרַיְיתָא דִקְשׁוֹט. לְמִזְכֵּי בָּהּ וּלְמִנְדַע אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּיִרְתוּן אַרְעָא קַדִּישָׁא. דְּכָל מַאן דְּזָכֵי בְּהַאי אַרְעָא קַדִּישָׁא, אִית לֵיהּ חוּלָקָא לְעַלְמָא דְאָתֵי. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ. וְהָא אִתְּמָר.","תְּלַת דַּרְגִּין הָכָא, בְּקַדְמִיתָא יַעֲקֹב, וּלְבָתַר יִשְׂרָאֵל, וּלְבָתַר יְשׁוּרוּן. תָּא חֲזֵי, יַעֲקֹב הָא אוּקְמוּהָ. יִשְׂרָאֵל אוּף הָכִי נָמֵי. וְאַף עַל גַּב דְּדַרְגִּין אִינוּן חַד.","יְשׁוּרוּן, אַמַּאי אִקְרוּן יִשְׂרָאֵל בִּשְׁמָא דָא. אֶלָּא יִשְׂרָאֵל וִישׁוּרוּן כֹּלָּא חַד. יְשׁוּרוּן, כְּמָה דְאַתְּ אָמֵר, (איוב ל״ג:כ״ז) יָשֹׁר עַל אֲנָשִׁים, בְּגִין דְּנָטִיל שׁוּרָה לְהַאי סִטְרָא וּלְהַאי סִטְרָא, וּבְגִין אִינוּן תְּרֵין שׁוּרִין אִקְרֵי יְשׁוּרוּן, וְדָא הוּא יִשְׂרָאֵל.","יִשְׂרָאֵל עַל דְּנָטִיל רְבוּ וְתוּקְפָא מִכֹּלָּא. יִשְׂרָאֵל (ס\"א ישורון) עַל אִינוּן חוּלָקֵי תְּרֵין סִטְרִין תְּרִין שׁוּרִין כְּדְקָא אֲמָרָן, וְכֹלָּא חַד.","וְאִינוּן שְׁמָהָן כֻּלְּהוּ סָלְקֵי לְחַד. יַעֲקֹב עַבְדִּי, זִמְנִין דְּאִיהוּ עֶבֶד כְּעַבְדָא דְּאִית לֵיהּ פִּקּוּדָא דְמָארֵיהּ וּלְמֶעְבַּד רְעוּתֵיהּ. וְכֵן יִשְׂרָאֵל בָּחַרְתִּי בוֹ, לְאַשְׁרָאָה עֲלֵיהּ, וְכֹלָּא בְּרָזָא עִלָּאָה אִיהוּ. כְּתִיב, (ישעיהו מ״ג:א׳) בֹּרַאֲךָ יַעֲקֹב וְיֹצֶרְךָ יִשְׂרָאֵל, וּכְתִיב כֹּה אָמַר יְיָ עֹשֶׂךָ, כָּל אִלֵּין דַּרְגִּין סָלְקִין לְחַד וְהָא אִתְּמָר, בּוֹרֵ\"א, יוֹצֵ\"ר. עוֹשֶׂ\"ה. וְכֻלְּהוּ דַרְגִּין אִלֵּין עַל אִלֵּין וְכֻלְּהוּ חַד.","זַכָּאָה חוּלַקְהוֹן דְּיִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ מִכָּל עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, בְּגִין דְּבְכֻלְּהוּ כְּתִיב, (ירמיהו י׳:ט״ו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים בְּעֵת פְּקֻדָּתָם יֹאבֵדוּ, בְּשַׁעְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְבַעֲרָא לוֹן מִן עַלְמָא, וְיִשְׁתָּאַר הוּא בִּלְחוֹדוֹי כְּמָה דְאַתְּ אָמֵר, (ישעיהו ב׳:י״א) וְנִשְׂגָּב יְיָ לְבַדּוֹ בַּיּוֹם הַהוּא.","רִבִּי יְהוּדָה פָּתַח וְאָמַר, (ישעיהו מ״א:י״ד) אַל תִּירְאִי תּוֹלַעַת יַעֲקֹב מְתֵי יִשְׂרָאֵל אֲנִי עֲזַרְתִּיךְ נְאֻם יְיָ וְגֹאֲלֵךְ קְדוֹשׁ יִשְׂרָאֵל. תָּא חֲזֵי, כָּל עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת דְּעַלְמָא, קוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן לִמְמַנָּן שָׁלְטָנִין יְדִיעִין כְּמָה דְאִתְּמָר. וְכֻלְּהוּ אָזְלֵי בָּתַר אֱלָהֲהוֹן, כְּמָה דִכְתִיב, (מיכה ד׳:ה׳) כִּי כָל הָעַמִּים יֵלְכוּ אִישׁ בְּשֵׁם אֱלהָיו. וְכֻלְּהוּ אוֹשְׁדִין דָּמִין וּמַגִּיחִין קְרָבָא גָּזְלִין קַפְּחִין וּמְנָאֲפִין, וְאִתְעָרְבֵי בְּכַמָּה עוֹבָדִין לְבִישׁ, וְאִתְתַּקָּפוּ בְּחֵילְהוֹן לְאַבְאָשָׁא."],[[0,"וכד מתפרשן דרגין וכו':","וכשהמדרגות נפרדות, דהיינו בג\"ר, נמצא בהן קשר המפסיק, דהיינו שלימת המנעולא, המפסקת הארת החכמה כנ\"ל, עד שמתקשר במקום הראוי לו. דהיינו עד שהארתו יורדת לו\"ק. ובחינות מדרגות הטומאה, שהן בצד שמאל, כולן מתחלקות לכמה אורחות שהם בחינות מפתחא, ושבילים, שהם בחינות מנעולא, (כנ\"ל ב\"א דף רנ\"א ד\"ה נחית ע\"ש) מבחינות הגבורות האדומות, הנמשכות מבינה שה\"ס אדום. ומשום זה, נבחנות הגבורות שלמטה לאלף אלפים ורבוא רבבות. ועל כן הנה קטן נתתיך בגוים בזוי אתה מאד, כמו שאמרנו."],[0,"","פירוש. אע\"פ שהצד השמאלי נמשך ממקום ו\"ק, ששם מקום שליטת המפתחא, מ\"מ גם הארת המנעולא מתפשטת שמה, וע\"כ צד הטומאה הנמשך מצד שמאל, כלול בהכרח גם משליטת המנעולא, ולפיכך מגיעה לו משם הקטנות, כנ\"ל בסמוך, בביאור הכתוב הנה קטן נתתיך בגוים ע\"ש."],[0,"","וז\"ש \u0003וכד מתפרשן דרגין אשתכח קטורא דפוסתקא,\u0004 שהיא שליטת המנעולא שבמקום ג\"ר, המפסיק הארת החכמה, כנ\"ל. \u0003עד דאתקשרא בסטרא דאתחזי לון\u0004 דהיינו שהארתו מתפשטת גם לו\"ק, אע\"פ ששם מקום שליטת המפתחא, ולפיכך, \u0003וסטרי דדרגי מסאבי\u0004 שהם נמשכים מצד שמאל, שב' השליטות מנעולא ומפתחא מראים שם כחם כנ\"ל. \u0003מתפרשן לכמה ארחין ושבילין,\u0004 כי ממפתחא מתפשטים אורחין, וממנעולא מתפשטים שבילין, כנ\"ל. \u0003ובג\"כ תליין גבורן לתתא\u0004 הנמשכים מצד שמאל \u0003לאלף אלפין ורבו רבבן.\u0004 שהארת המפתחא, שיש בה הארת חכמה, תלויים בה \u0003אלף אלפין,\u0004 כי אלפים הם בחכמה. והארת המנעולא המשמשת בג\"ר, ובחסדים מכוסים תלויים בה \u0003רבבות,\u0004 כי רבבות נמשכות מג\"ר ומבחינת החסדים. \u0003ועל דא הנה קטן נתתיך בגוים,\u0004 שמכח הארת המנעולא נמשכת הקטנות לעשו, כנ\"ל, \u0003בזוי אתה מאד,\u0004 שמכח הארת המפתחא הוא מקבל הארת השמאל ממעלה למטה, שמזה מגיע לו הריקנות ונעשה בזוי מאד (כנ\"ל דף ע\"א ד\"ה וז\"ש ע\"ש)."],[1,"ת\"ח ואלה המלכים אשר מלכו בארץ אדום:","בארץ, היינו בצד המדרגה שהיא מדרגת עשו, שכתוב עשו הוא אדום. וכל אלו המלכים באים מצד רוח הטומאה. \u0003לפני מלך מלך לבני ישראל,\u0004 משום שאלו המדרגות העומדות בבתי שער למטה, דהיינו המדרגות של עשו, הן קודמות להשתלם, ומשום זה אמר יעקב, \u0003יעבר נא אדני לפני עבדו,\u0004 משום שמדרגותיו של עשו הן קודמות להכנס ולהשתלם, כי מתחלה מתתקנות המדרגות הנמוכות ואח\"כ המדרגות הגבוהות. ומשום זה, \u0003לפני מלך מלך לבני ישראל.\u0004 כי עד עתה עוד לא הגיע הזמן של מלכות שמים לשלוט ולהתאחד בבני ישראל ומשום זה אמר, יעבר נא אדני לפני עבדו."],[2,"וכד שלימו אלין וכו':","וכשיושלמו תחילה אלו המדרגות, תתעורר אחר כך מלכות שמים לשלוט על התחתונים. וכשהתחילה לשלוט, התחילה בקטן של כל השבטים, שהוא בנימין, דהיינו שאול המלך שבא מבנימין, זה שכתוב, שם בנימין צעיר רודם וגו'. ובו התחילה המלכות להתעורר. ואחר כך באה המלכות במקומה, לדוד המלך, ונתקיימה בו, שלא תסור ממנו לעולם."],[3,"רבי חייא וכו':","ר\"ח פתח ואמר, ועתה שמע יעקב עבדי וישראל בחרתי בו וגו' וישורון בחרתי בו. בוא וראה, כמה הבטיח הקב\"ה לישראל בכמה מקומות שינחיל להם העולם הבא. כי לא רצה לקבל לחלקו שום עם ולשון רק את ישראל לבדם. ומשום זה נתנה להם תורת אמת, לזכות על ידה ולדעת דרכיו של הקב\"ה, כדי שינחלו את ארץ הקודש. כי כל מי שזכה בארץ הקודש הזאת, יש לו חלק לעולם הבא. כמש\"א, ועמך כולם צדיקים לעולם ירשו ארץ. וכבר בארוהו."],[4,"תלת דרגין הכא וכו':","שלש מדרגות כאן, בכתוב הזה שלפנינו, מתחלה \u0003יעקב,\u0004 ואחר כך \u0003ישראל,\u0004 ואח\"כ \u0003ישורון,\u0004 שצריכים לדעת מהו ההפרש ביניהן. בוא וראה, \u0003יעקב\u0004 כבר בארנו, ישראל גם כן, (דהיינו לעיל דף נ\"א ד\"ה לעיל) אשר יעקב הוא מדדגת ו\"ק בלי ראש, וישראל הוא מדרגת ג\"ר (ע\"ש) ואף על פי שהמדרגות הן אחת, כלומר, אע\"פ ששניהם הם מדרגת ז\"א כמ\"ש שם."],[5,"ישורון אמאי וכו':","ושואל, \u0003ישורון,\u0004 למה נקראים ישראל בשם הזה. ומשיב, אלא ישראל וישורון, הכל אחד, \u0003ישורון\u0004 פירושו, כמו שאתה אומר, \u0003ישור\u0004 על אנשים, משום שלוקח שורה מצד זה ושורה מצד זה, ומשום אלו שתי השורות, נקרא \u0003ישורון\u0004 בלשון רבים. וזה הוא ישראל, שהוא ג\"כ לשון שורה, שהוא נוטריקון \u0003ישר אל.\u0004 והוא לשון יחיד (הביאור הוא להלן בסמוך)."],[6,"ישראל, על דנטיל","וכו': \u0003ישראל\u0004 נקרא עם שין שמאלית, שהיא שררה על שלוקח גדלות ועז מכל. ישורון, נקרא, על שם אלו החלקים, שהם שני צדדים צד ימין וצד שמאל, שהם ב' שורות כמו שאמרנו, והכל אחד."],[6,"","ביאור הדברים. שורות פירושו, קוין. והשם \u0003ישורון\u0004 שהוא לשון רבים, מורה על ב' שורות, וע\"כ כולל בהכרח ב' הקוין העליונים, שהם חכמה ובינה. והשם \u0003ישראל\u0004, שהוא נוטריקון \u0003ישר אל\u0004, הוא ג\"כ לשון שורה, כמו \u0003ישור\u0004 על אנשים, והוא לשון יחיד, וע\"כ מורה על קו אמצעי שהוא דעת, הכולל ב' הקוין העליונים, שהם חו\"ב."],[6,"","וז\"ש (באות רמ\"ז), \u0003ישראל וישורון אינון חד,\u0004 ששניהם בחינת ג\"ר דז\"א, דהיינו בחינת מחזה ולמעלה דז\"א. \u0003ישורון, בגין דנטיל שורה להאי סטרא ולהאי סטרא,\u0004 דהיינו ב' הקוין העליונים ימין ושמאל וכנ\"ל. וע\"כ נקרא \u0003ישורון.\u0004 והוא חכמה ובינה דז\"א כנ\"ל. \u0003ודא הוא ישראל\u0004 וכן הוא השם ישראל מלשון שורה, שהוא נוטריקון \u0003ישר אל,\u0004 והוא קו אמצעי, דעת, שהוא ו\"ק דראש ז\"א, \u0003ישראל,\u0004 נקרא עם שין שמאלית שפירושו, לשון שררה, \u0003על דנטיל רבו ותוקפא מכלא\u0004 להיותו כולל שניהם ע\"כ נוטל \u0003רבו\u0004 מקו ימין, \u0003ותוקפא\u0004 מקו שמאל. \u0003ישורון\u0004 נקרא \u0003על אינון חולקי תרין סטרין, תרין שורין כדקא אמרן,\u0004 שהם ב' הקוין, חכמה ובינה, דראש ז\"א כנ\"ל. \u0003וכלא חד,\u0004 וכל אלו ג' השמות הם אחד, שכולם הם בז\"א."],[7,"ואינון שמהן כלהו וכו':","ומפרש. ואלו השמות כולם עולים לאחד, שהם ג' פרצופין: חב\"ד, חג\"ת, נה\"י, דז\"א, המכונים: בריאה, יצירה, עשיה, דז\"א. שישורון הוא חב\"ד וישראל חג\"ת, ויעקב תנה\"י. וע\"כ אוה\"כ, \u0003יעקב עבדי,\u0004 כי פעמים הוא עבד, כמו עבד שיש לו מצוות רבונו, ועושה רצונו. שזה מורה שאין לו מוחין, והוא משום שהוא פרצוף תנה\"י ובחינת עשיה דז\"א. \u0003וכן ישראל בחרתי בו\u0004 פירושו לשרות בו. דהיינו במוחין דג\"ר כנ\"ל. והכל הוא בסוד העליון. שכל ג' המדרגות הן כולן בסוד הראש. כתוב, \u0003בוראך\u0004 יעקב \u0003ויוצרך ישראל.\u0004 וכתוב, כה אמר ה' \u0003עושך.\u0004 כל אלו המדרגות עולות לאחד שהם ג' פרצופי ז\"א ישורון ישראל ויעקב, שהם חב\"ד חג\"ת נה\"י כנ\"ל, והם בריאה יצירה עשיה כנ\"ל. ולכן נאמר עליהם בורא יוצר עושה וכולם הם מדרגות אלו על אלו וכולם אחד."],[7,"","ואין להקשות לפי המתבאר, היה צריך לומר עושך יעקב, ולא בוראך יעקב. והענין הוא שיש ערך הפוך בין המאורות לכלים. (כנ\"ל בפתיחה לחכמת הקבלה אות כ\"ה ע\"ש) וכשאין בפרצוף אלא בחינת כלים דבריאה אין שם אלא בחינת יעקב, וכשנתוספה בחינת כלים דיצירה בפרצוף יש ג\"כ בחינת ישראל. וכשנתוספו כלים דעשיה בפרצוף יש ג\"כ בחינת ישורון. עש\"ה. וע\"כ נאמר בוראך יעקב ויוצרך ישראל. ומה שנאמר שישראל הוא יצירה וחג\"ת, אין הכונה שהוא בחינת ו\"ק בלי ראש, כי כל המדובר כאן הוא רק בבחינת מוחין וראש, דהיינו בג' פרצופין חב\"ד חג\"ת נה\"י שבראש ז\"א. כמו שאומר לעיל, \u0003וכלא ברזא עלאה איהו.\u0004"],[8,"זכאה חולקהון וכו':","אשרי חלקם של ישראל, שהקב\"ה רצה בהם מכל העמים עובדי עבודת כוכבים ומזלות, כי בכולם כתוב, הבל המה מעשה תעתועים בעת פקודתם יאבדו, היינו בשעה שעתיד הקב\"ה לבער אותם מן העולם, וישאר הוא בלבדו. כמו שאתה אומר, ונשגב ה' לבדו ביום ההוא."],[9,"רבי יהודה וכו':","ר\"י פתח ואמר, אל תיראי תולעת יעקב מתי ישראל וגו'. בוא וראה, כל עמי העולם עובדי עכו\"ם, נתן אותם הקב\"ה תחת שרים ממונים ידועים. כמו שלמדנו, וכולם הולכים אחר אלהיהם. כמו שכתוב, כי כל העמים ילכו איש בשם אלהיו. וכולם שופכי דמים ועושי מלחמה, גוזלים ומכים ומנאפים, ומתערבים בכל העושים מעשים להרע, ומתגברים תמיד בכחם להרע."]],[[0,"","וּכְשֶׁנִּפְרָדוֹת הַדְּרָגוֹת נִמְצָא קֶשֶׁר הַמַּפְסִיק, עַד שֶׁמִּתְקַשְּׁרִים לַצַּד שֶׁנִּרְאֶה לָהֶם, וְהַצְּדָדִים שֶׁל דַּרְגּוֹת הַטֻּמְאָה שֶׁהֵם בְּצַד שְׂמֹאל, כֻּלָּם נִפְרָדִים לְכַמָּה דְרָכִים וּשְׁבִילִים מִצִּדֵּי הַגְּבוּרוֹת הָאֲדֻמּוֹת, וְלָכֵן תְּלוּיוֹת הַגְּבוּרוֹת לְמַטָּה לְאֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת. וְעַל זֶה הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד, כְּמוֹ שֶׁאָמַ רְנוּ."],[1,"","בֹּא רְאֵה, וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם, בְּאֶרֶץ - בַּצַּד שֶׁל הַדַּרְגָּה שֶׁלּוֹ שֶׁהִיא דַּרְגַּת עֵשָׂו, שֶׁכָּתוּב עֵשָׂו הוּא אֱדוֹם, וְכֻלָּם בָּאִים מִצַּד שֶׁל רוּחַ הַטֻּמְאָה. לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל - מִשּׁוּם שֶׁאוֹתָן דְּרָגוֹת שֶׁעוֹמְדוֹת בְּבֵית הַשְּׁעָרִים לְמַטָּה קוֹדְמוֹת. וְלָכֵן אָמַר יַעֲקֹב יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ, בִּשְׁבִיל דַּרְגוֹתָיו הָרִאשׁוֹנוֹת הֵן לְהִכָּנֵס, וּמִשּׁוּם כָּךְ לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. שֶׁעַד עַכְשָׁו טֶרֶם הִגִּיעַ זְמַנָּהּ שֶׁל מַלְכוּת הַשָּׁמַיִם לִשְׁלֹט וּלְהֵאָחֵז בִּבְנֵי יִשְׂרָאֵל, וְלָכֵן אָמַר יַעֲבָר נָא אֲדנִי לִפְנֵי עַבְדּוֹ."],[2,"","וּכְשֶׁהֻשְׁלְמוּ דְּרָגוֹת אֵלּוּ בַּתְּחִלָּה, אַחַר כָּךְ מִתְעוֹרֶרֶת מַלְכוּת הַשָּׁמַיִם לִשְׁלֹט עַל הַתַּחְתּוֹנִים, וּכְשֶׁשּׁוֹרָה, שׁוֹרָה בַּקָּטָן שֶׁל כָּל הַשְּׁבָטִים, שֶׁהוּא בִּנְיָמִין, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סח) שָׁם בִּנְיָמִין צָעִיר רוֹדֵם וְגוֹ'. וּבוֹ שׁוֹרָה לְהִתְעוֹרֵר הַמַּלְכוּת. אַחַר כָּךְ בָּאָה הַמַּלְכוּת לִמְקוֹמָהּ וְעוֹמֶדֶת עִמּוֹ שֶׁלֹּא תָזוּז לְעוֹלָמִים."],[3,"","רַבִּי חִיָּיא פָּתַח וְאָמַר, (ישעיה מד) וְעַתָּה שְׁמַע יַעֲקֹב עַבְדִּי וְיִשְׂרָאֵל בָּחַרְתִּי בוֹ. כֹּה אָמַר ה' עֹשֶׂךְ וְיֹצֶרְךְ מִבֶּטֶן יַעְזְרֶךָּ אַל תִּירָא עַבְדִּי יַעֲקֹב וִישֻׁרוּן בָּחַרְתִּי בוֹ. בּא רְאֵה כַּמָּה הִבְטִיחַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל בְּכַמָּה מְקוֹמוֹת (כדי) לְזַכּוֹתָם לָעוֹלָם הַבָּא, שֶׁהֲרֵי לֹא הִתְרַצָּה לְחֶלְקוֹ לְכָל עַם וְלָשׁוֹן פְּרָט לְיִשְׂרָאֵל לְבַדָּם. וְלָכֵן נָתַן לָהֶם תּוֹרַת אֱמֶת, לִזְכּוֹת בָּהּ וְלָדַעַת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי שֶׁיִּירְשׁוּ אֶרֶץ הַקְּדוֹשָׁה, שֶׁכָּל מִי שֶׁזּוֹכֶה בָּאָרֶץ הַקְּדוֹשָׁה הַזּוֹ, יֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא, כְּמוֹ שֶׁנֶּאֱמַר (שם ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ, וַהֲרֵי נִתְבָּאֵר."],[4,"","שָׁלֹשׁ דְּרָגוֹת כָּאן: בַּתְּחִלָּה יַעֲקֹב, אַחַר כָּךְ יִשְׂרָאֵל, וְאַחַר כָּךְ יְשׁוּרוּן. בֹּא רְאֵה, יַעֲקֹב הֲרֵי כְּבָר בֵּאֲרוּהוּ, יִשְׂרָאֵל אַף גַם כָּךְ, וְאַף עַל גַּב שֶׁדְּרָגוֹת אֵלּוּ כְּאַחַת."],[5,"","יְשׁוּרוּן לָמָּה נִקְרְאוּ יִשְׂרָאֵל בְּשֵׁם זֶה? אֶלָּא יִשְׂרָאֵל וִישׁוּרוּן הַכֹּל אֶחָד. יְשׁוּרוּן, כְּמוֹ שֶׁנֶּאֱמַר (איוב לג) יָשֹׁר עַל אֲנָשִׁים, מִשּׁוּם שֶׁנָּטַל שׁוּרָה לְצַד זֶה וּלְצַד זֶה, וּמִשּׁוּם אוֹתָן שְׁתֵּי שׁוּרוֹת נִקְרָא יְשׁוּרוּן, וְזֶהוּ יִשְׂרָאֵל."],[6,"","יִשְׂרָאֵל עַל שֶׁנָּטַל גְּדֻלָּה וְתֹקֶף מֵהַכֹּל. יִשְׂרָאֵל (ישורון) עַל אוֹתָם חֲלָקִים שְׁנֵי צְדָדִים שְׁתֵּי שׁוּרוֹת, כְּמוֹ שֶׁאָמַרְנוּ, וְהַכֹּל אֶחָד."],[7,"","וְכָל אוֹתָם שֵׁמוֹת עוֹלִים לְאֶחָד. יַעֲקֹב עַבְדִּי, לִפְעָמִים הוּא עֶבֶד, כְּמוֹ עֶבֶד שֶׁיֵּשׁ לוֹ מִצְוַת אֲדוֹנוֹ וְלַעֲשׂוֹת רְצוֹנוֹ. וְכֵן יִשְׂרָאֵל בָּחַרְתִּי בוֹ, לְהַשְׁרוֹת עָלָיו, וְהַכֹּל הוּא בְּסוֹד עֶלְיוֹן. כָּתוּב (ישעיה מג) בֹּרַאֲךְ יַעֲקֹב וְיֹצֶרְךְ יִשְׂרָאֵל, וְכָתוּב כֹּה אָמַר ה' עֹשֶׂךְ. כָּל הַדְּרָגוֹת הַלָּלוּ עוֹלוֹת לְאֶחָד, וַהֲרֵי נֶאֱמַר, בּוֹרֵ\"א, יוֹצֵ\"ר, עוֹשֶׂ\"ה, וְכָל הַדְּרָגוֹת אֵלֶּה עַל אֵלֶּה וְכֻלָּן אֶחָד."],[8,"","אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כוֹכָבִים וּמַזָּלוֹת, מִשּׁוּם שֶׁבְּכֻלָּם כָּתוּב (ירמיה י) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים בְּעֵת פְּקֻדָּתָם יֹאבֵדוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְבַעֵר אוֹתָם מִן הָעוֹלָם וְיִשָּׁאֵר הוּא לְבַדּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ב) וְנִשְׂגָּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא."],[9,"","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שם מא) אַל תִּירְאִי תּוֹלַעַת יַעֲקֹב מְתֵי יִשְׂרָאֵל אֲנִי עֲזַרְתִּיךְ נְאֻם ה' וְגֹאֲלֵךְ קְדוֹשׁ יִשְׂרָאֵל. בֹּא רְאֵה, כָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן אוֹתָם לִמְמֻנִּים שַׁלִּיטִים יְדוּעִים כְּמוֹ שֶׁנֶּאֱמַר, וְכֻלָּם הוֹלְכִים אַחֲרֵי אֱלֹהֵיהֶם, כְּמוֹ שֶׁכָּתוּב (מיכה ד) כִּי כָל הָעַמִּים יֵלְכוּ אִישׁ בְּשֵׁם אֱלֹהָיו. וְכֻלָּם שׁוֹפְכִים דָּמִים וְעוֹרְכִים קְרָבוֹת אֵלּוּ בְּאֵלּוּ, גּוֹזְלִים רוֹצְחִים וְנוֹאֲפִים, וּמְעֹרָבִים בְּכַמָּה מַעֲשִׂים רָעִים, וּמִתְחַזְּקִים בְּכֹחָם לְהָרַע."]]],[["וְיִשְׂרָאֵל לֵית לוֹן תּוּקְפָא וְחֵילָא לְנַצְחָאָה לוֹן בַּר בְּפוּמְהוֹן, כְּתוֹלַעְתָּא דָא דְּלֵית לָהּ תּוּקְפָא וְחֵילָא אֶלָּא בְּפוּמָא, וּבְפוּמָא מִתְבַּר כֹּלָּא, וְעַל דָּא אִקְרוּן יִשְׂרָאֵל תּוֹלַעַת.","תוּ אַל תִּירְאִי תּוֹלַעַת יַעֲקֹב, מַה תּוֹלַעַת לֵית לִבְרִיָה דְעַלְמָא כְּהַאי תּוֹלַעַת דְּמֶשִׁי דְּסִיסְטְרָא, דְּמִנָּהּ נָפְקֵי כָּל לְבוּשֵׁי יְקָר טִיסְטְרֵי דְמַלְכִין, לְבָתַר זָרַע זַרְעִין וּמִית, וּלְבָתַר מֵהַהוּא זַרְעָא דְּאִשְׁתָּאַר מִנֵּיהּ אִתְקְיַּים כְּמִלְּקַדְּמִין וְהָא אִיהוּ בְּקִיּוּמָא. כָּךְ יִשְׂרָאֵל אִינוּן כְּהַאי תּוֹלַעַת. דְאַף עַל גַּב דְּמֵתִין, יִתְהַדְּרוּן וְיִתְקַיְּימוּן בְּעַלְמָא כְּמִלְּקַדְּמִין.","וְהָא אִתְּמָר (ד\"א ל\"ג דכתיב) (ירמיהו י״ח:ו׳) כִּי כַּחֹמֶר בְּיַד הַיּוֹצֵר כֵּן אַתֶּם בְּיָדִי בֵּית יִשְׂרָאֵל. מַאי כַּחֹמֶר. אֶלָא דָא הוּא חֹמֶר דְּהַהוּא זְכוּכִית, דְּאַף עַל גַּב דְּאִתָּבַר אִתְתַּקַּן וְאִית לֵיהּ תַּקָּנָה כְּמִלְּקַדְּמִין.","מְתֵי יִשְׂרָאֵל, דָּא אִילָנָא דְחַיֵּי, דִּבְגִין דְּיִשְׂרָאֵל אִינוּן אִתְדַּבָּקוּ בְּאִילָנָא דְחַיֵּי, בְּגִין כָּךְ יְהֵא חַיִּין לְהוֹן וִיקוּמוּן מֵעַפְרָא וְיִתְקַיְּימוּן בְּעַלְמָא, וִיהוֹן לְעַם חַד לְמִפְלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. כְּמָה דְאַתְּ אָמֵר (צפניה ג׳:ט׳) לִקְרֹא כֻּלָּם בְּשֵׁם יְיָ לְעָבְדוֹ שְׁכֶם אֶחָד.","רִבִּי אֶלְעָזָר וְרִבִּי יִצְחָק הֲווּ אָזְלֵי בְּאָרְחָא, וּמָטָא זִמְנָא דִּקְרִיאַת שְׁמַע, וְקָם רַבִּי אֶלְעָזָר וְקָרָא קְרִיאַת שְׁמַע וְצַלֵּי צְלוֹתֵיהּ. לְבָתַר אָמַר לֵיהּ רִבִּי יִצְחָק, וְהָא תָּנִינָן דְּעַד לָא יִפּוּק בַּר נַשׁ לְאָרְחָא אִבָּעֵי לֵיהּ לְנַטְלָא רְשׁוּ מִמָּארֵיהּ וּלְצַלֵּי צְלוֹתֵיהּ.","אָמַר לֵיהּ, בְּגִין דְּכַד נָפִיקְנָא לָא הֲוָה זְמַן צְלוֹתָא וְלָא מָטָא זִמְנָא דִּקְרִיאַת שְׁמַע, הַשְׁתָּא דְּשִׁמְשָׁא נָהִיר צַלֵּינָא. אֲבָל עַד לָא נָפַקְנָא לְאָרְחָא בָּעִינָא בָּעוּתָא מִנֵּיהּ וְאִמְלַכְנָא בֵּיהּ, אֲבָל צְלוֹתָא דָא לָא צַלֵּינָא.","דְּהָא אֲנָא אִשְׁתַּדַּלְנָא בְּאוֹרַיְיתָא מִפַּלְגוּת לֵילְיָא, וְכַד אֲתָא צַפְרָא עַד כְּעָן לָא הֲוָה עִדְנָא לְצַלֵּי צְלוֹתָא. בְּגִין דְּהַהִיא שַׁעְתָּא דְּקַדְרוּתָא דְצַפְרָא אִשְׁתַּכַּח, אִתְּתָא מִשְׁתָּעֲיָא בְּבַעֲלָהּ, וְאִינוּן בְּרָזָא כְּחֲדָא, דְּבָעְיָא אִיהִי לְמֵיהַךְ לְמִשְׁכְּנָא בְּעוּלֵמְתָהָא דְּיַתְבֵי בַּהֲדָהּ. וּבְגִין כָּךְ לָא בָּעֵי לֵיהּ לְבַר נָשׁ לְמִפְסַק מִלַיְיהוּ דְּמִתְחַבְּרָן כְּחֲדָא וּלְאַעֳלָא מִלָּה אַחֲרָא בֵּינַיְיהוּ.","וְהַשְׁתָּא דְּנָהִיר שִׁמְשָׁא הוּא עִדַּן צְלוֹתָא לְצַלָּאָה, כְּמָה דְאוּקְמוּהָ. דִּכְתִיב, (תהילים ע״ב:ה׳) יִירָאוּךָ עִם שָׁמֶשׁ. מַהוּ עִם שָׁמֶשׁ, לְנַטְרָא נְהוֹרָא דְּשִׁמְשָׁא בַּהֲדָן לְאַנְהָרָא לָהּ, דְּהָא יֵרָאֶה בַּהֲדֵי שִׁמְשָׁא אִצְטְרִיךְ וְלָא לְאַפְרָשָׁא לוֹן. וְכַד לָא נָהִיר יְמָמָא לָאו הוּא יֵרָאֶה בַּהֲדֵי שִׁמְשָׁא, וּצְרִיכָא לְחַבְּרָא לוֹן כְּחֲדָא. וְדָא הוּא עִם שָׁמֶשׁ.","אֲזְלֵי, כַּד מָטוּ חַד בֵּי חֲקַל, יָתְבוּ. זָקְפוּ עֵינַיְיהוּ וְחָמָא לֵיהּ לְטוּרָא דְּהֲווּ סָלְקוּ בְּרוּמֵיהּ בְּרִיָּין מְשַׁנְיָין, דָּחִיל רִבִּי יִצְחָק, אָמַר לֵיהּ רִבִּי אֶלְעָזָר אַמַּאי דְחִילַת. אָמַר לֵיהּ חָמֵינָא דְּהַאי טוּרָא אִיהוּ תַּקִּיף, וְחָמֵינָא אִלֵּין בְּרִיָּין דְּאִינוּן מְשַׁנְיָין וְדָחִילְנָא דְּלָא יְקַטְרְגוּ לוֹן, אָמַר לֵיהּ מַאן דְּדָחִיל מֵחֶטְאוֹי דְּבִידֵיהּ אִית לֵיהּ לְמִדְחַל. תָּא חֲזֵי, לָאו אִלֵּין מֵאִינוּן בְּרִיָּין תַּקִּיפִין דְּהֲווּ מִשְׁתַּכְּחִין בְּטוּרַיָא.","פָּתַח וְאָמַר. וְאֵלֶּה בְּנֵי צִבְעוֹן וְאַיָּה וַעֲנָה וְגו' הוּא עֲנָה אֲשֶׁר מָצָא אֶת הַיֵּמִים וְגו', הַאי קְרָא אוּקְמוּהָ, אֲבָל תָּא חֲזֵי, לָאו אִלֵּין אִינוּן דִּכְתִיב בְּהוּ (דברים ב׳:י״ב) הָאֵימִים לְפָנִים יָשְׁבוּ בָהּ וְגו' וּבְנֵי עֵשָׂו יִירָשׁוּם וְגו'.","אֲבָל אִלֵּין דְּקָאֲמַר קְרָא אֲשֶׁר מָצָא אֶת הַיֵּמִים בַּמִּדְבָּר, יֵמִם כְּתִיב. אִלֵּין הֲווּ בְּרִיָּין מְשַׁנְיָין. דְּכַד הֲוָה אִתָּרַךְ קַיִן מֵעַל אַפֵּי אַרְעָא כְּדִכְתִיב, (בראשית ד׳:י״ד) הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה וּמִפָּנְיךָ אֶסָּתֵר, וּכְתִיב וַיֵּשֶׁב בְּאֶרֶץ נוֹד וְאוּקְמוּהָ.","מִבְּנֵי בְּנוֹי בְּסִטְרָא (ויקרא עו ע\"ב) דְּרוּחִין וְעִלְעוּלִין וּמַזִּיקִין וְאִלֵּין קָיְימוּ, דְּהָא כַּד בָּעָא לְאִתְקַדְּשָׁא יוֹמָא דְשַׁבַּתָּא, אִתָּבְרוּן מֵהַהוּא סִטְרָא רוּחִין קָיְימִין טְסִירִין (נ\"א טהירין) בְּלָא גוּפָא. וְאִלֵין לָאו אִינוּן מִיּוֹמָא דְשַׁבַּתָּא וְלָא מִיּוֹמָא שְׁתִיתָאָה, וְאִשְׁתָּאֲרוּ אִלֵּין תְּרֵין יוֹמִין בְּהוּ בִּסְפֵקָא, וּבְגִין כָּךְ לָא אִתְקָיְימוּ לָא מֵהַאי וְלָא מֵהַאי."],[[0,"וישראל לית לון וכו':","וישראל אין להם גבורה וכח לנצח אותם רק בפיהם. דהיינו בתפלה. כמו תולעת זו, שאין לה גבורה וכח, אלא בפה. ובפה היא שוברת הכל. ועל כן נקראים ישראל תולעת."],[1,"תו, אל תיראי תולעת וגו':","עוד בביאור הכתוב אל תיראי תולעת יעקב, מה תולעת, אין לשום בריה בעולם, כמו לתולעת הזו של טוית המשי, שממנה יוצאים כל לבושי כבוד, תלבושת המלכים, ולאחר טויתה זורעת זרע ומתה, ואחר כך, מאותו זרע שנשאר ממנה, קמה לתחיה כמקודם לכן, ושוב היא חיה, כך הם ישראל, כאותה התולעת שאע\"פ שמתים יחזרו ויחיו בעולם, כמקודם לכן. \u0003סיסטרא\u0004 פירושו טויה, \u0003טיסטרי,\u0004 פירושו לפי הענין, תלבושת."],[2,"והא אתמר וכו':","וכן נאמר, כי כחמר ביד היוצר כן אתם בידי בית ישראל. ושואל, מהו כחמר. ומשיב, אלא זהו חומר של אותה זכוכית, אשר אע\"פ שנשברת חוזרת ומתתקנת ויש לה תקנה כמקודם לכן. כך ישראל, אע\"פ שמתים חוזרים לתחיה."],[3,"מתי ישראל:","זה הוא עץ החיים. דהיינו ז\"א הנקרא ישראל, ומשום שבני ישראל נתדבקו בעץ החיים, משום זה יהיו להם חיים ויקומו מעפר ויתקיימו בעולם ויהיו לעם אחד לעבוד את הקב\"ה, כמש\"א לקרא כלם בשם ה' לעבדו שכם אחד."],[4,"רבי אלעזר ור' יצחק וכו':","ר\"א ור\"י היו הולכים בדרך והגיע זמן קריאת שמע, וקם ר\"א וקרא ק\"ש היתפלל תפלתו. אח\"כ אמר לו ר\"י, והרי למדנו שמטרם שהאדם יוצא לדרך, צריך לקבל רשות מרבונו ולהתפלל תפלתו."],[5,"אמר ליה בגין וכו':","א\"ל משום, כשיצאתי, לא הגיע עדיין זמן התפלה, ולא הגיע זמן קריאת שמע. עתה שהאיר השמש התפללתי. אבל עוד מטרם שיצאתי לדרך בקשתי תחינה ממנו, ונועצתי בו, אלא תפלה זו של שחרית לא התפללתי."],[6,"דהא אנא אשתדלנא וכו':","כי עוסק אני בתורה מחצות לילה, וכשהגיע הבוקר, עד עתה עוד לא היה זמן תפלה, משום שבשעה ההיא שקדרות הבוקר נמצאת, האשה מספרת עם בעלה, והם בסוד היחוד כאחד, והיא צריכה ללכת למשכן בין נערותיה היושבות עמה שם. ולפיכך אין אדם צריך להפסיק הדברים, שמתחברים על ידיהם כאחד, ולהכניס דבר אחר ביניהם. (ביאור הדברים הוא להלן בסמוך)."],[7,"והשתא דנהיר שמשא וכו':","ועתה שהאיר השמש הגיע זמן תפלה להתפלל, כמו שבארוה, שכתוב, ייראוך עם שמש, מהו \u0003עם שמש,\u0004 היינו, לשמור עמנו אור השמש כדי להאיר אליה לנוקבא, הנקראת יראה. כי היראה שהיא הנוקבא, צריכה להיות בחיבור עם השמש, שהוא ז\"א, ולא להפריד אותם. וכל עוד שלא האיר היום אין היראה עם השמש, וע\"כ כשמאיר השמש, צריכים לחבר אותם יחד, וזהו \u0003עם שמש.\u0004"],[7,"","ביאור הדברים, כי יש ב' זווגים, א) להשלמת הכלים של הנוקבא, והוא זווג של לילה. ב) להשלמת המוחין שלה, והוא זווגו של יום. וענינם רחוק זה מזה עד לקצה, עד כי מעשה היחוד בזווג של הלילה, גורם פירוד אם ממשיכו בזווג של יום, וכן להיפך, שמעשה היחוד בזווג של יום, גורם פירוד אם ממשיכו בזווג של לילה."],[7,"","והענין הוא, כי יש ב' מצבים בנוקבא, א) מבחינת היותה בשלמות מטרם מיעוט הירח, שאז היתה קומתה שוה עם ז\"א בסוד ב' המאורות הגדולים. ב) מבחינת מציאותה עתה אחר מיעוטה, שנתמעטה עד לנקודה, ואין בה אלא מה שנותן לה ז\"א, ויש מעלה במצב הא', להיותה נשלמת בחכמה, וקומתה שוה עם ז\"א, אבל כנגד זה יש בה גרעון שמפאת חסרון אור החסדים גם החכמה שבה אינה מאירה והיא חשך. ואת המצב הזה ממשיכים לה ע\"י תפלת ערבית ועסק התורה בחצות לילה ואילך, והוא סוד זווג הלילה, בסו\"ה ותקם בעוד לילה ותתן טרף לביתה וחק לנערותיה. ויש מעלה במצב הב', שאז מקבלת חסדים מז\"א, והחכמה שבה מתלבשת בחסדים והמוחין מאירים בה בכל השלמות. אבל כנגד זה יש בה גרעון אז, כי נתמעטה קומתה ונעשתה טפלה לז\"א, ואין לה משהו מעצמה אלא מה שנותן לה ז\"א. (ועיין בענין זה לעיל בראשית א' דף ק\"ח ד\"ה וכבר) ואת המצב הזה ממשיכים לה ע\"י קריאת שמע ותפלה של שחרית, בזווג היום."],[7,"","וזה אמרו, (באות רנ\"ז) \u0003אשתדלנא באורייתא מפלגות ליליא\u0004 וכו' \u0003דההיא שעתא דקדרותא\u0004 וכו' \u0003אתתא משתיא בבעלה,\u0004 שז\"ס זווג של לילה להשלמת הכלים, שאז ממשיכים לה המצב הא', וז\"ש, \u0003ואינון ברזא כחדא,\u0004 דהיינו ששניהם הם בקומה שוה, \u0003דבעיא איהי למהך למשכנא,\u0004 שצריכה ללכת להשתלם בהארת הכלים, שה\"ס המשכן וכליו, \u0003בעולמתהא דיתבי בהדה,\u0004 ולהשפיע מאור זה אל העלמות היושבות עמה, בסו\"ה ותקם בעוד לילה וגו' וחק לנערותיה. \u0003ובגין כך, לא בעי ליה לבר נש למפסק מלייהו דמתחברן כחדא,\u0004 שאסור להפסיק הדברים הגורמים להם להתחבר כאחד בקומה שוה, דהיינו לבטל הארת החכמה שה\"ס המצב הא', \u0003ולאעלא מלה אחרא בינייהו,\u0004 ולהכניס דבר אחר ביניהם. דהיינו, שאסור אז לקרות שמע ולהתפלל תפלת שחרית, שבזה ממעט קומתה מקומת ז\"א, כדי להמשיך לה אור החסדים, שה\"ס המצב הב', ההפוך מהמצב הא' כנ\"ל, והמבטל אותו."],[7,"","וז\"ש \u0003והשתא דנהיר שמשא היא עדן צלותא,\u0004 כי כשהאיר השמש, דהיינו שהגיע הזמן לזווג של יום, ולהמשיך המצב הב' להשלמת המוחין, אז הוא זמן תפלה, כלומר שעל ידי התפלה ממשיכין לה את זה. וז\"ש \u0003לנטרא נהורא דשמשא בהדן,\u0004 דהיינו להמשיך אור ז\"א שנקרא שמש, שהיא אור החסדים, \u0003לאנהרא לה\u0004 להאיר אל הנוקבא, כדי שתתלבש החכמה שבה, באור החסדים דז\"א, \u0003דהא יראה בהדי שמשא אצטריך,\u0004 שהנוקבא צריכה אז להיות עם השמש, שהוא ז\"א, כלומר שאז אין לה מעצמה שום אור אלא צריכה לקבל מן השמש ולא \u0003לאפרשא לון,\u0004 שאם מפרידה מז\"א היא מתבטלת לגמרי, \u0003וכד לא נהיר יממא לאו הוא יראה בהדי שמשא,\u0004 דהיינו בלילה, אין היראה שהיא הנוקבא, עם השמש, כלומר שאינה מקבלת ממנו אור החסדים אלא היא מקבלת אור החכמה מבינה, (כנ\"ל דף מ' ד\"ה בשעתא ע\"ש) \u0003וצריכא לחברא לון כחדא,\u0004 וכשהגיע זמן זווג של יום צריכים לחבר אותם יחד, כי אז נעשית טפלה לו וצריכה לקבל ממנו הכל, כנ\"ל, \u0003ודא הוא עם שמש,\u0004 וע\"כ, אומר הכתוב ייראוך \u0003עם שמש,\u0004 דהיינו שנעשית אז מחוברת וטפלה לשמש."],[8,"אזלי, כד מטו וכו':","הלכו, ר\"א ור\"י. כשהגיעו לשדה אחד, ישבו. נשאו עיניהם וראו הר, שבריות משונות היו עולות בראשו. פחד רבי יצחק. אמר ליה ר' אלעזר, למה אתה מפחד. אמר ליה רואה אני את ההר הזה שהוא עצום, ואני רואה את אלו הבריות שעליו, שהן משונות, ואני מפחד שלא יצירו לנו. אמר לו, כל מי שמתיירא, יש לו להתיירא מהחטאים שבידו. בוא וראה, אין אלו מאותן הבריות החזקות שהיו נמצאות בהרים."],[9,"פתח ואמר ואלה בני צבעון","וגו': מקרא זה בארוהו. אבל בוא וראה, אין אלו אותם שכתוב בהם, \u0003האימים\u0004 לפנים ישבו בה וגו', ובני עשו יירשום וגו'."],[9,"","ביאור הדברים, כי נודע, שבהמשכת קו שמאל מתגלים דינים. ויש כאן הפרש בין אור הזכר אל אור הנקבה. כי בהמשכת קו שמאל בבחינת אור הזכר, שהוא ממעלה למטה מתגלים דינים קשים מאד. אבל אם ממשיך הארת השמאל בבחינת אור נקבה, שהיא ממטה למעלה, מתגלים רק דינים רפויים שאינם קשים. כמ\"ש בזהר אמור דף ע\"ג אות קצ\"ט, וז\"ל, \u0003אלא דההוא קלא לאו איהו לגבי יצחק כבקדמיתא,\u0004 דהיינו הארת קו שמאל שה\"ס יצחק, \u0003דתמן תוקפא תקיפא שרייא,\u0004 ששם שורים דינים קשים, \u0003אלא לגבי אינון בי דינא דלתתא,\u0004 דהיינו הארת קו שמאל, בבחינת אור הנקבה, הנקראת בית דין שלמטה, \u0003דאנון רפויין יתיר,\u0004 שהם דינים רפויים ואינם קשים ע\"ש."],[9,"","וזה אמרו כאן. \u0003אזלי,\u0004 שהלכו לתקן את הנוקבא, \u0003כד מטי חד בי חקל יתבו,\u0004 כשהגיעו אל הנוקבא, הנקראת \u0003חקל\u0004 תפוחין, ישבו, כי המוחין של הנוקבא נמשכים בישיבה, ולא בעמידה. פירוש. כי פעולת המשכת מוחין דג\"ר נרמזת בעמידה, כמו העומד הזוקף כל קומתו. ופעולת המשכת מוחין דו\"ק, נרמזת בישיבה, כמו היושב שקומתו מושפלת. וכיון שבאו להמשיך מוחין אל הנוקבא, שהארתה ממטה למעלה, שהיא בחינת מוחין דו\"ק, ע\"כ אומר, \u0003יתבו,\u0004 שהיא פעולה בישיבה."],[9,"","וז\"ש, \u0003זקפו עינייהו,\u0004 נשאו עיניהם, דהיינו שהתחילו להמשיך המוחין המכונים עינים וראיה \u0003וחמא ליה לטורא,\u0004 וראה בהר, דהיינו שהמשיך הארת השמאל המכונה הר, \u0003דהוו סלקו ברומיה בריין משניין,\u0004 שבריות משונות היו עולות בראשו, דהיינו גילוי הדינים הבאים עם המשכת הארת השמאל, מגילוי ג\"ר דקו שמאל, שה\"ס ראש ההר, ואע\"פ שהוא לא המשיך אלא ו\"ק שהם אור הנקבה, אמנם אי אפשר להמשיך ו\"ק זולת אם ממשיך מתחילה קומה שלמה, ואחר כך מניח את הג\"ר ונוטל רק ו\"ק, (כנ\"ל וירא דף ז' ד\"ה והוא ע\"ש) ולפיכך ראה את הדינים המתגלים מג\"ר דשמאל בעת המשכתו את ו\"ק דשמאל. וז\"ש, \u0003דהוו סלקו ברומיה\u0004 וכו'. וז\"ש \u0003חמינא דהאי טורא איהו תקיף,\u0004 ראה שההר הזה, דהיינו הארת השמאל, הוא קשה \u0003וחמינא אלין בריין דאינון משניין,\u0004 וראה אלו הבריות אשר שם, דהיינו פועלי הדין, שהן משונות, כלומר שמטילות אימה ופחד."],[9,"","וז\"ש, אמר ליה, \u0003מאן דדחיל מחטאוי דבידיה אית ליה למדחל,\u0004 כלומר, שאין לפחד אלא אם ממשיך אור זכר, שהוא ממעלה למטה, שהוא חטא עצה\"ד, (כנ\"ל ב\"ב דף קפ\"ט ד\"ה וע\"ד) אבל אם ממשיך אור הנקבה, שאין בזה חטא, אין כאן שום פחד. \u0003תא חזי, לאו אלין מאינון בריין תקיפין דהוו משתכחין בטוריא,\u0004 אלו הבריות שאתה רואה, אינן אותן הבריות החזקות הנמצאות בהרים, כלומר, אין אלו אותם הדינים הקשים, שדרכם להתגלות עם המשכת אור הזכר שבשמאל, כי אלו המתגלים עם אור הנקבה, שאתה רואה, אינם קשים, אלא דינים רפויים, כמבואר לעיל, וז\"ש \u0003פתח ואמר ואלה בני צבעון\u0004 וגו' \u0003אבל ת\"ח, לאו אלין אינון דכתיב בהו האימים לפנים\u0004 וגו', כי אלו שנקראים \u0003אימים\u0004 הם פועלי הדין המתגלים מהמשכת אור הזכר שבהארת השמאל, וע\"כ נקראים \u0003אימים,\u0004 להיותם דינים קשים המטילים אימה גדולה, ואלו הנקראים \u0003ימים,\u0004 הם פועלי הדין המתגלים עם המשכת אור הנקבה שבהארת השמאל, שאינם אלא דינים רפויים. וע\"כ נקראים ימים, ולא אימים."],[10,"אבל אלין דקאמר קרא וכו':","אבל אלו שאומר הכתוב, אשר מצא את \u0003הימים\u0004 במדבר, \u0003ימם\u0004 חסר י' כתוב, שזהו רומז שיש בהם שום מיעוט, ואומר, כי אלו הן בריות משונות, מבני בניו של קין, מאחר שקין גורש מעל פני האדמה, שכתוב, הן גרשת אותי מעל פני האדמה ומפניך אסתר. וכתוב וישב בארץ נוד. ובארוהו. פירוש. כי קין הוא הארת השמאל, אבל היו בו ב' בחינות, כי לפני שגורש מעל פני האדמה, היה בבחינת אור הזכר, שמתגלים בו דינים קשים כנ\"ל, ולאחר שגורש היה בו רק אור הנקבה של הארת השמאל, שמתגלים בו דינים רפויים בלבד. ואומר שאלו הימים שמצא ענה במדבר, הם מתולדות קין לאחר שגורש מעל פני האדמה, ועל כן הם נקראים \u0003ימים,\u0004 ולא \u0003אימים,\u0004 מפני שאין בהם דינים קשים."],[11,"מבני בנוי וכו':","מבני בניו של קין, בצד רוחות, סערות ומזיקים הם נמצאים, כי כשהיה צריך להתקדש יום השבת, דהיינו בין השמשות, נבראו מהצד ההוא רוחות, הנמצאות מעופפות בלי גוף, ואלו אינם מיום השבת ולא מיום הששי, להיותם מבין השמשות, ונשארו אלו שני ימים בהם בספק, ומשום זה, אין להם קיום לא מיום זה ולא מיום זה."]],[[0,"","וּלְיִשְׂרָאֵל אֵין תֹּקֶף וְכֹחַ לְנַצֵּחַ אוֹתָם פְּרָט לַפֶּה שֶׁלָּהֶם, כַּתּוֹלַעַת הַזּוֹ שֶׁאֵין לָהּ תֹּקֶף וְכֹחַ אֶלָּא בְּפִיהָ, וּבְפִיהָ הִיא שׁוֹבֶרֶת הַכֹּל, וְלָכֵן נִקְרְאוּ יִשְׂרָאֵל תּוֹלַעַת."],[1,"","עוֹד, אַל תִּירְאִי תּוֹלַעַת יַעֲקֹב - מַה תּוֹלַעַת אֵין בְּרִיָּה בָּעוֹלָם כְּמוֹ תּוֹלַעַת הַמֶּשִׁי הַזּוֹ שֶׁטּוֹוִים בּוֹ, שֶׁמִּמֶּנָּה יוֹצְאִים כָּל לְבוּשֵׁי כָבוֹד, לְבוּשֵׁי הַמְּלָכִים, אַחַר כָּךְ זוֹרַעַת זְרָעִים וּמֵתָה, וּמֵאוֹתוֹ הַזֶּרַע שֶׁנִּשְׁאָר מִמֶּנָּה מִתְקַיֶּמֶת כְּמוֹ מִקֹּדֶם וַהֲרֵיהִי בְּקִיּוּם - כָּךְ יִשְׂרָאֵל הֵם כְּמוֹ הַתּוֹלַעַת הַזּוֹ, שֶׁאַף עַל פִּי שֶׁמֵּתִים, יַחְזְרוּ וְיִתְקַיְּמוּ בָעוֹלָם כְּמוֹ מִקֹּדֶם."],[2,"","וַהֲרֵי נֶאֱמַר (שכתוב) (ירמיה יח) (כי) (הנה) כַחֹמֶר בְּיַד הַיּוֹצֵר כֵּן אַתֶּם בְּיָדִי בֵּית יִשְׂרָאֵל. מַה זֶּה כַּחֹמֶר? אֶלָּא זֶהוּ חֹמֶר שֶׁל אוֹתָהּ זְכוּכִית, שֶׁאַף עַל גַּב שֶׁנִּשְׁבָּר - נִתְקָן, וְיֵשׁ לוֹ תַּקָּנָה כְּמוֹ מִקֹּדֶם."],[3,"","מְתֵי יִשְׂרָאֵל - זֶה עֵץ הַחַיִּים. שֶׁמִּשּׁוּם שֶׁיִּשְׂרָאֵל דְּבוּקִים בְּעֵץ הַחַיִּים, לָכֵן יִהְיוּ לָהֶם חַיִּים וְיָקוּמוּ מִן הֶעָפָר וְיִתְקַיְּמוּ בָעוֹלָם וְיִהְיוּ לְעַם אֶחָד לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (צפניה ג) לִקְרֹא כֻלָּם בְּשֵׁם ה' לְעָבְדוֹ שְׁכֶם אֶחָד."],[4,"","רַבִּי אֶלְעָזָר וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ, וְהִגִּיעַ זְמַן קְרִיאַת שְׁמַע, וְקָם רַבִּי אֶלְעָזָר וְקָרָא קְרִיאַת שְׁמַע וְהִתְפַּלֵּל תְּפִלָּתוֹ. אַחַר כָּךְ אָמַר לוֹ רַבִּי יִצְחָק, וַהֲרֵי שָׁנִינוּ, שֶׁעַד שֶׁלֹּא יֵצֵא אָדָם לְדַרְכּוֹ, צָרִיךְ לִטֹּל רְשׁוּת מֵרִבּוֹנוֹ וּלְהִתְפַּלֵּל תְּפִלָּתוֹ."],[5,"","אָמַר לוֹ, מִשּׁוּם שֶׁכְּשֶׁיָּצָאתִי לֹא הָיָה זְמַן תְּפִלָּה וְלֹא הִגִּיעַ זְמַן קְרִיאַת שְׁמַע. עַכְשָׁו שֶׁהַשֶּׁמֶשׁ מְאִירָה, הִתְפַּלַּלְתִּי. אֲבָל עַד שֶׁלֹּא יָצָאתִי לַדֶּרֶךְ, בִּקַּשְׁתִּי בַקָּשָׁתִי מִמֶּנּוּ וְנִמְלַכְתִּי בוֹ, אֲבָל תְּפִלָּה זוֹ לֹא הִתְפַּלַּלְתִּי."],[6,"","שֶׁהֲרֵי אֲנִי עוֹסֵק בַּתּוֹרָה מֵחֲצוֹת הַלַּיְלָה, וְכַאֲשֶׁר הִגִּיעַ הַבֹּקֶר, עַד עַכְשָׁו לֹא הָיָה זְמַן לְהִתְפַּלֵּל תְּפִלָּה, מִשּׁוּם שֶׁאוֹתָהּ שָׁעָה שֶׁל קַדְרוּת הַשַּׁחַר נִמְצֵאת אִשָּׁה מְדַבֶּרֶת עִם בַּעְלָהּ וְהֵם בְּסוֹד כְּאֶחָד, שֶׁהִיא רוֹצָה לָלֶכֶת לְמִשְׁכָּנָהּ עִם עַלְמוֹתֶיהָ שֶׁיּוֹשְׁבוֹת עִמָּהּ, וְלָכֵן לֹא צָרִיךְ הָאָדָם לְהַפְסִיק דִּבּוּרָם כְּשֶׁמְּחֻבָּרִים כְּאֶחָד וּלְהַכְנִיס דָּבָר אַחֵר בֵּינֵיהֶם."],[7,"","וְעַכְשָׁו שֶׁהֵאִיר הַשֶּׁמֶשׁ, הוּא זְמַן הַתְּפִלָּה לְהִתְפַּלֵּל, כְּמוֹ שֶׁבֵּאֲרוּהוּ, שֶׁכָּתוּב (תהלים עב) יִירָאוּךְ עִם שָׁמֶשׁ. מַהוּ עִם שָׁמֶשׁ? לִשְׁמֹר אוֹר הַשֶּׁמֶשׁ עִמָּנוּ לְהָאִיר לָהּ, שֶׁהֲרי יֵרָאֶה עִם הַשֶּׁמֶשׁ צָרִיךְ, וְלֹא לְהַפְרִידָם. וּכְשֶׁלֹּא מֵאִיר הַיּוֹם, הוּא לֹא יֵרָאֶה עִם הַשֶּׁמֶשׁ, וְצָרִיךְ לְחַבֵּר אוֹתָם כְּאֶחָד, וְזֶהוּ עִם שָׁמֶשׁ."],[8,"","הָלְכוּ, כְּשֶׁהִגִּיעוּ לְבֵית שָׂדֶה אֶחָד יָשְׁבוּ. זָקְפוּ עֵינֵיהֶם וְרָאוּ הַר אֶחָד שֶׁהָיוּ עוֹלִים בְּרוּמוֹ בְּרִיּוֹת מְשֻׁנּוֹת. פָּחַד רַבִּי יִצְחָק. אָמַר לוֹ רַבִּי אֶלְעָזָר, לָמָּה אַתָּה פּוֹחֵד? אָמַר לוֹ, רָאִיתִי שֶׁהָהָר הַזֶּה קָשֶׁה, וְרָאִיתִי אֶת הַבְּרִיּוֹת הַלָּלוּ שֶׁהֵן מְשֻׁנּוֹת, וּפָחַדְתִּי שֶׁלֹּא יָצֵרוּ לָנוּ. אָמַר לוֹ, מִי שֶׁפּוֹחֵד - מֵחֲטָאִים שֶׁבְּיָדָיו יֵשׁ לוֹ לִפְחֹד. בֹּא רְאֵה, אֵין אֵלֶּה מֵאוֹתָן בְּרִיּוֹת קָשׁוֹת שֶׁהָיוּ נִמְצָאוֹת בֶּהָרִים."],[9,"","פָּתַח וְאָמַר: וְאֵלֶּה בְנֵי צִבְעוֹן וְאַיָּה וַעֲנָה הוּא עֲנָה אֲשֶׁר מָצָא אֶת הַיֵּמִם וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ, אֲבָל בֹּא רְאֵה, אֵין אֵלֶּה אוֹתָם שֶׁכָּתוּב בָּהֶם (דברים ב) הָאֵמִים לְפָנִים יָשְׁבוּ בָהּ וְגוֹ', וּבְנֵי עֵשָׂו יִירָשׁוּם וְגוֹ'."],[10,"","אֲבָל אֵלֶּה שֶׁאָמַר הַכָּתוּב אֲשֶׁר מָצָא אֶת הַיֵּמִם בַּמִּדְבָּר, יֵמִם כָּתוּב (חסר י'), אֵלּוּ הָיוּ בְּרִיּוֹת מְשֻׁנּוֹת. שֶׁכַּאֲשֶׁר גֹּרַשׁ קַיִן מֵעַל פְּנֵי הָאֲדָמָה, כַּכָּתוּב (בראשית ד) הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה וּמִפָּנֶיךְ אֶסָּתֵר, וְכָתוּב וַיֵּשֶׁב בְּאֶרֶץ נוֹד, וּבֵאֲרוּהוּ."],[11,"","מִבְּנֵי בָנָיו בְּצַד שֶׁל רוּחוֹת וּסְעָרוֹת וּמַזִּיקִים וְאֵלֶּה עָמְדוּ, שֶׁהֲרֵי כְּשֶׁרָצָה לְהִתְקַדֵּשׁ יוֹם הַשַּׁבָּת, נִבְרְאוּ מֵאוֹתוֹ צַד רוּחוֹת קַיָּמוֹת מְעוֹפְפוֹת (מאירות) בְּלִי גוּף, וְאֵלֶּה אֵינָם לֹא מִיּוֹם שַׁבָּת וְלֹא מִיּוֹם שִׁשִּׁי, וְנִשְׁאֲרוּ אֵלּוּ יוֹמַיִם בָּהֶם בְּסָפֵק, וְלָכֵן לֹא הִתְקַיְּמוּ לֹא מִזֶּה וְלֹא מִזֶּה."]]],[["וְאֲזְלוּ וְאִתְפַּשְּׁטוּ בְּהַהוּא סִטְרָא דְקַיִן וְאִגְלִימוּ בְּהַהוּא סִטְרָא וְלָא אִתְגְּלִימוּ לְאִתְקָיְימָא וְאִקְרוּן יֵמִ\"ם חָסֵר, דְּלָא אִתְקָיְימוּ לָא בְּיוֹמָא דָא וְלָא בְּיוֹמָא דָא, וְאִתְחֲזוּן לִבְנֵי נָשָׁא. וְאִיהוּ אַשְׁכַּח לוֹן וְאוֹלְפֵי לֵיהּ לְאַיְיתָאָה מַמְזֵרִין לְעַלְמָא. וְאִינוּן אָזְלֵי בֵּינֵי טוּרַיָא וְקָיְימִין בְּגוּפָא זִמְנָא חָדָא בְּיוֹמָא, וּלְבָתַר מִתְפַּשְׁטֵי מִנֵּיהּ.","תָּא חֲזֵי, עֲנָה דָא אִיהוּ מַמְזֵרָא הֲוָה, דְּאֲתָא צִבְעוֹן עַל אִמֵּיהּ וְאוֹלִיד מַמְזֵרָא, וְדָא אֲתָא מִסִּטְרָא דְרוּחַ מְסָאֲבָא דְּאִתְדָּבַּק בֵּיהּ. וּבְגִין כָּךְ אַשְׁכַּח לוֹן וְהֲווּ אוֹלְפֵי לֵיהּ כָּל זִינִין דִּסְטַר מְסָאֲבָא בְּגִין דָּא.","וְתָּא חֲזֵי, אִלֵּין אִינוּן וְכַמָּה אָחֳרָנִין מִתְפַּרְשָׁן אִלֵּין מֵאִלֵּין, כֻּלְּהוּ אַתְיָין מֵהַהוּא סִטְרָא וְאָזְלֵי בְּמַדְבְּרָא וְאִתְחֲזוּן תַמָּן. בְּגִין דְּמַדְבְּרָא אֲתַר חָרוּב וְאִיהוּ בֵּי מוֹתָבָא דִלְהוֹן. וְעִם כָּל דָּא, כָּל בַר נָשׁ דְּאָזִיל בְּאוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא וְדָחִיל לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא לָא מִסְתָּפֵי מִנַּיְיהוּ. אֲזְלוּ וְאָעֳלוּ בְּטוּרָא.","אָמַר רִבִּי יִצְחָק, כְּגַוְונָא דָא כָּל אִינוּן טוּרִין חֲרוּבִין אֲתַר בֵּי מוֹתָבָא דִלְהוֹן. אָמַר לֵיהּ, הָכִי הוּא, וְכָל אִינוּן דְּמִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא עֲלַיְיהוּ כְּתִיב, (תהילים קכ״א:ז׳-ח׳) יְיָ יִשְׁמָרְךָ מִכָּל רָע יִשְׁמֹר אֶת נַפְשֶׁךָ יְיָ יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ מֵעַתָּה וְעַד עוֹלָם.","פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (שם קיא) הַלְלוּיָה אוֹדֶה יְיָ בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה, הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, דָּוִד מַלְכָּא כָּל יוֹמוֹי הֲוָה מִשְׁתַּדַּל בְּפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְהֲוָה קָם בְּפַלְגוּת לֵילְיָא וּמְשַׁבַּח וּמוֹדֶה בְּשִׁירִין וְתוּשְׁבְּחָן, בְּגִין לְאִתְתַּקָּנָא דּוּכְתֵּיהּ בְּמַלְכוּ דִּלְעֵילָא.","דְּכַד אִתְעַר רוּחַ צָפוֹן בְּפַלְגוּת לֵילְיָא, הֲוָה יָדַע דְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַהִיא שַׁעְתָּא יִתְעַר בְּגִנְתָּא דְעֵדֶן לְאִשְׁתַּעְשֵׁעַ עִם צַדִּיקַיָּיא, וְאִיהוּ הֲוָה קָם בְּהַהִיא שַׁעְתָּא וְאִתְגַּבַּר בְּשִׁירִין וְתוּשְׁבְּחָן עַד דְּסָלִיק צַפְרָא.","בְּגִין דְּכַד קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתַּכַּח בְּגִנְתָּא דְעֵדֶן, הָא אוֹקִימְנָא דְּאִיהוּ וְכָל צַדִּיקַיָּיא דִּבְגִנְתָּא כֻּלְּהוּ צַיְיתִין לְקָלֵיהּ. כְּדִכְתִיב, (שיר השירים ח׳:י״ג) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי. וְלָא עוֹד, אֶלָּא דְחוּטָא דְחֶסֶד מָשִׁיךְ עֲלֵיהּ בִּימָמָא כְּמָה דְאִתְּמָר. דִּכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. וְלא עוֹד, אֶלָּא דְאִינוּן מִלִּין דְּאוֹרַיְיתָא דְּאִיהוּ אָמַר, כֻּלְּהוּ סָלְקִין וּמִתְעַטְּרִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כָּךְ דָּוִד מַלְכָּא הֲוָה מִשְׁתַּדֵּל בְּלֵילְיָא בְּפוּלְחָנָא דְמָארֵיהּ.","תָּא חֲזֵי, הַלְלוּיָהּ, בְּכָל אִינוּן שִׁירִין וְתוּשְׁבְּחָן דְּקָאֲמַר דָּוִד, הָא תָּנִינָן דִּלְעֵילָא מִכֻּלְּהוֹן הוּא הַלְלוּיָהּ וְאוּקְמוּהָ. מַאי טַעְמָא בְּגִין דְּכָלִיל שְׁמָא וּשְׁבָחָא כַּחֲדָא. מַאי שְׁמָא וּשְׁבָחָא. שְׁמָא דָּא (א) י\"ה. שְׁבָחָא מַאן אִיהוּ, אֶלָּא דָּא כְּנֶסֶת יִשְׂרָאֵל דְּאִיהוּ (הלל בגימ' ה\"ס שהוא אדני) מְתַקְנָּא שְׁבָחָא תָּדִיר לְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִשְׁתַּכְּכַת. כְּמָה דְאַתְּ אָמֵר, (תהילים פ״ג:ב׳) אֱלהִים אַל דֳּמִי לָךְ אַל תֶּחרָשׁ וְאַל תִּשְׁקֹט אֵל. בְּגִין דְּסִדּוּרָא דְּשְׁבָחָא אִיהִי מְסַדְּרַת וּמְשַׁבַּחַת תָּדִיר לְגַבֵּיהּ. וּבְגִין כָּךְ שְׁמָא וּשְׁבָחָא כַּחֲדָא.","אוֹדֶה יְיָ בְּכָל לֵבָב, כְּמָה דְאוּקְמוּהָ בְּיֵצֶר הַטּוֹב וּבְיֵצֶר הָרָע, בְּגִין דְּאִינוּן מִשְׁתַּכְּחֵי תָּדִיר לְגַבֵּיהּ דְּבַר נָשׁ, כְּמָה דְאַתְּ אָמֵר, (דברים ו) בְּכָל לְבָבְךָ וְאוּקְמוּהָ.","בְּסוֹד יְשָׁרִים (ועדה), אִלֵּין אִינוּן יִשְׂרָאֵל דְּכָל דַּרְגִּין בְּהוּ מִתְעַטְּרָן כַּהֲנֵי וְלֵיוָאֵי, צַדִּיקֵי וַחֲסִידֵי, יְשָׁרִים. וְעֵדָה, כְּמָה דְאַתְּ אָמֵר (תהילים פ״ב:א׳) נִצָּב בַּעֲדַת אֵל. וְאִינוּן רָזָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְעַטַּר בְּהוּ.","וּבְגִין כָּךְ בָּעֵי בַר נָשׁ לְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא תָּדִיר, בְּגִין דְּאִיהוּ אִתְרָעֵי בְּשִׁירִין וְתוּשְׁבְּחָן, וּמַאן דְּיָדַע לְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יְאוּת, קוּדְשָׁא בְּרִיךְ הוּא קַבִּיל צְלוֹתֵיהּ וְשֵׁזִיב לֵיהּ. הֲדָא הוּא דִכְתִיב (תהילים צ״א:י״ד) אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי וְגו' אֹרֶךְ יָמִים וְגו'.","פָּתַח רַבִּי יוֹסֵי וְאָמַר, (תהילים ל״ב:ז׳) אַתָּה סֵתֶר לִי מִצַּר תִּצְרֵנִי רָנִי פַלֵּט תְּסוֹבְבֵנִי סֶלָּה. אַתָּה סֵתֶר לִי, דָא קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ סִתְרָא וּמָגֵן לְבַר נָשׁ דְּאָזִיל בְּאָרְחֵי דְאוֹרַיְיתָא, וְאִיהוּ אִסְתַּתַּר בְּצִלָּא דְגַדְפוֹי דְּלָא יָכְלִין לְאַבְאָשָׁא לֵיהּ. מִצַּר תִּצְרֵנִי, מֵעֵילָא וּמִתַּתָּא, לְעֵילָא אִית לֵיהּ לְבַר נָשׁ מָארֵי דְבָבוּ, לְתַתָּא אוּף הָכִי נָמֵי. וּמַאן אִיהוּ, דָּא יֵצֶר הָרָע, דְאִיהוּ צַר לְעֵילָא וְצַר לְתַתָּא. וְאִלְמָלֵא יֵצֶר הָרָע, לָא אִשְׁתַּכַּח מָארֵי דְּבָבוּ לְבַר נָשׁ בְּעַלְמָא. בְּגִין כָּךְ מִצַּר תִּצְרֵנִי."],[[0,"ואזלו ואתפשטו וכו':","והלכו ונתפשטו באותו צד של קין. דהיינו בני בניו. ונתלבשו באותו הצד, ולא נתלבשו בהם להתקיים, בקיום ממשי, כי ע\"כ נקראות \u0003ימם\u0004 חסר \u0003י',\u0004 מפני שאין להם קיום לא מיום זה ולא מיום זה. דהיינו לא מיום ו' ולא מיום השבת, משום שנבראו בין השמשות כנ\"ל, והנה נראים לבני אדם. כלומר, אע\"פ שהן רוחות מ\"מ נראים, כי פעם א' ביום הן מתלבשות בגוף. כדלהלן, והוא, דהיינו \u0003ענה\u0004, מצא אותן הרוחות הנקראות ימים, ולמדו אותו להביא ממזרים לעולם, דהיינו לחבר חמור וסוס שיצא מהם פרד, והן הולכות בין ההרים ונמצאות מלובשות בגוף פעם אחת ביום, ואחר כך מתפשטות ממנו ונשארות בלי גוף."],[0,"","פירוש. אלו הרוחות נמשכות מהארת קו שמאל. ויש הפרש גדול בין הארת השמאל שבבחינת יום הששי, להארת השמאל מבחינת יום השבת, כי מבחינת יום הששי שה\"ס קו אמצעי, הוא נכלל ממסך דחירק, שה\"ס דינין דנוקבא. אבל מבחינת יום השבת, אין בו מסך כלל, ואלו הרוחות, כיון שנבראו בין השמשות, שהוא ספק יום ו' ספק יום השבת, נמצאים פגומים, ואינם יכולים לקבל לא מיום הששי ולא מיום השבת. וז\"ש \u0003ואקרון ימם חסר, דלא אתקיימו לא ביומא דא ולא ביומא דא,\u0004 כי הספק פוגם בהם ולא יוכלו לקבל. ועכ\"ז מקבלים הארה מקו שמאל המאיר בעת הזווג של זו\"ן ובכל יום ויום, וז\"ש, \u0003וקיימין בגופא זמנא חדא ביומא ולבתר מתפשטי מניה,\u0004 פירוש, ג' הקוין המאירים בזווג זו\"ן, מכונים ג' זמני, להיותם נמשכים מג' הנקודות חולם שורק וחירק המכונים ג' דוכתי (לעיל ב\"א דף כ' אות י\"ב) וזמנא חדא היינו קו שמאל הנמשך מדוכתא דשורק."],[1,"תא חזי ענה וכו':","בוא וראה ענה זה, ממזר היה, שבא צבעון על אמו והוליד ממזר, והוא בא על כן, מרוח הטומאה שנתדבק בו, ומשום זה מצא אותן הרוחות, והיו מלמדים אותו משום זה, כל מיני בחינות שבצד הטומאה."],[2,"ות\"ח אלין וכו':","ובוא וראה, אלו, הן וכמה אחרים היוצאים זה מזה, כולם באים מאותו הצד, דהיינו צד שמאל, והולכים במדבר ונראים שמה, משום שהמדבר הוא מקום חרב, הוא מקום מושב שלהם. כי החורבן נמשך תמיד מצד שמאל. ועם כל זה, כל אדם ההולך בדרכיו של הקב\"ה, ומתירא מפני הקב\"ה, אינו מפחד מהם. הלכו ונכנסו בהר. כלומר שהמשיכו הארת השמאל בנוקבא, ולא יראו."],[3,"אמר ר' יצחק וכו':","אר\"י, כעין זה, כל אלו ההרים החרבים הם מקום בית מושב שלהם. אמר לו, כן הוא, וכל אלו העוסקים בתורה, עליהם כתוב, ה' ישמרך מכל רע וגו'."],[4,"פתח ר' אלעזר וכו':","פתח ר\"א ואמר, הללויה אודה וגו', מקרא זה בארוהו, אבל בוא וראה, דוד המלך, כל ימיו היה עוסק בעבודת הקב\"ה, והיה קם בחצות לילה, ומשבח ומודה בשירות ותשבחות, כדי לתקן מקומו במלכות שלמעלה."],[5,"דכד אתער וכו':","וכאשר נתעורר רוח צפוני בחצות לילה, היה יודע, שהקב\"ה מתעורר באותה שעה בגן עדן להשתעשע עם הצדיקים, וע\"כ היה קם בשעה ההיא, והתגבר בשירות ותשבחות עד עלות הבוקר."],[6,"בגין דכד קב\"ה וכו':","משום, כי כשהקב\"ה נמצא בגן עדן, הנה בארנו, שהוא וכל הצדיקים שבגן, כולם מקשיבים לקולו, ככתוב, חברים מקשיבים לקולך השמיעני. ולא עוד אלא חוט של חסד נמשך עליו ביום, כמו שלמדנו, שכתוב, יומם יצוה ה' חסדו ובלילה שירה עמי. ולא עוד, אלא, אלו דברי תורה שאמר בלילה, כולם עולים ומתעטרים לפני הקב\"ה. ומשום זה, דוד המלך, היה עוסק בלילה בעבודת רבונו."],[7,"ת\"ח הללויה וכו':","בוא וראה, \u0003הללויה,\u0004 הנה בכל השירות והתשבחות שאמר דוד, למדנו, שהעליון מכולם הוא \u0003הללויה,\u0004 ובארוהו, מהו הטעם, משום שכולל שם ושבח ביחד, ושואל, מהו שם ושבח, הנה \u0003השם\u0004 הוא \u0003י\"ה\u0004 אבל \u0003השבח\u0004 מה הוא ומשיב, אלא \u0003שבח\u0004 הוא כנסת ישראל, שהיא הנוקבא שנקראת \u0003הלל\u0004 משום שהיא מסדרת תמיד שבח לקב\"ה ואינה שוככת, כמש\"א, אלקים אל דמי לך אל תחרש ואל תשקוט אל, כי סדרי שבח היא מסדרת, ומשבחת לו תמיד. ומשום זה מרומז במלה הללויה, שם ושבח ביחד. פי' שהשם הוא \u0003י\"ה\u0004 ושבח הוא \u0003הללו,\u0004 דהיינו השכינה, שמשבחת תמיד אליו."],[8,"אודה ה' בכל לבב:","כמו שבארוהו, שבכל לבב פירושו, ביצר טוב וביצר הרע. שהם נמצאים תמיד אצל האדם, כמו שאתה אומר, \u0003בכל לבבך,\u0004 ובארוהו שפירושו ביצ\"ט וביצה\"ר, כי יצה\"ט שורה בחלל הימני של הלב ויצה\"ר בחלל השמאלי שבו. אף כאן פירושו כן."],[9,"בסוד ישרים:","אלו הם ישראל, שנקראים ישרים, משום שכל המדרגות מתעטרות בהם, כהנים לויים צדיקים וחסידים. שהם ישרים. \u0003ועדה,\u0004 פירושו כמו שאתה אומר, נצב \u0003בעדת\u0004 אל, והם סוד שהקב\"ה מתעטר בהם."],[9,"","ביאור המאמר. ר' אלעזר ממשיך לבאר את טיב הזווג שבחצות לילה שהוא להמשכת החכמה בעיקר, וטיב הזווג של היום שהוא בעיקר להמשכת החסדים, שבלעדם אין החכמה שבנוקבא מאירה, והיא חשך ולא אור. וכן ז\"א אינו מתעטר בהארת החכמה זולת על ידי הנוקבא בסוד הזווג שבלילה. ומביא הכתוב אודה ה' בכל לבב וגו' שבו מבוארים ב' מיני ההארות הלילו. והשלמתם של זו\"ן זה מזה."],[9,"","ותחילה מבאר היטב ענין חצות לילה, ואומר (באות רס\"ז) \u0003דוד מלכא, כל יומוי הוה משתדל בפולחנא דקב\"ה,\u0004 פירוש, כי יש י\"ד עתים לטובה ויש י\"ד עתים לרעה, כמו שכתוב (קהלת ג')) וכרגיל, אי אפשר לעבוד את הקב\"ה כי אם באותם הימים שי\"ד עתים לטובה שולטים בהם, ולא בימים שי\"ד עתים לרעה שולטים בהם אבל הזוכה בהארת החכמה הוא מתקן עמהם גם את י\"ד העתים לרעה, שנעשות לו טובות גדולות, ואז יכול לעבוד ה' בכל ימיו, אף אחד מהם לא יחסר. וז\"ש, דוד מלכא, \u0003כל יומוי הוה משתדל בפולחנא דקב\"ה,\u0004 ואפילו בימים שי\"ד העתים לרעה היו שולטים. וז\"ש \u0003והוה קם בפלגות ליליא,\u0004 שאז הזמן לקבל המוחין הללו דהארת החכמה \u0003ומשבח ומודה וכו',\u0004 כי הארת המוחין הללו נמשכים בשירות ותשבחות, שהם בסוד הארת השמאל. \u0003בגין לאתתקנא דוכתיה במלכו דלעילא,\u0004 (כמ\"ש לעיל בפ' לך אות שע\"ה) \u0003דמלכותיה דיליה בהאי תלייא\u0004 ע\"ש. \u0003דכד אתער רוח צפון בפלגות ליליא,\u0004 וכו' כבר נתבאר ענין זה היטב לעיל (בפרשת לך דף ג' ד\"ה ת\"ח, ובדף קכ\"ג אות שס\"ג עש\"ה) ואין צורך להכפיל הדברים."],[9,"","וז\"ש \u0003ת\"ח הללויה,\u0004 וכו' \u0003דכליל שמא ושבחא כחדא.\u0004 דהיינו \u0003י\"ה\u0004 שהם מוחין דז\"א שה\"ס אור החסדים. \u0003והלל\u0004, שה\"ס הנוקבא, במוחין דהארת חכמה שנקראת אז \u0003הלל בגין דסדורא דשבחא איהי מסדרת ומשבחת תדיר לגביה,\u0004 דהיינו בין בי\"ד עתים לטובה ובין בי\"ד עתים לרעה, אמנם במוחין דאור החסדים אי אפשר לשבח \u0003תדיר לגביה,\u0004 כי בי\"ד עתים לרעה, אין שבח זולת ע\"י הארת חכמה כנ\"ל. ולפיכך \u0003אודה ה' בכל לבב כמה דאוקמוה ביצר הטוב וביצר הרע,\u0004 דהיינו בקו ימין שה\"ס יצה\"ט, שממנו י\"ד עתים לטובה ובקו שמאל שה\"ס יצר הרע. שממנו י\"ד עתים לרעה. \u0003בסוד ישרים, אלין אינון ישראל,\u0004 שה\"ס הקו האמצעי \u0003דכל דרגין בהו מתעטרן,\u0004 כי הקו האמצעי כולל בתוכו ב' הקוין, וע\"כ כולל כל המדרגות, שהם \u0003כהני וליואי צדיקי. ישרים ועדה,\u0004 פירושו \u0003כד\"א נצב בעדת אל,\u0004 שעדת ה\"ס הנוקבא, ונמצא \u0003ישרים ועדה\u0004 שהם זו\"ן, כי ישרים ה\"ס ישראל שהוא ז\"א, ועדה היא הנוקבא. ומשמיענו הכתוב, \u0003ואינון רזא דקב\"ה אתעטר בהו,\u0004 שהקב\"ה, שהוא ז\"א, מתעטר בהארת החכמה מן הנוקבא שנקראת \u0003עדה.\u0004 כי אינו מקבל חכמה אלא בעת הזווג עם הנוקבא כנודע. וע\"כ אוה\"כ ישרים ועדה."],[10,"ובג\"כ בעי ב\"נ וכו':","ומשום זה צריך האדם לשבח תמיד את הקב\"ה, משום שהוא רוצה שירות ותשבחות, דהיינו שרוצה להתעטר בחכמה כנ\"ל בדיבור הסמוך, ומי שיודע לשבח את הקב\"ה כראוי, דהיינו תמיד כנ\"ל, שהוא ע\"י המוחין דהארת חכמה, הקב\"ה מקבל תפלתו ומציל אותו. דהיינו כמו שאומר לעיל, (באות רנ\"ז) שמתחילה צריכים לזווג של לילה ואח\"כ לזווג של יום להמשכת חסדים בתפלת שחרית, וז\"ש אשגבהו כי ידע שמי וגו' אורך ימים וגו'."],[11,"פתח ר' יוסי ואמר:","אתה סתר לי מצר וגו' \u0003אתה סתר לי,\u0004 זה הקב\"ה, שהוא סתר ומגן לאדם ההולך בדרך התורה, שה\"ס קו אמצעי, והוא מסתתר בצל כנפיו, שלא יוכלו להרע לו, שואל א\"כ \u0003מצר תצרני,\u0004 למה לי, כי הוא אותו הדבר כמו אתה סתר לי. ומשיב, מלמעלה ומלמטה. מלמעלה יש לו לאדם שונאים, וע\"ז נאמר אתה סתר לי, ומלמטה גם כן, ומי הוא, זהו היצר הרע, וע\"ז נאמר מצר תצרני, והוא צר למעלה וצר למטה, כמ\"ש (מסכת ב\"ב ט\"ז.) יורד ומסית עולה ומסטין, ואלמלא היצר הרע, לא היה נמצא לאדם שונא בעולם. משום זה אוה\"כ, מצר תצרני, על היצר הרע."]],[[0,"","וְהָלְכוּ וְהִתְפַּשְּׁטוּ בְּאוֹתוֹ צַד שֶׁל קַיִן, וְהִתְלַבְּשׁוּ בְּאוֹתוֹ צַד, וְלֹא הִתְלַבְּשׁוּ לְהִתְקַיֵּם, וְנִקְרְאוּ יֵמִ\"ם חָסֵר, שֶׁלֹּא הִתְקַיְּמוּ לֹא בְּיוֹם זֶה וְלֹא בְּיוֹם זֶה, וְנִרְאִים לִבְנֵי אָדָם. וְהוּא מָצָא אוֹתָם וְלִמְּדוּ אוֹתוֹ לְהָבִיא מַמְזֵרִים לָעוֹלָם, וְהֵם הוֹלְכִים בֵּין הֶהָרִים וְעוֹמְדִים בְּגוּף פַּעַם אַחַת בַּיּוֹם, וְאַחַר כָּךְ מִתְפַּשְּׁטִים מִמֶּנּוּ."],[1,"","בֹּא רְאֵה, הָעֲנָה הַזֶּה הָיָה מַמְזֵר, שֶׁבָּא צִבְעוֹן עַל אִמּוֹ וְהוֹלִיד מַמְזֵר, וְזֶה בָּא מִצַּד רוּחַ הַטֻּמְאָה שֶׁנִּדְבַּק בּוֹ, וְלָכֵן מָצָא אוֹתָם וְלִמְּדוּ אוֹתוֹ כָּל מִינֵי צַד הַטֻּמְאָה בִּשְׁבִיל זֶה."],[2,"","וּבֹא וּרְאֵה, אֵלֶּה הֵם וְכַמָּה אֲחֵרִים נִפְרָדִים אֵלֶּה מֵאֵלֶּה, כֻּלָּם בָּאִים מֵאוֹתוֹ צַד וְהוֹלְכִים בַּמִּדְבָּר וְנִרְאִים שָׁם, מִשּׁוּם שֶׁהַמִּדְבָּר הוּא מָקוֹם חָרֵב וְהוּא בֵּית מוֹשָׁבָם. וְעִם כָּל זֶה, כָּל אָדָם שֶׁהוֹלֵךְ בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְיָרֵא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא פוֹחֵד מֵהֶם. הָלְכוּ וְנִכְנְסוּ בְּהַר."],[3,"","אָמַר רַבִּי יִצְחָק, כְּמוֹ זֶה כָּל אוֹתָם הָרִים חֲרֵבִים, מְקוֹם מוֹשָׁב שֶׁלָּהֶם הוּא. אָמַר לוֹ, כָּךְ זֶה, וְכָל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה כָּתוּב עֲלֵיהֶם (תהלים קכא) ה' יִשְׁמָרְךְ מִכָּל רָע יִשְׁמֹר אֶת נַפְשֶׁךְ ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ מֵעַתָּה וְעַד עוֹלָם."],[4,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (שם קיא) הַלְלוּיָהּ אוֹדֶה ה' בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה, פָּסוּק זֶה פֵּרְשׁוּהוּ, אֲבָל בֹּא רְאֵה, דָּוִד הַמֶּלֶךְ כָּל יָמָיו הָיָה מִשְׁתַּדֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָיָה קָם בַּחֲצוֹת הַלַּיְלָה וּמְשַׁבֵּחַ וּמוֹדֶה בְּשִׁירוֹת וְתִשְׁבָּחוֹת כְּדֵי לְתַקֵּן מְקוֹמוֹ בַּמַּלְכוּת שֶׁל מַעְלָה."],[5,"","שֶׁכְּשֶׁמִּתְעוֹרֵר רוּחַ צָפוֹן בַּחֲצוֹת הַלַּיְלָה, הָיָה יוֹדֵעַ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ שָׁעָה מִתְעוֹרֵר בְּגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, וְהוּא הָיָה קָם בְּאוֹתָהּ שָׁעָה וּמִתְגַּבֵּר בְּשִׁירִים וְתִשְׁבָּחוֹת עַד שֶׁעוֹלֶה הַשַּׁחַר."],[6,"","מִשּׁוּם שֶׁכְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בְּגַן עֵדֶן, הֲרֵי בֵּאַרְנוּ שֶׁהוּא וְכָל הַצַּדִּיקִים שֶׁבַּגָּן, כֻּלָּם מַקְשִׁיבִים לְקוֹלוֹ, כַּכָּתוּב (שיר ח) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי. וְלֹא עוֹד, אֶלָּא חוּט שֶׁל חֶסֶד מָשׁוּךְ עָלָיו בַּיּוֹם, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמּי. וְלֹא עוֹד, אֶלָּא שֶׁאוֹתָם דִּבְרֵי תוֹרָה שֶׁהוּא אוֹמֵר, כֻּלָּם עוֹלִים וּמִתְעַטְּרִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָכֵן דָּוִד הַמֶּלֶךְ הָיָה מִשְׁתַּדֵּל בַּלַּיְלָה בַּעֲבוֹדַת אֲדוֹנוֹ."],[7,"","בֹּא רְאֵה, הַלְלוּיָהּ, בְּכָל אוֹתָן שִׁירוֹת וְתִשְׁבָּחוֹת שֶׁדָּוִד אָמַר, הֲרֵי שָׁנִינוּ שֶׁלְּמַעְלָה מִכֻּלָּם הוּא הַלְלוּיָהּ, וּבֵאֲרוּהוּ, מָה הַטַּעַם? מִשּׁוּם שֶׁכּוֹלֵל הַשֵּׁם וְהַשֶּׁבַח כְּאֶחָד. מַה שֵּׁם וּמַה שֶּׁבַח? שֵׁם זֶה י\"ה. הַשֶּׁבַח מַהוּ? אֶלָּא זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא (הלל בגימטריא ה\"ס, שהוא אדנ\"י) מְתַקֶּנֶת שֶׁבַח תָּמִיד לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְלֹא שׁוֹקֶטֶת, כְּמוֹ שֶׁנֶּאֱמַר (שם פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרָשׁ וְאַל תִּשְׁקֹט אֵל. מִשּׁוּם שֶׁסִּדּוּר הַשֶּׁבַח הִיא מְסַדֶּרֶת וּמְשַׁבַּחַת תָּמִיד אֵלָיו, וְלָכֵן שֵׁם וְשֶׁבַח כְּאֶחָד."],[8,"","אוֹדֶה ה' בְּכָל לֵבָב, כְּמוֹ שֶׁבֵּאֲרוּהוּ - בַּיֵּצֶר הַטּוֹב וּבַיֵּצֶר הָרָע, מִשּׁוּם שֶׁהֵם נִמְצָאִים תָּמִיד אֵצֶל הָאָדָם, כְּמוֹ שֶׁנֶּאֱמַר (דברים ו) בְּכָל לְבָבְךְ, וּבֵאֲרוּהוּ."],[9,"","בְּסוֹד יְשָׁרִים וְעֵדָה - אֵלּוּ הֵם יִשְׂרָאֵל שֶׁכָּל הַדְּרָגוֹת מִתְעַטְּרוֹת בָּהֶם, כֹּהֲנִים וּלְוִיִּם, צַדִּיקִים וַחֲסִידִים, יְשָׁרִים. וְעֵדָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פג) נִצָּב בַּעֲדַת אֵל. וְהֵם סוֹד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בָּהֶם."],[10,"","וְלָכֵן צָרִיךְ הָאָדָם לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד, מִשּׁוּם שֶׁהוּא מִתְרַצֶּה בְּשִׁירִים וְתִשְׁבָּחוֹת, וּמִי שֶׁיּוֹדֵעַ לְשַׁבֵּחַ לוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא כָּרָאוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל תְּפִלָּתוֹ וּמַצִּילוֹ. זֶהוּ שֶׁכָּתוּב (שם צא) אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי וְגוֹ', אֹרֶךְ יָמִים וְגוֹ'."],[11,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שם לב) אַתָּה סֵתֶר לִי מִצַּר תִּצְּרֵנִי רָנֵּי פַלֵּט תְּסוֹבְבֵנִי סֶלָה. אַתָּה סֵתֶר לִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא סֵתֶר וּמָגֵן לְאָדָם שֶׁהוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, וְהוּא מִסְתַּתֵּר בְּצֵל כְּנָפָיו, שֶׁלֹּא יְכוֹלִים לְהָרַע לוֹ. מִצַּר תִּצְּרֵנִי - מִלְמַעְלָה וּמִלְּמַטָּה. לְמַעְלָה יֵשׁ לָאָדָם יְרִיבִים, אַף לְמַטָּה כָּךְ גַּם, וּמִיהוּ? זֶהוּ יֵצֶר הָרָע שֶׁהוּא צַר לְמַעְלָה וְצַר לְמַטָּה, וְאִלְמָלֵא יֵצֶר הָרָע - לֹא נִמְצָא בַּעַל רִיב לְאָדָם בָּעוֹלָם. בִּשְׁבִיל כָּךְ מִצַּר תִּצְּרֵנִי."]]],[["רָנֵי פַלֵּט תְּסוֹבְבֵנִי סֶלָה, יְסוֹבְבֵנִי סֶלָה מִבָּעֵי לֵיהּ, מַאי תְּסוֹבְבֵנִי. אִלֵּין אִינוּן שִׁירִין דְּאִית בְּהוּ דַּרְגִּין לְהַצָּלָה, תְּסוֹבְבֵנִי בְּהוּ לְשֵׁזָבָא לִי בְּאָרְחָא. וְהַאי קְרָא אִיהוּ כְּסִדְרָא וְאִיהוּ לְמַפְרֵעַ, מֵהַאי גִיסָא וּמֵהַאי גִיסָא.","תָּא חֲזֵי, בְּאִלֵּין שִׁירִין וְתוּשְׁבְּחָן דְּקָאֲמַר דָּוִד אִית בְּהוֹן רָזִין וּמִלִּין עִלָּאִין בְּרָזֵי דְחָכְמְתָא, בְּגִין דְּכֻלְּהוּ בְּרוּחַ קוּדְשָׁא אִתְאֲמָרוּ. דְּהֲוָה שָׁרַא רוּחַ קוּדְשָׁא עֲלֵיהּ דְּדָוִד, וְהֲוָה אָמַר שִׁירָתָא. וּבְגִין כָּךְ כֻּלְּהוּ בְּרָזֵי דְחָכְמְתָא אִתְאֲמָרוּ.","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהילים קי״ח:י״ג) דָּחֹה דְחִיתַנִי לִנְפֹּל וַיְיָ עֲזָרָנִי, דָּחֹה דְחִיתַנִי, דָּחֹה דָחוּנִי מִבָּעֵי לֵיהּ, מַאי דָּחֹה דְחִיתַנִי. אֶלָּא דָּא סִטְרָא אָחֳרָא דְּדַחְיָיא לֵיהּ לְבַר נָשׁ תָּדִיר, וּבָעֵי לְדַחְיָיא לֵיהּ וּלְאַסְטָאָה לֵיהּ מֵעִם קוּדְשָׁא בְּרִיךְ הוּא. וְדָא הוּא יֵצֶר הָרָע דְּאִשְׁתַּכַּח לְגַבֵּיהּ דְבַּר נָשׁ תָּדִיר. וּלְקֳבְלֵיהּ אַהֲדַר דָּוִד וְאָמַר דָּחֹה דְחִיתַנִי לִנְפּוֹל. בְּגִין דְּאִיהוּ הֲוָה אִשְׁתַּדַּל לְגַבֵּיהּ בְּכָל אִינוּן עַקְתִין לְאַסְטָאָה לֵיהּ מֵעִם קוּדְשָׁא בְּרִיךְ הוּא. וְעֲלֵיהּ אָמַר דָּוִד דָּחֹה דְחִיתַנִי לִנְפּוֹל בַּגֵּיהִנָּם. וַיְיָ עֲזָרָנִי דְּלָא אִתְמַסַּרְנָא בִּידָךְ. וְעַל דָּא אִית לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא מִנֵּיהּ, בְּגִין דְּלָא יִשְׁלוֹט עֲלֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא כְּדֵין נָטִיר לֵיהּ בְּכָל אָרְחוֹי. דִּכְתִיב, (משלי ג׳:כ״ג) אָז תֵּלֵךְ לָבֶטַח דַרְכֶּךָ וְרַגְלֶךָ לא תִגּוֹף (משלי ד׳:י״ב) בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ וְאִם תָּרוּץ לא תִכָּשֵׁל. וּכְתִיב, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וְאוֹר עַד נְכוֹן הַיּוֹם.","אָמַר רַבִּי יְהוּדָה זַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. דִּכְתִיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. (ע\"כ פרשת וישלח)"],[[0,"רני פלט תסובבני סלה:","שואל, יסובבני סלה היה צריך לומר, דהיינו לשון נסתר, שהרי תסובבני, סובב על רני פלט. ולמה אומר \u0003תסובבני\u0004 שהוא לשון נוכח ומשיב, שפירושו הוא, אלו השירים שיש בהם מדרגות להצלה תסובבני בהם להצילני בדרך. ולהקב\"ה אמר תסובבני. ומקרא זה אפשר לקראו כסדרו, ואפשר לקראו למפרע, דהיינו, \u0003סלה תסובבני פלט רני תצרני מצר לי סתר אתה\u0004 מצד זה ומצד זה, והבנתו אינה משתנה."],[0,"","פירוש. בעת שהקו השמאל האיר ממעלה למטה דהיינו מטרם שנכלל בימין, היה היצה\"ר נאחז באדם מלמעלה ומלמטה, כי מלמעלה קטרג עליו, והביא עליו שנאה, ומלמטה הסיתו לחטוא, ולהמשיך השמאל ממעלה למטה, שזה היה חטא עצה\"ד (כנ\"ל בהקסה\"ז דף קצ\"ט ד\"ה ודא חובה ע\"ש). וכשבא קו אמצעי, נכללו השמאל והימין זה בזה, והאירו ביחד, באופן שאור הימין האיר ממעלה למטה, והשמאל ממטה למעלה (כנ\"ל ב\"א דף נ\"ח ד\"ה עמודא ע\"ש) ואז נתבטלה השנאה שמלמעלה על האדם ונפרד ממנו היצה\"ר מלמטה."],[0,"","וז\"ש \u0003אתה סתר לי, דא קב\"ה,\u0004 דהיינו סוד הקו האמצעי. \u0003דאיהו סתרא ומגן\u0004 וכו', שיש בו ב' דברים. א) שהוא \u0003סתרא,\u0004 כי בגללו נתמעטו ג\"ר של הקו השמאל ואינו יכול להאיר רק ממטה למעלה שהיא בחינת ו\"ק דחכמה. ב) שהוא מגן, כי על ידיו נכללו השמאל והימין זה בזה, והעביר הקטרוג והשנאה מן האדם. וז\"ש \u0003ואיהו אסתתר בצלא דגדפוי, דלא יכלין לאבאשא ליה.\u0004 כי ההתמעטות שהביא לקו השמאלי בכח המסך דחירק, כמ\"ש שם, נבחנת ההתמעטות הזו לצל, והמסך לכנפים. וז\"ש \u0003לעילא אית ליה לבר נש מארי דבבו,\u0004 שה\"ס הקטרוג והשנאה הנמשכים לאדם מלמעלה בעת הארת השמאל ממעלה למטה. \u0003לתתא אוף הכי נמי ומאן איהו דא יצה\"ר,\u0004 היינו היצה\"ר המסיתו לחטוא ולהמשיך הארת השמאל ממעלה למטה כנ\"ל. \u0003דאיהו צר לעילא וצר לתתא,\u0004 דהיינו כמ\"ש יורד ומסית ועולה ומסטין, \u0003ואלמלא יצה\"ר לא אשתכח מארי דבבו לב\"נ בעלמא,\u0004 כלומר אם לא היה היצה\"ר עלול להסיתו לחטוא למטה, בעת הארת השמאל ממעלה למטה, אז לא היתה נמשכת שנאה על האדם מלמעלה."],[0,"","וז\"ש, \u0003מאי תסובבני אלין אינון שירין דאית בהו דרגין להצלה\u0004 שירים, ה\"ס החכמה המלובשת בחסדים, אחר שנתמעטה לו\"ק דג\"ר ע\"י קו אמצעי, שהיא נמשכת ומתגלית על ידי \u0003שירים,\u0004 ע\"כ מכונה שירים. וכיון שמקודם שנתמעטה החכמה ע\"י הקו האמצעי היה להיפך שהביאה עליו דינים, ע\"כ אמר להקב\"ה, שה\"ס קו אמצעי, \u0003רני פלט,\u0004 שפירושו, שירים שנפלטו ונשארו אחר התמעטותם על ידי הקו האמצעי, \u0003תסובבני\u0004 סלה להצילני בהם מכל המזיקים שהם בדרך. וז\"ש \u0003מאי תסובבני,\u0004 למה אמר להקב\"ה תסובבני. \u0003אלין אינון שירין דאית בהו דרגין להצלה,\u0004 אלו הם השירים, שיש בהם מדרגות, המספיקות להצלה, דהיינו אחר שנתמעטו ע\"י קו אמצעי, לו\"ק דג\"ר, נעשו מוכשרים להצלה כנ\"ל. \u0003תסובבני בהו לשזבא לי בארחא,\u0004 כי פעולה זו היא ע\"י קו אמצעי, שה\"ס הקב\"ה, וע\"כ אמר לו \u0003תסובבני,\u0004 לשון נוכח, ולא יסובבני."],[0,"","וז\"ש \u0003והאי קרא איהו כסדרא, ואיהו למפרע,\u0004 כי הקריאה כסדרו, תורה על קו ימין שה\"ס הארת החסדים המאירה ממעלה למטה. והקריאה למפרע, תורה על קו שמאל, שה\"ס הארת החכמה המאירה ממטה למעלה וכיון שמקרא זה מדבר על ב' מיני הארות הללו, ע\"כ אפשר לקראו כסדרו ואפשר לקראו כמפרע. \u0003מהאי גיסא ומהאי גיסא,\u0004 כי יש בו מצד ימין ומצד שמאל."],[1,"תא חזי באלין וכו':","בוא וראה, באלו שירות ותשבחות שאמר דוד, יש בהם סודות, ודברים עליונים בסודות החכמה. משום שכולם נאמרו ברוח הקודש, שרוח הקודש היה שורה על דוד ואמר שירה. ועל כן כולם ברוח הקודש נאמרו."],[2,"פתח ר' אלעזר וכו':","פתח ר\"א ואמר, דחה דחיתני לנפול וה' עזרני, ושואל, כתוב, \u0003דחה דחיתני,\u0004 דחה דחוני היה צריך לכתוב, מהי דחה דחיתני. שהרי הקב\"ה לא דחה אותו, אלא השונאים. ומשיב, אלא זה הסטרא אחרא, הדוחה האדם תמיד, ורוצה לדחותו ולהשטותו מעם הקב\"ה, וזה הוא היצה\"ר הנמצא עם האדם תמיד, ואליו חזר דוד ואמר דחה דחיתני לנפול, משום שהוא היה מסיתו בכל אלו הצרות שבאו עליו, להשטות אותו מעם הקב\"ה, ועליו אמר דוד \u0003דחה דחיתני לנפול,\u0004 בגיהנם \u0003וה' עזרני,\u0004 שלא נמסרתי בידך."],[3,"ועל דא אית ליה וכו':","ועל כן יש לו לאדם להזהר ממנו, כדי שלא ישלוט בו, ואז הקב\"ה שומר אותו בכל דרכיו. שכתוב אז תלך לבטח דרכך ורגלך לא תגוף, בלכתך לא יצר צעדך וגו'. וכתוב וארח צדיקים כאור נגה וגו'. אמר רבי יהודה אשרי הם ישראל, שהקב\"ה שומר אותם בעולם הזה ובעולם הבא. שכתוב ועמך כלם צדיקים לעולם ירשו ארץ. ברוך ה' לעולם אמן ואמן."]],[[0,"","רָנֵּי פַלֵּט תְּסוֹבְבֵנִי סֶלָה, הָיָה צָרִיךְ לִכְתֹּב יְסוֹבְבֵנִי סֶלָה, מַה זֶּה תְּסוֹבְבֵנִי? אֵלּוּ שִׁירִים שֶׁיֵּשׁ בָּהֶם דְּרָגוֹת לְהַצָּלָה, תְּסוֹבְבֵנִי בָּהֶם לְהַצִּילֵנִי בַּדֶּרֶךְ. וּפָסוּק זֶה הוּא גַּם כַּסֵּדֶר וְגַם לְמַפְרֵעַ, מִצַּד זֶה וּמִצַּד זֶה."],[1,"","בֹּא רְאֵה, בְּשִׁירִים וְתִשְׁבָּחוֹת הַלָּלוּ שֶׁאָמַר דָּוִד יֵשׁ בָּהּ סוֹדוֹת וּדְבָרִים עֶלְיוֹנִים בְּסוֹדוֹת הַחָכְמָה, מִשּׁוּם שֶׁכֻּלָּם נֶאֶמְרוּ בְּרוּחַ הַקֹּדֶשׁ, שֶׁהָיָה שׁוֹרֶה רוּחַ הַקֹּדֶשׁ עַל דָּוִד וְהָיָה אוֹמֵר שִׁירָה, וְלָכֵן כֻּלָּם נֶאֶמְרוּ בְּסוֹדוֹת הַחָכְמָה."],[2,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהלים קיח) דָּחֹה דְחִיתַנִי לִנְפֹּל וַה' עֲזָרָנִי. דָּחֹה דְחִיתַנִי, דָּחֹה דָחוּנִי הָיָה צָרִיךְ לִכְתֹּב! מַה זֶּה דָּחֹה דְחִיתַנִי? אֶלָּא זֶה צַד הָאַחֵר שֶׁדּוֹחֶה אֶת הָאָדָם תָּמִיד וְרוֹצֶה לִדְחוֹת אוֹתוֹ וּלְהַסְטוֹתוֹ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ יֵצֶר הָרָע שֶׁנִּמְצָא תָמִיד אֵצֶל הָאָדָם, וּכְנֶגְדּוֹ חָזַר דָּוִד וְאָמַר דָּחֹה דְחִיתַנִי לִנְפֹּל, מִשּׁוּם שֶׁהוּא הָיָה מִשְׁתַּדֵּל אֵלָיו בְּכָל אוֹתָן צָרוֹת לְהַסְטוֹתוֹ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעָלָיו אָמַר דָּוִד, דָּחֹה דְחִיתַנִי לִנְפֹּל - בַּגֵּיהִנֹּם, וַה' עֲזָרָנִי - שֶׁלֹּא נִמְסַרְתִּי לְיָדְךְ. וְעַל זֶה יֵשׁ לָאָדָם לְהִזָּהֵר מִמֶּנּוּ כְּדֵי שֶׁלֹּא יִשְׁלֹט עָלָיו, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתוֹ בְּכָל דְּרָכָיו, שֶׁכָּתוּב (משלי יג) אָז תֵּלֵךְ לָבֶטַח דַּרְכֶּךְ וְרַגְלְךְ לֹא תִגּוֹף, (שם ד) בְּלֶכְתְּךְ לֹא יֵצַר צַעֲדֶךְ וְאִם תָּרוּץ לֹא תִכָּשֵׁל, וְכָתוּב (שם) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם."],[3,"","אָמַר רַבִּי יְהוּדָה, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
